const finalization_cleanup_queue_reserve_granularity = 16;
const module_queue_reserve_granularity = 16;
const module_namespace_waiter_reserve_granularity = 16;
const runtime_gc_tenuring_age: u8 = 3;
const precise_gc_nursery_threshold_bytes: usize = 2 * 1024 * 1024;
const gc_auto_compaction_min_reclaimable_bytes: usize = 512 * 1024;

/// Serializes calls into an embedder allocator that may not itself be safe for
/// concurrent use. Under no-GIL execution, otherwise-independent engine locks
/// (arena refills, GC slab refills, JIT ownership, side lists) can all bottom
/// out in that same allocator at once. This wrapper is installed only for true
/// parallel contexts and sits below every Context allocator consumer.
const SerializedAllocator = struct {
    inner: std.mem.Allocator,
    lock: std.atomic.Value(u32) = .init(0),

    inline fn acquire(self: *SerializedAllocator) void {
        var spins: usize = 0;
        while (self.lock.cmpxchgWeak(0, 1, .acquire, .monotonic) != null) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
    }

    inline fn release(self: *SerializedAllocator) void {
        self.lock.store(0, .release);
    }

    fn allocFn(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *SerializedAllocator = @ptrCast(@alignCast(ctx));
        self.acquire();
        defer self.release();
        return self.inner.vtable.alloc(self.inner.ptr, len, alignment, ret_addr);
    }

    fn resizeFn(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *SerializedAllocator = @ptrCast(@alignCast(ctx));
        self.acquire();
        defer self.release();
        return self.inner.vtable.resize(self.inner.ptr, memory, alignment, new_len, ret_addr);
    }

    fn remapFn(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *SerializedAllocator = @ptrCast(@alignCast(ctx));
        self.acquire();
        defer self.release();
        return self.inner.vtable.remap(self.inner.ptr, memory, alignment, new_len, ret_addr);
    }

    fn freeFn(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *SerializedAllocator = @ptrCast(@alignCast(ctx));
        self.acquire();
        defer self.release();
        self.inner.vtable.free(self.inner.ptr, memory, alignment, ret_addr);
    }

    const vtable: std.mem.Allocator.VTable = .{
        .alloc = allocFn,
        .resize = resizeFn,
        .remap = remapFn,
        .free = freeFn,
    };

    fn allocator(self: *SerializedAllocator) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &vtable };
    }
};

test "SerializedAllocator prevents overlapping embedder allocator calls" {
    if (builtin.single_threaded) return error.SkipZigTest;

    const ProbeAllocator = struct {
        inner: std.mem.Allocator,
        active: std.atomic.Value(u32) = .init(0),
        overlapped: std.atomic.Value(bool) = .init(false),

        fn enter(self: *@This()) void {
            if (self.active.fetchAdd(1, .acq_rel) != 0) self.overlapped.store(true, .release);
            var i: usize = 0;
            while (i < 2000) : (i += 1) std.atomic.spinLoopHint();
        }

        fn leave(self: *@This()) void {
            _ = self.active.fetchSub(1, .release);
        }

        fn allocFn(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.enter();
            defer self.leave();
            return self.inner.vtable.alloc(self.inner.ptr, len, alignment, ret_addr);
        }

        fn resizeFn(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.enter();
            defer self.leave();
            return self.inner.vtable.resize(self.inner.ptr, memory, alignment, new_len, ret_addr);
        }

        fn remapFn(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.enter();
            defer self.leave();
            return self.inner.vtable.remap(self.inner.ptr, memory, alignment, new_len, ret_addr);
        }

        fn freeFn(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.enter();
            defer self.leave();
            self.inner.vtable.free(self.inner.ptr, memory, alignment, ret_addr);
        }

        const vtable: std.mem.Allocator.VTable = .{
            .alloc = allocFn,
            .resize = resizeFn,
            .remap = remapFn,
            .free = freeFn,
        };

        fn allocator(self: *@This()) std.mem.Allocator {
            return .{ .ptr = self, .vtable = &vtable };
        }
    };

    const Runner = struct {
        fn run(allocator: std.mem.Allocator) void {
            var i: usize = 0;
            while (i < 50) : (i += 1) {
                const memory = allocator.alloc(u8, 64) catch return;
                allocator.free(memory);
            }
        }
    };

    var probe = ProbeAllocator{ .inner = std.heap.page_allocator };
    var serialized = SerializedAllocator{ .inner = probe.allocator() };
    const allocator = serialized.allocator();
    var threads: [8]std.Thread = undefined;
    for (&threads) |*thread| thread.* = try std.Thread.spawn(.{}, Runner.run, .{allocator});
    for (&threads) |*thread| thread.join();

    try std.testing.expect(!probe.overlapped.load(.acquire));
    try std.testing.expectEqual(@as(u32, 0), probe.active.load(.acquire));

    const parallel = try Context.createWith(std.testing.allocator, .{ .enable_threads = true });
    try std.testing.expect(parallel.host_allocator_lock != null);
    parallel.destroy();
    const serialized_context = try Context.createWith(std.testing.allocator, .{ .enable_threads = true, .gil = true });
    try std.testing.expect(serialized_context.host_allocator_lock == null);
    serialized_context.destroy();
}

/// A mutex-guarded wrapper over the per-context arena allocator. Shapes,
/// interned strings, AST nodes, and Environment binding tables are all
/// arena-allocated, and `std.heap.ArenaAllocator` is not thread-safe — so once
/// the GIL is gone and multiple JS threads allocate at once, the arena's free
/// list would corrupt (issue #1 blocker #1). This serializes every arena
/// alloc/resize/remap/free behind a brief atomic spinlock. Installed only when
/// `enable_threads` (a single-thread context keeps the raw arena, no lock); the
/// no-GIL default may contend here, while `.gil = true` keeps it uncontended and
/// the single-thread path pays nothing.
pub const LockedArena = struct {
    const local_chunk_bytes: usize = 64 * 1024;
    const local_max_alloc: usize = 4096;
    const local_chunk_alignment: std.mem.Alignment = .@"64";

    const LocalChunk = struct {
        start: usize,
        end: usize,
    };

    inner: std.mem.Allocator,
    lock: std.atomic.Value(u32) = .init(0),
    local_chunks: std.ArrayListUnmanaged(LocalChunk) = .empty,

    threadlocal var local_owner: ?*LockedArena = null;
    threadlocal var local_start: usize = 0;
    threadlocal var local_cursor: usize = 0;
    threadlocal var local_end: usize = 0;

    inline fn acquire(self: *LockedArena) void {
        var spins: usize = 0;
        while (self.lock.cmpxchgWeak(0, 1, .acquire, .monotonic) != null) : (spins += 1) std.atomic.spinLoopHint();
        jsthread.recordArenaLockAcquire(spins);
    }
    inline fn unlock(self: *LockedArena) void {
        self.lock.store(0, .release);
    }

    inline fn canUseLocal(len: usize, alignment: std.mem.Alignment) bool {
        return len > 0 and
            len <= local_max_alloc and
            @backingInt(alignment) <= @backingInt(local_chunk_alignment);
    }

    inline fn resetLocalFor(self: *LockedArena) void {
        if (local_owner == self) {
            local_owner = null;
            local_start = 0;
            local_cursor = 0;
            local_end = 0;
        }
    }

    fn allocLocalExisting(self: *LockedArena, len: usize, alignment: std.mem.Alignment) ?[*]u8 {
        if (!canUseLocal(len, alignment)) return null;
        if (local_owner != self) return null;
        const aligned = alignment.forward(local_cursor);
        if (aligned > local_end or len > local_end - aligned) return null;
        local_cursor = aligned + len;
        return @ptrFromInt(aligned);
    }

    fn ownsCurrentLocal(self: *LockedArena, ptr: [*]u8) bool {
        if (local_owner != self) return false;
        const addr = @intFromPtr(ptr);
        return addr >= local_start and addr < local_end;
    }

    fn ownsLocalLocked(self: *LockedArena, ptr: [*]u8) bool {
        const addr = @intFromPtr(ptr);
        for (self.local_chunks.items) |chunk| {
            if (addr >= chunk.start and addr < chunk.end) return true;
        }
        return false;
    }

    fn refillLocal(self: *LockedArena, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        if (!canUseLocal(len, alignment)) return null;
        self.acquire();
        defer self.unlock();

        const raw = self.inner.vtable.alloc(self.inner.ptr, local_chunk_bytes, local_chunk_alignment, ret_addr) orelse return null;
        const start = @intFromPtr(raw);
        const end = start + local_chunk_bytes;
        self.local_chunks.append(self.inner, .{ .start = start, .end = end }) catch return null;
        local_owner = self;
        local_start = start;
        local_cursor = start;
        local_end = end;
        return self.allocLocalExisting(len, alignment);
    }

    fn allocFn(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *LockedArena = @ptrCast(@alignCast(ctx));
        if (self.allocLocalExisting(len, alignment)) |ptr| return ptr;
        if (self.refillLocal(len, alignment, ret_addr)) |ptr| return ptr;
        self.acquire();
        defer self.unlock();
        return self.inner.vtable.alloc(self.inner.ptr, len, alignment, ret_addr);
    }
    fn resizeFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *LockedArena = @ptrCast(@alignCast(ctx));
        if (self.ownsCurrentLocal(mem.ptr)) return false;
        self.acquire();
        defer self.unlock();
        if (self.ownsLocalLocked(mem.ptr)) return false;
        return self.inner.vtable.resize(self.inner.ptr, mem, alignment, new_len, ret_addr);
    }
    fn remapFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *LockedArena = @ptrCast(@alignCast(ctx));
        if (self.ownsCurrentLocal(mem.ptr)) return null;
        self.acquire();
        defer self.unlock();
        if (self.ownsLocalLocked(mem.ptr)) return null;
        return self.inner.vtable.remap(self.inner.ptr, mem, alignment, new_len, ret_addr);
    }
    fn freeFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *LockedArena = @ptrCast(@alignCast(ctx));
        if (self.ownsCurrentLocal(mem.ptr)) return;
        self.acquire();
        defer self.unlock();
        if (self.ownsLocalLocked(mem.ptr)) return;
        self.inner.vtable.free(self.inner.ptr, mem, alignment, ret_addr);
    }

    const vtable: std.mem.Allocator.VTable = .{
        .alloc = allocFn,
        .resize = resizeFn,
        .remap = remapFn,
        .free = freeFn,
    };

    pub fn allocator(self: *LockedArena) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &vtable };
    }
};

/// A small owned wrapper that enforces a per-Context outstanding-byte budget
/// over the embedder allocator. It is intentionally byte-count based rather than
/// JavaScript-semantics based: arena chunks, GC cell slabs, side stores, thread
/// records, and other Context-owned allocations all pass through this allocator,
/// so embedders get one fail-closed resource-control knob without requiring a
/// separate quota check at every allocation site.
pub const BudgetAllocator = struct {
    const RecoveryFn = *const fn (*anyopaque) bool;

    inner: std.mem.Allocator,
    limit: usize,
    used: std.atomic.Value(usize) = .init(0),
    peak: std.atomic.Value(usize) = .init(0),
    /// Precharged, one-shot recovery storage (#722). It is allocated through
    /// this wrapper, so it consumes part of `limit` from Context creation onward.
    /// If a full recovery collection cannot satisfy a request because the
    /// mutator's conservative stack still pins recently-dead storm garbage, the
    /// reserve is freed and the request retries inside the unchanged hard cap.
    recovery_reserve: []u8 = &.{},
    /// 0 = unavailable, 1 = held, 2 = being released, 3 = released. Multiple
    /// no-GIL mutators can miss the cap together; exactly one frees the reserve
    /// and peers wait only for that infallible allocator release to publish.
    recovery_reserve_state: std.atomic.Value(u8) = .init(0),
    recover_ctx: ?*anyopaque = null,
    recover_fn: ?RecoveryFn = null,
    /// A quota miss under an allocator/GC lock cannot collect synchronously.
    /// Preserve that miss until the JavaScript throw-to-catch unwind reaches a
    /// boundary where every trace-sensitive lock has been released.
    deferred_recovery_pending: std.atomic.Value(bool) = .init(false),

    threadlocal var recovery_depth: usize = 0;

    fn recordPeak(self: *BudgetAllocator, used_now: usize) void {
        var current = self.peak.load(.monotonic);
        while (used_now > current) {
            if (self.peak.cmpxchgWeak(current, used_now, .monotonic, .monotonic)) |observed| {
                current = observed;
                continue;
            }
            return;
        }
    }

    fn reserve(self: *BudgetAllocator, amount: usize) ?usize {
        var current = self.used.load(.monotonic);
        while (true) {
            if (amount > self.limit -| current) return null;
            const next = current + amount;
            if (self.used.cmpxchgWeak(current, next, .acq_rel, .monotonic)) |observed| {
                current = observed;
                continue;
            }
            return next;
        }
    }

    fn tryRecover(self: *BudgetAllocator) bool {
        if (recovery_depth != 0) return false;
        const ctx = self.recover_ctx orelse return false;
        if (gc_runtime.allocationRecoveryBlocked()) {
            self.deferred_recovery_pending.store(true, .release);
            return false;
        }
        const f = self.recover_fn orelse return false;
        recovery_depth += 1;
        defer recovery_depth -= 1;
        const recovered = f(ctx);
        if (recovered) self.deferred_recovery_pending.store(false, .release);
        return recovered;
    }

    fn reserveWithRecovery(self: *BudgetAllocator, amount: usize) ?usize {
        if (self.reserve(amount)) |next| return next;
        if (!self.tryRecover()) return null;
        if (self.reserve(amount)) |next| return next;
        // A full collection ran and the retry still missed (#722): release the
        // precharged reserve so the mutator can unwind past conservative stale
        // roots without ever raising or exceeding the configured hard limit.
        if (self.releaseRecoveryReserve()) return self.reserve(amount);
        return null;
    }

    fn release(self: *BudgetAllocator, amount: usize) void {
        const previous = self.used.fetchSub(amount, .acq_rel);
        std.debug.assert(previous >= amount);
    }

    fn installRecoveryReserve(self: *BudgetAllocator, amount: usize) !void {
        if (amount == 0) return;
        std.debug.assert(self.recovery_reserve_state.load(.monotonic) == 0);
        self.recovery_reserve = try self.allocator().alloc(u8, amount);
        self.recovery_reserve_state.store(1, .release);
    }

    fn releaseRecoveryReserve(self: *BudgetAllocator) bool {
        var state = self.recovery_reserve_state.load(.acquire);
        var spins: usize = 0;
        while (true) switch (state) {
            0 => return false,
            1 => {
                if (self.recovery_reserve_state.cmpxchgWeak(1, 2, .acq_rel, .acquire)) |observed| {
                    state = observed;
                    continue;
                }
                const memory = self.recovery_reserve;
                self.inner.free(memory);
                self.release(memory.len);
                self.recovery_reserve_state.store(3, .release);
                return true;
            },
            2 => {
                while (self.recovery_reserve_state.load(.acquire) == 2) : (spins += 1) {
                    if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
                }
                state = self.recovery_reserve_state.load(.acquire);
            },
            3 => return true,
            else => unreachable,
        };
    }

    fn deinit(self: *BudgetAllocator) void {
        const state = self.recovery_reserve_state.load(.acquire);
        std.debug.assert(state != 2);
        if (state == 1) {
            self.inner.free(self.recovery_reserve);
            self.release(self.recovery_reserve.len);
        }
        self.recovery_reserve = &.{};
        self.recovery_reserve_state.store(0, .release);
    }

    fn allocFn(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *BudgetAllocator = @ptrCast(@alignCast(ctx));
        const next = self.reserveWithRecovery(len) orelse return null;
        const ptr = self.inner.vtable.alloc(self.inner.ptr, len, alignment, ret_addr) orelse {
            self.release(len);
            return null;
        };
        self.recordPeak(next);
        return ptr;
    }

    fn resizeFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *BudgetAllocator = @ptrCast(@alignCast(ctx));
        const grow_next = if (new_len > mem.len) self.reserveWithRecovery(new_len - mem.len) orelse return false else null;
        if (!self.inner.vtable.resize(self.inner.ptr, mem, alignment, new_len, ret_addr)) {
            if (new_len > mem.len) self.release(new_len - mem.len);
            return false;
        }
        if (grow_next) |next| self.recordPeak(next);
        if (new_len < mem.len) self.release(mem.len - new_len);
        return true;
    }

    fn remapFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *BudgetAllocator = @ptrCast(@alignCast(ctx));
        const grow_next = if (new_len > mem.len) self.reserveWithRecovery(new_len - mem.len) orelse return null else null;
        const ptr = self.inner.vtable.remap(self.inner.ptr, mem, alignment, new_len, ret_addr) orelse {
            if (new_len > mem.len) self.release(new_len - mem.len);
            return null;
        };
        if (grow_next) |next| self.recordPeak(next);
        if (new_len < mem.len) self.release(mem.len - new_len);
        return ptr;
    }

    fn freeFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *BudgetAllocator = @ptrCast(@alignCast(ctx));
        self.inner.vtable.free(self.inner.ptr, mem, alignment, ret_addr);
        self.release(mem.len);
    }

    const vtable: std.mem.Allocator.VTable = .{
        .alloc = allocFn,
        .resize = resizeFn,
        .remap = remapFn,
        .free = freeFn,
    };

    pub fn allocator(self: *BudgetAllocator) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &vtable };
    }

    pub fn setRecovery(self: *BudgetAllocator, ctx: *anyopaque, f: RecoveryFn) void {
        self.recover_ctx = ctx;
        self.recover_fn = f;
    }

    pub fn stats(self: *const BudgetAllocator) Context.HeapBudgetStats {
        const used = @constCast(self).used.load(.acquire);
        const reserve_state = self.recovery_reserve_state.load(.acquire);
        return .{
            .limit_bytes = self.limit,
            .used_bytes = used,
            .peak_bytes = @constCast(self).peak.load(.acquire),
            .remaining_bytes = self.limit -| used,
            .recovery_reserve_bytes = self.recovery_reserve.len,
            .recovery_reserve_released_bytes = if (reserve_state == 3) self.recovery_reserve.len else 0,
        };
    }
};

/// Opt-in allocator and collection telemetry for causal attribution runs. The
/// wrapper is installed only when `profile_execution_tiers` is requested, so
/// ordinary contexts retain their existing allocator chain and allocate no
/// profiling storage. Their cell and collection boundaries perform only the
/// nullable-sink check measured by the instrumentation-overhead fixture.
/// Backing operations describe calls at the Context allocator boundary;
/// GC-cell operations separately describe logical cell storage issued by the
/// reusable slab allocator, avoiding any false claim that slab growth and cell
/// issuance are the same allocation site.
pub const RuntimeAttributionProfiler = struct {
    pub const max_gc_pause_samples = 4096;

    pub const CellAllocationKind = enum {
        fresh,
        reused,
        relocation,
        delegated,
    };

    pub const CellSlabLockPurpose = enum {
        single_allocation,
        batch_allocation,
        publication,
        unpublication,
        free,
        ownership,
        relocation,
        maintenance,
    };

    pub const CellSlabOwnershipPurpose = enum {
        exact_allocation,
        stable_identity,
        conservative_interior,
        realm_lookup,
        realm_scan,
        allocator_resize,
        allocator_remap,
    };

    pub const AllocationSnapshot = struct {
        backing_allocations: u64 = 0,
        backing_allocation_bytes: u64 = 0,
        backing_growths: u64 = 0,
        backing_growth_bytes: u64 = 0,
        backing_releases: u64 = 0,
        backing_released_bytes: u64 = 0,
        backing_current_bytes: u64 = 0,
        backing_peak_bytes: u64 = 0,
        gc_cell_allocations: u64 = 0,
        gc_cell_bytes: u64 = 0,
        gc_cell_fresh_allocations: u64 = 0,
        gc_cell_reused_allocations: u64 = 0,
        gc_cell_relocation_allocations: u64 = 0,
        gc_cell_delegated_allocations: u64 = 0,
        gc_cell_frees: u64 = 0,
        gc_cell_freed_bytes: u64 = 0,
    };

    pub const CellSlabLockSnapshot = struct {
        acquires: u64 = 0,
        contentions: u64 = 0,
        spins: u64 = 0,
        single_allocation_acquires: u64 = 0,
        batch_allocation_acquires: u64 = 0,
        publication_acquires: u64 = 0,
        unpublication_acquires: u64 = 0,
        free_acquires: u64 = 0,
        ownership_acquires: u64 = 0,
        relocation_acquires: u64 = 0,
        maintenance_acquires: u64 = 0,
        ownership_exact_allocation_acquires: u64 = 0,
        ownership_stable_identity_acquires: u64 = 0,
        ownership_conservative_interior_acquires: u64 = 0,
        ownership_realm_lookup_acquires: u64 = 0,
        ownership_realm_scan_acquires: u64 = 0,
        ownership_allocator_resize_acquires: u64 = 0,
        ownership_allocator_remap_acquires: u64 = 0,
        size_64_acquires: u64 = 0,
        size_64_contentions: u64 = 0,
        size_64_spins: u64 = 0,
        size_128_acquires: u64 = 0,
        size_128_contentions: u64 = 0,
        size_128_spins: u64 = 0,
        size_256_acquires: u64 = 0,
        size_256_contentions: u64 = 0,
        size_256_spins: u64 = 0,
        size_512_acquires: u64 = 0,
        size_512_contentions: u64 = 0,
        size_512_spins: u64 = 0,
        size_1024_acquires: u64 = 0,
        size_1024_contentions: u64 = 0,
        size_1024_spins: u64 = 0,
        size_2048_acquires: u64 = 0,
        size_2048_contentions: u64 = 0,
        size_2048_spins: u64 = 0,
    };

    pub const PauseSamples = struct {
        len: usize = 0,
        overflow: u64 = 0,
        values: [max_gc_pause_samples]u64 = @splat(0),
    };

    pub const Snapshot = struct {
        allocation: AllocationSnapshot = .{},
        cell_slab_lock: CellSlabLockSnapshot = .{},
        minor_pauses: PauseSamples = .{},
        full_pauses: PauseSamples = .{},
    };

    inner: std.mem.Allocator,
    debug_registry: interp.DebugRegistryStats = .{},
    // One profiler event updates several independent counters. Readers must
    // not publish a mixture of the old and new values while allocator or GC
    // writers are active. The active-writer count supports overlapping
    // writers; the epoch detects a complete mutation between the reader's two
    // boundary checks without serializing writers on a profiler lock.
    counter_mutations_active: std.atomic.Value(u64) = .init(0),
    counter_mutation_epoch: std.atomic.Value(u64) = .init(0),
    backing_allocations: std.atomic.Value(u64) = .init(0),
    backing_allocation_bytes: std.atomic.Value(u64) = .init(0),
    backing_growths: std.atomic.Value(u64) = .init(0),
    backing_growth_bytes: std.atomic.Value(u64) = .init(0),
    backing_releases: std.atomic.Value(u64) = .init(0),
    backing_released_bytes: std.atomic.Value(u64) = .init(0),
    backing_current_bytes: std.atomic.Value(u64) = .init(0),
    backing_peak_bytes: std.atomic.Value(u64) = .init(0),
    gc_cell_allocations: std.atomic.Value(u64) = .init(0),
    gc_cell_bytes: std.atomic.Value(u64) = .init(0),
    gc_cell_fresh_allocations: std.atomic.Value(u64) = .init(0),
    gc_cell_reused_allocations: std.atomic.Value(u64) = .init(0),
    gc_cell_relocation_allocations: std.atomic.Value(u64) = .init(0),
    gc_cell_delegated_allocations: std.atomic.Value(u64) = .init(0),
    gc_cell_frees: std.atomic.Value(u64) = .init(0),
    gc_cell_freed_bytes: std.atomic.Value(u64) = .init(0),
    cell_slab_lock_acquires: std.atomic.Value(u64) = .init(0),
    cell_slab_lock_contentions: std.atomic.Value(u64) = .init(0),
    cell_slab_lock_spins: std.atomic.Value(u64) = .init(0),
    cell_slab_lock_purpose_acquires: [8]std.atomic.Value(u64) = .{
        .init(0), .init(0), .init(0), .init(0), .init(0), .init(0), .init(0), .init(0),
    },
    cell_slab_ownership_purpose_acquires: [7]std.atomic.Value(u64) = .{
        .init(0), .init(0), .init(0), .init(0), .init(0), .init(0), .init(0),
    },
    cell_slab_lock_size_acquires: [6]std.atomic.Value(u64) = .{
        .init(0), .init(0), .init(0), .init(0), .init(0), .init(0),
    },
    cell_slab_lock_size_contentions: [6]std.atomic.Value(u64) = .{
        .init(0), .init(0), .init(0), .init(0), .init(0), .init(0),
    },
    cell_slab_lock_size_spins: [6]std.atomic.Value(u64) = .{
        .init(0), .init(0), .init(0), .init(0), .init(0), .init(0),
    },
    gc_cycle_started_ns: std.atomic.Value(u64) = .init(0),
    pause_lock: std.atomic.Mutex = .unlocked,
    minor_pause_len: usize = 0,
    minor_pause_overflow: u64 = 0,
    minor_pause_ns: [max_gc_pause_samples]u64 = @splat(0),
    full_pause_len: usize = 0,
    full_pause_overflow: u64 = 0,
    full_pause_ns: [max_gc_pause_samples]u64 = @splat(0),

    fn beginCounterMutation(self: *RuntimeAttributionProfiler) void {
        const previous = self.counter_mutations_active.fetchAdd(1, .acq_rel);
        std.debug.assert(previous != std.math.maxInt(u64));
    }

    fn finishCounterMutation(self: *RuntimeAttributionProfiler) void {
        _ = self.counter_mutation_epoch.fetchAdd(1, .release);
        const previous = self.counter_mutations_active.fetchSub(1, .acq_rel);
        std.debug.assert(previous != 0);
    }

    fn recordPeak(self: *RuntimeAttributionProfiler, current: u64) void {
        var peak = self.backing_peak_bytes.load(.monotonic);
        while (current > peak) {
            if (self.backing_peak_bytes.cmpxchgWeak(peak, current, .monotonic, .monotonic)) |observed| {
                peak = observed;
                continue;
            }
            return;
        }
    }

    fn recordBackingAllocation(self: *RuntimeAttributionProfiler, bytes: usize) void {
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        _ = self.backing_allocations.fetchAdd(1, .monotonic);
        _ = self.backing_allocation_bytes.fetchAdd(@intCast(bytes), .monotonic);
        const previous = self.backing_current_bytes.fetchAdd(@intCast(bytes), .monotonic);
        self.recordPeak(previous +| @as(u64, @intCast(bytes)));
    }

    fn recordBackingGrowth(self: *RuntimeAttributionProfiler, bytes: usize) void {
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        _ = self.backing_growths.fetchAdd(1, .monotonic);
        _ = self.backing_growth_bytes.fetchAdd(@intCast(bytes), .monotonic);
        const previous = self.backing_current_bytes.fetchAdd(@intCast(bytes), .monotonic);
        self.recordPeak(previous +| @as(u64, @intCast(bytes)));
    }

    fn recordBackingRelease(self: *RuntimeAttributionProfiler, bytes: usize) void {
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        _ = self.backing_releases.fetchAdd(1, .monotonic);
        _ = self.backing_released_bytes.fetchAdd(@intCast(bytes), .monotonic);
        _ = self.backing_current_bytes.fetchSub(@intCast(bytes), .monotonic);
    }

    pub fn recordCellAllocation(self: *RuntimeAttributionProfiler, bytes: usize, kind: CellAllocationKind) void {
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        _ = self.gc_cell_allocations.fetchAdd(1, .monotonic);
        _ = self.gc_cell_bytes.fetchAdd(@intCast(bytes), .monotonic);
        switch (kind) {
            .fresh => _ = self.gc_cell_fresh_allocations.fetchAdd(1, .monotonic),
            .reused => _ = self.gc_cell_reused_allocations.fetchAdd(1, .monotonic),
            .relocation => _ = self.gc_cell_relocation_allocations.fetchAdd(1, .monotonic),
            .delegated => _ = self.gc_cell_delegated_allocations.fetchAdd(1, .monotonic),
        }
    }

    pub fn recordCellAllocationBatch(
        self: *RuntimeAttributionProfiler,
        bytes_per_cell: usize,
        fresh: usize,
        reused: usize,
    ) void {
        const total = std.math.add(usize, fresh, reused) catch @panic("cell allocation attribution count overflow");
        if (total == 0) return;
        const total_bytes = std.math.mul(u64, @intCast(bytes_per_cell), @intCast(total)) catch
            @panic("cell allocation attribution byte overflow");
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        _ = self.gc_cell_allocations.fetchAdd(@intCast(total), .monotonic);
        _ = self.gc_cell_bytes.fetchAdd(total_bytes, .monotonic);
        _ = self.gc_cell_fresh_allocations.fetchAdd(@intCast(fresh), .monotonic);
        _ = self.gc_cell_reused_allocations.fetchAdd(@intCast(reused), .monotonic);
    }

    pub fn recordCellResize(self: *RuntimeAttributionProfiler, old_len: usize, new_len: usize) void {
        if (old_len == new_len) return;
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        if (new_len > old_len)
            _ = self.gc_cell_bytes.fetchAdd(@intCast(new_len - old_len), .monotonic)
        else
            _ = self.gc_cell_freed_bytes.fetchAdd(@intCast(old_len - new_len), .monotonic);
    }

    pub fn recordCellFree(self: *RuntimeAttributionProfiler, bytes: usize) void {
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        _ = self.gc_cell_frees.fetchAdd(1, .monotonic);
        _ = self.gc_cell_freed_bytes.fetchAdd(@intCast(bytes), .monotonic);
    }

    fn recordCellSlabLockAttempt(
        self: *RuntimeAttributionProfiler,
        bucket_idx: usize,
        purpose: CellSlabLockPurpose,
    ) void {
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        std.debug.assert(bucket_idx < self.cell_slab_lock_size_acquires.len);
        _ = self.cell_slab_lock_acquires.fetchAdd(1, .monotonic);
        _ = self.cell_slab_lock_purpose_acquires[@backingInt(purpose)].fetchAdd(1, .monotonic);
        _ = self.cell_slab_lock_size_acquires[bucket_idx].fetchAdd(1, .monotonic);
    }

    fn recordCellSlabLockContention(self: *RuntimeAttributionProfiler, bucket_idx: usize, spins: u64) void {
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        std.debug.assert(bucket_idx < self.cell_slab_lock_size_contentions.len);
        std.debug.assert(spins != 0);
        _ = self.cell_slab_lock_contentions.fetchAdd(1, .monotonic);
        _ = self.cell_slab_lock_size_contentions[bucket_idx].fetchAdd(1, .monotonic);
        _ = self.cell_slab_lock_spins.fetchAdd(spins, .monotonic);
        _ = self.cell_slab_lock_size_spins[bucket_idx].fetchAdd(spins, .monotonic);
    }

    fn recordCellSlabOwnershipAttempt(self: *RuntimeAttributionProfiler, purpose: CellSlabOwnershipPurpose) void {
        self.beginCounterMutation();
        defer self.finishCounterMutation();
        _ = self.cell_slab_ownership_purpose_acquires[@backingInt(purpose)].fetchAdd(1, .monotonic);
    }

    fn cellSlabLockSnapshot(self: *RuntimeAttributionProfiler) CellSlabLockSnapshot {
        const purpose = &self.cell_slab_lock_purpose_acquires;
        const ownership = &self.cell_slab_ownership_purpose_acquires;
        const acquires = &self.cell_slab_lock_size_acquires;
        const contentions = &self.cell_slab_lock_size_contentions;
        const spins = &self.cell_slab_lock_size_spins;
        return .{
            .acquires = self.cell_slab_lock_acquires.load(.acquire),
            .contentions = self.cell_slab_lock_contentions.load(.acquire),
            .spins = self.cell_slab_lock_spins.load(.acquire),
            .single_allocation_acquires = purpose[@backingInt(CellSlabLockPurpose.single_allocation)].load(.acquire),
            .batch_allocation_acquires = purpose[@backingInt(CellSlabLockPurpose.batch_allocation)].load(.acquire),
            .publication_acquires = purpose[@backingInt(CellSlabLockPurpose.publication)].load(.acquire),
            .unpublication_acquires = purpose[@backingInt(CellSlabLockPurpose.unpublication)].load(.acquire),
            .free_acquires = purpose[@backingInt(CellSlabLockPurpose.free)].load(.acquire),
            .ownership_acquires = purpose[@backingInt(CellSlabLockPurpose.ownership)].load(.acquire),
            .relocation_acquires = purpose[@backingInt(CellSlabLockPurpose.relocation)].load(.acquire),
            .maintenance_acquires = purpose[@backingInt(CellSlabLockPurpose.maintenance)].load(.acquire),
            .ownership_exact_allocation_acquires = ownership[@backingInt(CellSlabOwnershipPurpose.exact_allocation)].load(.acquire),
            .ownership_stable_identity_acquires = ownership[@backingInt(CellSlabOwnershipPurpose.stable_identity)].load(.acquire),
            .ownership_conservative_interior_acquires = ownership[@backingInt(CellSlabOwnershipPurpose.conservative_interior)].load(.acquire),
            .ownership_realm_lookup_acquires = ownership[@backingInt(CellSlabOwnershipPurpose.realm_lookup)].load(.acquire),
            .ownership_realm_scan_acquires = ownership[@backingInt(CellSlabOwnershipPurpose.realm_scan)].load(.acquire),
            .ownership_allocator_resize_acquires = ownership[@backingInt(CellSlabOwnershipPurpose.allocator_resize)].load(.acquire),
            .ownership_allocator_remap_acquires = ownership[@backingInt(CellSlabOwnershipPurpose.allocator_remap)].load(.acquire),
            .size_64_acquires = acquires[0].load(.acquire),
            .size_64_contentions = contentions[0].load(.acquire),
            .size_64_spins = spins[0].load(.acquire),
            .size_128_acquires = acquires[1].load(.acquire),
            .size_128_contentions = contentions[1].load(.acquire),
            .size_128_spins = spins[1].load(.acquire),
            .size_256_acquires = acquires[2].load(.acquire),
            .size_256_contentions = contentions[2].load(.acquire),
            .size_256_spins = spins[2].load(.acquire),
            .size_512_acquires = acquires[3].load(.acquire),
            .size_512_contentions = contentions[3].load(.acquire),
            .size_512_spins = spins[3].load(.acquire),
            .size_1024_acquires = acquires[4].load(.acquire),
            .size_1024_contentions = contentions[4].load(.acquire),
            .size_1024_spins = spins[4].load(.acquire),
            .size_2048_acquires = acquires[5].load(.acquire),
            .size_2048_contentions = contentions[5].load(.acquire),
            .size_2048_spins = spins[5].load(.acquire),
        };
    }

    fn lockPauses(self: *RuntimeAttributionProfiler) void {
        var spins: usize = 0;
        while (!self.pause_lock.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
    }

    pub fn beginGcCycle(self: *RuntimeAttributionProfiler, started_ns: u64) void {
        self.gc_cycle_started_ns.store(started_ns, .release);
    }

    pub fn finishGcCycle(self: *RuntimeAttributionProfiler, full: bool, finished_ns: u64) void {
        const started_ns = self.gc_cycle_started_ns.swap(0, .acq_rel);
        if (started_ns == 0) return;
        const elapsed = finished_ns -| started_ns;
        self.lockPauses();
        defer self.pause_lock.unlock();
        if (full) {
            if (self.full_pause_len == self.full_pause_ns.len) {
                self.full_pause_overflow += 1;
                return;
            }
            self.full_pause_ns[self.full_pause_len] = elapsed;
            self.full_pause_len += 1;
        } else {
            if (self.minor_pause_len == self.minor_pause_ns.len) {
                self.minor_pause_overflow += 1;
                return;
            }
            self.minor_pause_ns[self.minor_pause_len] = elapsed;
            self.minor_pause_len += 1;
        }
    }

    fn tryCounterSnapshot(self: *RuntimeAttributionProfiler) ?Snapshot {
        if (self.counter_mutations_active.load(.acquire) != 0) return null;
        const before = self.counter_mutation_epoch.load(.acquire);
        const out = Snapshot{
            .allocation = .{
                .backing_allocations = self.backing_allocations.load(.acquire),
                .backing_allocation_bytes = self.backing_allocation_bytes.load(.acquire),
                .backing_growths = self.backing_growths.load(.acquire),
                .backing_growth_bytes = self.backing_growth_bytes.load(.acquire),
                .backing_releases = self.backing_releases.load(.acquire),
                .backing_released_bytes = self.backing_released_bytes.load(.acquire),
                .backing_current_bytes = self.backing_current_bytes.load(.acquire),
                .backing_peak_bytes = self.backing_peak_bytes.load(.acquire),
                .gc_cell_allocations = self.gc_cell_allocations.load(.acquire),
                .gc_cell_bytes = self.gc_cell_bytes.load(.acquire),
                .gc_cell_fresh_allocations = self.gc_cell_fresh_allocations.load(.acquire),
                .gc_cell_reused_allocations = self.gc_cell_reused_allocations.load(.acquire),
                .gc_cell_relocation_allocations = self.gc_cell_relocation_allocations.load(.acquire),
                .gc_cell_delegated_allocations = self.gc_cell_delegated_allocations.load(.acquire),
                .gc_cell_frees = self.gc_cell_frees.load(.acquire),
                .gc_cell_freed_bytes = self.gc_cell_freed_bytes.load(.acquire),
            },
            .cell_slab_lock = self.cellSlabLockSnapshot(),
        };

        // Check the active count before the closing epoch. If a writer ends
        // between those reads, its release of the active count happens-before
        // the epoch load and the changed epoch rejects this attempt. A writer
        // that starts after the active-count check is ordered after the
        // snapshot and cannot invalidate the values already read.
        if (self.counter_mutations_active.load(.acquire) != 0) return null;
        if (self.counter_mutation_epoch.load(.acquire) != before) return null;
        return out;
    }

    pub fn snapshot(self: *RuntimeAttributionProfiler) Snapshot {
        var spins: usize = 0;
        var out: Snapshot = undefined;
        while (true) : (spins += 1) {
            if (self.tryCounterSnapshot()) |counter_snapshot| {
                out = counter_snapshot;
                break;
            }
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
        self.lockPauses();
        defer self.pause_lock.unlock();
        out.minor_pauses.len = self.minor_pause_len;
        out.minor_pauses.overflow = self.minor_pause_overflow;
        @memcpy(out.minor_pauses.values[0..self.minor_pause_len], self.minor_pause_ns[0..self.minor_pause_len]);
        out.full_pauses.len = self.full_pause_len;
        out.full_pauses.overflow = self.full_pause_overflow;
        @memcpy(out.full_pauses.values[0..self.full_pause_len], self.full_pause_ns[0..self.full_pause_len]);
        return out;
    }

    fn allocFn(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *RuntimeAttributionProfiler = @ptrCast(@alignCast(ctx));
        const ptr = self.inner.vtable.alloc(self.inner.ptr, len, alignment, ret_addr) orelse return null;
        self.recordBackingAllocation(len);
        return ptr;
    }

    fn resizeFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *RuntimeAttributionProfiler = @ptrCast(@alignCast(ctx));
        if (!self.inner.vtable.resize(self.inner.ptr, mem, alignment, new_len, ret_addr)) return false;
        if (new_len > mem.len)
            self.recordBackingGrowth(new_len - mem.len)
        else if (new_len < mem.len)
            self.recordBackingRelease(mem.len - new_len);
        return true;
    }

    fn remapFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *RuntimeAttributionProfiler = @ptrCast(@alignCast(ctx));
        const ptr = self.inner.vtable.remap(self.inner.ptr, mem, alignment, new_len, ret_addr) orelse return null;
        if (new_len > mem.len)
            self.recordBackingGrowth(new_len - mem.len)
        else if (new_len < mem.len)
            self.recordBackingRelease(mem.len - new_len);
        return ptr;
    }

    fn freeFn(ctx: *anyopaque, mem: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *RuntimeAttributionProfiler = @ptrCast(@alignCast(ctx));
        self.inner.vtable.free(self.inner.ptr, mem, alignment, ret_addr);
        self.recordBackingRelease(mem.len);
    }

    const vtable: std.mem.Allocator.VTable = .{
        .alloc = allocFn,
        .resize = resizeFn,
        .remap = remapFn,
        .free = freeFn,
    };

    pub fn allocator(self: *RuntimeAttributionProfiler) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &vtable };
    }
};

test "RuntimeAttributionProfiler records exact backing, cell, and pause samples" {
    var profile = RuntimeAttributionProfiler{ .inner = std.testing.allocator };
    const allocator = profile.allocator();
    const memory = try allocator.alloc(u8, 48);
    profile.recordCellAllocation(96, .fresh);
    profile.recordCellAllocation(112, .reused);
    profile.recordCellAllocation(128, .relocation);
    profile.recordCellAllocation(144, .delegated);
    profile.recordCellFree(96);
    profile.recordCellSlabLockAttempt(2, .single_allocation);
    profile.recordCellSlabLockContention(2, 3);
    profile.recordCellSlabLockAttempt(0, .free);
    profile.recordCellSlabOwnershipAttempt(.exact_allocation);
    profile.recordCellSlabLockAttempt(1, .ownership);
    profile.beginGcCycle(100);
    profile.finishGcCycle(false, 175);
    profile.beginGcCycle(200);
    profile.finishGcCycle(true, 325);

    const before_free = profile.snapshot();
    try std.testing.expectEqual(@as(u64, 1), before_free.allocation.backing_allocations);
    try std.testing.expectEqual(@as(u64, 48), before_free.allocation.backing_allocation_bytes);
    try std.testing.expectEqual(@as(u64, 48), before_free.allocation.backing_current_bytes);
    try std.testing.expectEqual(@as(u64, 4), before_free.allocation.gc_cell_allocations);
    try std.testing.expectEqual(@as(u64, 480), before_free.allocation.gc_cell_bytes);
    try std.testing.expectEqual(@as(u64, 3), before_free.cell_slab_lock.acquires);
    try std.testing.expectEqual(@as(u64, 1), before_free.cell_slab_lock.contentions);
    try std.testing.expectEqual(@as(u64, 3), before_free.cell_slab_lock.spins);
    try std.testing.expectEqual(@as(u64, 1), before_free.cell_slab_lock.single_allocation_acquires);
    try std.testing.expectEqual(@as(u64, 1), before_free.cell_slab_lock.free_acquires);
    try std.testing.expectEqual(@as(u64, 1), before_free.cell_slab_lock.ownership_acquires);
    try std.testing.expectEqual(@as(u64, 1), before_free.cell_slab_lock.ownership_exact_allocation_acquires);
    try std.testing.expectEqual(@as(u64, 1), before_free.cell_slab_lock.size_64_acquires);
    try std.testing.expectEqual(@as(u64, 1), before_free.cell_slab_lock.size_128_acquires);
    try std.testing.expectEqual(@as(u64, 1), before_free.cell_slab_lock.size_256_contentions);
    try std.testing.expectEqual(@as(usize, 1), before_free.minor_pauses.len);
    try std.testing.expectEqual(@as(u64, 75), before_free.minor_pauses.values[0]);
    try std.testing.expectEqual(@as(usize, 1), before_free.full_pauses.len);
    try std.testing.expectEqual(@as(u64, 125), before_free.full_pauses.values[0]);
    try std.testing.expectEqual(@as(u64, 0), profile.counter_mutations_active.load(.acquire));
    try std.testing.expectEqual(@as(u64, 11), profile.counter_mutation_epoch.load(.acquire));

    allocator.free(memory);
    const after_free = profile.snapshot();
    try std.testing.expectEqual(@as(u64, 1), after_free.allocation.backing_releases);
    try std.testing.expectEqual(@as(u64, 48), after_free.allocation.backing_released_bytes);
    try std.testing.expectEqual(@as(u64, 0), after_free.allocation.backing_current_bytes);
    try std.testing.expectEqual(@as(u64, 12), profile.counter_mutation_epoch.load(.acquire));
}

test "RuntimeAttributionProfiler rejects snapshots across concurrent partial mutations" {
    var profile = RuntimeAttributionProfiler{ .inner = std.testing.allocator };
    var first_started = std.atomic.Value(bool).init(false);
    var second_started = std.atomic.Value(bool).init(false);
    var release_first = std.atomic.Value(bool).init(false);
    var release_second = std.atomic.Value(bool).init(false);

    const Writer = struct {
        profile: *RuntimeAttributionProfiler,
        bytes: u64,
        started: *std.atomic.Value(bool),
        release: *std.atomic.Value(bool),

        fn run(self: @This()) void {
            self.profile.beginCounterMutation();
            _ = self.profile.backing_allocations.fetchAdd(1, .monotonic);
            self.started.store(true, .release);
            while (!self.release.load(.acquire)) std.atomic.spinLoopHint();
            _ = self.profile.backing_allocation_bytes.fetchAdd(self.bytes, .monotonic);
            const previous = self.profile.backing_current_bytes.fetchAdd(self.bytes, .monotonic);
            self.profile.recordPeak(previous +| self.bytes);
            self.profile.finishCounterMutation();
        }
    };

    var first = try std.Thread.spawn(.{}, Writer.run, .{Writer{
        .profile = &profile,
        .bytes = 48,
        .started = &first_started,
        .release = &release_first,
    }});
    var first_joined = false;
    defer {
        release_first.store(true, .release);
        if (!first_joined) first.join();
    }
    var second = try std.Thread.spawn(.{}, Writer.run, .{Writer{
        .profile = &profile,
        .bytes = 80,
        .started = &second_started,
        .release = &release_second,
    }});
    var second_joined = false;
    defer {
        release_second.store(true, .release);
        if (!second_joined) second.join();
    }

    while (!first_started.load(.acquire) or !second_started.load(.acquire)) std.atomic.spinLoopHint();
    try std.testing.expectEqual(@as(u64, 2), profile.counter_mutations_active.load(.acquire));
    try std.testing.expect(profile.tryCounterSnapshot() == null);

    release_first.store(true, .release);
    first.join();
    first_joined = true;
    try std.testing.expectEqual(@as(u64, 1), profile.counter_mutations_active.load(.acquire));
    try std.testing.expect(profile.tryCounterSnapshot() == null);

    release_second.store(true, .release);
    second.join();
    second_joined = true;
    const snapshot = profile.snapshot();
    try std.testing.expectEqual(@as(u64, 0), profile.counter_mutations_active.load(.acquire));
    try std.testing.expectEqual(@as(u64, 2), profile.counter_mutation_epoch.load(.acquire));
    try std.testing.expectEqual(@as(u64, 2), snapshot.allocation.backing_allocations);
    try std.testing.expectEqual(@as(u64, 128), snapshot.allocation.backing_allocation_bytes);
    try std.testing.expectEqual(@as(u64, 128), snapshot.allocation.backing_current_bytes);
    try std.testing.expectEqual(@as(u64, 128), snapshot.allocation.backing_peak_bytes);
}

test "BudgetAllocator enforces outstanding byte limit" {
    var budget = BudgetAllocator{ .inner = std.testing.allocator, .limit = 64 };
    const a = budget.allocator();

    const first = try a.alloc(u8, 48);
    try std.testing.expectEqual(@as(usize, 48), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 48), budget.peak.load(.acquire));
    try std.testing.expectError(error.OutOfMemory, a.alloc(u8, 17));
    try std.testing.expectEqual(@as(usize, 48), budget.peak.load(.acquire));

    a.free(first);
    try std.testing.expectEqual(@as(usize, 0), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 48), budget.peak.load(.acquire));

    const second = try a.alloc(u8, 64);
    try std.testing.expectEqual(@as(usize, 64), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 64), budget.peak.load(.acquire));
    try std.testing.expectError(error.OutOfMemory, a.alloc(u8, 1));
    a.free(second);
    try std.testing.expectEqual(@as(usize, 0), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 64), budget.peak.load(.acquire));
}

test "BudgetAllocator accounts resize growth and shrink" {
    var buf: [256]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&buf);
    var budget = BudgetAllocator{ .inner = fba.allocator(), .limit = 96 };
    const a = budget.allocator();

    var mem = try a.alloc(u8, 32);
    try std.testing.expectEqual(@as(usize, 32), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 32), budget.peak.load(.acquire));

    try std.testing.expect(a.resize(mem, 48));
    mem = mem.ptr[0..48];
    try std.testing.expectEqual(@as(usize, 48), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 48), budget.peak.load(.acquire));

    try std.testing.expect(!a.resize(mem, 128));
    try std.testing.expectEqual(@as(usize, 48), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 48), budget.peak.load(.acquire));

    try std.testing.expect(a.resize(mem, 16));
    mem = mem.ptr[0..16];
    try std.testing.expectEqual(@as(usize, 16), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 48), budget.peak.load(.acquire));

    a.free(mem);
    try std.testing.expectEqual(@as(usize, 0), budget.used.load(.acquire));
}

test "BudgetAllocator accounts remap growth and shrink" {
    var buf: [256]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&buf);
    var budget = BudgetAllocator{ .inner = fba.allocator(), .limit = 96 };
    const a = budget.allocator();

    var mem = try a.alloc(u8, 24);
    try std.testing.expectEqual(@as(usize, 24), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 24), budget.peak.load(.acquire));

    mem = a.remap(mem, 64) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 64), mem.len);
    try std.testing.expectEqual(@as(usize, 64), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 64), budget.peak.load(.acquire));

    try std.testing.expect(a.remap(mem, 128) == null);
    try std.testing.expectEqual(@as(usize, 64), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 64), budget.peak.load(.acquire));

    mem = a.remap(mem, 8) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 8), mem.len);
    try std.testing.expectEqual(@as(usize, 8), budget.used.load(.acquire));
    try std.testing.expectEqual(@as(usize, 64), budget.peak.load(.acquire));

    a.free(mem);
