    /// The engine's precise-GC heap type and its root-tracing binding (issue #1
    /// Phase 7). Held by pointer so addresses are stable; `null` costs nothing
    /// when the GC is off.
    pub const GcHeap = @import("gc.zig").Heap;
    pub const GcBinding = @import("gc.zig").Binding;
    pub const CApiHandle = struct {
        ref: *anyopaque,
        count: usize,
    };
    const ProtectedValueRecord = struct {
        owner: *Context,
        value: value.Value,
    };

    pub const ProtectedValue = opaque {
        fn record(self: *const ProtectedValue) *const ProtectedValueRecord {
            return @ptrCast(@alignCast(self));
        }

        /// Read the current payload only outside a compaction call. Copies of
        /// the returned Value are raw and must not cross the next movement.
        pub fn get(self: *const ProtectedValue) value.Value {
            const protected = self.record();
            protected.owner.assertOwnerThread();
            std.debug.assert(!protected.owner.gc_relocation_active.load(.acquire));
            return protected.value;
        }
    };
    /// Stable storage embedded in a private strong-reference handle. The C ABI
    /// owns the wrapper; the Context owns only this root-list entry.
    pub const PrivateStrongRoot = struct {
        value: value.Value,
    };
    pub const BunTimerTimespec = extern struct {
        sec: i64,
        nsec: i64,
    };
    pub const BunTimerState = enum(u8) {
        pending = 0,
        active = 1,
        cancelled = 2,
        fired = 3,
    };
    pub const BunTimerTag = enum(u8) {
        abort_signal_timeout = 17,
        _,
    };
    pub const BunTimerInHeap = enum(u8) {
        none = 0,
        regular = 1,
        fake = 2,
    };
    pub const BunTimerIntrusiveField = extern struct {
        child: ?*BunEventLoopTimer = null,
        prev: ?*BunEventLoopTimer = null,
        next: ?*BunEventLoopTimer = null,
    };
    /// Prefix-compatible with the pinned Bun EventLoopTimer. Bun treats the
    /// surrounding Timeout as private Rust/Zig layout but directly reads this
    /// `next`/`state` prefix in spawnSync's best-effort deadline path.
    pub const BunEventLoopTimer = extern struct {
        next: BunTimerTimespec,
        heap: BunTimerIntrusiveField = .{},
        state: BunTimerState,
        tag: BunTimerTag,
        in_heap: BunTimerInHeap = .none,
    };
    /// Exact four-field Timeout contract declared by the pinned Bun profile.
    /// Scheduler-only metadata lives in AbortSignalOwner so these offsets do
    /// not drift when zig-js adds lifecycle bookkeeping.
    pub const AbortSignalTimeout = extern struct {
        event_loop_timer: BunEventLoopTimer,
        signal: ?*anyopaque,
        flags: u32 = 1 << 30,
        generation: u32,
    };
    comptime {
        if (@sizeOf(usize) == 8) {
            std.debug.assert(@sizeOf(BunEventLoopTimer) == 48);
            std.debug.assert(@offsetOf(BunEventLoopTimer, "next") == 0);
            std.debug.assert(@offsetOf(BunEventLoopTimer, "heap") == 16);
            std.debug.assert(@offsetOf(BunEventLoopTimer, "state") == 40);
            std.debug.assert(@offsetOf(BunEventLoopTimer, "tag") == 41);
            std.debug.assert(@offsetOf(BunEventLoopTimer, "in_heap") == 42);
            std.debug.assert(@sizeOf(AbortSignalTimeout) == 64);
            std.debug.assert(@offsetOf(AbortSignalTimeout, "event_loop_timer") == 0);
            std.debug.assert(@offsetOf(AbortSignalTimeout, "signal") == 48);
            std.debug.assert(@offsetOf(AbortSignalTimeout, "flags") == 56);
            std.debug.assert(@offsetOf(AbortSignalTimeout, "generation") == 60);
        }
    }
    pub const AbortSignalOwner = struct {
        context: *Context,
        object: *value.Object,
        native: value.AbortSignalNativeState = .{},
        root: PrivateStrongRoot,
        timeout: ?*AbortSignalTimeout = null,
        deadline_ns: u64 = 0,
        js_observed: bool = false,
        native_observed: bool = false,
        rooted: bool = false,
    };
    pub const TimerRecord = struct {
        id: u64,
        owner: *promise.MicrotaskQueue,
        callback: value.Value,
        args: []value.Value,
        delay_ns: u64,
        deadline_ns: u64,
        sequence: u64,
        repeat: bool,
        refed: bool = true,
        running: bool = false,
        cancelled: bool = false,
        refresh_requested: bool = false,
    };
    pub const PrivateWeakFinalizeFn = *const fn (?*anyopaque) callconv(.c) void;
    /// Stable storage embedded in a private weak-reference handle. Atomic
    /// clearing lets the collector race safely with embedder `get`/`clear`.
    pub const PrivateWeakRoot = struct {
        target: std.atomic.Value(?*anyopaque) = .init(null),
        notify_on_collect: std.atomic.Value(bool) = .init(false),
        finalize_fn: ?PrivateWeakFinalizeFn = null,
        finalize_context: ?*anyopaque = null,
    };
    /// One precise heap has one immutable owner plus zero or more registered
    /// sibling realms. The registry is embedded beside the heap so root walks
    /// never depend on a realm that may already be retiring. #420 adds the
    /// sibling creation/retirement operations; the owner-only state here keeps
    /// standalone precise contexts behaviorally unchanged.
    pub const GcRealmRegistry = struct {
        owner: *Context,
        lock: std.atomic.Mutex = .unlocked,
        siblings: std.ArrayListUnmanaged(*Context) = .empty,
        /// Retired realms no longer contribute roots, but remain addressable by
        /// stable cell ownership until their final cell and deferred callback
        /// have drained. #419 performs the final release/destruction phase.
        retiring: std.ArrayListUnmanaged(*Context) = .empty,
        /// Partially initialized realms own attributed cells but do not yet
        /// contribute roots or qualify for allocation-recovery collection.
        /// Bootstrap is collection-free; on failure the caller collects those
        /// cells while this callback-routing tombstone remains registered.
        bootstrapping: std.ArrayListUnmanaged(*Context) = .empty,
        next_realm_id: GcCellBacking.RealmId = GcCellBacking.owner_realm + 1,
        /// Once any non-owner realm can own heap cells, collector callbacks
        /// must route by the stable per-cell realm ID forever. Owner-only heaps
        /// keep this false and avoid two metadata locks per finalized cell.
        cell_routing_required: std.atomic.Value(bool) = .init(false),

        pub fn requiresCellRouting(self: *const GcRealmRegistry) bool {
            return self.cell_routing_required.load(.acquire);
        }

        pub fn acquire(self: *GcRealmRegistry) void {
            var spins: usize = 0;
            while (!self.lock.tryLock()) : (spins += 1) {
                if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
            }
            // Binding.traceRoots/relocateRoots take this lock. Registry growth
            // must therefore fail closed instead of recovering allocation by
            // collecting back into the same lock.
            gc_runtime.enterTraceSensitiveLock();
        }

        pub fn release(self: *GcRealmRegistry) void {
            gc_runtime.leaveTraceSensitiveLock();
            self.lock.unlock();
        }

        /// Publish a completely initialized sibling as a root source. The
        /// caller owns bootstrap failure cleanup and must not expose or execute
        /// the realm before this succeeds.
        pub fn registerBootstrapped(
            self: *GcRealmRegistry,
            allocator: std.mem.Allocator,
            realm: *Context,
        ) !void {
            if (realm == self.owner) return error.OwnerCannotBeSibling;
            if (realm.gc != self.owner.gc or realm.gc_state != self.owner.gc_state)
                return error.ForeignPreciseHeap;
            // Publish before registration can expose the realm. False positives
            // after a later validation/allocation failure are safe; reverting
            // to the owner-only path after attributed cells existed is not.
            self.cell_routing_required.store(true, .release);
            self.acquire();
            defer self.release();
            for (self.siblings.items) |registered|
                if (registered == realm) return error.RealmAlreadyRegistered;
            try self.siblings.ensureUnusedCapacity(allocator, 1);
            if (realm.gc_realm_id == GcCellBacking.no_realm) {
                if (self.next_realm_id == GcCellBacking.no_realm)
                    return error.RealmIdentityExhausted;
                realm.gc_realm_id = self.next_realm_id;
                self.next_realm_id +%= 1;
            } else {
                var bootstrap_index: ?usize = null;
                for (self.bootstrapping.items, 0..) |candidate, index| {
                    if (candidate == realm) bootstrap_index = index;
                }
                const index = bootstrap_index orelse return error.RealmIdentityAlreadyAssigned;
                _ = self.bootstrapping.orderedRemove(index);
            }
            self.siblings.appendAssumeCapacity(realm);
        }

        /// Reserve a stable identity before the first precise cell is created.
        /// Bootstrapping realms are callback-addressable but deliberately not
        /// traced as roots until `registerBootstrapped` publishes completion.
        pub fn beginBootstrap(self: *GcRealmRegistry, allocator: std.mem.Allocator, realm: *Context) !void {
            if (realm == self.owner) return error.OwnerCannotBeSibling;
            if (realm.gc != self.owner.gc or realm.gc_state != self.owner.gc_state)
                return error.ForeignPreciseHeap;
            self.cell_routing_required.store(true, .release);
            self.acquire();
            defer self.release();
            if (realm.gc_realm_id != GcCellBacking.no_realm)
                return error.RealmIdentityAlreadyAssigned;
            if (self.next_realm_id == GcCellBacking.no_realm)
                return error.RealmIdentityExhausted;
            try self.bootstrapping.ensureUnusedCapacity(allocator, 1);
            realm.gc_realm_id = self.next_realm_id;
            self.next_realm_id +%= 1;
            self.bootstrapping.appendAssumeCapacity(realm);
        }

        pub fn releaseFailedBootstrap(self: *GcRealmRegistry, realm: *Context) !void {
            if (self.owner.gc_cell_backing) |backing|
                if (backing.hasRealmCells(realm.gc_realm_id)) return error.RealmCellsRemain;
            self.acquire();
            defer self.release();
            for (self.bootstrapping.items, 0..) |candidate, index| {
                if (candidate != realm) continue;
                _ = self.bootstrapping.orderedRemove(index);
                return;
            }
            return error.RealmBootstrapNotRegistered;
        }

        /// Remove one stopped sibling from the root set. Dropping realm-owned
        /// cell/storage state is a later phase: callers must first make every
        /// execution and host-job source quiescent, and keep the Context alive
        /// until collection/finalization has consumed its cells.
        pub fn retireQuiescent(self: *GcRealmRegistry, realm: *Context) !void {
            if (realm == self.owner) return error.OwnerCannotRetire;
            if (!realm.preciseRealmIsQuiescent()) return error.RealmNotQuiescent;
            self.acquire();
            defer self.release();
            for (self.siblings.items, 0..) |registered, index| {
                if (registered != realm) continue;
                try self.retiring.ensureUnusedCapacity(self.owner.gpa, 1);
                _ = self.siblings.orderedRemove(index);
                self.retiring.appendAssumeCapacity(realm);
                return;
            }
            return error.RealmNotRegistered;
        }

        /// Complete retirement only after collection has finalized and freed
        /// every cell attributed to the realm. This prevents stale callback
        /// routing while allowing the live root list to stop retaining it.
        pub fn releaseRetired(self: *GcRealmRegistry, realm: *Context) !void {
            if (!realm.preciseRealmIsQuiescent()) return error.RealmNotQuiescent;
            if (self.owner.gc_cell_backing) |backing|
                if (backing.hasRealmCells(realm.gc_realm_id)) return error.RealmCellsRemain;
            self.acquire();
            defer self.release();
            for (self.retiring.items, 0..) |registered, index| {
                if (registered != realm) continue;
                _ = self.retiring.orderedRemove(index);
                return;
            }
            return error.RealmNotRetiring;
        }

        /// Resolve a live or retiring realm without retaining the registry
        /// lock across collector/embedder work. Callers rely on the retirement
        /// contract above to keep the Context allocation alive until release.
        pub fn realmForId(self: *GcRealmRegistry, realm_id: GcCellBacking.RealmId) ?*Context {
            if (realm_id == GcCellBacking.no_realm) return null;
            self.acquire();
            defer self.release();
            if (realm_id == self.owner.gc_realm_id) return self.owner;
            for (self.siblings.items) |realm| if (realm.gc_realm_id == realm_id) return realm;
            for (self.retiring.items) |realm| if (realm.gc_realm_id == realm_id) return realm;
            for (self.bootstrapping.items) |realm| if (realm.gc_realm_id == realm_id) return realm;
            return null;
        }

        pub fn liveRealmForId(self: *GcRealmRegistry, realm_id: GcCellBacking.RealmId) ?*Context {
            if (realm_id == GcCellBacking.no_realm) return null;
            self.acquire();
            defer self.release();
            if (realm_id == self.owner.gc_realm_id) return self.owner;
            for (self.siblings.items) |realm| if (realm.gc_realm_id == realm_id) return realm;
            return null;
        }

        /// Copy every callback target under the registry lock; callbacks run
        /// only after it is released. Null means the caller-provided stack was
        /// too small and should be retried with a larger temporary buffer.
        pub fn copyCallbackRealms(self: *GcRealmRegistry, output: []*Context) ?[]*Context {
            self.acquire();
            defer self.release();
            const needed = 1 + self.siblings.items.len + self.retiring.items.len + self.bootstrapping.items.len;
            if (output.len < needed) return null;
            output[0] = self.owner;
            @memcpy(output[1 .. 1 + self.siblings.items.len], self.siblings.items);
            const bootstrap_start = 1 + self.siblings.items.len + self.retiring.items.len;
            @memcpy(output[1 + self.siblings.items.len .. bootstrap_start], self.retiring.items);
            @memcpy(output[bootstrap_start..needed], self.bootstrapping.items);
            return output[0..needed];
        }

        pub fn callbackRealmCount(self: *GcRealmRegistry) usize {
            self.acquire();
            defer self.release();
            return 1 + self.siblings.items.len + self.retiring.items.len + self.bootstrapping.items.len;
        }

        pub fn siblingCount(self: *GcRealmRegistry) usize {
            self.acquire();
            defer self.release();
            return self.siblings.items.len;
        }

        pub fn ownerCanDestroy(self: *GcRealmRegistry) bool {
            self.acquire();
            defer self.release();
            return self.siblings.items.len == 0 and self.retiring.items.len == 0 and
                self.bootstrapping.items.len == 0;
        }

        pub fn liveSiblingsAreQuiescent(self: *GcRealmRegistry) bool {
            self.acquire();
            defer self.release();
            for (self.siblings.items) |realm|
                if (!realm.preciseRealmIsQuiescent()) return false;
            return true;
        }

        fn deinit(self: *GcRealmRegistry, allocator: std.mem.Allocator) void {
            std.debug.assert(self.siblings.items.len == 0);
            std.debug.assert(self.retiring.items.len == 0);
            std.debug.assert(self.bootstrapping.items.len == 0);
            self.siblings.deinit(allocator);
            self.retiring.deinit(allocator);
            self.bootstrapping.deinit(allocator);
        }
    };

    pub const JitGcConductor = struct {
        lock: std.atomic.Mutex = .unlocked,
        /// Prevent a shared-heap GC publication window and a realm-exclusive
        /// mutator operation from opening together. This belongs to the shared
        /// conductor rather than one Context because sibling realms share GC.
        exclusive_phase: std.atomic.Value(u8) = .init(0),
        class_a_stops: std.atomic.Value(u64) = .init(0),
        /// Threads that have observed `lock` held and are actively waiting to
        /// enter. This is a live gauge, unlike the cumulative iteration counts.
        waiting_threads: std.atomic.Value(u64) = .init(0),
        wait_iterations: std.atomic.Value(u64) = .init(0),
        wait_iterations_max: std.atomic.Value(u64) = .init(0),
        /// Thread currently holding `lock`, or 0. The gate is not reentrant, so
        /// a same-thread re-entry would spin against its own lock forever; this
        /// is what lets that case be recognized and declined. Written only by
        /// the holder, between acquiring and releasing, so a plain atomic store
        /// is enough.
        holder_thread: std.atomic.Value(u64) = .init(0),
    };

    /// Heap, root binding, realm registry, and cell backing are allocated together so
    /// GC-enabled context creation/destruction pays one GPA allocation instead
    /// of three while keeping each subobject's address stable.
    pub const GcState = struct {
        binding: GcBinding,
        heap: GcHeap,
        backing: GcCellBacking,
        realms: GcRealmRegistry,
        conductor: JitGcConductor,
        /// Collector half of the private Environment write handshake. This is
        /// heap-wide because one precise collection traces every registered
        /// realm. See `gc.tryEnterPrivateEnvironmentWrite` for the mutator half.
        environment_trace_active: std.atomic.Value(bool) = .init(false),
        /// Promotion debt since the last *quiescent* full sweep. A mid-script
        /// full collection can observe a whole Promise/job burst as live and
        /// raise the ordinary old-heap threshold accordingly. These markers
        /// belong to the shared heap rather than one realm so sibling entries
        /// make one conductor-serialized boundary decision.
        quiescent_full_promoted_bytes: usize,
        quiescent_full_live_bytes: usize,
    };
    pub const CooperativeGcProfile = struct {
        attempts: u64,
        collections: u64,
        timeouts: u64,
        peer_parks: u64,
        exit_cleanups: u64,
        pause_ns_total: u64,
        pause_ns_max: u64,
        rendezvous_ns_total: u64,
        rendezvous_ns_max: u64,
        tranche_bytes: usize,
        bytes_reset_total: usize,
        bytes_at_start: usize,
        bytes_since_collection: usize,
        minor_profile_cycles: u64,
        minor_prepare_ns_total: u64,
        minor_trace_ns_total: u64,
        minor_sweep_ns_total: u64,
        minor_post_sweep_ns_total: u64,
        full_profile_cycles: u64,
        full_prepare_ns_total: u64,
        full_trace_ns_total: u64,
        full_sweep_ns_total: u64,
        full_post_sweep_ns_total: u64,
        object_batch_calls: u64,
        object_batch_cells: u64,
        object_batch_ns_total: u64,
        object_batch_ns_max: u64,
        heap: GcHeap.Accounting,
        backing: GcCellBacking.Stats,

        pub fn bytesIssued(self: CooperativeGcProfile) usize {
            return self.bytes_reset_total + self.bytes_since_collection -| self.bytes_at_start;
        }
    };
    pub const GcFinalizerStats = struct {
        cells: usize = 0,
        bulk_cell_frees_skipped: usize = 0,
        objects: usize = 0,
        strings: usize = 0,
        environments: usize = 0,
        functions: usize = 0,
        bound_functions: usize = 0,
        promises: usize = 0,
        generators: usize = 0,
        iter_helpers: usize = 0,
        module_namespaces: usize = 0,
        object_backing_releases: usize = 0,
        array_buffers: usize = 0,
        shared_array_buffers: usize = 0,
        promise_reactions: usize = 0,

        pub fn addKind(self: *GcFinalizerStats, kind: gc_mod.CellKind) void {
            self.cells += 1;
            switch (kind) {
                .object => self.objects += 1,
                .string => self.strings += 1,
                .environment => self.environments += 1,
                .function => self.functions += 1,
                .bound_fn => self.bound_functions += 1,
                .promise => self.promises += 1,
                .generator => self.generators += 1,
                .iter_helper => self.iter_helpers += 1,
                .module_ns => self.module_namespaces += 1,
            }
        }
    };

    pub fn create(gpa: std.mem.Allocator) !*Context {
        return createWith(gpa, .{});
    }

    pub fn createWith(gpa: std.mem.Allocator, options: Options) !*Context {
        // Threads run TRUE-parallel (no GIL) by default; `gil` opts back into the
        // serialized path. Parallel execution implies GC-managed, thread-safe cells
        // (enable_gc + parallel_gc). A non-threaded context is single-threaded
        // either way, so it stays on whatever allocator it asked for and pays none
        // of the parallel sync cost.
        const want_parallel = options.enable_threads and !options.gil;
        return createWithTestingOptions(gpa, .{
            .enable_jit = options.enable_jit,
            .enable_threads = options.enable_threads,
            .enable_gc = options.enable_gc or want_parallel,
            .concurrent_gc = options.concurrent_gc,
            .parallel_gc = want_parallel,
            .parallel_js = want_parallel,
            .heap_limit_bytes = options.heap_limit_bytes,
            .wasm_features = options.wasm_features,
            .profile_execution_tiers = options.profile_execution_tiers,
            .native_observability = options.native_observability,
            .native_code_publisher = options.native_code_publisher,
        });
    }

    /// Create another global realm on a standalone arena context's allocation
    /// heap. This is the C-API context-group path: realms have distinct globals,
    /// intrinsic objects, environments, shapes, and microtask queues, while all
    /// values and executable mappings share one VM lifetime. The primary owns
    /// the arena and must outlive every realm created here.
    pub fn createSharedArenaRealm(primary: *Context) !*Context {
        if (primary.gc != null or primary.locked_arena != null or primary.gil != null)
            return error.UnsupportedSharedRuntime;
        primary.assertOwnerThread();
        const a = primary.arena();
        const allocator = primary.gpa;
        const self = try allocator.create(Context);
        errdefer allocator.destroy(self);
        self.* = .{
            .host_gpa = primary.host_gpa,
            .gpa = allocator,
            .arena_state = primary.arena_state,
            .jit_owner = jit.Owner.initWithOptions(allocator, .{
                .native_observability = primary.jit_owner.nativeObservabilityEnabled(),
                .native_code_publisher = primary.jit_owner.nativeCodePublisher(),
            }),
            .shared_jit_owner = primary.shared_jit_owner orelse &primary.jit_owner,
            .enable_jit = primary.enable_jit,
            .bytecode_execution_mode = primary.bytecode_execution_mode,
            .bytecode_binary_quickening = primary.bytecode_binary_quickening,
            .profile_execution_tiers = primary.profile_execution_tiers,
            .owner_thread = primary.owner_thread,
            .sab_retains = .{ .gpa = allocator },
            .env = .{ .arena = a, .fn_scope = true, .binding_lock_required = false },
            .global_object = undefined,
            .root_shape = try Shape.createRoot(a),
            .tdz_marker = undefined,
            .main_can_block = primary.main_can_block,
            .max_js_threads = 0,
            .parallel_js = false,
            .wasm_features = primary.wasm_features,
        };
        self.env.useRealmHashKeys(self.root_shape);
        errdefer self.jit_owner.deinit();

        const gc_saved = gc_mod.setActiveHeap(null);
        defer _ = gc_mod.setActiveHeap(gc_saved);
        const sa_saved = strcell.setActiveArena(a);
        defer _ = strcell.setActiveArena(sa_saved);

        const global_obj = try gc_mod.allocObj(a);
        global_obj.* = .{};
        self.global_object = global_obj;
        self.env.realm_global = global_obj;
        const tdz = try gc_mod.allocObj(a);
        tdz.* = .{};
        self.tdz_marker = tdz;

        const parent_symbol: ?*value.Object = if (primary.env.get("Symbol")) |symbol|
            if (symbol.isObject()) symbol.asObj() else null
        else
            null;
        try interp.installGlobalsInner(&self.env, self.root_shape, parent_symbol);
        if (parent_symbol) |source_symbol| {
            // Every exposed C-API realm must point at one VM-wide
            // GlobalSymbolRegistry even when no realm has called Symbol.for yet.
            // Lazily creating a separate registry after sibling construction
            // breaks Symbol identity across a context group.
            const registry = source_symbol.getOwn("\x00registry") orelse create: {
                const object = try gc_mod.allocObj(a);
                object.* = .{};
                const value_ = Value.obj(object);
                try source_symbol.setOwn(a, primary.root_shape, "\x00registry", value_);
                break :create value_;
            };
            if (self.env.get("Symbol")) |symbol| {
                if (symbol.isObject())
                    try symbol.asObj().setOwn(a, self.root_shape, "\x00registry", registry);
            }
        }
        inline for (.{ "Date", "Error", "RegExp", "Function" }, 0..) |name, index| {
            self.c_api_builtin_constructors[index] = self.env.get(name) orelse Value.undef();
        }
        try self.env.put("globalThis", Value.obj(global_obj));
        if (self.env.get("Object")) |object_ctor| {
            if (object_ctor.isObject()) {
                if (object_ctor.asObj().getOwn("prototype")) |object_proto| {
                    if (object_proto.isObject()) global_obj.proto = object_proto.asObj();
                }
            }
        }
        var it = self.env.vars.iterator();
        while (it.next()) |entry| {
            const name = entry.key_ptr.*;
            const frozen = std.mem.eql(u8, name, "undefined") or
                std.mem.eql(u8, name, "NaN") or std.mem.eql(u8, name, "Infinity");
            try global_obj.setOwnWithAttr(a, self.root_shape, name, entry.value_ptr.*, if (frozen)
                .{ .writable = false, .enumerable = false, .configurable = false }
            else
                .{ .writable = true, .enumerable = false, .configurable = true });
        }
        if (self.env.get("$262")) |harness| {
            if (harness.isObject()) try harness.asObj().setOwn(a, self.root_shape, "global", Value.obj(global_obj));
        }
        return self;
    }

    pub fn createWithTestingOptions(gpa: std.mem.Allocator, options: TestingOptions) !*Context {
        return createWithTestingOptionsForSharedOwner(gpa, options, null);
    }

    /// Engine-core constructor used by #419 tests and, later, #416's private
    /// lifecycle. Arena C context groups deliberately keep their existing path.
    pub fn createSharedPreciseRealm(primary: *Context) !*Context {
        if (primary.gc == null or primary.gc_state == null or primary.shared_jit_owner != null or
            primary.gil != null or primary.parallel_js)
            return error.UnsupportedSharedRuntime;
        primary.assertOwnerThread();
        return createWithTestingOptionsForSharedOwner(primary.host_gpa, .{
            .enable_jit = primary.enable_jit,
            .bytecode_execution_mode = primary.bytecode_execution_mode,
            .bytecode_binary_quickening = primary.bytecode_binary_quickening,
            .profile_execution_tiers = primary.profile_execution_tiers,
            .native_observability = primary.jit_owner.nativeObservabilityEnabled(),
            .native_code_publisher = primary.jit_owner.nativeCodePublisher(),
            .enable_gc = true,
            .wasm_features = primary.wasm_features,
        }, primary);
    }

    fn createWithTestingOptionsForSharedOwner(
        gpa: std.mem.Allocator,
        options: TestingOptions,
        shared_owner: ?*Context,
    ) !*Context {
        // Validate option dependencies before allocating anything, so the error
        // path leaks nothing.
        if (options.parallel_js and !(options.enable_threads and options.enable_gc and options.parallel_gc))
            return error.InvalidThreadTestingOptions;
        if (options.parallel_midscript_gc and !options.parallel_js)
            return error.InvalidThreadTestingOptions;
        if (options.wasm_features.missingDependency() != null)
            return error.InvalidWasmFeatures;
        var host_allocator_lock: ?*SerializedAllocator = null;
        errdefer if (host_allocator_lock) |lock| gpa.destroy(lock);
        const serialized_gpa = if (options.parallel_gc) blk: {
            const lock = try gpa.create(SerializedAllocator);
            lock.* = .{ .inner = gpa };
            host_allocator_lock = lock;
            break :blk lock.allocator();
        } else gpa;

        var budget_allocator: ?*BudgetAllocator = null;
        errdefer if (budget_allocator) |ba| {
            ba.deinit();
            gpa.destroy(ba);
        };
        const limited_gpa = if (options.heap_limit_bytes) |limit| blk: {
            const ba = try gpa.create(BudgetAllocator);
            ba.* = .{ .inner = serialized_gpa, .limit = limit };
            budget_allocator = ba;
            // #722: reserve proportional emergency headroom inside, rather than
            // above, the public hard cap. A too-small cap fails at creation.
            try ba.installRecoveryReserve(@min(limit / 64, 1024 * 1024));
            break :blk ba.allocator();
        } else serialized_gpa;
        var runtime_attribution_profiler: ?*RuntimeAttributionProfiler = null;
        errdefer if (runtime_attribution_profiler) |profile| gpa.destroy(profile);
        const context_gpa = if (options.profile_execution_tiers) blk: {
            const profile = try gpa.create(RuntimeAttributionProfiler);
            profile.* = .{ .inner = limited_gpa };
            runtime_attribution_profiler = profile;
            break :blk profile.allocator();
        } else limited_gpa;
        const arena_state = try context_gpa.create(std.heap.ArenaAllocator);
        arena_state.* = std.heap.ArenaAllocator.init(context_gpa);
        errdefer {
            arena_state.deinit();
            context_gpa.destroy(arena_state);
        }
        // When threads (or the parallel-GC bring-up) are enabled, every
        // arena-allocated structure — shapes, scratch strings/buffers, AST,
        // binding tables —
        // must allocate through a thread-safe wrapper, because the raw
        // `ArenaAllocator` corrupts under parallel allocation (#1). Crucially the
        // wrapper must be installed *before* `a` is captured here: `root_shape`,
        // the global `env`, and every later create-time alloc bind this `a`, and
        // `Shape.transition` reuses the root shape's captured allocator — so a
        // wrapper installed later would leave shape transitions on the raw arena.
        var locked_arena: ?*LockedArena = null;
        errdefer if (locked_arena) |la| {
            la.resetLocalFor();
            context_gpa.destroy(la);
        };
        const a = if (options.enable_threads or options.parallel_gc) blk: {
            const la = try context_gpa.create(LockedArena);
            la.* = .{ .inner = arena_state.allocator() };
            locked_arena = la;
            break :blk la.allocator();
        } else arena_state.allocator();

        const self = try context_gpa.create(Context);
        errdefer context_gpa.destroy(self);
        self.* = .{
            .host_gpa = gpa,
            .gpa = context_gpa,
            .host_allocator_lock = host_allocator_lock,
            .budget_allocator = budget_allocator,
            .runtime_attribution_profiler = runtime_attribution_profiler,
            .step_budget = options.step_budget orelse interp.max_steps,
            .arena_state = arena_state,
            .locked_arena = locked_arena,
            .jit_owner = jit.Owner.initWithOptions(context_gpa, .{
                .native_observability = options.native_observability,
                .native_code_publisher = options.native_code_publisher,
            }),
            .shared_jit_owner = if (shared_owner) |owner| owner.shared_jit_owner orelse &owner.jit_owner else null,
            .enable_jit = options.enable_jit,
            .bytecode_execution_mode = options.bytecode_execution_mode,
            .bytecode_binary_quickening = options.bytecode_binary_quickening,
            .profile_execution_tiers = options.profile_execution_tiers,
            .owner_thread = std.Thread.getCurrentId(),
            .sab_retains = .{ .gpa = context_gpa },
            .env = .{
                .arena = a,
                .fn_scope = true,
                .binding_lock_required = rootEnvironmentBindingLockRequired(options),
            }, // global is a variable scope
            .global_object = undefined, // set below, once the heap exists
            .root_shape = try Shape.createRoot(a),
            .tdz_marker = undefined, // set below
            .main_can_block = options.main_can_block,
            .max_js_threads = options.max_js_threads,
            .parallel_js = options.parallel_js,
            .promise_state_locking = options.concurrent_gc or options.parallel_gc or options.parallel_js,
            .wasm_features = options.wasm_features,
        };
        self.env.useRealmHashKeys(self.root_shape);
        self.gc_par_enabled = options.parallel_midscript_gc;
        self.gc_cooperative_enabled = options.enable_gc and options.parallel_js and !options.parallel_midscript_gc;
        var owned_gc_state: ?*GcState = null;
        errdefer if (owned_gc_state) |state| {
            state.backing.beginBulkTeardown();
            state.heap.deinitRetainingCellStorage();
            self.runDeferredPostSweepCallbacks();
            state.backing.deinit();
            state.realms.deinit(context_gpa);
            context_gpa.destroy(state);
            self.gc = null;
            self.gc_binding = null;
            self.gc_cell_backing = null;
            self.gc_state = null;
        };
        if (shared_owner) |owner| {
            self.gc = owner.gc;
            self.gc_binding = owner.gc_binding;
            self.gc_cell_backing = owner.gc_cell_backing;
            self.gc_state = owner.gc_state;
            try owner.gc_state.?.realms.beginBootstrap(owner.gpa, self);
            errdefer {
                const saved = gc_mod.setActiveContext(owner);
                defer gc_mod.restoreActiveContext(saved);
                owner.collectGarbage();
                owner.gc_state.?.realms.releaseFailedBootstrap(self) catch {};
            }
        } else if (options.enable_gc) {
            // GC cells are gpa-backed (the collector frees them individually).
            // Keep the heap, binding, and cell backing in one stable allocation
            // to reduce GC-enabled context lifecycle churn.
            const gc_state = try context_gpa.create(GcState);
            self.gc_realm_id = GcCellBacking.owner_realm;
            gc_state.binding = .{ .context = self };
            gc_state.realms = .{ .owner = self };
            gc_state.conductor = .{};
            gc_state.environment_trace_active = .init(false);
            gc_state.quiescent_full_promoted_bytes = 0;
            gc_state.quiescent_full_live_bytes = 0;
            // GC cells are individually collectable, but their allocation shape
            // is regular: one 16-byte-aligned slab per cell. Use the reusable
            // size-class backing for every GC mode. Keep the heap/backing in
            // single-mutator mode during private context bootstrap; no Thread
            // can observe the realm until createWithTestingOptions returns, and
            // delaying these locks keeps no-GIL context creation on the fast
            // allocation path. Parallel mode is enabled immediately before
            // returning below.
            gc_state.backing = .{
                .inner = context_gpa,
                .runtime_attribution_profiler = runtime_attribution_profiler,
                .parallel = false,
                .expanded_chunks = true,
                .moving_checkpoint_request = if (options.enable_jit and jit.supported)
                    &self.gc_moving_checkpoint_requested
                else
                    null,
                .moving_checkpoint_threshold = &self.gc_cooperative_tranche_bytes,
            };
            const cell_backing = gc_state.backing.allocator();
            gc_state.heap = GcHeap.init(cell_backing, &gc_state.binding);
            const h = &gc_state.heap;
            // A concurrent marker or peer mutator can touch GC scratch alongside
            // the owning thread, so those modes retain the process-global,
            // thread-safe page allocator. A private heap has no such requirement:
            // keep its pointer stacks on the host allocator supplied for the
            // context, avoiding process-global VM allocation for independent
            // heaps. Use the unbudgeted host allocator so collector scratch stays
            // outside the public heap limit, as it did before this specialization.
            // Set this before any allocation so deinit frees with the same
            // allocator. See zig-gc `Heap.setAuxAllocator`.
            const private_gc_scratch = !options.enable_threads and
                !options.concurrent_gc and !options.parallel_gc;
            h.setAuxAllocator(if (private_gc_scratch) gpa else std.heap.page_allocator);
            h.setNurseryTenuringAge(runtime_gc_tenuring_age);
            h.setNurseryEnabled(true);
            h.setMovingNurseryEnabled(true);
            self.gc = h;
            self.gc_binding = &gc_state.binding;
            self.gc_cell_backing = &gc_state.backing;
            self.gc_state = gc_state;
            owned_gc_state = gc_state;
            // Single-mutator only for now: concurrent marking + no peer mutators.
            self.gc_concurrent = options.concurrent_gc and !options.enable_threads;
            // A dedicated marker thread can still read the heap's payload index
            // and all-list while the lone mutator allocates. Keep that metadata
            // serialized without opting into the multi-mutator parallel finish
            // protocol (`h.parallel` stays false in this mode).
            h.setConcurrentMarkerMetadata(self.gc_concurrent);
        }
        // Route all cell allocation (the global object + TDZ sentinel,
        // installGlobals, and the mirror loop below) through the GC when
        // enabled; restore on return so a nested createWith on this thread is
        // unaffected. Creating the heap first means even these roots are GC
        // cells (required once mid-run collection marks from them).
        const gc_saved = gc_mod.setActiveContext(self);
        defer gc_mod.restoreActiveContext(gc_saved);
        const sa_saved = strcell.setActiveArena(self.arena());
        defer _ = strcell.setActiveArena(sa_saved);

        const global_obj = try gc_mod.allocObj(a);
        global_obj.* = .{};
        self.global_object = global_obj;
        self.env.realm_global = global_obj;
        // A unique sentinel object marking a `let`/`const` binding in its
        // temporal dead zone (declared but not yet initialized).
        const tdz = try gc_mod.allocObj(a);
        tdz.* = .{};
        self.tdz_marker = tdz;

        try interp.installGlobals(&self.env, self.root_shape);
        if (shared_owner) |owner| try self.shareSymbolRegistry(owner);
        if (options.wasm_spec_bit_exact)
            try wasm_api.installSpecHarness(&self.env, self.root_shape);
        inline for (.{ "Date", "Error", "RegExp", "Function" }, 0..) |name, index| {
            self.c_api_builtin_constructors[index] = self.env.get(name) orelse Value.undef();
        }
        if (!options.enable_shared_array_buffer) {
            _ = self.env.removeVar("SharedArrayBuffer");
        }
        // `globalThis` names the global object itself.
        try self.env.put("globalThis", Value.obj(global_obj));
        if (self.env.get("Object")) |object_ctor| {
            if (object_ctor.isObject()) {
                if (object_ctor.asObj().getOwn("prototype")) |object_proto| {
                    if (object_proto.isObject()) global_obj.proto = object_proto.asObj();
                }
            }
        }
        // Mirror the installed globals onto the global object as real own
        // properties (with spec attributes), so `Object.getOwnPropertyDescriptor
        // (globalThis, "Math")`, `Object.keys`, `hasOwnProperty`, etc. see them.
        // `undefined`/`NaN`/`Infinity` are non-writable/-enumerable/-configurable;
        // the rest are writable, non-enumerable, configurable.
        var it = self.env.vars.iterator();
        while (it.next()) |e| {
            const name = e.key_ptr.*;
            const frozen = std.mem.eql(u8, name, "undefined") or
                std.mem.eql(u8, name, "NaN") or std.mem.eql(u8, name, "Infinity");
            try global_obj.setOwnWithAttr(a, self.root_shape, name, e.value_ptr.*, if (frozen)
                .{ .writable = false, .enumerable = false, .configurable = false }
            else
                .{ .writable = true, .enumerable = false, .configurable = true });
        }
        // `$262.global` is this realm's global object.
        if (self.env.get("$262")) |d| {
            if (d.isObject()) try d.asObj().setOwn(a, self.root_shape, "global", Value.obj(global_obj));
        }
        if (options.heap_limit_bytes != null) {
            self.reserved_thread_oom_error = try self.createReservedThreadOomError();
        }
        if (options.enable_threads) {
            // `locked_arena` (the thread-safe arena, #1) was installed before any
            // create-time allocation above, so shapes/env/etc. already use it.
            const g = try context_gpa.create(gil_mod.Gil);
            g.* = .{};
            g.park_alloc = context_gpa;
            g.prop_alloc = context_gpa;
            self.gil = g;
            g.acquire();
            defer g.release();
            // Register the main thread's park record (this thread). A spawned
            // thread that becomes the collector roots the main thread's parked
            // stack through it (e.g. while main waits in the keepalive loop).
            g.registerPark(stack_scan.parkRecord());
            if (options.concurrent_gc or options.parallel_gc) enableParallelSync();
            try jsthread.installThreadAPI(self);
        }
        if (options.parallel_gc) {
            if (self.gc) |h| h.setParallel(true);
            if (self.gc_cell_backing) |backing| backing.parallel = true;
        }
        if (!options.enable_threads and (options.concurrent_gc or options.parallel_gc)) enableParallelSync();
        if (self.budget_allocator) |ba| ba.setRecovery(self, recoverAllocationFailure);
        if (shared_owner) |owner| try owner.gc_state.?.realms.registerBootstrapped(owner.gpa, self);
        self.gc_bootstrapping = false;
        return self;
    }

    fn shareSymbolRegistry(self: *Context, owner: *Context) !void {
        const source_symbol = if (owner.env.get("Symbol")) |symbol|
            if (symbol.isObject()) symbol.asObj() else return
        else
            return;
        const registry = source_symbol.getOwn("\x00registry") orelse create: {
            const saved = gc_mod.setActiveContext(owner);
            defer gc_mod.restoreActiveContext(saved);
            const object = try gc_mod.allocObj(owner.arena());
            object.* = .{};
            const registry_value = Value.obj(object);
            try source_symbol.setOwn(owner.arena(), owner.root_shape, "\x00registry", registry_value);
            break :create registry_value;
        };
        if (self.env.get("Symbol")) |symbol|
            if (symbol.isObject())
                try symbol.asObj().setOwn(self.arena(), self.root_shape, "\x00registry", registry);
    }

    /// Name a heap-limit allocation failure that escaped a host entry without
    /// an enclosing `try`. `Thread` bodies already publish the reserved
    /// `OutOfMemoryError` as their completion value, but a top-level escape used
    /// to return a bare `error.OutOfMemory` with `exception` left null, so hosts
    /// and test runners could only report an anonymous failure (#100). The error
    /// code is unchanged — embeddings that special-case `error.OutOfMemory` keep
    /// working — but `exception` now identifies the exact failure. No-op without
    /// a configured heap limit: there the failure is the host allocator's, not a
    /// realm-visible one, and no reserved value exists to report.
    fn surfaceEscapedOutOfMemory(self: *Context, err: anyerror) void {
        if (err != error.OutOfMemory) return;
        if (self.exception != null) return;
        self.exception = self.reserved_thread_oom_error;
    }

    fn createReservedThreadOomError(self: *Context) !Value {
        var machine = self.interpreter();
        const err = try machine.makeError("OutOfMemoryError", "Context heap limit exceeded");
        const obj = err.asObj();
        try obj.setOwnWithAttr(self.arena(), self.root_shape, "name", Value.str("OutOfMemoryError"), .{ .writable = false, .enumerable = false, .configurable = false });
        try obj.setAttr(self.arena(), "message", .{ .writable = false, .enumerable = false, .configurable = false });
        obj.setExtensible(false);
        return err;
    }

    /// An interpreter bound to this context's arena, globals, and shape tree.
    /// Top-level `this` is the global object (so `this`/`globalThis` are real
    /// objects and reflection over the global works).
    pub fn interpreter(self: *Context) interp.Interpreter {
        return .{
            .arena = self.arena(),
            .scratch_allocator = self.gpa,
            .env = &self.env,
            .jit_owner = if (self.enable_jit and self.debug_statement_hook == null and self.host_statement_hook == null and self.profile_statement_hook == null) (self.shared_jit_owner orelse &self.jit_owner) else null,
            .jit_invalidation_ctx = if (self.parallel_js and self.enable_jit) self else null,
            .jit_invalidation_fn = if (self.parallel_js and self.enable_jit) clearJitCodeFromInterpreter else null,
            .debug_statement_ctx = self.debug_statement_ctx,
            .debug_statement_hook = self.debug_statement_hook,
            .host_statement_ctx = self.host_statement_ctx,
            .host_statement_hook = self.host_statement_hook,
            .profile_statement_ctx = self.profile_statement_ctx,
            .profile_statement_hook = self.profile_statement_hook,
            .bytecode_admission_inventory = &self.bytecode_admission_inventory,
            .execution_tier_inventory = if (self.profile_execution_tiers) &self.execution_tier_inventory else null,
            .debug_registry_stats = if (self.runtime_attribution_profiler) |profile| &profile.debug_registry else null,
            .bytecode_execution_mode = self.bytecode_execution_mode,
            .bytecode_binary_quickening = self.bytecode_binary_quickening,
            .debug_statement_locations = &self.debug_statement_locations,
            .debug_registry_lock = if (self.parallel_js) &self.debug_registry_lock else null,
            .debug_script_ctx = self,
            .debug_script_hook = registerInterpreterDebugScript,
            .debug_exception_ctx = self.debug_statement_ctx,
            .debug_exception_hook = self.debug_exception_hook,
            .global_object = self.global_object,
            .this_value = Value.obj(self.global_object),
            .root_shape = self.root_shape,
            .microtasks = &self.microtasks,
            .next_ticks = &self.next_ticks,
            .unhandled_rejections = &self.unhandled_rejections,
            .handled_rejections = &self.handled_rejections,
            .out_of_memory_exception = self.reserved_thread_oom_error orelse Value.undef(),
            .step_budget = self.step_budget,
            // Only engage per-queue microtask locking in no-GIL mode;
            // single-threaded and `.gil = true` execution stay lock-free.
            .lock_microtasks = self.parallel_js,
            .lock_promise_state = self.promise_state_locking,
            .realm_lock = if (self.parallel_js) &self.realm_lock else null,
            .prototype_lock = if (self.parallel_js) &self.prototype_lock else null,
            .print_buffer = &self.print_buffer,
            .tdz_marker = self.tdz_marker,
            .sab_retains = &self.sab_retains,
            .async_waiters = &self.async_waiters,
            .abort_timeout_ctx = self,
            .abort_timeout_schedule = scheduleAbortSignalTimeout,
            .abort_timeout_poll = pollAbortSignalTimeouts,
            .fetch_headers_attach_ctx = self,
            .fetch_headers_attach = attachFetchHeadersObject,
            .timer_ctx = self,
            .timer_schedule = scheduleTimer,
            .timer_cancel = cancelTimer,
            .timer_set_ref = setTimerRef,
            .timer_refresh = refreshTimer,
            .timer_poll = pollTimers,
            .timer_keepalive = keepaliveTimers,
            .timer_abandon = abandonTimers,
            .finalization_cleanup_jobs = &self.finalization_cleanup_jobs,
            .stop_flag = self.stop_flag orelse &self.teardown_stop,
            .watchdog_check_flag = self.watchdog_check_flag,
            .watchdog_deadline_ns = self.watchdog_deadline_ns,
            .shell_timeout_check_flag = self.shell_timeout_check_flag,
            .termination_request_flag = self.termination_request_flag,
            .main_can_block = self.main_can_block,
            .use_thread_gil = self.gil != null and !self.parallel_js,
            .gil = self.gil,
            .gc = self.gc,
            .gc_realm_context = if (self.gc != null) self else null,
            .gc_environment_trace_active = if (self.gc_state) |state| &state.environment_trace_active else null,
            // Interpreter-owned buffers are reclaimable side storage, not GC
            // cells. Allocate them directly from the Context allocator so a
            // budget miss can trigger collection before retrying. Routing them
            // through GcCellBacking would delegate while holding its internal
            // allocator lock, where recursive allocation recovery is correctly
            // blocked.
            .gc_side_storage = if (self.gc != null) self.gpa else null,
            .gc_array_buffer_bytes_live = if (self.gc != null) &self.gc_array_buffer_bytes_live else null,
            .gc_promise_reactions_live = if (self.gc != null) &self.gc_promise_reactions_live else null,
            .gc_environment_name_bytes_live = if (self.gc != null) &self.gc_environment_name_bytes_live else null,
            .gc_weak_work = if (self.gc != null) &self.gc_weak_work else null,
            .gc_requested = &self.gc_requested,
            .gc_moving_requested = if (self.gc != null) self.movingCheckpointRequest() else null,
            .gc_checkpoint_ctx = self,
            .gc_checkpoint_fn = serviceRequestedGcCheckpoint,
            .gc_recover_allocation_fn = recoverAllocationFailure,
            .gc_deferred_allocation_recovery = if (self.budget_allocator) |ba| &ba.deferred_recovery_pending else null,
            // Mid-script collection hook: wired only when the GC is on, so the
            // arena engine pays nothing (the VM/tree-walker skip on a null fn).
            .gc_safepoint_ctx = if (self.gc != null) self else null,
            .gc_safepoint_fn = if (self.gc != null) collectMidScript else null,
            .mutator_stop_request = if (self.parallel_js) &self.mutator_stop_request else null,
            .mutator_stop_ctx = if (self.parallel_js) self else null,
            .mutator_stop_fn = if (self.parallel_js) joinMutatorStop else null,
            .parallel_worker_count = if (self.parallel_js) &self.parallel_worker_count else null,
            .private_name_serial = &self.private_name_serial,
            .wasm_store_ctx = self,
            .dyn_import = if (self.mod_host != null) dynImportHook else null,
            .dyn_import_ctx = if (self.mod_host != null) self else null,
            .defer_trigger = if (self.mod_host != null) deferTriggerHook else null,
            .defer_trigger_ctx = if (self.mod_host != null) self else null,
        };
    }

    pub fn lockDebugRegistry(self: *Context) void {
        if (self.parallel_js) self.debug_registry_lock.lockProfiled(if (self.runtime_attribution_profiler) |profile| &profile.debug_registry else null);
    }

    pub fn unlockDebugRegistry(self: *Context) void {
        if (self.parallel_js) self.debug_registry_lock.unlock();
    }

    pub fn bytecodeAdmissionSnapshot(self: *const Context) interp.BytecodeAdmissionSnapshot {
        return self.bytecode_admission_inventory.snapshot();
    }

    /// Record an embedding boundary that executes without constructing an
    /// Interpreter, such as a direct public-C-API host-function call.
    pub inline fn recordExecutionTier(self: *Context, metric: interp.ExecutionTierMetric) void {
        if (self.profile_execution_tiers) self.execution_tier_inventory.record(metric);
    }

    pub const TierAttributionSnapshot = struct {
        execution: interp.ExecutionTierSnapshot,
        quick_binary: interp.QuickBinarySnapshot,
        timing: interp.TierTimingSnapshot,
        admissions: interp.BytecodeAdmissionSnapshot,
        baseline_publications: u64,
        optimizer_publications: u64,
        generated_code_bytes: usize,
        native_code: NativeCodeAttributionSnapshot,
        debug_registry: interp.DebugRegistrySnapshot,
        heap: RuntimeHeapAccounting,
        runtime: RuntimeAttributionProfiler.Snapshot,
    };

    pub const NativeCodeAttributionSnapshot = struct {
        live_artifacts: usize,
        live_bytes: usize,
        retired_artifacts: usize,
        retired_bytes_current: usize,
        reclaimed_artifacts: usize,
        reclaimed_bytes_total: usize,
        shape_invalidation_events: u64,
        shape_retired_artifacts: u64,
        shape_survivor_artifacts: u64,
        shape_retired_bytes: u64,
        full_invalidation_events: u64,
        unknown_shape_invalidation_events: u64,
        shape_fallback_events: u64,
    };

    /// Allocation-free exact generated-PC lookup for host crash/signal paths.
    /// The Context and caller-owned buffers must outlive the call.
    pub fn lookupNativeCodeSignalSafe(
        self: *Context,
        pc: usize,
        buffers: jit.NativeSignalSafeBuffers,
    ) jit.NativeSignalSafeLookupError!?jit.NativeSignalSafeSnapshot {
        const owner = self.shared_jit_owner orelse &self.jit_owner;
        return owner.lookupNativeCodeSignalSafe(pc, buffers);
    }

    /// Phase-boundary attribution snapshot. Counters are monotonic while live
    /// byte/artifact fields are gauges; every shared component is read through
    /// its atomic/accounting snapshot after benchmark workers have joined.
    pub fn tierAttributionSnapshot(self: *Context) TierAttributionSnapshot {
        const owner = self.shared_jit_owner orelse &self.jit_owner;
        const code = owner.stats();
        return .{
            .execution = self.execution_tier_inventory.snapshot(),
            .quick_binary = self.execution_tier_inventory.quickBinarySnapshot(),
            .timing = self.execution_tier_inventory.timingSnapshot(),
            .admissions = self.bytecode_admission_inventory.snapshot(),
            .baseline_publications = owner.baselinePublications(),
            .optimizer_publications = owner.optimizerPublications(),
            .generated_code_bytes = code.live_bytes,
            .native_code = .{
                .live_artifacts = code.live_artifacts,
                .live_bytes = code.live_bytes,
                .retired_artifacts = code.retired_artifacts,
                .retired_bytes_current = code.retired_bytes,
                .reclaimed_artifacts = code.reclaimed_artifacts,
                .reclaimed_bytes_total = code.reclaimed_bytes,
                .shape_invalidation_events = code.shape_invalidation_events,
                .shape_retired_artifacts = code.shape_retired_artifacts,
                .shape_survivor_artifacts = code.shape_survivor_artifacts,
                .shape_retired_bytes = code.shape_retired_bytes,
                .full_invalidation_events = code.full_invalidation_events,
                .unknown_shape_invalidation_events = code.unknown_shape_invalidation_events,
                .shape_fallback_events = code.shape_fallback_events,
            },
            .debug_registry = if (self.runtime_attribution_profiler) |profile|
                profile.debug_registry.snapshot()
            else
                .{},
            .heap = self.runtimeHeapAccounting(),
            .runtime = if (self.runtime_attribution_profiler) |profile|
                profile.snapshot()
            else
                .{},
        };
    }

    fn registerDebugLocationsLocked(
        self: *Context,
        allocator: std.mem.Allocator,
        script: DebugScript,
        locations: []const parser_mod.StatementLocation,
    ) !void {
        const additional_locations = std.math.cast(u32, locations.len) orelse return error.OutOfMemory;
        try self.debug_statement_locations.ensureUnusedCapacity(allocator, additional_locations, self.root_shape);
        for (locations) |entry| self.debug_statement_locations.putAssumeCapacity(entry.node, .{
            .script_id = script.id,
            .location = .{
                .byte_offset = entry.location.byte_offset,
                .line = entry.location.line + script.start_line - 1,
                .column = entry.location.column,
            },
            .source_url = script.url,
            .debugger_statement = entry.debugger_statement,
        });
    }

    fn registerDebugLocations(
        self: *Context,
        script: DebugScript,
        locations: []const parser_mod.StatementLocation,
    ) !void {
        self.lockDebugRegistry();
        defer self.unlockDebugRegistry();
        try self.registerDebugLocationsLocked(self.arena(), script, locations);
    }

    pub fn registerDebugScriptWithLocations(
        self: *Context,
        source: []const u8,
        url: []const u8,
        start_line: usize,
        locations: []const parser_mod.StatementLocation,
    ) !DebugScript {
        return self.registerDebugScriptWithLocationsIndexAllocator(
            self.arena(),
            source,
            url,
            start_line,
            locations,
        );
    }

    fn registerDebugScriptWithLocationsIndexAllocator(
        self: *Context,
        index_allocator: std.mem.Allocator,
        source: []const u8,
        url: []const u8,
        start_line: usize,
        locations: []const parser_mod.StatementLocation,
    ) !DebugScript {
        const allocator = self.arena();
        const owned_url = try allocator.dupe(u8, url);
        const owned_source = try allocator.dupe(u8, source);
        self.lockDebugRegistry();
        defer self.unlockDebugRegistry();
        try self.debug_scripts.ensureUnusedCapacity(allocator, 1);
        const additional_locations = std.math.cast(u32, locations.len) orelse return error.OutOfMemory;
        try self.debug_statement_locations.ensureUnusedCapacity(index_allocator, additional_locations, self.root_shape);
        const script = DebugScript{
            .id = self.next_debug_script_id,
            .url = owned_url,
            .source = owned_source,
            .start_line = @max(start_line, 1),
        };
        self.debug_scripts.appendAssumeCapacity(script);
        self.next_debug_script_id += 1;
        for (locations) |entry| self.debug_statement_locations.putAssumeCapacity(entry.node, .{
            .script_id = script.id,
            .location = .{
                .byte_offset = entry.location.byte_offset,
                .line = entry.location.line + script.start_line - 1,
                .column = entry.location.column,
            },
            .source_url = script.url,
            .debugger_statement = entry.debugger_statement,
        });
        if (self.debug_script_notify_hook) |hook| {
            if (!hook(self.debug_script_notify_ctx.?, script)) return error.OutOfMemory;
        }
        return script;
    }

    pub fn registerDebugScript(self: *Context, source: []const u8, url: []const u8, start_line: usize) !DebugScript {
        return self.registerDebugScriptWithLocations(source, url, start_line, &.{});
    }

    fn registerInterpreterDebugScript(
        ctx: *anyopaque,
        source: []const u8,
        url: []const u8,
        start_line: usize,
        locations: []const parser_mod.StatementLocation,
    ) interp.EvalError!interp.DebugScriptRegistration {
        const self: *Context = @ptrCast(@alignCast(ctx));
        const script = self.registerDebugScriptWithLocations(source, url, start_line, locations) catch return error.OutOfMemory;
        return .{ .id = script.id, .start_line = script.start_line };
    }

    fn debugScriptById(self: *Context, id: u64) ?DebugScript {
        self.lockDebugRegistry();
        defer self.unlockDebugRegistry();
        for (self.debug_scripts.items) |script| if (script.id == id) return script;
        return null;
    }

    /// Request cooperative termination of the current evaluation and any
    /// shared-realm JavaScript threads owned by this context. This operation is
    /// thread-safe and allocation-free, so a host watchdog may call it from a
    /// different native thread. Treat the request as terminal for the context:
    /// destroy it after the interrupted evaluation instead of attempting reuse.
    pub fn requestTermination(self: *Context) void {
        self.teardown_stop.store(true, .release);
        agent.interruptWaiters();
    }

    pub fn terminationRequested(self: *const Context) bool {
        if (self.stop_flag) |flag| if (flag.load(.acquire)) return true;
        return @constCast(&self.teardown_stop).load(.acquire);
    }

    fn preciseRealmIsQuiescent(self: *Context) bool {
        self.lockActiveInterpreters();
        const has_active_interpreters = self.active_interpreters.items.len != 0;
        self.unlockActiveInterpreters();
        if (has_active_interpreters) return false;
        if (self.gil) |g| {
            g.lockApi();
            const has_live_thread_or_task = g.tasks_queued.load(.acquire) != 0 or
                g.hasInFlightTasks() or threads: {
                const io = agent.engineIo();
                for (self.js_threads.items) |record| {
                    record.join_mutex.lockUncancelable(io);
                    const exited = record.exited;
                    record.join_mutex.unlock(io);
                    if (!exited) break :threads true;
                }
                break :threads false;
            };
            g.unlockApi();
            if (has_live_thread_or_task) return false;
            g.lockPropWaiters();
            const has_property_waiter = g.prop_waiters.items.len != 0 or g.prop_async.items.len != 0;
            g.unlockPropWaiters();
            if (has_property_waiter) return false;
        } else {
            for (self.js_threads.items) |record| if (!record.exited) return false;
        }
        return self.microtasks.isEmpty() and
            self.next_ticks.isEmpty() and
            self.unhandled_rejections.items.len == 0 and
            self.handled_rejections.items.len == 0 and
            self.timers.items.len == 0 and
            self.finalization_cleanup_jobs.items.len == 0 and
            self.async_waiters.items.len == 0;
    }

    fn deinitProtectedValues(self: *Context) void {
        for (self.protected_values.items) |handle| self.gpa.destroy(handle);
        self.protected_values.deinit(self.gpa);
    }

    pub fn destroy(self: *Context) void {
        if (self.gc_state) |state| {
            if (state.realms.owner == self and !state.realms.ownerCanDestroy())
                @panic("precise heap owner destroyed before every sibling realm");
        }
        std.debug.assert(self.c_api_inspector_state == null);
        if (self.c_api_script_execution_context_unregister) |unregister| {
            self.c_api_script_execution_context_unregister = null;
            unregister(self);
        }
        const host_gpa = self.host_gpa;
        const context_gpa = self.gpa;
        const budget_allocator = self.budget_allocator;
        const runtime_attribution_profiler = self.runtime_attribution_profiler;
        const host_allocator_lock = self.host_allocator_lock;
        if (self.gil) |g| {
            self.teardown_stop.store(true, .release);
            agent.interruptWaiters();
            // Spawned threads need the lock to finish: park until each is
            // done, then OS-join the handles.
            if (self.parallel_js) {
                const io = agent.engineIo();
                for (self.js_threads.items) |rec| {
                    rec.join_mutex.lockUncancelable(io);
                    while (!rec.exited) rec.done_cond.wait(io, &rec.join_mutex) catch {};
                    rec.join_mutex.unlock(io);
                }
            } else {
                g.acquire();
                for (self.js_threads.items) |rec| {
                    while (!rec.done) g.wait(&rec.done_cond);
                }
                g.release();
            }
            for (self.js_threads.items) |rec| {
                if (rec.thread) |t| t.join();
            }
            jsthread.abandonPropAsync(g);
            g.unregisterPark(stack_scan.parkRecord());
            g.park_records.deinit(self.gpa);
            self.gpa.destroy(g);
            self.gil = null;
        } else {
            self.assertOwnerThread();
        }
        self.js_threads.deinit(self.gpa);
        self.active_interpreters.deinit(self.gpa);
        self.cancelAllTimers();
        self.finalization_cleanup_jobs.deinit(self.gpa);
        self.c_api_handles.deinit(self.gpa);
        self.deinitProtectedValues();
        self.private_strong_roots.deinit(self.gpa);
        self.private_weak_roots.deinit(self.gpa);
        for (self.private_commonjs_functions.items) |root| self.gpa.destroy(root);
        self.private_commonjs_functions.deinit(self.gpa);
        // Reclaim every GC cell (running finalizers) before the arena and the
        // Context itself go away — GC cells are gpa-backed and disjoint from the
        // arena. Keep `sab_retains` alive until after finalizers run: live
        // SharedArrayBuffer wrapper cells release their tracked storage refs
        // there when GC is enabled.
        _ = self.finishConcurrentGCIfActive(); // join any marker before heap teardown
        if (self.gc) |h| {
            if (self.gc_cell_backing) |backing| {
                backing.beginBulkTeardown();
                if (self.gc_finalizer_stats_out) |stats| {
                    stats.bulk_cell_frees_skipped = h.live_cells;
                }
                // Finalize every logical cell and release collector side buffers,
                // but skip one allocator free per cell: the backing owns those
                // cells in whole slabs and releases the slabs immediately below.
                h.deinitRetainingCellStorage();
            } else {
                h.deinit();
            }
            self.gc = null;
        }
        self.runDeferredPostSweepCallbacks();
        if (self.gc_cell_backing) |backing| {
            backing.deinit(); // safe now: heap.deinit() is done using it
            self.gc_cell_backing = null;
        }
        self.gc_binding = null;
        if (self.gc_state) |state| {
            state.realms.deinit(self.gpa);
            self.gpa.destroy(state);
            self.gc_state = null;
        }
        for (self.native_array_buffer_handles.items) |handle| {
            handle.releaseWrapper();
            handle.releaseTracking();
        }
        self.native_array_buffer_handles.deinit(self.gpa);
        for (self.c_api_object_owners.items) |owner| {
            owner.finishOnce();
            self.gpa.destroy(owner);
        }
        self.c_api_object_owners.deinit(self.gpa);
        std.debug.assert(self.abort_signal_timeout_owners.items.len == 0);
        self.abort_signal_timeout_owners.deinit(self.gpa);
        for (self.c_api_class_prototypes.items) |owner| {
            owner.finish();
            self.gpa.destroy(owner);
        }
        self.c_api_class_prototypes.deinit(self.gpa);
        for (self.external_buffer_owners.items) |owner| {
            _ = owner.release();
            self.gpa.destroy(owner);
        }
        self.external_buffer_owners.deinit(self.gpa);
        for (self.external_string_owners.items) |owner| {
            _ = owner.release();
            self.gpa.destroy(owner);
        }
        self.external_string_owners.deinit(self.gpa);
        self.module_registry.deinit(self.arena());
        self.module_loader_sources.deinit(self.arena());
        self.unhandled_rejections.deinit(self.arena());
        self.handled_rejections.deinit(self.arena());
        if (self.locked_arena) |la| {
            la.resetLocalFor();
            self.gpa.destroy(la);
            self.locked_arena = null;
        }
        // Free every WebAssembly native allocation while the arena (which may
        // still hold JS wrappers pointing at them) is alive; idempotent, and
        // the registry list itself is gpa-owned (issue #141).
        wasm_api.teardownWasmStore(self);
        self.wasm_registry.deinit(self.gpa);
        self.sab_retains.deinit();
        self.jit_owner.deinit();
        self.arena_state.deinit();
        context_gpa.destroy(self.arena_state);
        context_gpa.destroy(self);
        if (runtime_attribution_profiler) |profile| host_gpa.destroy(profile);
        if (budget_allocator) |ba| {
            ba.deinit();
            host_gpa.destroy(ba);
        }
        if (host_allocator_lock) |lock| host_gpa.destroy(lock);
    }

    fn deinitSharedRealmState(self: *Context) void {
        std.debug.assert(self.c_api_inspector_state == null);
        if (self.c_api_script_execution_context_unregister) |unregister| {
            self.c_api_script_execution_context_unregister = null;
            unregister(self);
        }
        self.js_threads.deinit(self.gpa);
        self.active_interpreters.deinit(self.gpa);
        self.cancelAllTimers();
        self.finalization_cleanup_jobs.deinit(self.gpa);
        self.c_api_handles.deinit(self.gpa);
        self.deinitProtectedValues();
        self.private_strong_roots.deinit(self.gpa);
        self.private_weak_roots.deinit(self.gpa);
        for (self.private_commonjs_functions.items) |root| self.gpa.destroy(root);
        self.private_commonjs_functions.deinit(self.gpa);
        for (self.native_array_buffer_handles.items) |handle| {
            handle.releaseWrapper();
            handle.releaseTracking();
        }
        self.native_array_buffer_handles.deinit(self.gpa);
        for (self.c_api_object_owners.items) |owner| {
            owner.finishOnce();
            self.gpa.destroy(owner);
        }
        self.c_api_object_owners.deinit(self.gpa);
        std.debug.assert(self.abort_signal_timeout_owners.items.len == 0);
        self.abort_signal_timeout_owners.deinit(self.gpa);
        for (self.c_api_class_prototypes.items) |owner| {
            owner.finish();
            self.gpa.destroy(owner);
        }
        self.c_api_class_prototypes.deinit(self.gpa);
        for (self.external_buffer_owners.items) |owner| {
            _ = owner.release();
            self.gpa.destroy(owner);
        }
        self.external_buffer_owners.deinit(self.gpa);
        for (self.external_string_owners.items) |owner| {
            _ = owner.release();
            self.gpa.destroy(owner);
        }
        self.external_string_owners.deinit(self.gpa);
        self.module_registry.deinit(self.arena());
        self.module_loader_sources.deinit(self.arena());
        self.unhandled_rejections.deinit(self.arena());
        self.handled_rejections.deinit(self.arena());
        wasm_api.teardownWasmStore(self);
        self.wasm_registry.deinit(self.gpa);
        self.sab_retains.deinit();
        self.jit_owner.deinit();
    }

    /// Tear down one secondary shared-arena realm without releasing the primary
    /// VM heap. The group calls this only after its last external/context retain
    /// is gone, so callbacks and embedder deallocators run while every realm and
    /// every cross-realm value is still allocated.
    pub fn destroySharedArenaRealm(self: *Context) void {
        self.assertOwnerThread();
        std.debug.assert(self.gc == null and self.locked_arena == null and self.gil == null);
        std.debug.assert(self.shared_jit_owner != null);
        self.deinitSharedRealmState();
        self.gpa.destroy(self);
    }

    /// Terminal engine-core lifecycle for a sibling with its own non-cell
    /// arena and the owner's precise cell heap. A retained cross-realm edge
    /// makes the operation fail with `RealmCellsRemain`; the Context stays
    /// intact and callback-addressable so the caller can drop that edge and
    /// retry without use-after-free.
    pub fn destroySharedPreciseRealm(self: *Context) !void {
        self.assertOwnerThread();
        std.debug.assert(self.gc != null and self.gc_state != null and self.gil == null);
        std.debug.assert(self.shared_jit_owner != null);
        const state = self.gc_state.?;
        const owner = state.realms.owner;
        self.lockActiveInterpreters();
        const has_active_interpreters = self.active_interpreters.items.len != 0;
        self.unlockActiveInterpreters();
        if (has_active_interpreters) return error.RealmNotQuiescent;
        for (self.js_threads.items) |record| if (!record.exited) return error.RealmNotQuiescent;
        self.teardown_stop.store(true, .release);
        agent.interruptWaiters();
        self.cancelAllTimers();
        self.microtasks.clearRetainingCapacity();
        self.next_ticks.clearRetainingCapacity();
        self.unhandled_rejections.clearRetainingCapacity();
        self.handled_rejections.clearRetainingCapacity();
        self.finalization_cleanup_jobs.clearRetainingCapacity();
        self.async_waiters.clearRetainingCapacity();
        for (self.protected_values.items) |handle| self.gpa.destroy(handle);
        self.protected_values.clearRetainingCapacity();
        self.private_strong_roots.clearRetainingCapacity();
        self.c_api_handles.clearRetainingCapacity();
        state.realms.retireQuiescent(self) catch |err| switch (err) {
            error.RealmNotRegistered => {
                if (state.realms.realmForId(self.gc_realm_id) != self) return err;
            },
            else => return err,
        };
        const saved = gc_mod.setActiveContext(owner);
        owner.collectGarbage();
        gc_mod.restoreActiveContext(saved);
        try state.realms.releaseRetired(self);

        self.gc = null;
        self.gc_binding = null;
        self.gc_cell_backing = null;
        self.gc_state = null;
        const host_gpa = self.host_gpa;
        const context_gpa = self.gpa;
        const budget_allocator = self.budget_allocator;
        const runtime_attribution_profiler = self.runtime_attribution_profiler;
        const host_allocator_lock = self.host_allocator_lock;
        self.deinitSharedRealmState();
        if (self.locked_arena) |la| {
            la.resetLocalFor();
            context_gpa.destroy(la);
            self.locked_arena = null;
        }
        self.arena_state.deinit();
        context_gpa.destroy(self.arena_state);
        context_gpa.destroy(self);
        if (runtime_attribution_profiler) |profile| host_gpa.destroy(profile);
        if (budget_allocator) |ba| {
            ba.deinit();
            host_gpa.destroy(ba);
        }
        if (host_allocator_lock) |lock| host_gpa.destroy(lock);
    }

    pub fn initCApiRef(self: *Context) void {
        self.c_api_ref_count.store(1, .release);
    }

    pub fn retainCApiRef(self: *Context) bool {
        var current = self.c_api_ref_count.load(.monotonic);
        while (true) {
            if (current == std.math.maxInt(usize)) return false;
            if (self.c_api_ref_count.cmpxchgWeak(current, current + 1, .monotonic, .monotonic)) |observed| {
                current = observed;
                continue;
            }
            return true;
        }
    }

    pub fn releaseCApiRef(self: *Context) bool {
        var current = self.c_api_ref_count.load(.acquire);
        while (true) {
            if (current == 0) return true;
            const next = current - 1;
            if (self.c_api_ref_count.cmpxchgWeak(current, next, .acq_rel, .acquire)) |observed| {
                current = observed;
                continue;
            }
            return next == 0;
        }
    }

    pub fn createExternalBufferOwner(
        self: *Context,
        bytes: ?*anyopaque,
        deallocator: ?value.ExternalBufferDeallocator,
        deallocator_context: ?*anyopaque,
    ) !*value.ExternalBufferOwner {
        const owner = try self.gpa.create(value.ExternalBufferOwner);
        errdefer self.gpa.destroy(owner);
        owner.* = .{
            .bytes = bytes,
            .deallocator = deallocator,
            .deallocator_context = deallocator_context,
        };
        try self.external_buffer_owners.append(self.gpa, owner);
        return owner;
    }

    pub fn queueExternalOwnerRelease(self: *Context, owner: *value.ExternalBufferOwner) void {
        if (owner.released.load(.acquire)) return;
        if (owner.release_queued.swap(true, .acq_rel)) return;
        var head = self.external_owner_release_head.load(.acquire);
        while (true) {
            owner.pending_next = head;
            if (self.external_owner_release_head.cmpxchgWeak(head, owner, .release, .acquire)) |observed| {
                head = observed;
                continue;
            }
            return;
        }
    }

    pub fn createExternalStringOwner(
        self: *Context,
        pointer: ?*anyopaque,
        len: usize,
        callback_context: ?*anyopaque,
        deallocator: strcell.ExternalStringDeallocator,
    ) !*strcell.ExternalStringOwner {
        const owner = try self.gpa.create(strcell.ExternalStringOwner);
        errdefer self.gpa.destroy(owner);
        owner.* = .{
            .pointer = pointer,
            .len = len,
            .context = callback_context,
            .deallocator = deallocator,
        };
        try self.external_string_owners.append(self.gpa, owner);
        return owner;
    }

    pub fn queueExternalStringRelease(self: *Context, owner: *strcell.ExternalStringOwner) void {
        if (owner.released.load(.acquire)) return;
        if (owner.release_queued.swap(true, .acq_rel)) return;
        var head = self.external_string_release_head.load(.acquire);
        while (true) {
            owner.pending_next = head;
            if (self.external_string_release_head.cmpxchgWeak(head, owner, .release, .acquire)) |observed| {
                head = observed;
                continue;
            }
            return;
        }
    }

    pub fn queueCApiObjectFinish(self: *Context, owner: *value.CApiObjectOwner) void {
        if (owner.finalized.load(.acquire)) return;
        if (owner.finish_queued.swap(true, .acq_rel)) return;
        var head = self.c_api_object_finish_head.load(.acquire);
        while (true) {
            owner.pending_next = head;
            if (self.c_api_object_finish_head.cmpxchgWeak(head, owner, .release, .acquire)) |observed| {
                head = observed;
                continue;
            }
            return;
        }
    }

    /// Invoke every callback a cell finalizer published only after zig-gc has
    /// released collector locks. Each intrusive stack is allocation-free on the
    /// sweep path and is drained to a fixed point so reentrant collections are
    /// harmless.
    pub fn runDeferredPostSweepCallbacks(self: *Context) void {
        while (self.external_owner_release_head.swap(null, .acq_rel)) |first| {
            var current: ?*value.ExternalBufferOwner = first;
            while (current) |owner| {
                const next = owner.pending_next;
                owner.pending_next = null;
                owner.release_queued.store(false, .release);
                _ = owner.release();
                current = next;
            }
        }
        while (self.external_string_release_head.swap(null, .acq_rel)) |first| {
            var current: ?*strcell.ExternalStringOwner = first;
            while (current) |owner| {
                const next = owner.pending_next;
                owner.pending_next = null;
                owner.release_queued.store(false, .release);
                _ = owner.release();
                current = next;
            }
        }
        while (self.c_api_object_finish_head.swap(null, .acq_rel)) |first| {
            var current: ?*value.CApiObjectOwner = first;
            while (current) |owner| {
                const next = owner.pending_next;
                owner.pending_next = null;
                owner.finish_queued.store(false, .release);
                owner.finishOnce();
                current = next;
            }
        }
    }

    pub fn trackNativeArrayBufferHandle(self: *Context, handle: *value.NativeArrayBufferHandle) !void {
        self.realmLock();
        defer self.realmUnlock();
        try self.native_array_buffer_handles.append(self.gpa, handle);
    }

    pub fn createCApiObjectOwner(
        self: *Context,
        class_ref: *anyopaque,
        finish_fn: *const fn (*value.CApiObjectOwner) void,
    ) !*value.CApiObjectOwner {
        const owner = try self.gpa.create(value.CApiObjectOwner);
        errdefer self.gpa.destroy(owner);
        owner.* = .{ .allocator = self.gpa, .class_ref = class_ref, .finish_fn = finish_fn };
        spinLockMutex(&self.c_api_object_owner_lock);
        defer self.c_api_object_owner_lock.unlock();
        try self.c_api_object_owners.append(self.gpa, owner);
        return owner;
    }

    fn abortSignalOwnerFromNative(native: *value.AbortSignalNativeState) *AbortSignalOwner {
        return @fieldParentPtr("native", native);
    }

    fn abortSignalTimeoutNowNs() u64 {
        return @intCast(@max(std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds, 0));
    }

    fn removeAbortSignalTimeoutOwnerLocked(self: *Context, target: *AbortSignalOwner) void {
        for (self.abort_signal_timeout_owners.items, 0..) |owner, index| {
            if (owner == target) {
                _ = self.abort_signal_timeout_owners.swapRemove(index);
                return;
            }
        }
    }

    fn refreshAbortSignalTimeoutRoot(owner: *AbortSignalOwner) bool {
        const self = owner.context;
        spinLockMutex(&self.abort_signal_timeout_lock);
        defer self.abort_signal_timeout_lock.unlock();
        const should_root = owner.timeout != null and (owner.js_observed or owner.native_observed);
        if (should_root == owner.rooted) return true;
        self.realmLock();
        defer self.realmUnlock();
        if (should_root) {
            self.private_strong_roots.append(self.gpa, &owner.root) catch return false;
            owner.rooted = true;
            return true;
        }
        for (self.private_strong_roots.items, 0..) |root, index| {
            if (root == &owner.root) {
                _ = self.private_strong_roots.swapRemove(index);
                break;
            }
        }
        owner.rooted = false;
        return true;
    }

    fn setAbortSignalJsObserved(native: *value.AbortSignalNativeState, observed: bool) bool {
        const owner = abortSignalOwnerFromNative(native);
        owner.js_observed = observed;
        return refreshAbortSignalTimeoutRoot(owner);
    }

    fn setAbortSignalNativeObserved(native: *value.AbortSignalNativeState, observed: bool) bool {
        const owner = abortSignalOwnerFromNative(native);
        owner.native_observed = observed;
        return refreshAbortSignalTimeoutRoot(owner);
    }

    fn cancelAbortSignalTimeout(owner: *AbortSignalOwner) void {
        const self = owner.context;
        var timeout: ?*AbortSignalTimeout = null;
        spinLockMutex(&self.abort_signal_timeout_lock);
        if (owner.timeout) |active| {
            active.event_loop_timer.state = .cancelled;
            timeout = active;
            owner.timeout = null;
            owner.deadline_ns = 0;
            owner.native.timeout_handle = null;
            self.removeAbortSignalTimeoutOwnerLocked(owner);
        }
        self.abort_signal_timeout_lock.unlock();
        _ = refreshAbortSignalTimeoutRoot(owner);
        if (timeout) |active| self.gpa.destroy(active);
    }

    fn cancelAbortSignalTimeoutFromNative(native: *value.AbortSignalNativeState) void {
        cancelAbortSignalTimeout(abortSignalOwnerFromNative(native));
    }

    fn finishAbortSignalObject(object_owner: *value.CApiObjectOwner) void {
        const raw = object_owner.payload orelse return;
        const owner: *AbortSignalOwner = @ptrCast(@alignCast(raw));
        object_owner.payload = null;
        cancelAbortSignalTimeout(owner);
        if (owner.native.finish_owner) |finish| finish(owner.native.owner);
        owner.native.owner = null;
        owner.native.run_abort_steps = null;
        owner.native.finish_owner = null;
        owner.context.gpa.destroy(owner);
    }

    fn finishFetchHeadersObject(object_owner: *value.CApiObjectOwner) void {
        const raw = object_owner.payload orelse return;
        object_owner.payload = null;
        const record: *fetch_headers.Record = @ptrCast(@alignCast(raw));
        record.release();
    }

    fn attachFetchHeadersObject(
        raw_context: ?*anyopaque,
        object: *value.Object,
        record: *fetch_headers.Record,
    ) interp.EvalError!void {
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return error.OutOfMemory));
        if (object.private_data_tag != .none or object.private_data != null or object.cApiObjectOwner() != null)
            return error.OutOfMemory;
        const owner = self.createCApiObjectOwner(@ptrCast(record), finishFetchHeadersObject) catch return error.OutOfMemory;
        object.setCApiObjectOwner(self.arena(), owner) catch {
            // Payload is intentionally still null: the caller retains ownership
            // of the record when attachment cannot be completed.
            owner.finishOnce();
            return error.OutOfMemory;
        };
        owner.payload = @ptrCast(record);
        object.private_data = @ptrCast(record);
        object.private_data_tag = .fetch_headers;
    }

    pub fn ensureAbortSignalNativeState(
        self: *Context,
        object: *value.Object,
    ) error{OutOfMemory}!*value.AbortSignalNativeState {
        if (!object.behavior.is_abort_signal) return error.OutOfMemory;
        if (object.private_data_tag == .abort_signal) {
            return @ptrCast(@alignCast(object.private_data orelse return error.OutOfMemory));
        }
        if (object.private_data_tag != .none or object.private_data != null or object.cApiObjectOwner() != null)
            return error.OutOfMemory;

        const owner = self.gpa.create(AbortSignalOwner) catch return error.OutOfMemory;
        owner.* = .{
            .context = self,
            .object = object,
            .root = .{ .value = value.Value.obj(object) },
        };
        owner.native = .{
            .cancel_timeout = cancelAbortSignalTimeoutFromNative,
            .set_js_observed = setAbortSignalJsObserved,
            .set_native_observed = setAbortSignalNativeObserved,
        };
        const object_owner = self.createCApiObjectOwner(@ptrCast(owner), finishAbortSignalObject) catch {
            self.gpa.destroy(owner);
            return error.OutOfMemory;
        };
        object_owner.payload = @ptrCast(owner);
        object.setCApiObjectOwner(self.arena(), object_owner) catch {
            object_owner.finishOnce();
            return error.OutOfMemory;
        };
        object.private_data = @ptrCast(&owner.native);
        object.private_data_tag = .abort_signal;
        return &owner.native;
    }

    fn scheduleAbortSignalTimeout(
        raw_context: ?*anyopaque,
        machine: *interp.Interpreter,
        signal: *value.Object,
        milliseconds: u64,
    ) interp.EvalError!void {
        _ = machine;
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return error.OutOfMemory));
        const native = self.ensureAbortSignalNativeState(signal) catch return error.OutOfMemory;
        const owner = abortSignalOwnerFromNative(native);
        if (owner.timeout != null) cancelAbortSignalTimeout(owner);

        const now = abortSignalTimeoutNowNs();
        const delta = std.math.mul(u64, milliseconds, std.time.ns_per_ms) catch std.math.maxInt(u64);
        const deadline = std.math.add(u64, now, delta) catch std.math.maxInt(u64);
        const generation = self.abort_signal_timeout_generation.load(.acquire);
        const timeout = self.gpa.create(AbortSignalTimeout) catch return error.OutOfMemory;
        timeout.* = .{
            .event_loop_timer = .{
                .next = .{
                    .sec = @intCast(deadline / std.time.ns_per_s),
                    .nsec = @intCast(deadline % std.time.ns_per_s),
                },
                .state = .active,
                .tag = .abort_signal_timeout,
            },
            .signal = @ptrCast(signal),
            .generation = generation,
        };
        spinLockMutex(&self.abort_signal_timeout_lock);
        self.abort_signal_timeout_owners.append(self.gpa, owner) catch {
            self.abort_signal_timeout_lock.unlock();
            self.gpa.destroy(timeout);
            return error.OutOfMemory;
        };
        owner.timeout = timeout;
        owner.deadline_ns = deadline;
        native.timeout_handle = @ptrCast(timeout);
        self.abort_signal_timeout_lock.unlock();
    }

    fn pollAbortSignalTimeouts(
        raw_context: ?*anyopaque,
        machine: *interp.Interpreter,
    ) interp.EvalError!void {
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return));
        while (true) {
            const now = abortSignalTimeoutNowNs();
            const generation = self.abort_signal_timeout_generation.load(.acquire);
            var selected: ?*AbortSignalOwner = null;
            var selected_timeout: ?*AbortSignalTimeout = null;
            var stale = false;

            spinLockMutex(&self.abort_signal_timeout_lock);
            for (self.abort_signal_timeout_owners.items) |owner| {
                const timeout = owner.timeout orelse continue;
                if (timeout.generation != generation or owner.deadline_ns <= now) {
                    selected = owner;
                    selected_timeout = timeout;
                    stale = timeout.generation != generation;
                    break;
                }
            }
            self.abort_signal_timeout_lock.unlock();
            const owner = selected orelse return;
            const timeout = selected_timeout.?;

            // Scope both defers to this timer. Multiple due timers may be
            // drained by one checkpoint, so their temporary roots and native
            // records must not accumulate until the outer function returns.
            {
                var root_mark: ?usize = null;
                if (!stale) root_mark = try machine.pushTempRoot(value.Value.obj(owner.object));
                defer if (root_mark) |mark| machine.restoreTempRoots(mark);

                spinLockMutex(&self.abort_signal_timeout_lock);
                if (owner.timeout != timeout) {
                    self.abort_signal_timeout_lock.unlock();
                    continue;
                }
                timeout.event_loop_timer.state = if (stale) .cancelled else .fired;
                owner.timeout = null;
                owner.deadline_ns = 0;
                owner.native.timeout_handle = null;
                self.removeAbortSignalTimeoutOwnerLocked(owner);
                self.abort_signal_timeout_lock.unlock();

                _ = refreshAbortSignalTimeoutRoot(owner);
                defer self.gpa.destroy(timeout);
                if (!stale) {
                    const reason = try machine.makeDOMException("TimeoutError", "The operation timed out.");
                    try interp.signalAbort(machine, owner.object, reason);
                    // Each fired timeout is its own task. Finish the microtask
                    // checkpoint it created before selecting another due timer;
                    // the interpreter's polling guard prevents recursive timer
                    // selection during this nested drain.
                    try machine.drainMicrotasks();
                }
            }
        }
    }

    pub fn advanceAbortSignalTimeoutGeneration(self: *Context) void {
        var current = self.abort_signal_timeout_generation.load(.monotonic);
        while (true) {
            var next = current +% 1;
            if (next == 0) next = 1;
            if (self.abort_signal_timeout_generation.cmpxchgWeak(current, next, .acq_rel, .monotonic)) |observed| {
                current = observed;
                continue;
            }
            return;
        }
    }

    fn timerNowNs() u64 {
        return @intCast(@max(std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds, 0));
    }

    fn timerDeadline(now: u64, delay_ns: u64) u64 {
        return std.math.add(u64, now, delay_ns) catch std.math.maxInt(u64);
    }

    fn timerIdLiveLocked(self: *Context, id: u64) bool {
        for (self.timers.items) |timer| if (timer.id == id) return true;
        return false;
    }

    fn mintTimerIdLocked(self: *Context) u64 {
        while (true) {
            const id = self.next_timer_id;
            self.next_timer_id +%= 1;
            if (self.next_timer_id == 0 or self.next_timer_id > 9007199254740991) self.next_timer_id = 1;
            if (id != 0 and !self.timerIdLiveLocked(id)) return id;
        }
    }

    fn mintTimerSequenceLocked(self: *Context) u64 {
        const sequence = self.next_timer_sequence;
        self.next_timer_sequence +%= 1;
        if (self.next_timer_sequence == 0) self.next_timer_sequence = 1;
        return sequence;
    }

    fn removeTimerLocked(self: *Context, target: *TimerRecord) bool {
        for (self.timers.items, 0..) |timer, index| {
            if (timer == target) {
                _ = self.timers.swapRemove(index);
                return true;
            }
        }
        return false;
    }

    fn destroyTimer(self: *Context, timer: *TimerRecord) void {
        self.gpa.free(timer.args);
        self.gpa.destroy(timer);
    }

    fn scheduleTimer(
        raw_context: ?*anyopaque,
        machine: *interp.Interpreter,
        callback: value.Value,
        args: []const value.Value,
        delay_ms: u64,
        repeat: bool,
    ) interp.EvalError!u64 {
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return error.OutOfMemory));
        const owner = machine.microtasks orelse return error.OutOfMemory;
        const copied_args = self.gpa.dupe(value.Value, args) catch return error.OutOfMemory;
        errdefer self.gpa.free(copied_args);
        const timer = self.gpa.create(TimerRecord) catch return error.OutOfMemory;
        errdefer self.gpa.destroy(timer);
        const delay_ns = std.math.mul(u64, delay_ms, std.time.ns_per_ms) catch std.math.maxInt(u64);
        const now = timerNowNs();

        self.realmLock();
        defer self.realmUnlock();
        const id = self.mintTimerIdLocked();
        timer.* = .{
            .id = id,
            .owner = owner,
            .callback = callback,
            .args = copied_args,
            .delay_ns = delay_ns,
            .deadline_ns = timerDeadline(now, delay_ns),
            .sequence = self.mintTimerSequenceLocked(),
            .repeat = repeat,
        };
        self.timers.append(self.gpa, timer) catch return error.OutOfMemory;
        // The parallel marker may already have traced the Context root list.
        // Shade every newly published edge as part of the insertion barrier.
        gc_mod.barrierValue(callback);
        for (copied_args) |arg_value| gc_mod.barrierValue(arg_value);
        return id;
    }

    fn cancelTimer(raw_context: ?*anyopaque, machine: *interp.Interpreter, id: u64) void {
        _ = machine;
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return));
        var dead: ?*TimerRecord = null;
        self.realmLock();
        for (self.timers.items) |timer| {
            if (timer.id != id) continue;
            timer.cancelled = true;
            if (!timer.running and self.removeTimerLocked(timer)) dead = timer;
            break;
        }
        self.realmUnlock();
        if (dead) |timer| self.destroyTimer(timer);
    }

    fn setTimerRef(raw_context: ?*anyopaque, machine: *interp.Interpreter, id: u64, refed: ?bool) bool {
        _ = machine;
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return false));
        self.realmLock();
        defer self.realmUnlock();
        for (self.timers.items) |timer| {
            if (timer.id != id or timer.cancelled) continue;
            if (refed) |new_ref| timer.refed = new_ref;
            return timer.refed;
        }
        return false;
    }

    fn refreshTimer(raw_context: ?*anyopaque, machine: *interp.Interpreter, id: u64) bool {
        _ = machine;
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return false));
        self.realmLock();
        defer self.realmUnlock();
        for (self.timers.items) |timer| {
            if (timer.id != id or timer.cancelled) continue;
            timer.deadline_ns = timerDeadline(timerNowNs(), timer.delay_ns);
            timer.sequence = self.mintTimerSequenceLocked();
            timer.refresh_requested = timer.running;
            return true;
        }
        return false;
    }

    fn pollTimers(raw_context: ?*anyopaque, machine: *interp.Interpreter) interp.EvalError!void {
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return));
        const owner = machine.microtasks orelse return;
        while (true) {
            const now = timerNowNs();
            var selected: ?*TimerRecord = null;
            self.realmLock();
            for (self.timers.items) |timer| {
                if (timer.owner != owner or timer.running or timer.cancelled or timer.deadline_ns > now) continue;
                if (selected == null or timer.deadline_ns < selected.?.deadline_ns or
                    (timer.deadline_ns == selected.?.deadline_ns and timer.sequence < selected.?.sequence))
                {
                    selected = timer;
                }
            }
            if (selected) |timer| timer.running = true;
            self.realmUnlock();
            const timer = selected orelse return;

            const call_result = machine.callValueWithThis(timer.callback, timer.args, value.Value.undef());

            var dead = false;
            self.realmLock();
            if (!timer.cancelled and (timer.repeat or timer.refresh_requested)) {
                if (!timer.refresh_requested) timer.deadline_ns = timerDeadline(timerNowNs(), timer.delay_ns);
                timer.sequence = self.mintTimerSequenceLocked();
                timer.running = false;
                timer.refresh_requested = false;
            } else {
                dead = self.removeTimerLocked(timer);
            }
            self.realmUnlock();
            if (dead) self.destroyTimer(timer);

            if (call_result) |_| {} else |err| {
                if (err != error.Throw) return err;
                const thrown = machine.exception;
                machine.exception = value.Value.undef();
                const handled = try interp.handleProcessUncaughtException(machine, thrown, false);
                if (!handled) {
                    machine.exception = thrown;
                    return error.Throw;
                }
            }
            // A timer callback is one task. Drain every job it queued before
            // selecting another due timer; the interpreter polling guard keeps
            // this nested checkpoint from recursively selecting timer tasks.
            try machine.drainMicrotasks();
        }
    }

    fn earliestRefedTimerDeadline(self: *Context, owner: *promise.MicrotaskQueue) ?u64 {
        self.realmLock();
        defer self.realmUnlock();
        var earliest: ?u64 = null;
        for (self.timers.items) |timer| {
            if (timer.owner != owner or timer.cancelled or !timer.refed) continue;
            if (earliest == null or timer.deadline_ns < earliest.?) earliest = timer.deadline_ns;
        }
        return earliest;
    }

    fn keepaliveTimers(raw_context: ?*anyopaque, machine: *interp.Interpreter) void {
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return));
        const owner = machine.microtasks orelse return;
        while (self.earliestRefedTimerDeadline(owner)) |deadline| {
            machine.drainMicrotasks() catch return;
            const next = self.earliestRefedTimerDeadline(owner) orelse return;
            const now = timerNowNs();
            if (next <= now) continue;
            // Bound parks so a peer can cancel/unref a shared-realm timer
            // without leaving the owner asleep until the old deadline.
            const park_ns = @min(next - now, 5 * std.time.ns_per_ms);
            const release_gil = machine.use_thread_gil and machine.gil != null;
            if (release_gil) machine.gil.?.release();
            std.Io.sleep(agent.engineIo(), .fromNanoseconds(@intCast(park_ns)), .awake) catch {};
            if (release_gil) machine.gil.?.acquire();
            _ = deadline;
        }
    }

    fn cancelAllTimers(self: *Context) void {
        self.realmLock();
        var owned = self.timers;
        self.timers = .empty;
        self.realmUnlock();
        for (owned.items) |timer| self.destroyTimer(timer);
        owned.deinit(self.gpa);
    }

    fn abandonTimers(raw_context: ?*anyopaque, machine: *interp.Interpreter) void {
        const self: *Context = @ptrCast(@alignCast(raw_context orelse return));
        const owner = machine.microtasks orelse return;
        while (true) {
            var dead: ?*TimerRecord = null;
            self.realmLock();
            for (self.timers.items) |timer| {
                if (timer.owner != owner) continue;
                _ = self.removeTimerLocked(timer);
                dead = timer;
                break;
            }
            self.realmUnlock();
            if (dead) |timer| {
                self.destroyTimer(timer);
            } else {
                return;
            }
        }
    }

    pub fn findCApiClassPrototype(self: *Context, class_ref: *anyopaque) ?*value.Object {
        self.realmLock();
        defer self.realmUnlock();
        for (self.c_api_class_prototypes.items) |owner| {
            if (owner.class_ref == class_ref) return owner.object;
        }
        return null;
    }

    pub fn createCApiClassPrototype(
        self: *Context,
        class_ref: *anyopaque,
        object: *value.Object,
        finish_fn: *const fn (*value.CApiClassPrototypeOwner) void,
    ) !void {
        const owner = try self.gpa.create(value.CApiClassPrototypeOwner);
        errdefer self.gpa.destroy(owner);
        owner.* = .{ .class_ref = class_ref, .object = object, .finish_fn = finish_fn };
        self.realmLock();
        defer self.realmUnlock();
        try self.c_api_class_prototypes.append(self.gpa, owner);
    }

    pub fn heapBudgetStats(self: *const Context) ?HeapBudgetStats {
        const ba = self.budget_allocator orelse return null;
        return ba.stats();
    }

    pub fn parallelGcStats(self: *const Context) ?ParallelGcStats {
        if (!self.gc_par_enabled) return null;
        return .{
            .attempts = self.gc_par_attempts.load(.monotonic),
            .collections = self.gc_par_collections.load(.monotonic),
            .aborts = self.gc_par_aborts.load(.monotonic),
            .publication_timeout_aborts = self.gc_par_publication_timeout_aborts.load(.monotonic),
            .round_limit_aborts = self.gc_par_round_limit_aborts.load(.monotonic),
            .generations = self.gc_par_generations.load(.monotonic),
            .peer_publications = self.gc_par_peer_publications.load(.monotonic),
            .finish_retries = self.gc_par_finish_retries.load(.monotonic),
            .born_growth_rounds = self.gc_par_born_growth_rounds.load(.monotonic),
            .deferred_rounds = self.gc_par_deferred_rounds.load(.monotonic),
            .deferred_aborts = self.gc_par_deferred_aborts.load(.monotonic),
        };
    }

    pub const RuntimeHeapAccounting = struct {
        live_bytes: usize,
        last_full_collection_bytes: usize,
        collections: usize,
        full_collections: usize,
    };

    /// VM-facing heap accounting used by revision-pinned private bindings.
    /// Precise heaps delegate to zig-gc's race-safe snapshot. Arena heaps report
    /// committed arena capacity, which is the only reclaimable unit they own.
    pub fn runtimeHeapAccounting(self: *Context) RuntimeHeapAccounting {
        if (self.gc) |heap| {
            const accounting = heap.accounting();
            return .{
                .live_bytes = accounting.live_bytes,
                .last_full_collection_bytes = accounting.last_full_collection_bytes,
                .collections = accounting.collections,
                .full_collections = accounting.full_collections,
            };
        }
        if (self.locked_arena) |arena_lock| arena_lock.acquire();
        defer if (self.locked_arena) |arena_lock| arena_lock.unlock();
        const capacity = self.arena_state.queryCapacity();
        return .{
            .live_bytes = capacity,
            .last_full_collection_bytes = capacity,
            .collections = 0,
            .full_collections = 0,
        };
    }

    pub fn automaticGcCompactionStats(self: *const Context) AutomaticGcCompactionStats {
        return .{
            .requests = self.gc_auto_compaction_requests.load(.monotonic),
            .attempts = self.gc_auto_compaction_attempts.load(.monotonic),
            .compacted = self.gc_auto_compaction_compacted.load(.monotonic),
            .no_candidates = self.gc_auto_compaction_no_candidates.load(.monotonic),
            .unsupported = self.gc_auto_compaction_unsupported.load(.monotonic),
            .out_of_memory = self.gc_auto_compaction_out_of_memory.load(.monotonic),
            .moved_cells = self.gc_auto_compaction_moved_cells.load(.monotonic),
            .moved_bytes = self.gc_auto_compaction_moved_bytes.load(.monotonic),
            .shared_attempts = self.gc_auto_compaction_shared_attempts.load(.monotonic),
            .shared_timeouts = self.gc_auto_compaction_shared_timeouts.load(.monotonic),
            .shared_rendezvous_ns_total = self.gc_auto_compaction_shared_rendezvous_ns_total.load(.monotonic),
            .shared_rendezvous_ns_max = self.gc_auto_compaction_shared_rendezvous_ns_max.load(.monotonic),
            .shared_pause_ns_total = self.gc_auto_compaction_shared_pause_ns_total.load(.monotonic),
            .shared_pause_ns_max = self.gc_auto_compaction_shared_pause_ns_max.load(.monotonic),
        };
    }

    pub fn requestGarbageCollection(self: *Context) void {
        if (self.gc != null) self.gc_requested.store(true, .release);
    }

    fn movingCheckpointRequest(self: *Context) *std.atomic.Value(bool) {
        if (self.gc_cell_backing) |backing|
            if (backing.moving_checkpoint_request) |request| return request;
        return &self.gc_moving_checkpoint_requested;
    }

    /// Request one moving collection at the next engine checkpoint that has
    /// published every managed value in precise registered roots and declared
    /// it can resume without raw managed pointers. Generic interpreter/native/
    /// host checkpoints leave the request pending. A direct quiescent
    /// `compactGarbage` call also consumes it after a supported attempt. Raw
    /// Values must not cross the requested movement boundary; use
    /// `ProtectedValue` when the payload must survive it.
    pub fn requestGarbageCompaction(self: *Context) bool {
        if (self.gc == null) return false;
        self.gc_compaction_requested.store(true, .release);
        self.movingCheckpointRequest().store(true, .release);
        return true;
    }

    /// Root a managed Value in address-stable storage. Keep the returned handle
    /// rather than a raw Value copy across `compactGarbage`; call `get` after
    /// movement to read its rewritten payload.
    pub fn protectValue(self: *Context, protected: value.Value) std.mem.Allocator.Error!*ProtectedValue {
        self.assertOwnerThread();
        self.realmLock();
        defer self.realmUnlock();
        const spare = self.protected_values.capacity - self.protected_values.items.len;
        if (spare == 0) try self.protected_values.ensureTotalCapacity(
            self.gpa,
            self.protected_values.items.len + protected_value_reserve_granularity,
        );
        const handle = try self.gpa.create(ProtectedValueRecord);
        handle.* = .{ .owner = self, .value = protected };
        self.protected_values.appendAssumeCapacity(handle);
        return @ptrCast(handle);
    }

    /// Remove and destroy one handle owned by this Context. A pointer absent
    /// from this Context is rejected by list identity without dereference; the
    /// handle becomes invalid after this returns true.
    pub fn unprotectValue(self: *Context, handle: *ProtectedValue) bool {
        self.assertOwnerThread();
        const record: *ProtectedValueRecord = @ptrCast(@alignCast(handle));
        self.realmLock();
        var found = false;
        for (self.protected_values.items, 0..) |candidate, index| {
            if (candidate != record) continue;
            _ = self.protected_values.swapRemove(index);
            found = true;
            break;
        }
        self.realmUnlock();
        if (!found) return false;
        std.debug.assert(record.owner == self);
        self.gpa.destroy(record);
        return true;
    }

    /// Whether the calling thread is the one that created this context.
    pub fn isOwnerThread(self: *const Context) bool {
        return std.Thread.getCurrentId() == self.owner_thread;
    }

    /// Debug-only access check. No-GIL registered interpreters use synchronized
    /// realm state, `.gil = true` requires VM-lock ownership, and non-threaded
    /// contexts require creator-thread affinity. Compiles out in release modes.
    pub fn assertOwnerThread(self: *const Context) void {
        if (comptime debug_build) {
            if (self.gil) |g| {
                if (self.parallel_js) return;
                if (!g.holds()) std.debug.panic(
                    "Context (enable_threads) used without holding the GIL (docs/threads/P6-thread-api.md)",
                    .{},
                );
            } else if (!self.isOwnerThread()) std.debug.panic(
                "Context is single-thread-affine: used from thread {d}, owned by thread {d} (docs/threads/bindings.md)",
                .{ std.Thread.getCurrentId(), self.owner_thread },
            );
        }
    }

    pub fn arena(self: *Context) std.mem.Allocator {
        if (self.locked_arena) |la| return la.allocator();
        return self.arena_state.allocator();
    }

    fn serviceRequestedGcCheckpoint(ctx: *anyopaque) void {
        const self: *Context = @ptrCast(@alignCast(ctx));
        self.collectRequestedGarbage();
    }

    fn recoverAllocationFailure(ctx: *anyopaque) bool {
        const self: *Context = @ptrCast(@alignCast(ctx));
        return self.collectForAllocationFailure(gc_mod.currentInterpreter());
    }

    fn hasRunningJsThreads(self: *const Context) bool {
        const g = self.gil;
        if (g) |threading| threading.lockApi();
        defer if (g) |threading| threading.unlockApi();
        for (self.js_threads.items) |rec| {
            if (!threadRecordExited(rec)) return true;
        }
        return false;
    }

    fn threadRecordExited(rec: *jsthread.ThreadRecord) bool {
        const io = agent.engineIo();
        rec.join_mutex.lockUncancelable(io);
        defer rec.join_mutex.unlock(io);
        return rec.exited;
    }

    pub fn lockActiveInterpreters(self: *Context) void {
        while (self.active_interp_lock.cmpxchgWeak(0, 1, .acquire, .monotonic) != null) std.atomic.spinLoopHint();
        // The parallel tracer takes this lock before walking the interpreter
        // root registry. Registry growth must not collect back into the lock.
        gc_runtime.enterTraceSensitiveLock();
    }
    pub fn unlockActiveInterpreters(self: *Context) void {
        gc_runtime.leaveTraceSensitiveLock();
        self.active_interp_lock.store(0, .release);
    }

    fn realmHasPrivateEnvironmentWrite(realm: *Context) bool {
        realm.lockActiveInterpreters();
        defer realm.unlockActiveInterpreters();
        for (realm.active_interpreters.items) |machine|
            if (machine.gc_private_environment_writes.load(.seq_cst) != 0) return true;
        return false;
    }

    /// Publish concurrent Environment tracing across the shared precise heap
    /// before the collector can touch a binding table, then wait for private
    /// writes in every registered realm that entered before that publication.
    /// Later private writes observe the flag and take each Environment's
    /// ordinary binding lock. The seq_cst pairing with
    /// `gc.tryEnterPrivateEnvironmentWrite` prevents both sides from missing
    /// one another on weakly ordered targets.
    fn beginConcurrentEnvironmentTrace(self: *Context) void {
        const state = self.gc_state orelse unreachable;
        std.debug.assert(state.environment_trace_active.cmpxchgStrong(
            false,
            true,
            .seq_cst,
            .seq_cst,
        ) == null);
        // Binding.traceRoots already establishes registry -> active-interpreter
        // as the lock order. Holding the registry keeps the live realm set fixed
        // while pre-publication writers drain. Include bootstrapping realms so
        // one cannot become a live root source with an older private write still
        // running; retiring realms are included as a fail-closed lifecycle
        // invariant even though retirement already requires quiescence.
        state.realms.acquire();
        defer state.realms.release();
        var spins: usize = 0;
        while (true) : (spins += 1) {
            var private_write_active = realmHasPrivateEnvironmentWrite(state.realms.owner);
            if (!private_write_active) for (state.realms.siblings.items) |realm| {
                if (realmHasPrivateEnvironmentWrite(realm)) {
                    private_write_active = true;
                    break;
                }
            };
            if (!private_write_active) for (state.realms.bootstrapping.items) |realm| {
                if (realmHasPrivateEnvironmentWrite(realm)) {
                    private_write_active = true;
                    break;
                }
            };
            if (!private_write_active) for (state.realms.retiring.items) |realm| {
                if (realmHasPrivateEnvironmentWrite(realm)) {
                    private_write_active = true;
                    break;
                }
            };
            if (!private_write_active) return;
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
    }

    fn endConcurrentEnvironmentTrace(self: *Context) void {
        const state = self.gc_state orelse unreachable;
        std.debug.assert(state.environment_trace_active.swap(false, .seq_cst));
    }

    /// Lock `realm_lock` only under `parallel_js` (a no-op in GIL mode, so those
    /// realm-list mutations stay byte-identical there). Guards `async_waiters`,
    /// public `timers`, `protected_values`, `c_api_handles`, and
    /// `finalization_cleanup_jobs`
    /// against the mid-script parallel collector's reads.
    fn spinLockMutex(m: *std.atomic.Mutex) void {
        var spins: usize = 0;
        while (!m.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
    }
    pub fn appendWasmOwned(self: *Context, owned: WasmOwned) std.mem.Allocator.Error!void {
        spinLockMutex(&self.wasm_registry_lock);
        defer self.wasm_registry_lock.unlock();
        try self.wasm_registry.append(self.gpa, owned);
    }
    pub fn realmLock(self: *Context) void {
        if (self.parallel_js) {
            spinLockMutex(&self.realm_lock);
            gc_runtime.enterTraceSensitiveLock();
        }
    }
    pub fn realmUnlock(self: *Context) void {
        if (self.parallel_js) {
            gc_runtime.leaveTraceSensitiveLock();
            self.realm_lock.unlock();
        }
    }

    /// Deliver private weak-owner cleanup after zig-gc has atomically cleared
    /// dead targets. Claim one callback under the realm lock, then invoke it
    /// unlocked because host cleanup may delete handles or otherwise re-enter.
    pub fn runPrivateWeakFinalizers(self: *Context) void {
        while (true) {
            var found = false;
            var finalize_fn: ?PrivateWeakFinalizeFn = null;
            var finalize_context: ?*anyopaque = null;
            self.realmLock();
            for (self.private_weak_roots.items) |root| {
                if (root.target.load(.acquire) != null) continue;
                if (root.notify_on_collect.cmpxchgStrong(true, false, .acq_rel, .acquire) != null) continue;
                found = true;
                finalize_fn = root.finalize_fn;
                finalize_context = root.finalize_context;
                break;
            }
            self.realmUnlock();
            if (!found) return;
            if (finalize_fn) |function| function(finalize_context);
        }
    }

    /// Lock the realm microtask queue (`microtasks`). The collector takes this
    /// directly while tracing the queue; interpreters lock their current queue.
    pub fn lockMicrotasks(self: *Context) void {
        self.microtasks.acquire();
    }
    pub fn unlockMicrotasks(self: *Context) void {
        self.microtasks.release();
    }

    pub fn pushActiveInterpreter(self: *Context, machine: *interp.Interpreter) !void {
        if (!self.gc_cooperative_enabled) {
            self.lockActiveInterpreters();
            defer self.unlockActiveInterpreters();
            try self.reserveActiveInterpretersLocked(1);
            self.active_interpreters.appendAssumeCapacity(machine);
            return;
        }
        while (true) {
            self.waitForCooperativeGcGate();
            self.lockActiveInterpreters();
            if (self.gc_cooperative_enabled and self.gc_par_request.load(.acquire) != 0) {
                self.unlockActiveInterpreters();
                continue;
            }
            self.reserveActiveInterpretersLocked(1) catch |err| {
                self.unlockActiveInterpreters();
                return err;
            };
            self.active_interpreters.appendAssumeCapacity(machine);
            self.unlockActiveInterpreters();
            return;
        }
    }

    pub fn popActiveInterpreter(self: *Context, machine: *interp.Interpreter) void {
        if (!self.gc_cooperative_enabled) {
            self.lockActiveInterpreters();
            defer self.unlockActiveInterpreters();
            var i: usize = self.active_interpreters.items.len;
            while (i > 0) {
                i -= 1;
                if (self.active_interpreters.items[i] == machine) {
                    _ = self.active_interpreters.swapRemove(i);
                    return;
                }
            }
            return;
        }
        // An abrupt worker exit can bypass the normal collector-return path
        // after publishing ownership (notably a quota OOM during recovery).
        // Only the owning interpreter may close that stale generation; peers
        // must still join a live collector before unregistering.
        if (self.gc_par_request.load(.acquire) != 0 and
            self.gc_par_collector.load(.acquire) == machine)
        {
            self.gc_par_request.store(0, .release);
            self.gc_par_collector.store(null, .release);
            _ = self.gc_cooperative_exit_cleanups.fetchAdd(1, .monotonic);
        }
        while (true) {
            if (self.gc_cooperative_enabled and self.gc_par_request.load(.acquire) != 0 and
                self.gc_par_collector.load(.acquire) != machine)
            {
                self.joinCooperativeGcRequest(machine);
            }
            self.lockActiveInterpreters();
            if (self.gc_cooperative_enabled and self.gc_par_request.load(.acquire) != 0 and
                self.gc_par_collector.load(.acquire) != machine)
            {
                self.unlockActiveInterpreters();
                continue;
            }
            var i: usize = self.active_interpreters.items.len;
            while (i > 0) {
                i -= 1;
                if (self.active_interpreters.items[i] == machine) {
                    _ = self.active_interpreters.swapRemove(i);
                    self.unlockActiveInterpreters();
                    return;
                }
            }
            self.unlockActiveInterpreters();
            return;
        }
    }

    fn waitForCooperativeGcGate(self: *Context) void {
        if (!self.gc_cooperative_enabled) return;
        var spins: usize = 0;
        while (self.gc_par_request.load(.acquire) != 0) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
    }

    const exclusive_phase_idle: u8 = 0;
    const exclusive_phase_gc: u8 = 1;
    const exclusive_phase_mutator_stop: u8 = 2;

    pub const MutatorStop = struct {
        context: *Context,

        pub fn end(self: *MutatorStop) void {
            const context = self.context;
            context.mutator_stop_request.store(0, .release);
            context.mutator_stop_owner.store(null, .release);
            context.jitGcConductor().exclusive_phase.store(exclusive_phase_idle, .release);
        }
    };

    fn mintMutatorStopGeneration(self: *Context) u64 {
        var current = self.mutator_stop_next_request.load(.monotonic);
        while (true) {
            const generation = if (current == 0) 1 else current;
            const next = if (generation == std.math.maxInt(u64)) 1 else generation + 1;
            if (self.mutator_stop_next_request.cmpxchgWeak(current, next, .monotonic, .monotonic)) |observed| {
                current = observed;
                continue;
            }
            return generation;
        }
    }

    fn allMutatorsStoppedAtBoundary(self: *Context, request: u64, owner: *interp.Interpreter) bool {
        self.lockActiveInterpreters();
        defer self.unlockActiveInterpreters();
        for (self.active_interpreters.items) |machine| {
            if (machine == owner) continue;
            if (machine.mutator_stop_published_gen.load(.acquire) != request) return false;
        }
        return true;
    }

    fn joinMutatorStop(raw_context: *anyopaque, raw_machine: *anyopaque) void {
        const self: *Context = @ptrCast(@alignCast(raw_context));
        const machine: *interp.Interpreter = @ptrCast(@alignCast(raw_machine));
        if (self.mutator_stop_owner.load(.acquire) == machine) return;
        const request = self.mutator_stop_request.load(.acquire);
        if (request == 0) return;

        stack_scan.beginPark();
        defer stack_scan.endPark();
        machine.mutator_stop_published_gen.store(request, .release);
        var spins: usize = 0;
        while (self.mutator_stop_request.load(.acquire) == request) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
    }

    /// Stop every peer mutator at a whole-statement/native boundary. The
    /// conductor is held only while publishing the phase, so unrelated JIT
    /// invalidation can proceed while peers are parked. A contending mutator
    /// remains a participant in any GC or earlier operation stop instead of
    /// blocking at an opaque mutex and deadlocking its current owner.
    pub fn beginMutatorStop(self: *Context, machine: *interp.Interpreter) MutatorStop {
        std.debug.assert(self.parallel_js);
        while (true) {
            self.enterJitGcConductorFromInterpreter(machine);
            if (self.jitGcConductor().exclusive_phase.cmpxchgStrong(
                exclusive_phase_idle,
                exclusive_phase_mutator_stop,
                .acq_rel,
                .acquire,
            ) == null) {
                self.mutator_stop_owner.store(machine, .release);
                const request = self.mintMutatorStopGeneration();
                self.mutator_stop_request.store(request, .release);
                self.leaveJitGcConductor();

                var spins: usize = 0;
                while (!self.allMutatorsStoppedAtBoundary(request, machine)) : (spins += 1) {
                    if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
                }
                return .{ .context = self };
            }
            self.leaveJitGcConductor();

            if (self.mutator_stop_request.load(.acquire) != 0) {
                machine.serviceMutatorStopSafepoint();
            } else if (self.gc_cooperative_enabled and self.gc_par_request.load(.acquire) != 0) {
                self.joinCooperativeGcRequest(machine);
            } else if (self.gc_par_collector.load(.acquire) != null) {
                self.publishParallelRoots(machine);
            } else {
                std.Thread.yield() catch {};
            }
        }
    }

    fn jitGcConductor(self: *Context) *JitGcConductor {
        return if (self.gc_state) |state| &state.conductor else &self.local_jit_gc_conductor;
    }

    fn tryEnterJitGcConductor(self: *Context) bool {
        return self.jitGcConductor().lock.tryLock();
    }

    fn enterJitGcConductor(self: *Context) void {
        var waited: u64 = 0;
        var published_waiter = false;
        while (!self.tryEnterJitGcConductor()) : (waited += 1) {
            if (!published_waiter) {
                _ = self.jitGcConductor().waiting_threads.fetchAdd(1, .acq_rel);
                published_waiter = true;
            }
            if ((waited & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
        const conductor = self.jitGcConductor();
        if (published_waiter) _ = conductor.waiting_threads.fetchSub(1, .acq_rel);
        conductor.holder_thread.store(currentThreadId(), .release);
        if (waited != 0) {
            _ = conductor.wait_iterations.fetchAdd(waited, .monotonic);
            self.recordParallelGcMax(&conductor.wait_iterations_max, waited);
        }
    }

    fn currentThreadId() u64 {
        return @intCast(std.Thread.getCurrentId());
    }

    /// Whether this thread is already inside the conductor. The gate is not
    /// reentrant by design — a nested collection would run against a heap that
    /// is mid-sweep — so the callers that a host callback can re-enter check
    /// this and decline instead of spinning against their own lock.
    fn holdsJitGcConductor(self: *Context) bool {
        return self.jitGcConductor().holder_thread.load(.acquire) == currentThreadId();
    }

    /// A mutator waiting to fire Class-A invalidation must remain a GC
    /// safepoint participant. Otherwise a collector holding the conductor can
    /// wait for this same mutator forever.
    fn enterJitGcConductorFromInterpreter(self: *Context, machine: *interp.Interpreter) void {
        var waited: u64 = 0;
        var published_waiter = false;
        while (!self.tryEnterJitGcConductor()) : (waited += 1) {
            if (!published_waiter) {
                _ = self.jitGcConductor().waiting_threads.fetchAdd(1, .acq_rel);
                published_waiter = true;
            }
            if (self.gc_cooperative_enabled and self.gc_par_request.load(.acquire) != 0) {
                self.joinCooperativeGcRequest(machine);
            } else if (self.gc_par_collector.load(.acquire) != null) {
                self.publishParallelRoots(machine);
            } else if ((waited & 0xff) == 0) {
                std.Thread.yield() catch {};
            } else {
                std.atomic.spinLoopHint();
            }
        }
        if (published_waiter) _ = self.jitGcConductor().waiting_threads.fetchSub(1, .acq_rel);
        if (waited != 0) {
            const conductor = self.jitGcConductor();
            _ = conductor.wait_iterations.fetchAdd(waited, .monotonic);
            self.recordParallelGcMax(&conductor.wait_iterations_max, waited);
        }
    }

    fn leaveJitGcConductor(self: *Context) void {
        const conductor = self.jitGcConductor();
        // Clear before unlocking: after the unlock the next holder owns the
        // field, and a stale id there would make an unrelated thread believe
        // it already holds the gate.
        conductor.holder_thread.store(0, .release);
        conductor.lock.unlock();
    }

    /// Class-A invalidation shares the collection conductor. The owner bumps
    /// its generation and jettisons tiers before this scope reopens either
    /// native entry or a later collection publication window.
    pub fn clearJitCode(self: *Context) void {
        self.enterJitGcConductor();
        defer self.leaveJitGcConductor();
        (self.shared_jit_owner orelse &self.jit_owner).clear();
        _ = self.jitGcConductor().class_a_stops.fetchAdd(1, .monotonic);
    }

    fn clearJitCodeFromInterpreter(raw_context: *anyopaque, machine: *interp.Interpreter, shape_token: usize) void {
        const self: *Context = @ptrCast(@alignCast(raw_context));
        self.enterJitGcConductorFromInterpreter(machine);
        defer self.leaveJitGcConductor();
        if ((self.shared_jit_owner orelse &self.jit_owner).clearShape(shape_token))
            _ = self.jitGcConductor().class_a_stops.fetchAdd(1, .monotonic);
    }

    /// Run a precise mark-sweep over the GC heap (Phase 7). Single-threaded, this
    /// is precise: persistent Context roots plus registered active Interpreter
    /// state. With spawned threads it is sound only when this thread holds the
    /// GIL and every peer is parked-and-published, in which case it additionally
    /// conservatively roots this thread's and every parked peer's native stack
    /// (the multi-thread safepoint protocol, `stack_scan.zig`); otherwise it
    /// skips, because a peer may hold an unscanned native-stack root. No-op when
    /// the GC is off.
    pub fn collectGarbage(self: *Context) void {
        const h = self.gc orelse return;
        // A requested shell/host collection is precise only at a realm
        // quiescent point. If spawned threads are still alive, or a
        // mid-script parallel collector is currently elected, leave the request
        // pending for a later checkpoint rather than disturbing its scratch
        // buffers from a joining/draining thread.
        if (self.hasRunningJsThreads()) {
            return;
        }
        if (self.gc_par_collector.load(.acquire) != null) {
            return;
        }
        // A finalizer reached from a collection's own post-sweep drain may call
        // back in — `runDeferredPostSweepCallbacks` documents that as
        // supported, one C-API test is named for it, and the C API lets a
        // `JSObjectMakeArrayBufferWithBytesNoCopy` deallocator call
        // `JSGarbageCollect`. The conductor gate is not reentrant, so that
        // nested request spun against the lock this same thread already held,
        // forever. Decline it instead, on the same footing as the two checks
        // above: a collection is already in flight on this thread and will
        // sweep everything the nested one would have. This covers re-entry from
        // any conductor holder, not just `collectGarbage`, because allocation-
        // failure and quiescent collections run finalizers too.
        if (self.holdsJitGcConductor()) return;
        self.enterJitGcConductor();
        defer self.leaveJitGcConductor();
        if (self.hasRunningJsThreads() or self.gc_par_collector.load(.acquire) != null) return;
        _ = self.finishConcurrentGCIfActive(); // close or abort any in-flight mark first
        if (self.drainConcurrentPostSweepMaintenance(.ordinary_collection, false)) {
            self.gc_requested.store(false, .monotonic);
            return;
        }
        h.collect();
        self.noteQuiescentFullCollection(h);
        wasm_api.collectWasmGarbage(self);
        self.trimCollectedCellBacking(.ordinary_collection);
        self.gc_requested.store(false, .monotonic);
    }

    /// Explicit stop-the-world compaction for a fully quiescent, interpreter-
    /// free realm. Raw `Value`/cell pointers held outside the registered Context
    /// roots are not discoverable, so callers must use stable protected/private
    /// handles across this boundary. The current baseline JIT embeds no movable
    /// pointers, and any live native frame is covered by the active-interpreter
    /// rejection below. Conservative native-stack modes still fail closed;
    /// ordinary `collectGarbage` remains the non-moving path.
    pub fn compactGarbage(self: *Context) GcHeap.CompactionResult {
        return self.compactGarbageChecked(null);
    }

    /// Private moving entry used only by an engine checkpoint that has already
    /// materialized all managed state. The public entry above never supplies an
    /// interpreter and therefore retains its fully quiescent contract.
    fn compactGarbageAtMovingSafepoint(self: *Context, machine: *interp.Interpreter) GcHeap.CompactionResult {
        if (!machine.gc_precise_safepoint or !machine.gc_moving_safepoint)
            return .{ .status = .unsupported };
        return self.compactGarbageChecked(machine);
    }

    fn compactGarbageChecked(self: *Context, allowed_active_interpreter: ?*interp.Interpreter) GcHeap.CompactionResult {
        if (self.gc_state) |state| {
            if (state.realms.owner != self or !state.realms.liveSiblingsAreQuiescent())
                return .{ .status = .unsupported };
        }
        if (self.gc_scan_native_stack or self.gc_scan_parked_stacks)
            return .{ .status = .unsupported };
        if (self.hasRunningJsThreads() or self.gc_par_collector.load(.acquire) != null)
            return .{ .status = .unsupported };

        self.enterJitGcConductor();
        defer self.leaveJitGcConductor();
        const automatic = self.gc_auto_compaction_pending.load(.acquire);
        if (automatic) _ = self.gc_auto_compaction_attempts.fetchAdd(1, .monotonic);
        const result = self.compactGarbageWithConductor(allowed_active_interpreter);
        if (automatic) {
            self.recordAutomaticCompactionResult(result);
            if (result.status != .unsupported)
                self.gc_auto_compaction_pending.store(false, .release);
        }
        return result;
    }

    fn compactGarbageWithConductor(self: *Context, allowed_active_interpreter: ?*interp.Interpreter) GcHeap.CompactionResult {
        if (self.gc_state) |state| {
            if (state.realms.owner != self or !state.realms.liveSiblingsAreQuiescent())
                return .{ .status = .unsupported };
        }
        if (self.gc_scan_native_stack or self.gc_scan_parked_stacks)
            return .{ .status = .unsupported };
        if (self.hasRunningJsThreads() or self.gc_par_collector.load(.acquire) != null)
            return .{ .status = .unsupported };
        self.lockActiveInterpreters();
        const has_active_interpreter = self.active_interpreters.items.len != 0;
        const active_interpreter_can_move = if (allowed_active_interpreter) |machine|
            self.active_interpreters.items.len == 1 and self.active_interpreters.items[0] == machine and
                machine.gc_precise_safepoint and machine.gc_moving_safepoint
        else
            !has_active_interpreter;
        self.unlockActiveInterpreters();
        if (!active_interpreter_can_move) return .{ .status = .unsupported };
        return self.compactGarbageAfterRootValidation(allowed_active_interpreter != null);
    }

    /// Moving entry for the cooperative no-GIL stop. The caller owns the
    /// conductor and collector election, and every peer has release-published a
    /// relocation-safe park for this exact generation. Unlike the public
    /// quiescent entry, live Thread records are expected here; only materialized
    /// interpreter roots are rewritten.
    fn compactGarbageWithCooperativeStop(
        self: *Context,
        machine: *interp.Interpreter,
        request: u64,
    ) GcHeap.CompactionResult {
        if (self.gc_state) |state| {
            if (state.realms.owner != self or !state.realms.liveSiblingsAreQuiescent())
                return .{ .status = .unsupported };
        }
        if (self.gc_scan_native_stack or self.gc_scan_parked_stacks)
            return .{ .status = .unsupported };
        if (self.gc_par_collector.load(.acquire) != machine)
            return .{ .status = .unsupported };
        if (!self.allCooperativePeersAtMovingSafepoint(request, machine))
            return .{ .status = .unsupported };
        return self.compactGarbageAfterRootValidation(true);
    }

    /// Common moving body after the caller proves that every active interpreter
    /// can have its precise slots rewritten. The conductor is held throughout.
    fn compactGarbageAfterRootValidation(self: *Context, moving_safepoint: bool) GcHeap.CompactionResult {
        const h = self.gc orelse return .{ .status = .unsupported };
        if (!moving_safepoint) {
            _ = self.finishConcurrentGCIfActive();
            _ = self.drainConcurrentPostSweepMaintenance(.ordinary_collection, false);
        }
        if (h.marking.load(.acquire) or h.concurrent.load(.acquire))
            return .{ .status = .unsupported };

        if (self.gc_relocation_active.cmpxchgStrong(false, true, .acq_rel, .acquire) != null)
            return .{ .status = .unsupported };
        defer self.gc_relocation_active.store(false, .release);
        const backing = self.gc_cell_backing orelse return .{ .status = .unsupported };
        backing.beginRelocationPlanning();
        defer backing.endRelocationPlanning();
        const result = h.collectAndCompact();
        if (!moving_safepoint and result.status != .unsupported and result.status != .out_of_memory)
            self.noteQuiescentFullCollection(h);
        wasm_api.collectWasmGarbage(self);
        if (result.status == .compacted or result.status == .no_candidates)
            _ = backing.trimCompactedTailChunks();
        self.gc_requested.store(false, .monotonic);
        self.gc_compaction_requested.store(false, .release);
        self.movingCheckpointRequest().store(false, .release);
        if (builtin.is_test and moving_safepoint)
            _ = self.gc_moving_safepoint_compactions.fetchAdd(1, .monotonic);
        return result;
    }

    /// Relocate the exact survivor set of one nursery cycle. Unlike full-heap
    /// compaction, this does not open a dense-prefix evacuation plan: the
    /// reusable backing reserves ordinary unpublished destinations, while the
    /// Context relocation token keeps every typed root rewriteable.
    fn collectYoungAfterRootValidation(self: *Context, h: *GcHeap) GcHeap.CompactionResult {
        if (h.marking.load(.acquire) or h.concurrent.load(.acquire))
            return .{ .status = .unsupported };
        if (self.gc_relocation_active.cmpxchgStrong(false, true, .acq_rel, .acquire) != null)
            return .{ .status = .unsupported };
        defer self.gc_relocation_active.store(false, .release);

        const result = h.collectYoungAndCompact();
        if (result.status == .compacted or result.status == .no_candidates) {
            if (self.gc_cell_backing) |backing| _ = backing.trimEmptyTailChunks();
        }
        return result;
    }

    /// Keep the normal eight-chunk reuse tail while allocator headroom is
    /// healthy. Once a hard Context cap is within either one sixteenth of its
    /// limit or two base slab refills (whichever is larger), empty slabs compete
    /// directly with result side storage and complete object publication. At
    /// that boundary return every fully empty tail; the next allocation can
    /// still grow a slot-aligned adaptive chunk through #637.
    const CellTailTrimCause = enum {
        ordinary_collection,
        allocation_failure,
    };

    fn shouldReleaseEmptyCellTails(stats: ?HeapBudgetStats, cause: CellTailTrimCause) bool {
        if (cause == .allocation_failure) return true;
        const bounded = stats orelse return false;
        const protected_headroom = @max(
            bounded.limit_bytes / 16,
            2 * GcCellBacking.chunk_bytes,
        );
        return bounded.remaining_bytes < protected_headroom;
    }

    fn trimCollectedCellBacking(self: *Context, cause: CellTailTrimCause) void {
        const backing = self.gc_cell_backing orelse return;
        if (shouldReleaseEmptyCellTails(self.heapBudgetStats(), cause)) {
            _ = backing.trimEmptyTailChunksUnderPressure();
            return;
        }
        _ = backing.trimEmptyTailChunks();
    }

    fn shouldAutoCompactAfterCollection(self: *Context) bool {
        const backing = self.gc_cell_backing orelse return false;
        const pressure = backing.compactionPressure();
        return pressure.reclaimable_bytes >= gc_auto_compaction_min_reclaimable_bytes and
            (pressure.relocatable_live_slots != 0 or pressure.retained_empty_tail_bytes != 0);
    }

    fn scheduleAutomaticCompactionIfNeeded(self: *Context) bool {
        if (!self.shouldAutoCompactAfterCollection()) return false;
        if (self.gc_auto_compaction_pending.cmpxchgStrong(false, true, .acq_rel, .acquire) != null)
            return false;
        _ = self.gc_auto_compaction_requests.fetchAdd(1, .monotonic);
        self.gc_compaction_requested.store(true, .release);
        self.movingCheckpointRequest().store(true, .release);
        return true;
    }

    fn recordAutomaticCompactionResult(self: *Context, result: GcHeap.CompactionResult) void {
        switch (result.status) {
            .compacted => {
                _ = self.gc_auto_compaction_compacted.fetchAdd(1, .monotonic);
                _ = self.gc_auto_compaction_moved_cells.fetchAdd(@intCast(result.moved_cells), .monotonic);
                _ = self.gc_auto_compaction_moved_bytes.fetchAdd(@intCast(result.moved_bytes), .monotonic);
            },
            .no_candidates => _ = self.gc_auto_compaction_no_candidates.fetchAdd(1, .monotonic),
            .unsupported => _ = self.gc_auto_compaction_unsupported.fetchAdd(1, .monotonic),
            .out_of_memory => _ = self.gc_auto_compaction_out_of_memory.fetchAdd(1, .monotonic),
        }
    }

    fn runAutomaticCompactionWithConductor(self: *Context) GcHeap.CompactionResult {
        _ = self.gc_auto_compaction_attempts.fetchAdd(1, .monotonic);
        const result = self.compactGarbageWithConductor(null);
        self.recordAutomaticCompactionResult(result);
        if (result.status != .unsupported)
            self.gc_auto_compaction_pending.store(false, .release);
        return result;
    }

    fn noteQuiescentFullCollection(self: *Context, h: *GcHeap) void {
        const state = self.gc_state orelse return;
        state.quiescent_full_promoted_bytes = h.total_minor_promoted_bytes;
        state.quiescent_full_live_bytes = h.bytes_live;
    }

    fn hasQuiescentPromotionDebt(self: *const Context, h: *const GcHeap) bool {
        const state = self.gc_state orelse return false;
        const promoted_since_full = h.total_minor_promoted_bytes -| state.quiescent_full_promoted_bytes;
        const trusted_live_baseline = @max(
            GcHeap.min_nursery_threshold_bytes,
            state.quiescent_full_live_bytes,
        );
        return promoted_since_full >= trusted_live_baseline;
    }

    /// Automatic quiescent policy used at evaluation boundaries. Young space is
    /// collected only after its nursery threshold; once tenured bytes cross the
    /// full-heap threshold, or promotions since the last quiescent full sweep
    /// equal that sweep's live baseline, the precise collector reclaims old
    /// garbage. The promotion-debt path closes a gap where a mid-script full
    /// sweep observes a transient Promise burst as live, inflates the old-heap
    /// threshold, and otherwise lets that now-dead tenured graph cross host-task
    /// boundaries.
    /// A full collection that leaves a large fragmented or retained slab suffix
    /// schedules one guarded moving pass and records whether the same movement
    /// gates accepted it.
    fn collectQuiescentGarbage(self: *Context) void {
        const h = self.gc orelse return;
        if (self.hasRunningJsThreads()) return;
        if (self.gc_par_collector.load(.acquire) != null) return;
        self.enterJitGcConductor();
        defer self.leaveJitGcConductor();
        if (self.hasRunningJsThreads() or self.gc_par_collector.load(.acquire) != null) return;
        _ = self.finishConcurrentGCIfActive();
        const finished_concurrent = self.drainConcurrentPostSweepMaintenance(.ordinary_collection, true);
        if (finished_concurrent) {
            if (self.gc_auto_compaction_pending.load(.acquire))
                _ = self.runAutomaticCompactionWithConductor();
            return;
        }
        if (self.gc_auto_compaction_pending.load(.acquire)) {
            const result = self.runAutomaticCompactionWithConductor();
            if (result.status != .unsupported) return;
        }
        var full_collection = false;
        if (h.shouldCollectOld() or self.hasQuiescentPromotionDebt(h)) {
            h.collect();
            self.noteQuiescentFullCollection(h);
            full_collection = true;
        } else if (h.shouldCollectYoung()) {
            const result = self.collectYoungAfterRootValidation(h);
            if (result.status == .unsupported) h.collectYoung();
        } else {
            return;
        }
        wasm_api.collectWasmGarbage(self);
        self.trimCollectedCellBacking(.ordinary_collection);
        const scheduled_auto_compaction =
            full_collection and self.scheduleAutomaticCompactionIfNeeded();
        if (scheduled_auto_compaction) _ = self.runAutomaticCompactionWithConductor();
    }

    fn collectRequestedGarbage(self: *Context) void {
        if (!self.gc_requested.load(.monotonic)) return;
        self.collectGarbage();
    }

    /// Emergency retry path for GC cell allocation under an external allocator
    /// cap. Serialized/GIL contexts run a conservative current-thread stack scan
    /// only when peers are frozen by the parking protocol. In no-GIL
    /// `parallel_js`, recovery is allowed only when allocation happened under an
    /// active interpreter that can safely elect the abort/no-sweep parallel
    /// collector; otherwise it fails closed to ordinary OOM.
    /// How long an allocation-failure recovery in GIL mode waits for running
    /// peers to reach their next natural park before refusing to collect.
    /// Long enough to span typical Atomics.wait backoffs; short enough to stay
    /// inside allocation-failure latency budgets (#722).
    const recovery_peer_park_wait: u64 = 50 * std.time.ns_per_ms;

    pub fn collectForAllocationFailure(self: *Context, machine: ?*interp.Interpreter) bool {
        if (self.gc_bootstrapping) return false;
        const h = self.gc orelse return false;
        if (!stack_scan.supported) return false;
        if (self.gc_par_collector.load(.acquire) != null) return false;
        if (self.parallel_js and self.hasRunningJsThreads()) {
            return self.collectForParallelAllocationFailure(h, machine);
        }
        if (self.gil) |g| {
            // Peers release the GIL for non-JS work without publishing a scan
            // range, so demanding an already-all-parked world made heap-cap
            // recovery effectively sticky under sustained multi-thread
            // allocation (#722): the allocating thread's bounded retry threw a
            // second, uncaught OOM before any peer reached its next natural
            // park, even though peers park constantly (Atomics.wait backoffs,
            // join). Wait bounded for the SAME safety predicate instead of
            // requiring it instantly — this is a spin on an existing condition,
            // not a new handshake; on timeout the behavior is exactly the old
            // refusal. Parallel-JS keeps its own conductor-coordinated path.
            if (!g.allOthersParked()) {
                const deadline = timerNowNs() + recovery_peer_park_wait;
                while (!g.allOthersParked()) {
                    if (timerNowNs() >= deadline) return false;
                    std.Thread.yield() catch {};
                }
            }
        } else if (self.hasRunningJsThreads()) {
            return false;
        }
        self.enterJitGcConductor();
        defer self.leaveJitGcConductor();
        if (self.gc_par_collector.load(.acquire) != null) return false;
        _ = self.finishConcurrentGCIfActive();
        if (self.drainConcurrentPostSweepMaintenance(.allocation_failure, false)) {
            self.gc_requested.store(false, .monotonic);
            return true;
        }
        self.gc_scan_native_stack = true;
        defer self.gc_scan_native_stack = false;
        h.collect();
        // The failed request may itself be larger than the ordinary headroom
        // threshold, so recovery gives up every eligible empty suffix.
        self.trimCollectedCellBacking(.allocation_failure);
        self.gc_requested.store(false, .monotonic);
        return true;
    }

    fn collectForParallelAllocationFailure(self: *Context, h: *GcHeap, maybe_machine: ?*interp.Interpreter) bool {
        const machine = maybe_machine orelse return false;
        if (!h.parallel) return false;
        if (gc_runtime.inTraceSensitiveLock()) return false;
        if (self.shouldDeferParallelGcRetry()) return false;
        if (!self.tryEnterJitGcConductor()) return false;
        defer self.leaveJitGcConductor();
        if (self.gc_par_collector.cmpxchgStrong(null, machine, .acq_rel, .acquire) != null) return false;
        _ = self.gc_par_attempts.fetchAdd(1, .monotonic);
        defer self.gc_par_collector.store(null, .release);
        defer self.gc_par_request.store(0, .release);
        // Allocation cannot make progress without a sweep. Give running peers a
        // larger scheduling window than routine opportunistic mid-script GC;
        // this stays bounded and still aborts without sweeping if publication
        // cannot be proven.
        const swept = self.driveParallelCollection(h, machine, 100 * std.time.ns_per_ms);
        if (!swept) return false;
        self.trimCollectedCellBacking(.allocation_failure);
        self.gc_requested.store(false, .monotonic);
        return true;
    }

    /// Heap-growth-triggered collection at an engine step checkpoint, while the
    /// native stack holds live `Value`s. Sound because the GC binding adds two
    /// extra root sources: registered active VM `Exec` operand stacks (precise,
    /// for every active interpreter including parked threads') and a conservative
    /// scan of native stacks + spilled registers (`stack_scan.zig`) — the
    /// collecting thread's own, plus every *parked* peer thread's published
    /// range. No-op unless the GC is on and the conservative scan is available.
    ///
    /// With threads, collection only proceeds when every other registered thread
    /// is parked-and-published (`allOthersParked`); otherwise some peer released
    /// the GIL without publishing a scan range (or is mid startup), so we abort
    /// rather than risk missing a live native-stack root. The collector holds
    /// the GIL throughout, so parked peers cannot run and their stacks stay
    /// frozen during the scan.
    /// Per-`markStep` cell budget for incremental marking (M2): bounds the pause
    /// per safepoint while still draining faster than the mutator allocates
    /// between safepoints, so a cycle converges in a few steps.
    const mark_budget: usize = 4096;

    /// Marker-thread body for concurrent marking (M3): drain grey work + fold in
    /// the mutator's barrier hand-off until the mutator sets `gc_marker_stop`.
    /// Never scans the native stack, never traces a cell born this cycle (those
    /// are deferred to finish), and allocates only on the thread-safe `aux`.
    fn gcMarkerLoop(self: *Context) void {
        const h = self.gc orelse return;
        while (!self.gc_marker_stop.load(.acquire)) {
            if (h.concurrentMarkRound()) std.atomic.spinLoopHint();
        }
    }

    const ConcurrentGcFinishResult = enum {
        inactive,
        finished,
        aborted,
        deferred,
    };

    /// Stop+join the marker and close any in-flight concurrent cycle
    /// (world-stopped: fold born cells, re-scan roots, sweep). Called at the
    /// finish safepoint and every quiescent boundary so a marker never outlives
    /// it. The conductor also makes embedder callbacks drained by the sweep see
    /// an in-flight collection and decline reentrant GC. Context-owned
    /// reclamation is deliberately deferred until a caller reaches a boundary
    /// with no registered interpreter roots.
    fn finishConcurrentGCIfActive(self: *Context) ConcurrentGcFinishResult {
        const h = self.gc orelse return .inactive;
        const entered_conductor = !self.holdsJitGcConductor();
        if (entered_conductor) self.enterJitGcConductor();
        defer if (entered_conductor) self.leaveJitGcConductor();
        if (self.gc_marker) |t| {
            self.gc_marker_stop.store(true, .release);
            t.join();
            self.gc_marker = null;
        }
        if (h.concurrent.load(.acquire)) {
            if (h.parallel) {
                // Parallel mid-script cycles are finished only by the elected
                // driver after its root-publication handshake. A quiescent
                // boundary can safely discard leftover mark state, then run a
                // fresh precise collection if the caller still wants one.
                if (self.gc_par_collector.load(.acquire) != null) return .deferred;
                h.abortConcurrentMarkParallel();
                return .aborted;
            }
            self.gc_scan_native_stack = true;
            defer self.gc_scan_native_stack = false;
            h.finishConcurrentMark();
            self.endConcurrentEnvironmentTrace();
            self.gc_concurrent_post_sweep_pending = true;
            return .finished;
        }
        return .inactive;
    }

    /// Complete the Context half of a concurrent full sweep at a quiescent
    /// boundary. Several mid-script cycles may coalesce behind one pending bit;
    /// their heap finalizers already ran independently, while Wasm reclamation,
    /// slab trimming, and compaction policy depend only on the latest survivor
    /// state and must not be repeated through a counter guess.
    fn drainConcurrentPostSweepMaintenance(
        self: *Context,
        trim_cause: CellTailTrimCause,
        schedule_compaction: bool,
    ) bool {
        if (!self.gc_concurrent_post_sweep_pending) return false;
        self.gc_concurrent_post_sweep_pending = false;
        const h = self.gc orelse return false;
        self.noteQuiescentFullCollection(h);
        wasm_api.collectWasmGarbage(self);
        self.trimCollectedCellBacking(trim_cause);
        if (schedule_compaction) _ = self.scheduleAutomaticCompactionIfNeeded();
        return true;
    }

    fn finishConcurrentGCAtEvaluationBoundary(self: *Context) void {
        _ = self.finishConcurrentGCIfActive();
        _ = self.drainConcurrentPostSweepMaintenance(.ordinary_collection, true);
    }

    /// Reclaim a nursery batch at a safe single-mutator VM checkpoint. This is
    /// deliberately synchronous: the current interpreter is parked in the
    /// safepoint call and active interpreter roots are registered. Generic
    /// paths conservatively scan temporary host/register roots; a specialized
    /// path may prove those roots fully materialized and request precise tracing.
    /// A full or concurrent cycle already in progress keeps ownership of the checkpoint.
    fn collectYoungMidScriptIfNeeded(self: *Context, h: *GcHeap, machine: *interp.Interpreter) bool {
        if (h.marking.load(.acquire) or h.concurrent.load(.acquire)) return false;
        const precise_roots = machine.gc_precise_safepoint;
        const precise_root_amortization_bytes = if (precise_roots and !h.parallel)
            @max(
                @min(precise_gc_nursery_threshold_bytes, h.nursery_threshold_bytes),
                machine.preciseJobRootBytes(),
            )
        else
            0;
        // Exact single-mutator checkpoints have no conservative false roots,
        // so reclaim a cache-local young batch before the wider general nursery
        // threshold. Amortize that collection against the explicit job-root
        // frontier: otherwise a large Promise burst retraces nearly its entire
        // pending tail for every fixed-size nursery refill. A remembered-set
        // failure remains fail-closed and bypasses the amortization floor. With
        // no queued-job frontier, an explicitly lower nursery threshold remains
        // authoritative (including exact moving-nursery checkpoints).
        // Generic, concurrent, and shared checkpoints keep zig-gc's established
        // cadence to avoid repeated promotion of ambiguous roots.
        const force_young_collection = h.nursery_force_full.load(.acquire);
        const below_precise_amortization =
            precise_root_amortization_bytes != 0 and
            h.young_bytes < precise_root_amortization_bytes and
            !force_young_collection;
        if (below_precise_amortization) return false;
        const precise_cache_batch =
            precise_roots and !h.parallel and h.young_bytes >= precise_gc_nursery_threshold_bytes;
        if (!h.shouldCollectYoung() and !precise_cache_batch) return false;
        self.gc_scan_native_stack = !precise_roots;
        defer self.gc_scan_native_stack = false;
        self.gc_scan_parked_stacks = !precise_roots;
        defer self.gc_scan_parked_stacks = false;
        const started_ns = parallelGcNowNs();
        const result = if (precise_roots and machine.gc_moving_safepoint)
            self.collectYoungAfterRootValidation(h)
        else
            GcHeap.CompactionResult{ .status = .unsupported };
        if (result.status == .unsupported) h.collectYoung();
        const elapsed = parallelGcNowNs() -| started_ns;
        _ = self.gc_minor_pause_ns_total.fetchAdd(elapsed, .monotonic);
        self.recordParallelGcMax(&self.gc_minor_pause_ns_max, elapsed);
        return true;
    }

    fn joinCooperativeGcRequest(self: *Context, machine: *interp.Interpreter) void {
        if (self.gc_par_request.load(.acquire) == 0 or
            self.gc_par_collector.load(.acquire) == machine) return;

        machine.gc_moving_parked.store(
            machine.gc_precise_safepoint and machine.gc_moving_safepoint,
            .monotonic,
        );
        stack_scan.beginPark();
        machine.gc_parked.store(true, .release);
        var spins: usize = 0;
        while (true) {
            const request = self.gc_par_request.load(.acquire);
            if (request == 0 or self.gc_par_collector.load(.acquire) == machine) break;
            if (machine.gc_published_gen.load(.monotonic) != request) {
                machine.gc_published_gen.store(request, .release);
                _ = self.gc_cooperative_peer_parks.fetchAdd(1, .monotonic);
            }
            while (self.gc_par_request.load(.acquire) == request) : (spins += 1) {
                if ((spins & 0xff) == 0 and !self.cooperativeCollectorIsActive()) {
                    if (self.gc_par_request.cmpxchgStrong(request, 0, .acq_rel, .acquire) == null) {
                        self.gc_par_collector.store(null, .release);
                        _ = self.gc_cooperative_exit_cleanups.fetchAdd(1, .monotonic);
                    }
                    break;
                }
                if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
            }
            // A successor request can open before this peer has left the old
            // park. Publish it in-place and remain frozen, closing the gap where
            // a back-to-back collector could otherwise observe stale parked
            // state while this mutator resumes.
        }
        machine.lockGcRoots();
        machine.gc_moving_parked.store(false, .monotonic);
        machine.gc_parked.store(false, .release);
        machine.unlockGcRoots();
        stack_scan.endPark();
    }

    fn cooperativeCollectorIsActive(self: *Context) bool {
        const collector = self.gc_par_collector.load(.acquire) orelse return false;
        self.lockActiveInterpreters();
        defer self.unlockActiveInterpreters();
        for (self.active_interpreters.items) |machine| {
            if (machine == collector) return true;
        }
        return false;
    }

    fn allCooperativePeersStopped(self: *Context, request: u64, me: *interp.Interpreter) bool {
        self.lockActiveInterpreters();
        defer self.unlockActiveInterpreters();
        for (self.active_interpreters.items) |machine| {
            if (machine == me) continue;
            if (!machine.gc_parked.load(.acquire)) return false;
            // `gc_parked` can still be true while a peer leaves the preceding
            // request (or while it waits in an unrelated native park). Require
            // this exact generation's publication before treating the peer as
            // stopped; otherwise back-to-back minors can sweep while that peer
            // clears the stale park flag and resumes JavaScript.
            if (machine.gc_published_gen.load(.acquire) != request) return false;
        }
        return true;
    }

    /// Stronger stop predicate for relocation. `gc_parked` alone also covers
    /// native waits whose conservative stack words can be traced but not
    /// rewritten. The release publication of `gc_parked` makes the preceding
    /// moving token and the interpreter's materialized roots visible here.
    fn allCooperativePeersAtMovingSafepoint(self: *Context, request: u64, me: *interp.Interpreter) bool {
        if (!me.gc_precise_safepoint or !me.gc_moving_safepoint) return false;
        self.lockActiveInterpreters();
        defer self.unlockActiveInterpreters();
        for (self.active_interpreters.items) |machine| {
            if (machine == me) continue;
            if (!machine.gc_parked.load(.acquire)) return false;
            if (machine.gc_published_gen.load(.acquire) != request) return false;
            if (!machine.gc_moving_parked.load(.acquire)) return false;
        }
        return true;
    }

    fn hasCooperativeRunningPeer(self: *Context, me: *interp.Interpreter) bool {
        self.lockActiveInterpreters();
        defer self.unlockActiveInterpreters();
        for (self.active_interpreters.items) |machine| {
            if (machine != me and !machine.gc_parked.load(.acquire)) return true;
        }
        return false;
    }

    fn recordCooperativeGcPause(self: *Context, started_ns: u64) void {
        const elapsed = parallelGcNowNs() -| started_ns;
        _ = self.gc_cooperative_pause_ns_total.fetchAdd(elapsed, .monotonic);
        self.recordParallelGcMax(&self.gc_cooperative_pause_ns_max, elapsed);
    }

    fn recordCooperativeGcRendezvous(self: *Context, started_ns: u64) void {
        const elapsed = parallelGcNowNs() -| started_ns;
        _ = self.gc_cooperative_rendezvous_ns_total.fetchAdd(elapsed, .monotonic);
        self.recordParallelGcMax(&self.gc_cooperative_rendezvous_ns_max, elapsed);
    }

    fn recordAutomaticSharedCompactionRendezvous(self: *Context, started_ns: u64) void {
        const elapsed = parallelGcNowNs() -| started_ns;
        _ = self.gc_auto_compaction_shared_rendezvous_ns_total.fetchAdd(elapsed, .monotonic);
        self.recordParallelGcMax(&self.gc_auto_compaction_shared_rendezvous_ns_max, elapsed);
    }

    fn recordAutomaticSharedCompactionPause(self: *Context, started_ns: u64) void {
        const elapsed = parallelGcNowNs() -| started_ns;
        _ = self.gc_auto_compaction_shared_pause_ns_total.fetchAdd(elapsed, .monotonic);
        self.recordParallelGcMax(&self.gc_auto_compaction_shared_pause_ns_max, elapsed);
    }

    /// Reclaim a large shared allocation tranche with every mutator frozen at
    /// an existing lock-free checkpoint, or service pending movement when every
    /// peer reaches its declared relocation-safe checkpoint. The 1 GiB nursery
    /// trigger amortizes native stack publication/scan cost while bounding the
    /// former multi-gigabyte quiescent-only object batch.
    fn serviceCooperativeYoungGc(self: *Context, h: *GcHeap, machine: *interp.Interpreter) void {
        if (self.gc_par_request.load(.acquire) != 0) {
            self.joinCooperativeGcRequest(machine);
            return;
        }
        if (machine.gc_parked.load(.acquire) or self.shouldDeferParallelGcRetry()) return;
        const backing = self.gc_cell_backing orelse return;
        const tranche_ready =
            backing.parallelCellBytesSinceCollection() >= self.gc_cooperative_tranche_bytes;
        const pending_compaction = self.gc_compaction_requested.load(.acquire);
        const exact_moving_checkpoint =
            machine.gc_precise_safepoint and machine.gc_moving_safepoint;
        const compaction_request =
            exact_moving_checkpoint and pending_compaction;
        const nursery_checkpoint_pending =
            !pending_compaction and tranche_ready and h.movingNurseryEnabled() and
            h.shouldCollectYoung() and
            self.movingCheckpointRequest().load(.acquire);
        const moving_nursery_request =
            nursery_checkpoint_pending and exact_moving_checkpoint;
        const moving_request = compaction_request or moving_nursery_request;
        if (!moving_request and !tranche_ready) return;
        // A JIT-enabled heap that crossed the normal tranche gets a bounded
        // chance to reach a declared exact native checkpoint. If it remains in
        // an opaque/tree-walker path for four tranches, fall back to the
        // conservative non-moving minor rather than allowing unbounded growth.
        if (nursery_checkpoint_pending and !exact_moving_checkpoint and
            backing.parallelCellBytesSinceCollection() <
                self.gc_cooperative_tranche_bytes *| 4)
        {
            return;
        }
        // A lone running mutator is faster collecting precisely at the host
        // boundary. Forget its tranche so it pays this registry check only once
        // per GiB rather than at every later VM checkpoint. A pending moving
        // request is different: a live Thread record blocks the host boundary,
        // while this interpreter checkpoint can safely service it by itself.
        if (!moving_request and !pending_compaction and !self.hasCooperativeRunningPeer(machine)) {
            const reset_bytes = backing.resetParallelCellBytesSinceCollection();
            _ = self.gc_cooperative_bytes_reset_total.fetchAdd(reset_bytes, .monotonic);
            self.movingCheckpointRequest().store(false, .release);
            return;
        }
        if (!self.tryEnterJitGcConductor()) {
            if (self.gc_par_request.load(.acquire) != 0) self.joinCooperativeGcRequest(machine);
            return;
        }
        defer self.leaveJitGcConductor();
        if (self.jitGcConductor().exclusive_phase.cmpxchgStrong(
            exclusive_phase_idle,
            exclusive_phase_gc,
            .acq_rel,
            .acquire,
        ) != null) return;
        defer self.jitGcConductor().exclusive_phase.store(exclusive_phase_idle, .release);
        if (self.gc_par_collector.load(.acquire) != null) return;
        if (self.gc_par_collector.cmpxchgStrong(null, machine, .acq_rel, .acquire) != null) {
            if (self.gc_par_request.load(.acquire) != 0) self.joinCooperativeGcRequest(machine);
            return;
        }
        defer self.gc_par_collector.store(null, .release);
        const started_ns = parallelGcNowNs();
        const automatic_moving_request =
            compaction_request and self.gc_auto_compaction_pending.load(.acquire);
        if (!compaction_request)
            _ = self.gc_cooperative_attempts.fetchAdd(1, .monotonic);
        defer if (!compaction_request) self.recordCooperativeGcPause(started_ns);
        defer if (automatic_moving_request)
            self.recordAutomaticSharedCompactionPause(started_ns);

        self.lockActiveInterpreters();
        const request = self.openParallelPublicationGeneration();
        self.unlockActiveInterpreters();
        defer self.gc_par_request.store(0, .release);

        const deadline = parallelGcNowNs() + 100 * std.time.ns_per_ms;
        var spins: usize = 0;
        while (!(if (moving_request)
            self.allCooperativePeersAtMovingSafepoint(request, machine)
        else
            self.allCooperativePeersStopped(request, machine))) : (spins += 1)
        {
            if (parallelGcNowNs() >= deadline) {
                if (moving_request) {
                    if (automatic_moving_request) {
                        _ = self.gc_auto_compaction_shared_timeouts.fetchAdd(1, .monotonic);
                        self.recordAutomaticSharedCompactionRendezvous(started_ns);
                    } else {
                        _ = self.gc_cooperative_timeouts.fetchAdd(1, .monotonic);
                        self.recordCooperativeGcRendezvous(started_ns);
                    }
                } else {
                    _ = self.gc_cooperative_timeouts.fetchAdd(1, .monotonic);
                    self.recordCooperativeGcRendezvous(started_ns);
                }
                self.deferParallelGcRetry();
                return;
            }
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
        if (moving_request) {
            if (automatic_moving_request) {
                self.recordAutomaticSharedCompactionRendezvous(started_ns);
            } else {
                self.recordCooperativeGcRendezvous(started_ns);
            }
            if (moving_nursery_request) {
                const result = self.collectYoungAfterRootValidation(h);
                if (result.status == .unsupported) h.collectYoung();
                const reset_bytes = backing.resetParallelCellBytesSinceCollection();
                _ = self.gc_cooperative_bytes_reset_total.fetchAdd(reset_bytes, .monotonic);
                self.movingCheckpointRequest().store(false, .release);
                self.gc_par_retry_after_ns.store(0, .release);
                _ = self.gc_cooperative_collections.fetchAdd(1, .monotonic);
                _ = self.scheduleAutomaticCompactionIfNeeded();
                return;
            }
            const automatic = self.gc_auto_compaction_pending.load(.acquire);
            if (automatic) {
                _ = self.gc_auto_compaction_attempts.fetchAdd(1, .monotonic);
                _ = self.gc_auto_compaction_shared_attempts.fetchAdd(1, .monotonic);
            }
            const result = self.compactGarbageWithCooperativeStop(machine, request);
            if (automatic) {
                self.recordAutomaticCompactionResult(result);
                if (result.status != .unsupported)
                    self.gc_auto_compaction_pending.store(false, .release);
            }
            if (result.status != .unsupported) {
                const reset_bytes = backing.resetParallelCellBytesSinceCollection();
                _ = self.gc_cooperative_bytes_reset_total.fetchAdd(reset_bytes, .monotonic);
                self.movingCheckpointRequest().store(false, .release);
                self.gc_par_retry_after_ns.store(0, .release);
            }
            return;
        }
        self.recordCooperativeGcRendezvous(started_ns);

        self.gc_scan_native_stack = true;
        self.gc_scan_parked_stacks = true;
        h.collectYoung();
        self.gc_scan_parked_stacks = false;
        self.gc_scan_native_stack = false;
        const reset_bytes = backing.resetParallelCellBytesSinceCollection();
        _ = self.gc_cooperative_bytes_reset_total.fetchAdd(reset_bytes, .monotonic);
        if (!pending_compaction)
            self.movingCheckpointRequest().store(false, .release);
        self.gc_par_retry_after_ns.store(0, .release);
        _ = self.gc_cooperative_collections.fetchAdd(1, .monotonic);
        _ = self.scheduleAutomaticCompactionIfNeeded();
    }

    fn collectMidScript(raw_ctx: *anyopaque, raw_machine: *anyopaque) void {
        const self: *Context = @ptrCast(@alignCast(raw_ctx));
        const machine: *interp.Interpreter = @ptrCast(@alignCast(raw_machine));
        // Root tracing reacquires the realm's promise/object/waiter registries.
        // Native helpers can reach a VM checkpoint while one of those locks is
        // held (for example while publishing an Atomics.waitAsync result). Do
        // not elect or join a collection from that critical section: the
        // current cycle remains abort-safe and a later lock-free checkpoint
        // will publish or collect normally.
        if (gc_runtime.inTraceSensitiveLock()) return;
        const h = self.gc orelse return;
        const precise_roots = machine.gc_precise_safepoint;
        if (machine.gc_moving_safepoint and self.gc_compaction_requested.load(.acquire) and
            !(h.parallel and self.gc_cooperative_enabled))
        {
            const result = self.compactGarbageAtMovingSafepoint(machine);
            if (result.status != .unsupported) return;
        }
        if (!stack_scan.supported) return;
        if (h.parallel and self.gc_cooperative_enabled) {
            self.serviceCooperativeYoungGc(h, machine);
            return;
        }
        // Parallel mid-script collection (opt-in: `parallel_midscript_gc`). Runs
        // even though `gil != null` because `parallel_js` drops the *execution*
        // GIL. Abort-safe; see `serviceParallelGc`.
        if (h.parallel and (self.gc_par_enabled or self.gc_par_collector.load(.acquire) != null)) {
            self.serviceParallelGc(h, machine);
            return;
        }
        if (self.gil != null) return;
        // Parallel-mutator mode (parallel_gc): mid-script collection is not yet
        // safe with multiple mutators running without the GIL — it needs the
        // world-stop/safepoint protocol generalized to parallel threads (a later
        // step of the execution-path GIL drop). Until then, collection in this
        // mode is explicit/quiescent only (`collectGarbage`); skip the safepoint
        // collector so parallel execution never races a marker.
        if (h.parallel) return;
        if (builtin.is_test and precise_roots) _ = self.gc_precise_safepoints.fetchAdd(1, .monotonic);
        // The default cell nursery is useful only if allocation-heavy scripts
        // can reclaim it before returning to a host boundary. A single mutator
        // is stopped here, so collect young garbage directly instead of
        // repeatedly starting full-heap cycles from total live bytes.
        if (self.collectYoungMidScriptIfNeeded(h, machine)) return;
        // M3 concurrent driver (single-mutator, opt-in): begin a concurrent mark
        // at one safepoint and close it at the next, a dedicated marker thread
        // tracing during the window while the mutator runs. Stores feed the marker
        // via the insertion barrier; cells born this cycle are deferred (traced at
        // finish, so the marker never sees a half-built cell); begin/finish
        // snapshot the native stack at the safepoint, and finish re-scans roots.
        if (self.gc_concurrent) {
            if (h.concurrent.load(.acquire)) {
                _ = self.finishConcurrentGCIfActive();
            } else if (h.shouldCollectOld()) {
                self.beginConcurrentEnvironmentTrace();
                self.gc_scan_native_stack = true;
                h.beginConcurrentMark();
                self.gc_scan_native_stack = false;
                self.gc_marker_stop.store(false, .release);
                self.gc_marker = std.Thread.spawn(.{}, gcMarkerLoop, .{self}) catch blk: {
                    self.gc_scan_native_stack = true;
                    h.finishConcurrentMark();
                    self.gc_scan_native_stack = false;
                    self.endConcurrentEnvironmentTrace();
                    break :blk null;
                };
            }
            return;
        }
        // Only advance marking while every peer is parked-and-published: the
        // start/finish root scans then see complete roots (own + parked peers'
        // native stacks), and the collector holds the GIL so those stacks are
        // frozen. Heap stores by peers between steps are caught by the global
        // insertion write barrier; mid-cycle allocations are born grey.
        if (self.gil) |g| {
            if (!g.allOthersParked()) return;
        }
        self.gc_scan_native_stack = !precise_roots;
        defer self.gc_scan_native_stack = false;
        self.gc_scan_parked_stacks = !precise_roots;
        defer self.gc_scan_parked_stacks = false;
        if (h.marking.load(.acquire)) {
            // Drain a bounded slice of the grey set; when it empties, close the
            // cycle (re-scan roots under the GIL, then sweep).
            if (h.markStep(mark_budget)) h.finishMarking();
        } else if (h.shouldCollectOld()) {
            // Begin an incremental cycle: snapshot roots, then let the mutator
            // run between safepoints with the barrier shading its stores.
            h.startMarking();
        }
    }

    // ---- Mid-script parallel collector (issue #1 M3) ----------------------
    //
    // Every interpreter (the host + each spawned `Thread`) reaches this from its
    // safepoint (~every 1024 steps). The first to win the `gc_par_collector`
    // election drives a concurrent mark; the rest publish their precise roots
    // through the insertion barrier and resume — no mutator ever blocks for the
    // collector. The driver is *abort-safe*: it sweeps only after a root
    // handshake confirms every peer has published and the heap is stable, and
    // otherwise discards the mark without freeing anything (falling back to the
    // next quiescent `collectGarbage`). So it can neither deadlock nor
    // use-after-free. See docs/threads/P7-gil-removal.md.

    fn serviceParallelGc(self: *Context, h: *GcHeap, machine: *interp.Interpreter) void {
        if (self.gc_par_collector.load(.acquire)) |c| {
            // A collection is in progress; if we aren't the collector, publish
            // our roots for the requested generation and resume.
            if (c != machine) self.publishParallelRoots(machine);
            return;
        }
        // No collection running. Start one only under heap pressure. After an
        // abort-safe fallback, briefly avoid immediate re-election churn; a
        // quiescent full collection remains the reclaim fallback.
        if (self.shouldDeferParallelGcRetry()) return;
        if (!h.shouldCollect()) return;
        if (!self.tryEnterJitGcConductor()) return;
        defer self.leaveJitGcConductor();
        if (self.jitGcConductor().exclusive_phase.cmpxchgStrong(
            exclusive_phase_idle,
            exclusive_phase_gc,
            .acq_rel,
            .acquire,
        ) != null) return;
        defer self.jitGcConductor().exclusive_phase.store(exclusive_phase_idle, .release);
        if (self.gc_par_collector.load(.acquire)) |collector| {
            if (collector != machine) self.publishParallelRoots(machine);
            return;
        }
        // Elect a single collector; losers publish and resume.
        if (self.gc_par_collector.cmpxchgStrong(null, machine, .acq_rel, .acquire) != null) {
            self.publishParallelRoots(machine);
            return;
        }
        _ = self.gc_par_attempts.fetchAdd(1, .monotonic);
        defer self.gc_par_collector.store(null, .release);
        defer self.gc_par_request.store(0, .release);
        _ = self.driveParallelCollection(h, machine, 25 * std.time.ns_per_ms);
    }

    /// Peer/loser path: if the collector has an open request this interpreter
    /// hasn't served, shade its precise roots into the marker's hand-off buffer
    /// and record the generation. Called from a safepoint (or the park path),
    /// where the interpreter holds no per-structure lock.
    fn publishParallelRoots(self: *Context, machine: *interp.Interpreter) void {
        var req = self.gc_par_request.load(.acquire);
        // The collector arms marking before opening the first publication
        // generation. A peer leaving a native activation during that narrow
        // interval must remain at this safepoint until it can publish the
        // activation's children; otherwise the marker may already have skipped
        // the owner-held Generator in reliance on the handshake.
        var spins: usize = 0;
        while (req == 0 and self.gc_par_collector.load(.acquire) != null) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
            req = self.gc_par_request.load(.acquire);
        }
        if (req == 0) return;
        if (machine.gc_published_gen.load(.acquire) == req) return;
        gc_mod.publishInterpreterRoots(machine, req);
        machine.gc_published_gen.store(req, .release);
        _ = self.gc_par_peer_publications.fetchAdd(1, .monotonic);
    }

    /// Snapshot peer state once for each opened publication generation. Polling
    /// `allParallelPublished` may run thousands of times, so counting there
    /// would turn scheduler latency into a misleading peer metric.
    fn countParallelPeers(self: *Context, me: *interp.Interpreter) void {
        var running: u64 = 0;
        var parked: u64 = 0;
        self.lockActiveInterpreters();
        defer self.unlockActiveInterpreters();
        for (self.active_interpreters.items) |m| {
            if (m == me) continue;
            if (m.gc_parked.load(.acquire)) parked += 1 else running += 1;
        }
        if (running != 0) _ = self.gc_par_running_peer_requests.fetchAdd(running, .monotonic);
        if (parked != 0) _ = self.gc_par_parked_peer_observations.fetchAdd(parked, .monotonic);
    }

    fn recordParallelGcPause(self: *Context, started_ns: i96) void {
        const ended_ns = std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds;
        const elapsed: u64 = @intCast(@max(ended_ns - started_ns, 0));
        _ = self.gc_par_pause_ns_total.fetchAdd(elapsed, .monotonic);
        self.recordParallelGcMax(&self.gc_par_pause_ns_max, elapsed);
    }

    fn recordParallelGcMax(_: *Context, counter: *std.atomic.Value(u64), sample: u64) void {
        var observed = counter.load(.monotonic);
        while (sample > observed) {
            observed = counter.cmpxchgWeak(
                observed,
                sample,
                .monotonic,
                .monotonic,
            ) orelse break;
        }
    }

    fn parallelGcNowNs() u64 {
        return @intCast(@max(std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds, 0));
    }

    fn shouldDeferParallelGcRetry(self: *Context) bool {
        const retry_after = self.gc_par_retry_after_ns.load(.acquire);
        if (retry_after == 0) return false;
        if (parallelGcNowNs() < retry_after) {
            _ = self.gc_par_backoff_skips.fetchAdd(1, .monotonic);
            return true;
        }
        self.gc_par_retry_after_ns.store(0, .release);
        return false;
    }

    fn deferParallelGcRetry(self: *Context) void {
        self.gc_par_retry_after_ns.store(
            parallelGcNowNs() + std.time.ns_per_ms,
            .release,
        );
    }

    /// True once every active peer interpreter (all but the collector) has
    /// published generation `gen`. A peer that has exited is gone from the list;
    /// a peer that parked published via the park path. Never blocks a peer.
    fn allParallelPublished(self: *Context, gen: u64, me: *interp.Interpreter) bool {
        self.lockActiveInterpreters();
        defer self.unlockActiveInterpreters();
        for (self.active_interpreters.items) |m| {
            if (m == me) continue;
            // A parked peer is frozen and traced directly by the collector, so it
            // need not publish; only running peers must reach the generation.
            if (m.gc_parked.load(.acquire)) continue;
            if (m.gc_published_gen.load(.acquire) != gen) return false;
        }
        return true;
    }

    fn openParallelPublicationGeneration(self: *Context) u64 {
        var current = self.gc_par_next_request.load(.monotonic);
        while (true) {
            const gen = if (current == 0) 1 else current;
            const next = if (gen == std.math.maxInt(u64)) 1 else gen + 1;
            if (self.gc_par_next_request.cmpxchgWeak(current, next, .monotonic, .monotonic)) |observed| {
                current = observed;
                continue;
            }
            self.gc_par_request.store(gen, .release);
            return gen;
        }
    }

    fn driveParallelCollection(
        self: *Context,
        h: *GcHeap,
        machine: *interp.Interpreter,
        publication_wait_floor_ns: i96,
    ) bool {
        const started_ns = std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds;
        defer self.recordParallelGcPause(started_ns);
        // BEGIN: whiten + arm the barrier under alloc_lock, then trace the
        // collector-safe roots — realm roots (lock-guarded), this collector's own
        // interpreter + native stack, and parked peers' frozen stacks. Running
        // peers self-publish via the handshake (traceRoots reads gc_par_collector
        // to skip them). gc_par_collector is already set to `machine`.
        self.beginConcurrentEnvironmentTrace();
        defer self.endConcurrentEnvironmentTrace();
        self.gc_scan_native_stack = true;
        h.beginConcurrentMarkParallel();
        self.gc_scan_native_stack = false;

        const base_max_rounds: u32 = 32;
        const max_rounds: u32 = 64;
        // Per-round bound on how long to spend waiting for every running peer to
        // publish before giving up and aborting. Each iteration drains marker
        // work, so this is not pure spinning; a peer reaches its safepoint
        // within ~1024 JS steps, and sync-wait peers now service the same hook at
        // their pump points between bounded 5ms parks. The time floor gives
        // those waiters at least one wake/publish opportunity under local load,
        // TSan slowdown, or core oversubscription.
        const wait_budget: u64 = 50_000;
        var prev_born: usize = h.bornPendingLen();
        var attempt_finish_retries: u64 = 0;
        var round: u32 = 0;
        while (round < max_rounds) : (round += 1) {
            // Open a fresh root-publication generation; peers catch up at their
            // safepoints. Mark concurrently while we wait (the collector is also
            // the marker here — no separate marker thread).
            const gen = self.openParallelPublicationGeneration();
            _ = self.gc_par_generations.fetchAdd(1, .monotonic);
            self.countParallelPeers(machine);
            const deadline_ns = std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds + publication_wait_floor_ns;
            var waited: u64 = 0;
            while (!self.allParallelPublished(gen, machine)) {
                self.gc_scan_native_stack = true;
                _ = h.concurrentMarkRound();
                self.gc_scan_native_stack = false;
                waited += 1;
                const now_ns = std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds;
                if (waited >= wait_budget and now_ns >= deadline_ns) {
                    _ = self.gc_par_publication_wait_iterations.fetchAdd(waited, .monotonic);
                    self.recordParallelGcMax(&self.gc_par_publication_wait_iterations_max, waited);
                    self.gc_scan_native_stack = true;
                    h.abortConcurrentMarkParallel();
                    self.gc_scan_native_stack = false;
                    _ = self.gc_par_aborts.fetchAdd(1, .monotonic);
                    _ = self.gc_par_publication_timeout_aborts.fetchAdd(1, .monotonic);
                    self.deferParallelGcRetry();
                    return false;
                }
                // Yield so peers get scheduled to reach their safepoints and
                // publish, rather than starving them by busy-spinning.
                if ((waited & 0x3ff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
            }
            if (waited != 0) {
                _ = self.gc_par_publication_wait_iterations.fetchAdd(waited, .monotonic);
                self.recordParallelGcMax(&self.gc_par_publication_wait_iterations_max, waited);
            }
            // Everyone published this generation. Drain to local quiescence.
            self.gc_scan_native_stack = true;
            while (!h.concurrentMarkRound()) {}
            self.gc_scan_native_stack = false;

            // On any one-round lull (born-cell set unchanged → peers not
            // mid-allocation, so born payloads are initialized) with nothing
            // deferred (a running peer's generator can't be traced soundly),
            // ATTEMPT to finish. `finishConcurrentMarkParallel` is itself
            // self-checking: it sweeps only if no peer allocated during the
            // finish, otherwise it returns false (having done useful marking) and
            // we simply keep going. So being aggressive here is safe and lets the
            // collector converge as soon as it catches a genuine lull.
            const born = h.bornPendingLen();
            const deferred = h.deferredPendingLen();
            const born_grew = born != prev_born;
            var finish_raced_allocation = false;
            if (born_grew) _ = self.gc_par_born_growth_rounds.fetchAdd(1, .monotonic);
            if (deferred != 0) _ = self.gc_par_deferred_rounds.fetchAdd(1, .monotonic);
            if (!born_grew and deferred == 0) {
                self.gc_scan_native_stack = true;
                const swept = h.finishConcurrentMarkParallel();
                self.gc_scan_native_stack = false;
                if (swept) {
                    _ = self.gc_par_collections.fetchAdd(1, .monotonic);
                    self.gc_par_retry_after_ns.store(0, .release);
                    return true;
                }
                _ = self.gc_par_finish_retries.fetchAdd(1, .monotonic);
                attempt_finish_retries += 1;
                self.recordParallelGcMax(&self.gc_par_finish_retries_max, attempt_finish_retries);
                // Allocation happened during the finish — its born fold already
                // ran, so refresh the baseline and keep marking.
                finish_raced_allocation = true;
            }
            if (round + 1 >= base_max_rounds and round + 1 < max_rounds) {
                if (deferred == 0 and (born_grew or finish_raced_allocation)) {
                    _ = self.gc_par_round_extension_rounds.fetchAdd(1, .monotonic);
                } else {
                    break;
                }
            }
            prev_born = h.bornPendingLen();
        }
        // Couldn't converge within the round budget (heavy continuous allocation
        // or a deferred generator) — abort and let quiescent collection reclaim.
        const deferred_blocked_finish = h.deferredPendingLen() != 0;
        self.gc_scan_native_stack = true;
        h.abortConcurrentMarkParallel();
        self.gc_scan_native_stack = false;
        _ = self.gc_par_aborts.fetchAdd(1, .monotonic);
        _ = self.gc_par_round_limit_aborts.fetchAdd(1, .monotonic);
        if (deferred_blocked_finish) _ = self.gc_par_deferred_aborts.fetchAdd(1, .monotonic);
        self.deferParallelGcRetry();
        return false;
    }

    pub fn queueFinalizationRegistryCleanup(self: *Context, registry: *value.Object) void {
        // Read by the mid-script parallel collector; guard under `realm_lock`
        // (a no-op outside parallel_js).
        self.realmLock();
        defer self.realmUnlock();
        for (self.finalization_cleanup_jobs.items) |queued| {
            if (queued == registry) return;
        }
        self.reserveFinalizationCleanupJobsLocked(1) catch return;
        self.finalization_cleanup_jobs.appendAssumeCapacity(registry);
    }

    pub fn noteWeakWork(self: *Context) void {
        self.gc_weak_work.store(true, .release);
    }

    fn reserveFinalizationCleanupJobsLocked(self: *Context, additional: usize) error{OutOfMemory}!void {
        const spare = self.finalization_cleanup_jobs.capacity - self.finalization_cleanup_jobs.items.len;
        if (spare >= additional) return;
        const extra = @max(additional, finalization_cleanup_queue_reserve_granularity);
        try self.finalization_cleanup_jobs.ensureTotalCapacity(self.gpa, self.finalization_cleanup_jobs.items.len + extra);
    }

    pub fn reserveCApiHandlesLocked(self: *Context, additional: usize) error{OutOfMemory}!void {
        const spare = self.c_api_handles.capacity - self.c_api_handles.items.len;
        if (spare >= additional) return;
        const extra = @max(additional, c_api_handle_reserve_granularity);
        try self.c_api_handles.ensureTotalCapacity(self.gpa, self.c_api_handles.items.len + extra);
    }

    pub fn reserveJsThreadsLocked(self: *Context, additional: usize) error{OutOfMemory}!void {
        const spare = self.js_threads.capacity - self.js_threads.items.len;
        if (spare >= additional) return;
        const extra = @max(additional, js_thread_reserve_granularity);
        try self.js_threads.ensureTotalCapacity(self.gpa, self.js_threads.items.len + extra);
    }

    /// Enable the internal collection profiler for one quiescent benchmark
    /// interval. Normal execution keeps phase clocks disabled; existing
    /// correctness counters remain independent of this diagnostic boundary.
    pub fn beginCooperativeGcProfile(self: *Context) bool {
        if (self.gc == null or self.gc_cell_backing == null or !self.gc_cooperative_enabled) return false;
        std.debug.assert(!self.hasRunningJsThreads());
        self.gc_phase_profile_enabled.store(false, .release);
        inline for (.{
            &self.gc_cooperative_attempts,
            &self.gc_cooperative_collections,
            &self.gc_cooperative_timeouts,
            &self.gc_cooperative_peer_parks,
            &self.gc_cooperative_exit_cleanups,
            &self.gc_cooperative_pause_ns_total,
            &self.gc_cooperative_pause_ns_max,
            &self.gc_cooperative_rendezvous_ns_total,
            &self.gc_cooperative_rendezvous_ns_max,
            &self.gc_minor_profile_cycles,
            &self.gc_minor_prepare_ns_total,
            &self.gc_minor_trace_ns_total,
            &self.gc_minor_sweep_ns_total,
            &self.gc_minor_post_sweep_ns_total,
            &self.gc_full_profile_cycles,
            &self.gc_full_prepare_ns_total,
            &self.gc_full_trace_ns_total,
            &self.gc_full_sweep_ns_total,
            &self.gc_full_post_sweep_ns_total,
            &self.gc_object_batch_calls,
            &self.gc_object_batch_cells,
            &self.gc_object_batch_ns_total,
            &self.gc_object_batch_ns_max,
        }) |counter| counter.store(0, .release);
        self.gc_cooperative_bytes_reset_total.store(0, .release);
        self.gc_cooperative_bytes_at_profile_start.store(
            self.gc_cell_backing.?.parallelCellBytesSinceCollection(),
            .release,
        );
        self.gc_phase_started_ns.store(0, .release);
        self.gc_phase_profile_enabled.store(true, .release);
        return true;
    }

    pub fn endCooperativeGcProfile(self: *Context) ?CooperativeGcProfile {
        self.gc_phase_profile_enabled.store(false, .release);
        return self.cooperativeGcProfile();
    }

    pub fn cooperativeGcProfile(self: *Context) ?CooperativeGcProfile {
        const h = self.gc orelse return null;
        const backing = self.gc_cell_backing orelse return null;
        return .{
            .attempts = self.gc_cooperative_attempts.load(.acquire),
            .collections = self.gc_cooperative_collections.load(.acquire),
            .timeouts = self.gc_cooperative_timeouts.load(.acquire),
            .peer_parks = self.gc_cooperative_peer_parks.load(.acquire),
            .exit_cleanups = self.gc_cooperative_exit_cleanups.load(.acquire),
            .pause_ns_total = self.gc_cooperative_pause_ns_total.load(.acquire),
            .pause_ns_max = self.gc_cooperative_pause_ns_max.load(.acquire),
            .rendezvous_ns_total = self.gc_cooperative_rendezvous_ns_total.load(.acquire),
            .rendezvous_ns_max = self.gc_cooperative_rendezvous_ns_max.load(.acquire),
            .tranche_bytes = self.gc_cooperative_tranche_bytes,
            .bytes_reset_total = self.gc_cooperative_bytes_reset_total.load(.acquire),
            .bytes_at_start = self.gc_cooperative_bytes_at_profile_start.load(.acquire),
            .bytes_since_collection = backing.parallelCellBytesSinceCollection(),
            .minor_profile_cycles = self.gc_minor_profile_cycles.load(.acquire),
            .minor_prepare_ns_total = self.gc_minor_prepare_ns_total.load(.acquire),
            .minor_trace_ns_total = self.gc_minor_trace_ns_total.load(.acquire),
            .minor_sweep_ns_total = self.gc_minor_sweep_ns_total.load(.acquire),
            .minor_post_sweep_ns_total = self.gc_minor_post_sweep_ns_total.load(.acquire),
            .full_profile_cycles = self.gc_full_profile_cycles.load(.acquire),
            .full_prepare_ns_total = self.gc_full_prepare_ns_total.load(.acquire),
            .full_trace_ns_total = self.gc_full_trace_ns_total.load(.acquire),
            .full_sweep_ns_total = self.gc_full_sweep_ns_total.load(.acquire),
            .full_post_sweep_ns_total = self.gc_full_post_sweep_ns_total.load(.acquire),
            .object_batch_calls = self.gc_object_batch_calls.load(.acquire),
            .object_batch_cells = self.gc_object_batch_cells.load(.acquire),
            .object_batch_ns_total = self.gc_object_batch_ns_total.load(.acquire),
            .object_batch_ns_max = self.gc_object_batch_ns_max.load(.acquire),
            .heap = h.accounting(),
            .backing = backing.stats(),
        };
    }

    pub fn recordGcCollectionPhase(self: *Context, boundary: @import("gc").CollectionPhaseBoundary) void {
        const phase_profile_enabled = self.gc_phase_profile_enabled.load(.acquire);
        const runtime_profile = self.runtime_attribution_profiler;
        if (!phase_profile_enabled and runtime_profile == null) return;
        const now = parallelGcNowNs();
        if (runtime_profile) |profile| switch (boundary) {
            .minor_prepare_begin, .full_prepare_begin => profile.beginGcCycle(now),
            .minor_post_sweep_end => profile.finishGcCycle(false, now),
            .full_post_sweep_end => profile.finishGcCycle(true, now),
            else => {},
        };
        if (!phase_profile_enabled) return;
        const started = self.gc_phase_started_ns.swap(now, .acq_rel);
        const elapsed = now -| started;
        switch (boundary) {
            .minor_prepare_begin, .full_prepare_begin => {},
            .minor_trace_begin => _ = self.gc_minor_prepare_ns_total.fetchAdd(elapsed, .monotonic),
            .minor_sweep_begin => _ = self.gc_minor_trace_ns_total.fetchAdd(elapsed, .monotonic),
            .minor_sweep_end => _ = self.gc_minor_sweep_ns_total.fetchAdd(elapsed, .monotonic),
            .minor_post_sweep_end => {
                _ = self.gc_minor_post_sweep_ns_total.fetchAdd(elapsed, .monotonic);
                _ = self.gc_minor_profile_cycles.fetchAdd(1, .monotonic);
            },
            .full_trace_begin => _ = self.gc_full_prepare_ns_total.fetchAdd(elapsed, .monotonic),
            .full_sweep_begin => _ = self.gc_full_trace_ns_total.fetchAdd(elapsed, .monotonic),
            .full_sweep_end => _ = self.gc_full_sweep_ns_total.fetchAdd(elapsed, .monotonic),
            .full_post_sweep_end => {
                _ = self.gc_full_post_sweep_ns_total.fetchAdd(elapsed, .monotonic);
                _ = self.gc_full_profile_cycles.fetchAdd(1, .monotonic);
            },
        }
    }

    pub fn beginGcObjectBatchProfile(self: *Context) ?u64 {
        if (!self.gc_phase_profile_enabled.load(.monotonic)) return null;
        return parallelGcNowNs();
    }

    pub fn finishGcObjectBatchProfile(self: *Context, started_ns: ?u64, cells: usize) void {
        const started = started_ns orelse return;
        const elapsed = parallelGcNowNs() -| started;
        _ = self.gc_object_batch_calls.fetchAdd(1, .monotonic);
        _ = self.gc_object_batch_cells.fetchAdd(cells, .monotonic);
        _ = self.gc_object_batch_ns_total.fetchAdd(elapsed, .monotonic);
        self.recordParallelGcMax(&self.gc_object_batch_ns_max, elapsed);
    }

    /// Called under the Thread API lock after a second worker record is
    /// registered. Lone-worker shared contexts keep their allocation fast path
    /// byte-identical; two or more workers arm cooperative-GC byte accounting.
    pub fn enableCooperativeGcTracking(self: *Context) void {
        if (!self.gc_cooperative_enabled) return;
        const backing = self.gc_cell_backing orelse return;
        backing.parallel_cell_tracking_enabled.store(true, .release);
    }

    fn reserveActiveInterpretersLocked(self: *Context, additional: usize) error{OutOfMemory}!void {
        const spare = self.active_interpreters.capacity - self.active_interpreters.items.len;
        if (spare >= additional) return;
        const extra = @max(additional, active_interpreter_reserve_granularity);
        try self.active_interpreters.ensureTotalCapacity(self.gpa, self.active_interpreters.items.len + extra);
    }

    fn scriptTreeWalkPolicy(source: []const u8) ?interp.BytecodeAdmissionReason {
        const policies = [_]struct { needle: []const u8, reason: interp.BytecodeAdmissionReason }{
            .{ .needle = "let ", .reason = .program_policy_lexical_declaration },
            .{ .needle = "const ", .reason = .program_policy_lexical_declaration },
            .{ .needle = "catch", .reason = .program_policy_catch },
            .{ .needle = "switch", .reason = .program_policy_switch },
            .{ .needle = "label:", .reason = .program_policy_label },
            .{ .needle = "function arguments", .reason = .program_policy_arguments_function },
            .{ .needle = ".caller", .reason = .program_policy_legacy_caller },
            .{ .needle = ".arguments", .reason = .program_policy_legacy_arguments },
            .{ .needle = "\n    function ", .reason = .program_policy_nested_function_declaration },
        };
        for (policies) |policy| {
            if (std.mem.indexOf(u8, source, policy.needle) != null) return policy.reason;
        }
        return null;
    }

    /// Lex + parse + run `source`, returning the completion value. On an
    /// uncaught JS exception this returns `error.Throw` and leaves the thrown
    /// value in `self.exception` for the caller (e.g. the C-API boundary).
    ///
    /// Fast path: compile to bytecode and run on the VM. Programs that use
    /// constructs the compiler doesn't lower yet fall back to the tree-walker,
    /// so behavior is identical either way — the VM just handles the hot subset.
    ///
    /// Conformance runners may change the forced tier after installing their
    /// own host-side assertion scaffolding. Keeping this test-only switch on
    /// Context makes that boundary explicit without exposing it in Options.
    pub fn setBytecodeExecutionModeForTesting(self: *Context, mode: interp.BytecodeExecutionMode) void {
        if (self.gil) |g| if (!self.parallel_js) g.acquire();
        defer if (self.gil) |g| if (!self.parallel_js) g.release();
        self.assertOwnerThread();
        self.bytecode_execution_mode = mode;
    }

    pub fn evaluate(self: *Context, source: []const u8) RunError!value.Value {
        return self.evaluateWithThis(source, Value.obj(self.global_object));
    }

    /// Parse global Script source and apply the same early-error scan as
    /// evaluation, without creating an Interpreter or executing any code.
    pub fn checkScriptSyntax(self: *Context, source: []const u8) RunError!void {
        if (self.gil) |g| if (!self.parallel_js) g.acquire();
        defer if (self.gil) |g| if (!self.parallel_js) g.release();
        self.assertOwnerThread();
        const gc_saved = gc_mod.setActiveContext(self);
        defer gc_mod.restoreActiveContext(gc_saved);
        const sa_saved = strcell.setActiveArena(self.arena());
        defer _ = strcell.setActiveArena(sa_saved);

        const a = self.arena();
        const owned_source = try a.dupe(u8, source);
        self.last_evaluation_diagnostic = null;
        var lex_diagnostic: ?parser_mod.SourceLocation = null;
        var parser = Parser.initWithScratchDiagnostic(a, self.gpa, owned_source, &lex_diagnostic) catch |err| {
            self.last_evaluation_diagnostic = lex_diagnostic orelse parser_mod.sourceLocationAt(owned_source, 0);
            return err;
        };
        parser.useRealmHashKeys(self.root_shape);
        const program = parser.parseProgram() catch |err| {
            self.last_evaluation_diagnostic = parser.errorLocation();
            return err;
        };
        if (program.* == .program) parser.scanEvalContext(program.program, true, true) catch |err| {
            self.last_evaluation_diagnostic = parser.errorLocation();
            return err;
        };
    }

    /// Like `evaluate`, but with an explicit top-level `this` binding. This is
    /// used by the C API's `JSEvaluateScript(thisObject, ...)` entry point while
    /// the plain embedder-facing Zig API keeps the normal Script default of the
    /// global object.
    pub fn evaluateWithThis(self: *Context, source: []const u8, this_value: Value) RunError!value.Value {
        if (self.gil) |g| if (!self.parallel_js) g.acquire();
        defer if (self.gil) |g| if (!self.parallel_js) g.release();
        self.assertOwnerThread();
        const gc_saved = gc_mod.setActiveContext(self);
        defer gc_mod.restoreActiveContext(gc_saved);
        const sa_saved = strcell.setActiveArena(self.arena());
        defer _ = strcell.setActiveArena(sa_saved);
        // Register this frame as the high boundary of the live native stack so a
        // mid-script collection can conservatively root the interpreter's
        // `Value` locals below it (`stack_scan.zig`). Cheap; matters only when
        // the GC is on.
        const ss_saved = stack_scan.enter(@frameAddress());
        defer stack_scan.leave(ss_saved);
        // Close any concurrent mark before returning (runs first at exit, LIFO,
        // so the stack boundary above is still valid for its re-scan).
        defer self.finishConcurrentGCAtEvaluationBoundary();
        // Quiescent point: reclaim garbage from prior evaluations on this
        // context before running (nothing is executing yet, so the Context
        // roots are complete).
        self.collectQuiescentGarbage();
        self.collectRequestedGarbage();
        const a = self.arena();
        const owned_source = try a.dupe(u8, source);
        self.last_evaluation_diagnostic = null;
        var lex_diagnostic: ?parser_mod.SourceLocation = null;
        var parser = Parser.initWithScratchDiagnostic(a, self.gpa, owned_source, &lex_diagnostic) catch |err| {
            self.last_evaluation_diagnostic = lex_diagnostic orelse parser_mod.sourceLocationAt(owned_source, 0);
            return err;
        };
        parser.useRealmHashKeys(self.root_shape);
        const prog = parser.parseProgram() catch |err| {
            self.last_evaluation_diagnostic = parser.errorLocation();
            return err;
        };
        if (self.debug_script_id != 0) {
            const script = self.debugScriptById(self.debug_script_id).?;
            try self.registerDebugLocations(script, parser.statement_locations.items);
        } else {
            _ = try self.registerDebugScriptWithLocations(
                owned_source,
                "",
                1,
                parser.statement_locations.items,
            );
        }
        // Global (Script) code has no `super` binding, so a top-level SuperCall or
        // SuperProperty — including inside a top-level arrow — is an early
        // SyntaxError. (Direct/indirect `eval` runs its own context-aware scan
        // via the interpreter, so this entry is genuine global code only.) The
        // scan descends into arrows but stops at nested functions/classes/methods.
        if (prog.* == .program) parser.scanEvalContext(prog.program, true, true) catch |err| {
            self.last_evaluation_diagnostic = parser.errorLocation();
            return err;
        };
        var machine = self.interpreter();
        machine.this_value = this_value;
        try self.pushActiveInterpreter(&machine);
        defer self.popActiveInterpreter(&machine);
        const ai_saved = gc_mod.setActiveInterpreter(&machine);
        defer _ = gc_mod.setActiveInterpreter(ai_saved);
        // Reserve the successful completion root before any host checkpoint or
        // attacker-controlled script can exhaust the bounded realm. Nested
        // helpers stack above this placeholder; replacing it after evaluation
        // is allocation-free, so a completed script cannot lose its result at
        // the host boundary (#645).
        const result_root_mark = try machine.pushTempRoot(Value.undef());
        defer machine.restoreTempRoots(result_root_mark);
        // A later host entry is a timer checkpoint. Poll before executing the
        // new script so elapsed unrefed timeouts are already observable to it.
        try machine.pollAbortSignalTimeouts();
        try machine.pollTimers();
        // Top-level strictness from the program's directive prologue (the parser
        // leaves `strict` set if it saw a leading `"use strict"`).
        machine.strict = parser.strict;
        var stack_trace_frame = interp.StackTraceCallFrame{
            .function_identity = @intFromPtr(self.global_object),
            .code_type = .global,
        };
        machine.stack_trace_call_frame = &stack_trace_frame;
        self.exception = null;
        // Top-level-script dynamic `import()`: when a module host is installed,
        // resolve specifiers relative to the script's referrer path.
        if (self.mod_host != null) {
            machine.dyn_import = dynImportHook;
            machine.dyn_import_ctx = self;
            machine.defer_trigger = deferTriggerHook;
            machine.defer_trigger_ctx = self;
            machine.cur_module = self.script_referrer;
        }

        const outcome: interp.EvalError!value.Value = admission: {
            if (self.bytecode_execution_mode == .tree_walker) {
                self.bytecode_admission_inventory.record(.program_forced_tree_walker);
                machine.recordExecutionTier(.tree_walker_entries);
                break :admission machine.eval(prog);
            }
            if (self.debug_statement_hook != null) {
                self.bytecode_admission_inventory.record(.program_debugger);
                if (self.bytecode_execution_mode == .required)
                    break :admission machine.throwError("InternalError", "required bytecode program is blocked by debugger execution");
                machine.recordExecutionTier(.tree_walker_entries);
                break :admission machine.eval(prog);
            }
            if (self.bytecode_execution_mode != .required) {
                if (scriptTreeWalkPolicy(owned_source)) |reason| {
                    self.bytecode_admission_inventory.record(reason);
                    machine.recordExecutionTier(.tree_walker_entries);
                    break :admission machine.eval(prog);
                }
            }
            switch (compiler.Compiler.admitProgram(a, prog) catch return error.OutOfMemory) {
                .compiled => |chunk| {
                    self.bytecode_admission_inventory.record(.program_compiled);
                    break :admission vm.run(&machine, chunk, null);
                },
                .rejected => |reason| {
                    self.bytecode_admission_inventory.record(interp.programRejectionAdmission(reason));
                    if (self.bytecode_execution_mode == .required)
                        break :admission machine.throwError("InternalError", "required bytecode program was rejected by the compiler");
                    machine.recordExecutionTier(.tree_walker_entries);
                    break :admission machine.eval(prog);
                },
            }
        };
        // Once script execution completes, its result is no longer present in
        // the interpreter's operand stack. Child Threads can still elect a
        // parallel collection while the host drains microtasks and waits for
        // their completion, so fill the pre-reserved precise root for that
        // whole interval rather than allocating here or relying on a native
        // local/register.
        if (outcome) |result| machine.setTempRoot(result_root_mark, result) else |_| {}
        const top_level_failed = if (outcome) |_| false else |_| true;
        if (outcome) |_| {} else |err| {
            if (err == error.Throw) {
                if (!machine.debug_exception_origin_notified) machine.notifyDebuggerException(false) catch |notify_err| {
                    if (notify_err != error.Throw) return notify_err;
                };
                machine.notifyDebuggerException(true) catch |notify_err| {
                    if (notify_err != error.Throw) return notify_err;
                };
            }
        }

        // Microtask checkpoint: run queued Promise reactions before returning, so
        // settled `.then`/`await` continuations and the async harness's `$DONE`
        // have executed by the time `evaluate` returns. Then the waitAsync
        // tail: block for outstanding async waiters (notify/deadline), resolve
        // them, and drain again until quiescent.
        machine.drainMicrotasks() catch {};
        machine.settleAsyncWaiters();
        machine.drainFinalizationCleanupJobs() catch {};
        machine.drainMicrotasks() catch {};
        machine.settleAsyncWaiters();
        if (!top_level_failed) machine.keepaliveTimers();
        // Shell keepalive (threads mode): a pending Thread completion is a
        // pending settlement — the realm stays alive until every spawned
        // thread finishes (each drains its own queue and settles its
        // asyncJoins), then drains whatever those settlements queued here.
        if (self.gil) |g| {
            if (top_level_failed) {
                self.teardown_stop.store(true, .release);
                agent.interruptWaiters();
            }
            var i: usize = 0;
            while (i < self.js_threads.items.len) : (i += 1) {
                const rec = self.js_threads.items[i];
                if (self.parallel_js) {
                    const io = agent.engineIo();
                    // A child may already be exited by the time teardown reaches
                    // its record. Still give an in-flight parallel collector one
                    // host publication/drive point before observing the join
                    // state, otherwise fast exits can skip the safepoint that the
                    // slower parked path below provides.
                    if (self.hasRunningJsThreads()) {
                        machine.serviceMutatorStopSafepoint();
                        machine.serviceGcSafepoint();
                    }
                    rec.join_mutex.lockUncancelable(io);
                    while (!rec.exited) {
                        // Parked keepalive still serves run-loop tasks: a waiting
                        // thread may need a grant delivery pumped to finish.
                        rec.join_mutex.unlock(io);
                        jsthread.pumpTasks(&machine);
                        // This host frame is a registered active interpreter, so a
                        // terminating peer that wins the collector election counts
                        // it in `allParallelPublished`. Between these bounded parks
                        // the host runs no JS safepoint, so publish its precise
                        // roots for the collector's current generation here — else
                        // the collector spins out its budget waiting on a peer that
                        // will not reach a safepoint until every thread has exited,
                        // and aborts the very collection that must finish during
                        // termination (threadfuzz-midgc "did not finish a parallel
                        // collection"). The host stack is stable across the park, so
                        // the published set stays current. No-op when the GC is off.
                        machine.serviceMutatorStopSafepoint();
                        machine.serviceGcSafepoint();
                        rec.join_mutex.lockUncancelable(io);
                        if (rec.exited) break;
                        stack_scan.beginPark();
                        io_compat.conditionWaitTimeout(&rec.done_cond, io, &rec.join_mutex, .{ .duration = .{
                            .raw = .fromMilliseconds(5),
                            .clock = .awake,
                        } }) catch {};
                        stack_scan.endPark();
                    }
                    rec.join_mutex.unlock(io);
                    // Mirror the pre-join tick after the record is observed
                    // exited. This covers the race where the peer exits after the
                    // pump/safepoint but before the host parks, leaving no next
                    // loop iteration to publish roots for a collector elected by
                    // another still-running peer.
                    if (self.hasRunningJsThreads()) {
                        machine.serviceMutatorStopSafepoint();
                        machine.serviceGcSafepoint();
                    }
                } else {
                    while (!threadRecordExited(rec)) {
                        // Parked keepalive still serves run-loop tasks: a waiting
                        // thread may need a grant delivery pumped to finish.
                        jsthread.pumpTasks(&machine);
                        if (threadRecordExited(rec)) break;
                        g.waitTimeout(&rec.done_cond, .{ .duration = .{
                            .raw = .fromMilliseconds(5),
                            .clock = .awake,
                        } }) catch {};
                    }
                }
            }
            // `teardown_stop` exists to make spawned threads leave their
            // blocking loops after a top-level failure. Once every spawned
            // thread has exited, the host still has to drain their asyncJoin
            // rejection reactions. Do that with the main interpreter's stop
            // flag cleared: otherwise a step checkpoint inside a cleanup
            // reaction can throw "worker terminated", abort the microtask batch,
            // and silently drop later reactions copied into that batch.
            if (top_level_failed) self.teardown_stop.store(false, .release);
            machine.drainMicrotasks() catch {};
            machine.settleAsyncWaiters();
            machine.drainFinalizationCleanupJobs() catch {};
            machine.drainMicrotasks() catch {};
            machine.settleAsyncWaiters();
            if (!top_level_failed) machine.keepaliveTimers();
        }
        if (outcome) |result| {
            // A script-visible `gc()` request is serviced before returning to
            // the host, while this interpreter and its result root are still
            // registered as precise root sources.
            self.collectRequestedGarbage();
            return machine.tempRoot(result_root_mark, result);
        } else |err| {
            self.collectRequestedGarbage();
            if (err == error.Throw) self.exception = machine.exception;
            self.surfaceEscapedOutOfMemory(err);
            return err;
        }
    }

    // ----------------------------------------------------------------------
    // ES Modules: load a module graph, link it (wiring `import` bindings to the
    // exporting module's live bindings), then evaluate every module once in
    // dependency order. The *host* resolves a specifier to a canonical path and
    // its source text (the engine itself does no file I/O).
    // ----------------------------------------------------------------------

    /// How the host resolves a module specifier: given the importing module's
    /// canonical path and the specifier string, return the imported module's
    /// source text and write its canonical path into `out_path` (the dedup key),
    /// or null when it cannot be found.
    pub const ModuleHost = struct {
        ctx: *anyopaque,
        load: *const fn (ctx: *anyopaque, referrer: []const u8, specifier: []const u8, out_path: *[]const u8) ?[]const u8,
    };

    const ExportKind = union(enum) {
        local: []const u8, // a binding name in this module's environment
        indirect: struct { module: *Module, name: []const u8 }, // re-export
    };

    fn isSourceImport(entry: ast.ImportEntry) bool {
        return std.mem.eql(u8, entry.imported, "source");
    }

    fn isHostModuleSourceSpecifier(specifier: []const u8) bool {
        return std.mem.eql(u8, specifier, "<module source>");
    }

    pub const Module = struct {
        path: []const u8,
        source: []const u8 = "",
        items: []*ast.Node,
        env: *interp.Environment,
        deps: SecureModuleStringMapUnmanaged(*Module) = .{}, // specifier -> module
        exports: SecureModuleStringMapUnmanaged(ExportKind) = .{}, // exported name -> binding
        star_sources: std.ArrayListUnmanaged(*Module) = .empty, // `export * from`
        ns: ?*value.Object = null, // the namespace exotic object, if requested
        deferred_ns: ?*value.Object = null, // the `import defer` namespace, if requested (distinct, cached)
        import_meta_slot: interp.ImportMetaSlot = .{},
        linked: bool = false,
        eval_started: bool = false, // [[Status]] reached ~evaluating~
        evaluated: bool = false, // [[Status]] reached ~evaluated~ (completed, even if it threw)
        eval_error: ?Value = null, // cached evaluation error for repeated Evaluate()
        has_tla: bool = false,
        eval_index: usize = 0,
        body_hoisted: bool = false,
        async_suspended: bool = false,
        waiting_on_deps: bool = false,
        pending_await: ModuleAwait = .none,
        async_parents: std.ArrayListUnmanaged(*Module) = .empty,
        dynamic_waiters: std.ArrayListUnmanaged(ModuleNamespaceWaiter) = .empty,
        completion_promise: ?*promise.Promise = null,
        cycle_root: ?*Module = null,
        // A synthetic module (`import x from "m" with { type: "json"|"text" }`):
        // its raw source, turned into the sole `default` export at evaluation
        // time per `syn_type` ("json" → JSON.parse, "text" → the string itself).
        // Null for an ordinary JS module (`items` holds its AST instead).
        syn_source: ?[]const u8 = null,
        syn_type: []const u8 = "",
    };

    const ModuleAwait = union(enum) {
        none,
        discard,
        binding: struct { name: []const u8, kind: ast.DeclKind },
        default_export,
    };

    const ModuleAwaitResume = struct {
        ctx: *Context,
        module: *Module,
        rejected: bool,
    };

    const ModuleNamespaceWaiter = struct {
        capability: *promise.Promise,
        namespace: *value.Object,
    };

    fn isSyntheticModuleType(module_type: []const u8) bool {
        return std.mem.eql(u8, module_type, "json") or
            std.mem.eql(u8, module_type, "text") or
            std.mem.eql(u8, module_type, "bytes");
    }

    fn syntheticModuleCacheKey(self: *Context, path: []const u8, syn_type: []const u8) RunError![]const u8 {
        return try std.fmt.allocPrint(self.arena(), "{s}\x00{s}", .{ path, syn_type });
    }

    /// Load, link, and evaluate a module graph rooted at `entry_path`. The
    /// completion is the entry module having run; an uncaught throw leaves the
    /// reason in `self.exception` and returns `error.Throw`.
    pub fn evaluateModule(self: *Context, entry_path: []const u8, entry_source: []const u8, host: ModuleHost) RunError!value.Value {
        if (self.gil) |g| if (!self.parallel_js) g.acquire();
        defer if (self.gil) |g| if (!self.parallel_js) g.release();
        self.assertOwnerThread();
        const gc_saved = gc_mod.setActiveContext(self);
        defer gc_mod.restoreActiveContext(gc_saved);
        const sa_saved = strcell.setActiveArena(self.arena());
        defer _ = strcell.setActiveArena(sa_saved);
        // See `evaluate`: register the native-stack scan boundary for mid-script
        // collection during module execution.
        const ss_saved = stack_scan.enter(@frameAddress());
        defer stack_scan.leave(ss_saved);
        defer self.finishConcurrentGCAtEvaluationBoundary(); // close any concurrent mark (see evaluate)
        // Quiescent point before module execution; a prior shell `gc()` request
        // can be serviced before the live module graph is installed.
        self.collectQuiescentGarbage();
        self.collectRequestedGarbage();
        const root = try self.loadModule(entry_path, entry_source, host, &self.module_registry);
        try self.linkModule(root);
        var machine = self.interpreter();
        try self.pushActiveInterpreter(&machine);
        defer self.popActiveInterpreter(&machine);
        const ai_saved = gc_mod.setActiveInterpreter(&machine);
        defer _ = gc_mod.setActiveInterpreter(ai_saved);
        try machine.pollAbortSignalTimeouts();
        try machine.pollTimers();
        machine.strict = true;
        // Expose the graph to runtime dynamic `import()`.
        const previous_host = self.mod_host;
        const previous_cache = self.mod_cache;
        self.mod_host = host;
        self.mod_cache = &self.module_registry;
        defer {
            self.mod_cache = previous_cache;
            self.mod_host = previous_host;
            self.deferred_async_queue.clearRetainingCapacity();
            self.deferred_async_started.clearRetainingCapacity();
            self.clearCompletedParentQueue();
            self.parent_resume_depth = 0;
        }
        machine.dyn_import = dynImportHook;
        machine.dyn_import_ctx = self;
        machine.defer_trigger = deferTriggerHook;
        machine.defer_trigger_ctx = self;
        // Populate any namespace objects after the whole graph has evaluated, so
        // every exported binding holds its final value.
        const outcome = self.evalModule(&machine, root);
        const module_started = if (outcome) |_| true else |_| false;
        if (module_started) try self.drainUntilModuleSettled(&machine, root);
        machine.drainMicrotasks() catch {};
        machine.settleAsyncWaiters();
        machine.drainFinalizationCleanupJobs() catch {};
        machine.drainMicrotasks() catch {};
        machine.settleAsyncWaiters();
        if (outcome) |_| machine.keepaliveTimers() else |_| {}
        outcome catch |err| {
            if (err == error.Throw) self.exception = machine.exception;
            self.surfaceEscapedOutOfMemory(err);
            return err;
        };
        return Value.undef();
    }

    fn moduleLoaderResolve(self: *Context, referrer: []const u8, specifier: []const u8) ![]const u8 {
        if (specifier.len == 0) return self.arena().dupe(u8, specifier);
        if (std.fs.path.isAbsolute(specifier))
            return std.fs.path.resolve(self.arena(), &.{specifier});
        if (specifier[0] != '.') return self.arena().dupe(u8, specifier);
        const base = std.fs.path.dirname(referrer) orelse "";
        return std.fs.path.resolve(self.arena(), &.{ base, specifier });
    }

    fn moduleLoaderHostLoad(
        opaque_ctx: *anyopaque,
        referrer: []const u8,
        specifier: []const u8,
        out_path: *[]const u8,
    ) ?[]const u8 {
        const self: *Context = @ptrCast(@alignCast(opaque_ctx));
        const path = self.moduleLoaderResolve(referrer, specifier) catch return null;
        out_path.* = path;
        self.realmLock();
        const supplied = self.module_loader_sources.get(path);
        const cached = self.module_registry.get(path);
        self.realmUnlock();
        if (supplied) |source| return source;
        if (cached) |module| return module.source;
        return std.Io.Dir.cwd().readFileAlloc(agent.engineIo(), path, self.arena(), .unlimited) catch null;
    }

    fn installPrivateModuleLoader(self: *Context) void {
        self.mod_host = .{ .ctx = self, .load = moduleLoaderHostLoad };
        self.mod_cache = &self.module_registry;
    }

    /// Register source text under the same canonical loader key used by private
    /// JSC imports. Registration does not invalidate an already-instantiated
    /// module: the module registry remains the identity/cache boundary.
    pub fn provideModuleLoaderSource(self: *Context, origin: []const u8, source: []const u8) ![]const u8 {
        const path = try self.moduleLoaderResolve("", origin);
        const owned_source = try self.arena().dupe(u8, source);
        {
            self.realmLock();
            defer self.realmUnlock();
            try self.module_loader_sources.put(self.arena(), self.root_shape, path, owned_source);
        }
        self.installPrivateModuleLoader();
        return path;
    }

    fn rejectedModuleLoaderPromise(self: *Context, machine: *interp.Interpreter, err: anyerror) RunError!Value {
        const reason = if (err == error.Throw and self.exception != null)
            self.exception.?
        else if (err == error.Throw and !machine.exception.isUndefined())
            machine.exception
        else
            try machine.makeError("SyntaxError", "Cannot load or evaluate module");
        self.exception = null;
        machine.exception = Value.undef();
        return Value.obj(try promise.newRejectedPromise(machine, reason));
    }

    /// Resolve, link, and begin evaluating a module through the persistent
    /// private loader. The returned value is always an intrinsic Promise whose
    /// fulfillment value is the cached module namespace. Top-level await stays
    /// pending until a later host microtask checkpoint.
    pub fn loadAndEvaluateModule(self: *Context, specifier: []const u8, referrer: []const u8) RunError!Value {
        if (self.gil) |g| if (!self.parallel_js) g.acquire();
        defer if (self.gil) |g| if (!self.parallel_js) g.release();
        self.assertOwnerThread();
        const gc_saved = gc_mod.setActiveContext(self);
        defer gc_mod.restoreActiveContext(gc_saved);
        const sa_saved = strcell.setActiveArena(self.arena());
        defer _ = strcell.setActiveArena(sa_saved);
        const ss_saved = stack_scan.enter(@frameAddress());
        defer stack_scan.leave(ss_saved);
        defer self.finishConcurrentGCAtEvaluationBoundary();
        self.collectQuiescentGarbage();
        self.collectRequestedGarbage();
        self.installPrivateModuleLoader();
        self.exception = null;

        var machine = self.interpreter();
        try self.pushActiveInterpreter(&machine);
        defer self.popActiveInterpreter(&machine);
        const ai_saved = gc_mod.setActiveInterpreter(&machine);
        defer _ = gc_mod.setActiveInterpreter(ai_saved);
        try machine.pollAbortSignalTimeouts();
        try machine.pollTimers();
        machine.strict = true;

        var path: []const u8 = "";
        const host = self.mod_host.?;
        const source = host.load(host.ctx, referrer, specifier, &path) orelse {
            machine.throwError("TypeError", "Cannot resolve module specifier") catch {};
            self.exception = machine.exception;
            return self.rejectedModuleLoaderPromise(&machine, error.Throw);
        };
        const root = self.loadModule(path, source, host, &self.module_registry) catch |err|
            return self.rejectedModuleLoaderPromise(&machine, err);
        self.linkModule(root) catch |err|
            return self.rejectedModuleLoaderPromise(&machine, err);
        self.evalModule(&machine, root) catch |err|
            return self.rejectedModuleLoaderPromise(&machine, err);

        const namespace = self.namespaceObject(root) catch |err|
            return self.rejectedModuleLoaderPromise(&machine, err);
        if (!root.evaluated)
            return self.moduleNamespaceAfterCompletion(&machine, root, namespace) catch |err|
                return self.rejectedModuleLoaderPromise(&machine, err);
        if (root.eval_error) |reason|
            return Value.obj(try promise.newRejectedPromise(&machine, reason));
        try self.fillNamespace(&machine, root, namespace);
        const result = try promise.newPromise(&machine);
        try promise.resolve(&machine, promise.promiseOf(Value.obj(result)).?, Value.obj(namespace));
        return Value.obj(result);
    }

    /// Remove one exact loader key from this realm. Module graph tracing takes
    /// the same realm lock under parallel collection, matching JSC's cellLock
    /// synchronization without serializing the ordinary single-thread path.
    pub fn deleteModuleRegistryEntry(self: *Context, key: []const u8) bool {
        self.realmLock();
        defer self.realmUnlock();
        _ = self.module_loader_sources.remove(key);
        return self.module_registry.remove(key);
    }

    /// Clear loader-visible modules and the cached module-source object for the
    /// pinned delete-all-code boundary.
    pub fn clearModuleRegistry(self: *Context) void {
        self.realmLock();
        defer self.realmUnlock();
        self.module_registry.clearRetainingCapacity();
        self.module_loader_sources.clearRetainingCapacity();
        self.module_source_object = null;
    }

    fn putModuleCache(
        self: *Context,
        cache: *ModuleCache,
        key: []const u8,
        module: *Module,
    ) RunError!void {
        if (cache == &self.module_registry) self.realmLock();
        defer if (cache == &self.module_registry) self.realmUnlock();
        try cache.put(self.arena(), self.root_shape, key, module);
    }

    /// Recursively load and parse a module and its dependencies into `cache`
    /// (keyed by canonical path), collecting each module's imports and exports.
    fn loadModule(self: *Context, path: []const u8, source: []const u8, host: ModuleHost, cache: *ModuleCache) RunError!*Module {
        if (cache.get(path)) |m| return m;
        const a = self.arena();

        const owned_source = try a.dupe(u8, source);
        var parser = try Parser.initWithScratch(a, self.gpa, owned_source);
        parser.useRealmHashKeys(self.root_shape);
        const prog = try parser.parseModule();
        _ = try self.registerDebugScriptWithLocations(
            owned_source,
            path,
            1,
            parser.statement_locations.items,
        );
        const items = prog.program;

        const env = try gc_mod.allocEnv(a);
        // A module environment is a variable scope whose parent is the global
        // scope (so globals resolve), but its own declarations stay module-local.
        env.* = .{
            .arena = a,
            .binding_hash_state = .{ .realm_shape = self.root_shape },
            .bindings_allocator = if (self.gc != null) self.gpa else null,
            .gc_name_bytes_live = if (self.gc != null) &self.gc_environment_name_bytes_live else null,
            .parent = &self.env,
            .gc_managed = gc_mod.allocationsAreManaged(),
            .fn_scope = true,
        };

        const m = try a.create(Module);
        m.* = .{
            .path = try a.dupe(u8, path),
            .source = owned_source,
            .items = items,
            .env = env,
            .has_tla = moduleItemsHaveTopLevelAwait(items),
        };
        try self.putModuleCache(cache, m.path, m);

        // Load every dependency and record this module's export map.
        for (items) |item| switch (item.*) {
            .import_decl => |imp| {
                const source_only = imp.entries.len == 1 and isSourceImport(imp.entries[0]);
                if (!source_only)
                    _ = try self.loadDep(m, imp.specifier, imp.attr_type, host, cache);
            },
            .export_decl => |e| {
                if (e.from.len > 0) _ = try self.loadDep(m, e.from, "", host, cache);
                try self.collectExports(m, e);
            },
            else => {},
        };
        return m;
    }

    fn moduleItemsHaveTopLevelAwait(items: []const *ast.Node) bool {
        for (items) |item| if (nodeHasTopLevelAwait(item)) return true;
        return false;
    }

    fn nodeHasTopLevelAwait(node: *const ast.Node) bool {
        return switch (node.*) {
            .await_expr => true,
            .function, .func_decl => false,
            .class_expr => |c| blk: {
                if (c.superclass) |sc| if (nodeHasTopLevelAwait(sc)) break :blk true;
                for (c.members) |m| if (m.key_expr) |ke| if (nodeHasTopLevelAwait(ke)) break :blk true;
                break :blk false;
            },
            .unary => |u| nodeHasTopLevelAwait(u.operand),
            .delete_expr => |d| nodeHasTopLevelAwait(d),
            .update => |u| nodeHasTopLevelAwait(u.target),
            .binary => |b| nodeHasTopLevelAwait(b.left) or nodeHasTopLevelAwait(b.right),
            .logical => |l| nodeHasTopLevelAwait(l.left) or nodeHasTopLevelAwait(l.right),
            .sequence => |s| nodeHasTopLevelAwait(s.first) or nodeHasTopLevelAwait(s.second),
            .assign => |a| nodeHasTopLevelAwait(a.target) or nodeHasTopLevelAwait(a.value),
            .op_assign => |a| nodeHasTopLevelAwait(a.target) or nodeHasTopLevelAwait(a.value),
            .logical_assign => |a| nodeHasTopLevelAwait(a.target) or nodeHasTopLevelAwait(a.value),
            .conditional => |c| nodeHasTopLevelAwait(c.cond) or nodeHasTopLevelAwait(c.consequent) or nodeHasTopLevelAwait(c.alternate),
            .import_call => |ic| nodeHasTopLevelAwait(ic.specifier) or (ic.options != null and nodeHasTopLevelAwait(ic.options.?)),
            .call => |c| blk: {
                if (nodeHasTopLevelAwait(c.callee)) break :blk true;
                for (c.args) |arg| if (nodeHasTopLevelAwait(arg)) break :blk true;
                break :blk false;
            },
            .new_expr => |n| blk: {
                if (nodeHasTopLevelAwait(n.callee)) break :blk true;
                for (n.args) |arg| if (nodeHasTopLevelAwait(arg)) break :blk true;
                break :blk false;
            },
            .tagged_template => |t| blk: {
                if (nodeHasTopLevelAwait(t.tag)) break :blk true;
                for (t.exprs) |expr| if (nodeHasTopLevelAwait(expr)) break :blk true;
                break :blk false;
            },
            .member => |m| nodeHasTopLevelAwait(m.object) or (m.computed != null and nodeHasTopLevelAwait(m.computed.?)),
            .super_member => |m| m.computed != null and nodeHasTopLevelAwait(m.computed.?),
            .optional_chain => |c| nodeHasTopLevelAwait(c),
            .object_lit => |props| blk: {
                for (props) |p| {
                    if (p.key_expr) |ke| if (nodeHasTopLevelAwait(ke)) break :blk true;
                    if (nodeHasTopLevelAwait(p.value)) break :blk true;
                }
                break :blk false;
            },
            .array_lit => |items| blk: {
                for (items) |item| if (nodeHasTopLevelAwait(item)) break :blk true;
                break :blk false;
            },
            .spread => |s| nodeHasTopLevelAwait(s),
            .var_decl => |d| d.init != null and nodeHasTopLevelAwait(d.init.?),
            .destructure_decl => |d| nodeHasTopLevelAwait(d.init),
            .return_stmt => |r| r != null and nodeHasTopLevelAwait(r.?),
            .throw_stmt => |t| nodeHasTopLevelAwait(t),
            .expr_stmt => |e| nodeHasTopLevelAwait(e),
            .block => |stmts| moduleItemsHaveTopLevelAwait(stmts),
            .decl_group => |stmts| moduleItemsHaveTopLevelAwait(stmts),
            .if_stmt => |i| nodeHasTopLevelAwait(i.cond) or nodeHasTopLevelAwait(i.consequent) or (i.alternate != null and nodeHasTopLevelAwait(i.alternate.?)),
            .while_stmt => |w| nodeHasTopLevelAwait(w.cond) or nodeHasTopLevelAwait(w.body),
            .do_while_stmt => |d| nodeHasTopLevelAwait(d.body) or nodeHasTopLevelAwait(d.cond),
            .for_stmt => |f| (f.init != null and nodeHasTopLevelAwait(f.init.?)) or (f.cond != null and nodeHasTopLevelAwait(f.cond.?)) or (f.update != null and nodeHasTopLevelAwait(f.update.?)) or nodeHasTopLevelAwait(f.body),
            .for_in => |f| nodeHasTopLevelAwait(f.target) or (f.var_init != null and nodeHasTopLevelAwait(f.var_init.?)) or nodeHasTopLevelAwait(f.iterable) or nodeHasTopLevelAwait(f.body),
            .switch_stmt => |sw| blk: {
                if (nodeHasTopLevelAwait(sw.disc)) break :blk true;
                for (sw.cases) |case| {
                    if (case.@"test") |t| if (nodeHasTopLevelAwait(t)) break :blk true;
                    for (case.body) |body| if (nodeHasTopLevelAwait(body)) break :blk true;
                }
                break :blk false;
            },
            .try_stmt => |t| nodeHasTopLevelAwait(t.block) or (t.catch_param != null and nodeHasTopLevelAwait(t.catch_param.?)) or (t.catch_block != null and nodeHasTopLevelAwait(t.catch_block.?)) or (t.finally_block != null and nodeHasTopLevelAwait(t.finally_block.?)),
            .labeled_stmt => |l| nodeHasTopLevelAwait(l.body),
            .with_stmt => |w| nodeHasTopLevelAwait(w.obj) or nodeHasTopLevelAwait(w.body),
            .export_decl => |e| (e.declaration != null and nodeHasTopLevelAwait(e.declaration.?)) or (e.default_expr != null and nodeHasTopLevelAwait(e.default_expr.?)),
            else => false,
        };
    }

    /// Resolve `specifier` against module `m`, load it, and record it in `m.deps`.
    /// `module_type` is the `type` import attribute ("json" → a synthetic JSON
    /// module; "" → an ordinary JS module).
    fn loadDep(self: *Context, m: *Module, specifier: []const u8, module_type: []const u8, host: ModuleHost, cache: *ModuleCache) RunError!*Module {
        if (m.deps.get(specifier)) |d| return d;
        var dep_path: []const u8 = "";
        const dep_src = host.load(host.ctx, m.path, specifier, &dep_path) orelse
            return self.moduleTypeError("Cannot resolve module specifier");
        const dep = if (isSyntheticModuleType(module_type))
            try self.loadSyntheticModule(dep_path, dep_src, module_type, cache)
        else
            try self.loadModule(dep_path, dep_src, host, cache);
        try m.deps.put(self.arena(), self.root_shape, specifier, dep);
        return dep;
    }

    /// Build a synthetic module (JSON, text, or bytes): no JS body, a single
    /// `default` export materialized at evaluation time from the raw source.
    fn loadSyntheticModule(self: *Context, path: []const u8, source: []const u8, syn_type: []const u8, cache: *ModuleCache) RunError!*Module {
        const a = self.arena();
        const cache_key = try self.syntheticModuleCacheKey(path, syn_type);
        if (cache.get(cache_key)) |m| return m;
        const env = try gc_mod.allocEnv(a);
        env.* = .{
            .arena = a,
            .binding_hash_state = .{ .realm_shape = self.root_shape },
            .bindings_allocator = if (self.gc != null) self.gpa else null,
            .gc_name_bytes_live = if (self.gc != null) &self.gc_environment_name_bytes_live else null,
            .parent = &self.env,
            .gc_managed = gc_mod.allocationsAreManaged(),
            .fn_scope = true,
        };
        const m = try a.create(Module);
        m.* = .{ .path = cache_key, .items = &.{}, .env = env, .syn_source = try a.dupe(u8, source), .syn_type = syn_type };
        try m.exports.put(a, self.root_shape, "default", .{ .local = "*default*" });
        try self.putModuleCache(cache, m.path, m);
        return m;
    }

    fn newModuleSourceObject(self: *Context) RunError!*value.Object {
        if (self.module_source_object) |cached| return cached;
        const a = self.arena();
        const obj = try gc_mod.allocObj(a);
        obj.* = .{};
        if (self.env.get("$262")) |host| if (host.isObject()) {
            if (host.asObj().getOwn("AbstractModuleSource")) |ctor| if (ctor.isObject()) {
                if (ctor.asObj().getOwn("prototype")) |proto| if (proto.isObject()) {
                    obj.proto = proto.asObj();
                };
            };
        };
        self.module_source_object = obj;
        return obj;
    }

    /// Record the export names introduced by one `export` declaration.
    fn collectExports(self: *Context, m: *Module, e: *ast.ExportNode) RunError!void {
        const a = self.arena();
        if (e.declaration) |d| {
            try declaredExportNames(self, m, d);
        }
        if (e.default_expr != null) {
            const local = if (e.default_name.len > 0) e.default_name else "*default*";
            try m.exports.put(a, self.root_shape, "default", .{ .local = local });
        }
        for (e.entries) |entry| {
            if (e.from.len == 0) {
                try m.exports.put(a, self.root_shape, entry.exported, .{ .local = entry.local });
            } else {
                const dep = m.deps.get(e.from).?;
                try m.exports.put(a, self.root_shape, entry.exported, .{ .indirect = .{ .module = dep, .name = entry.imported } });
            }
        }
        if (e.star) {
            const dep = m.deps.get(e.from).?;
            if (e.star_as.len > 0) {
                // `export * as ns from "m"` — a namespace re-export.
                try m.exports.put(a, self.root_shape, e.star_as, .{ .local = e.star_as });
            } else {
                try m.star_sources.append(a, dep); // `export * from "m"`
            }
        }
    }

    /// Add the names bound by an exported declaration as local exports.
    fn declaredExportNames(self: *Context, m: *Module, d: *ast.Node) RunError!void {
        const a = self.arena();
        switch (d.*) {
            .func_decl => |f| try m.exports.put(a, self.root_shape, f.name, .{ .local = f.name }),
            .var_decl => |v| try m.exports.put(a, self.root_shape, v.name, .{ .local = v.name }),
            .destructure_decl => |dd| {
                var names: std.ArrayListUnmanaged([]const u8) = .empty;
                try modulePatternBoundNames(a, dd.pattern, &names);
                for (names.items) |name| try m.exports.put(a, self.root_shape, name, .{ .local = name });
            },
            .decl_group => |group| for (group) |g| try declaredExportNames(self, m, g),
            else => {},
        }
    }

    fn modulePatternBoundNames(a: std.mem.Allocator, node: *const ast.Node, out: *std.ArrayListUnmanaged([]const u8)) !void {
        switch (node.*) {
            .identifier => |name| try out.append(a, name),
            .obj_pattern => |p| {
                for (p.props) |prop| try modulePatternBoundNames(a, prop.target, out);
                if (p.rest) |rest| try modulePatternBoundNames(a, rest, out);
            },
            .arr_pattern => |p| {
                for (p.elems) |elem| if (elem.target) |target| try modulePatternBoundNames(a, target, out);
                if (p.rest) |rest| try modulePatternBoundNames(a, rest, out);
            },
            else => {},
        }
    }

    fn moduleError(self: *Context, msg: []const u8) RunError {
        var machine = self.interpreter();
        machine.throwError("SyntaxError", msg) catch {};
        self.exception = machine.exception; // surface to the caller (load/link run outside evalModule)
        return error.Throw;
    }

    fn moduleTypeError(self: *Context, msg: []const u8) RunError {
        var machine = self.interpreter();
        machine.throwError("TypeError", msg) catch {};
        self.exception = machine.exception;
        return error.Throw;
    }

    const ExportResolution = union(enum) {
        not_found,
        found: interp.Environment.Alias,
        ambiguous,
    };

    fn sameExportResolution(self: *Context, a: interp.Environment.Alias, b: interp.Environment.Alias) bool {
        if (a.env == b.env and std.mem.eql(u8, a.name, b.name)) return true;
        const left = a.env.get(a.name) orelse return false;
        const right = b.env.get(b.name) orelse return false;
        if (!left.isObject() or !right.isObject()) return false;
        const lo = left.asObj();
        if (lo == self.tdz_marker) return false;
        return lo == right.asObj();
    }

    /// Resolve an export `name` of `module`, chasing re-exports and `export *`
    /// sources. Distinguishes the spec's "ambiguous" result from "not found",
    /// because indirect exports/imports must reject both while namespace objects
    /// merely omit ambiguous star names.
    const ResolveEntry = struct { module: *Module, name: []const u8 };

    fn resolveExport(self: *Context, module: *Module, name: []const u8, depth: u32) ExportResolution {
        _ = depth; // superseded by the resolveSet threaded through resolveExportSet
        var set: std.ArrayListUnmanaged(ResolveEntry) = .empty;
        defer set.deinit(self.gpa);
        return self.resolveExportSet(module, name, &set);
    }

    /// ResolveExport with the spec's `resolveSet` (sec-resolveexport): re-entering
    /// a (module, exportName) already in progress returns not_found. A plain depth
    /// cap does not prevent the `export *` / indirect-re-export recursion from
    /// re-walking the same nodes along every cyclic path — an exponential blow-up
    /// that hangs on multi-cycle graphs. The resolveSet prunes that to a finite,
    /// linear traversal while still detecting genuine ambiguity (distinct
    /// (module, name) targets are never pruned, so two different source bindings
    /// still resolve to `.ambiguous`).
    fn resolveExportSet(self: *Context, module: *Module, name: []const u8, set: *std.ArrayListUnmanaged(ResolveEntry)) ExportResolution {
        for (set.items) |e| {
            if (e.module == module and std.mem.eql(u8, e.name, name)) return .not_found;
        }
        set.append(self.gpa, .{ .module = module, .name = name }) catch return .not_found;
        if (module.exports.get(name)) |kind| switch (kind) {
            .local => |local| {
                if (module.env.aliases.get(module.env.bindingHashContext(), local)) |alias|
                    return .{ .found = alias };
                return .{ .found = .{ .env = module.env, .name = local } };
            },
            .indirect => |ind| {
                if (std.mem.eql(u8, ind.name, "*namespace*")) return .not_found; // namespace handled separately
                return self.resolveExportSet(ind.module, ind.name, set);
            },
        };
        // `export *` sources: a name not directly exported may come from one.
        var star_resolution: ?interp.Environment.Alias = null;
        for (module.star_sources.items) |src| {
            switch (self.resolveExportSet(src, name, set)) {
                .not_found => {},
                .ambiguous => return .ambiguous,
                .found => |r| {
                    if (star_resolution) |existing| {
                        if (!self.sameExportResolution(existing, r)) return .ambiguous;
                    } else {
                        star_resolution = r;
                    }
                },
            }
        }
        return if (star_resolution) |r| .{ .found = r } else .not_found;
    }

    /// Link a module: load-order recursion that wires every `import` binding in
    /// the module's environment to the exporting module's live binding (or a
    /// namespace object). Idempotent and cycle-safe via the `linked` flag.
    fn linkModule(self: *Context, m: *Module) RunError!void {
        if (m.linked) return;
        m.linked = true;
        // Source-phase imports do not instantiate the target as an ordinary
        // module. Reject unsupported host source records before dependency
        // linking so their host-defined failure is not masked by unrelated
        // linking errors in sibling imports.
        for (m.items) |item| switch (item.*) {
            .import_decl => |imp| for (imp.entries) |entry| {
                if (isSourceImport(entry) and !isHostModuleSourceSpecifier(imp.specifier)) {
                    // The grammar is accepted; hosts that cannot provide a
                    // ModuleSource record fail during module linking, not parse.
                    if (std.mem.startsWith(u8, imp.specifier, "<"))
                        return self.moduleTypeError("source phase import is not available");
                    return self.moduleError("source phase import is not available");
                }
            },
            else => {},
        };
        // Link dependencies first.
        var dit = m.deps.valueIterator();
        while (dit.next()) |dep| try self.linkModule(dep.*);

        var eit = m.exports.iterator();
        while (eit.next()) |entry| switch (entry.value_ptr.*) {
            .local => {},
            .indirect => |ind| {
                if (std.mem.eql(u8, ind.name, "*namespace*")) continue;
                switch (self.resolveExport(ind.module, ind.name, 0)) {
                    .found => {},
                    .not_found, .ambiguous => return self.moduleError("does not provide an export"),
                }
            },
        };

        for (m.items) |item| switch (item.*) {
            .import_decl => |imp| {
                const dep = if (m.deps.get(imp.specifier)) |d| d else null;
                for (imp.entries) |entry| {
                    if (isSourceImport(entry)) {
                        try m.env.putConst(entry.local, Value.obj(try self.newModuleSourceObject()));
                    } else if (entry.namespace) {
                        const nsobj = if (imp.deferred) try self.deferredNamespaceObject(dep.?) else try self.namespaceObject(dep.?);
                        try m.env.putConst(entry.local, Value.obj(nsobj));
                    } else {
                        switch (self.resolveExport(dep.?, entry.imported, 0)) {
                            .found => |res| try m.env.putAlias(entry.local, res.env, res.name),
                            .not_found, .ambiguous => return self.moduleError("does not provide an export"),
                        }
                    }
                }
            },
            .export_decl => |e| {
                // `export * as ns from "m"` needs a namespace object for `m`.
                if (e.star and e.star_as.len > 0) {
                    const dep = m.deps.get(e.from).?;
                    try m.env.put(e.star_as, Value.obj(try self.namespaceObject(dep)));
                }
            },
            else => {},
        };

        // ModuleDeclarationInstantiation (lexical part): top-level let/const/class
        // bindings exist in the module environment in their TDZ before any code
        // runs, so observing them through the namespace (e.g. a circular or self
        // import) throws a ReferenceError until they are initialized.
        for (m.items) |item| self.instantiateLexical(m, item);
        try self.instantiateModuleFunctions(m);
        // A synthetic module's sole `default` binding is in TDZ until its
        // evaluation materializes it (so observing it before then is a
        // ReferenceError).
        if (m.syn_source != null) m.env.put("*default*", Value.obj(self.tdz_marker)) catch {};
    }

    /// Pre-declare a statement's top-level lexical (`let`/`const`) bindings as
    /// TDZ sentinels in the module environment.
    fn instantiateLexical(self: *Context, m: *Module, item: *ast.Node) void {
        const tdz = Value.obj(self.tdz_marker);
        switch (item.*) {
            .var_decl => |v| if (v.kind != .@"var") m.env.put(v.name, tdz) catch {},
            .destructure_decl => |d| if (d.kind != .@"var") {
                var names: std.ArrayListUnmanaged([]const u8) = .empty;
                modulePatternBoundNames(self.arena(), d.pattern, &names) catch return;
                for (names.items) |name| m.env.put(name, tdz) catch {};
            },
            .decl_group => |g| for (g) |s| self.instantiateLexical(m, s),
            .export_decl => |e| {
                if (e.declaration) |d| self.instantiateLexical(m, d);
                if (e.default_expr) |dx| switch (dx.*) {
                    .class_expr => {
                        m.env.put("*default*", tdz) catch {};
                        if (e.default_name.len > 0) m.env.put(e.default_name, tdz) catch {};
                    },
                    else => m.env.put("*default*", tdz) catch {},
                };
            },
            else => {},
        }
    }

    fn instantiateModuleFunctions(self: *Context, m: *Module) RunError!void {
        var machine = self.interpreter();
        machine.env = m.env;
        machine.strict = true;
        machine.cur_module = m.path;
        machine.import_meta_slot = &m.import_meta_slot;
        machine.import_meta_obj = m.import_meta_slot.load();
        for (m.items) |item| try self.instantiateModuleFunctionItem(&machine, m, item);
    }

    fn instantiateModuleFunctionItem(self: *Context, machine: *interp.Interpreter, m: *Module, item: *ast.Node) interp.EvalError!void {
        switch (item.*) {
            .func_decl => |fnode| try m.env.put(fnode.name, try machine.makeFunction(fnode, m.env)),
            .decl_group => |group| for (group) |g| try self.instantiateModuleFunctionItem(machine, m, g),
            .export_decl => |e| {
                if (e.declaration) |d| try self.instantiateModuleFunctionItem(machine, m, d);
                if (e.default_expr) |dx| switch (dx.*) {
                    .func_decl => |fnode| {
                        const v = try machine.makeFunction(fnode, m.env);
                        try m.env.put("*default*", v);
                        if (e.default_name.len > 0) try m.env.put(e.default_name, v);
                    },
                    .function => |fnode| if (fnode.is_default_export_decl) {
                        const v = try machine.makeFunction(fnode, m.env);
                        if (e.default_name.len > 0) {
                            try m.env.put(e.default_name, v);
                        } else {
                            try machine.maybeNameAnon(v, dx, "default");
                        }
                        try m.env.put("*default*", v);
                    },
                    else => {},
                };
            },
            else => {},
        }
    }

    /// Evaluate a module (and its not-yet-evaluated dependencies first), running
    /// its top-level items in its own environment with `this === undefined`.
    fn evalModule(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!void {
        if (m.evaluated) {
            if (m.eval_error) |err| {
                machine.exception = err;
                self.exception = err;
                return error.Throw;
            }
            return;
        }
        if (m.eval_started) return;
        m.eval_started = true;
        self.evalModuleDependencies(machine, m) catch |err| {
            if (err == error.Throw) {
                m.eval_error = machine.exception;
                self.exception = machine.exception;
                m.evaluated = true;
            }
            return err;
        };
        if (!try self.waitModuleDependencies(machine, m)) return;
        try self.evalModuleBody(machine, m);
    }

    fn finishModuleError(self: *Context, machine: *interp.Interpreter, m: *Module, err: interp.EvalError) interp.EvalError {
        if (err == error.Throw) {
            m.eval_error = machine.exception;
            self.exception = machine.exception;
            m.evaluated = true;
            self.rejectModuleNamespaceWaiters(machine, m, machine.exception) catch {};
            if (m.completion_promise) |p| promise.reject(machine, p, machine.exception) catch {};
            self.rejectModuleParents(machine, m, machine.exception) catch {};
        }
        return err;
    }

    fn finishModuleSuccess(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!void {
        if (m.evaluated) return;
        m.evaluated = true;
        try self.resolveModuleNamespaceWaiters(machine, m);
        if (m.completion_promise) |p| try promise.resolve(machine, p, Value.undef());
        if (self.parent_resume_depth > 0) {
            try self.appendUniqueModule(&self.completed_parent_queue, m);
            return;
        }
        try self.resumeModuleParents(machine, m);
    }

    fn evalModuleDependencies(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!void {
        self.module_dependency_depth += 1;
        defer self.module_dependency_depth -= 1;
        if (m.syn_source) |src| {
            // The synthetic module's `default` export: JSON.parse(source) for a
            // JSON module, the raw source string for text, or an immutable
            // Uint8Array view for bytes.
            const def = if (std.mem.eql(u8, m.syn_type, "json"))
                try builtins.jsonParse(machine, Value.undef(), &.{try Value.strAlloc(machine.arena, src)})
            else if (std.mem.eql(u8, m.syn_type, "bytes"))
                Value.obj(try machine.makeImmutableUint8ArrayFromBytes(src))
            else
                try Value.strAlloc(machine.arena, src);
            try m.env.put("*default*", def);
            try self.finishModuleSuccess(machine, m);
            return;
        }
        for (m.items) |item| switch (item.*) {
            .import_decl => |imp| {
                const source_only = imp.entries.len == 1 and isSourceImport(imp.entries[0]);
                // A deferred import (`import defer`) is NOT eagerly evaluated; its
                // evaluation is triggered lazily on first namespace access. Its
                // async dependencies still start eagerly so top-level-await work
                // completes before the deferred namespace is exposed.
                if ((!source_only or !isHostModuleSourceSpecifier(imp.specifier)) and !imp.deferred) {
                    try self.evalModule(machine, m.deps.get(imp.specifier).?);
                } else if (imp.deferred) {
                    try self.evalDeferredAsyncDependencies(machine, m.deps.get(imp.specifier).?);
                }
            },
            .export_decl => |e| if (e.from.len > 0) try self.evalModule(machine, m.deps.get(e.from).?),
            else => {},
        };
        if (self.module_dependency_depth == 1) try self.drainDeferredAsyncWork(machine);
    }

    fn waitModuleDependencies(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!bool {
        for (m.items) |item| switch (item.*) {
            .import_decl => |imp| {
                if (imp.deferred) continue;
                const source_only = imp.entries.len == 1 and isSourceImport(imp.entries[0]);
                if (source_only and isHostModuleSourceSpecifier(imp.specifier)) continue;
                if (!try self.waitModuleDependency(machine, m, m.deps.get(imp.specifier).?)) return false;
            },
            .export_decl => |e| if (e.from.len > 0) {
                if (!try self.waitModuleDependency(machine, m, m.deps.get(e.from).?)) return false;
            },
            else => {},
        };
        m.waiting_on_deps = false;
        return true;
    }

    fn waitModuleDependency(self: *Context, machine: *interp.Interpreter, parent: *Module, dep0: *Module) interp.EvalError!bool {
        if (dep0 == parent) return true;
        if (!dep0.evaluated and (dep0.async_suspended or dep0.waiting_on_deps)) {
            try self.appendUniqueModule(&dep0.async_parents, parent);
            parent.waiting_on_deps = true;
            return false;
        }
        var dep = dep0;
        if (dep0.cycle_root) |root| {
            if (!root.evaluated) dep = root;
        }
        if (dep.eval_started and !dep.evaluated and !dep.async_suspended and !dep.waiting_on_deps) {
            parent.cycle_root = dep;
            return true;
        }
        if (!dep.evaluated and (dep.async_suspended or dep.waiting_on_deps)) {
            try self.appendUniqueModule(&dep.async_parents, parent);
            parent.waiting_on_deps = true;
            return false;
        }
        try self.drainUntilModuleSettled(machine, dep);
        if (dep.evaluated) {
            if (dep.eval_error) |err| {
                machine.exception = err;
                self.exception = err;
                return error.Throw;
            }
            return true;
        }
        if (dep.async_suspended or dep.waiting_on_deps) {
            try self.appendUniqueModule(&dep.async_parents, parent);
            parent.waiting_on_deps = true;
            return false;
        }
        return true;
    }

    fn evalModuleBody(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!void {
        if (m.evaluated or m.async_suspended) return;
        const saved_env = machine.env;
        const saved_this = machine.this_value;
        const saved_mod = machine.cur_module;
        const saved_import_meta_slot = machine.import_meta_slot;
        const saved_import_meta_obj = machine.import_meta_obj;
        const saved_stack_trace_call_frame = machine.stack_trace_call_frame;
        var stack_trace_call_frame = interp.StackTraceCallFrame{
            .function_identity = @intFromPtr(m),
            .code_type = .module,
            .caller = saved_stack_trace_call_frame,
        };
        machine.env = m.env;
        machine.this_value = Value.undef(); // module top-level `this` is undefined
        machine.cur_module = m.path; // referrer for runtime import()
        machine.import_meta_slot = &m.import_meta_slot;
        machine.import_meta_obj = m.import_meta_slot.load();
        machine.stack_trace_call_frame = &stack_trace_call_frame;
        defer {
            machine.env = saved_env;
            machine.this_value = saved_this;
            machine.cur_module = saved_mod;
            machine.import_meta_slot = saved_import_meta_slot;
            machine.import_meta_obj = saved_import_meta_obj;
            machine.stack_trace_call_frame = saved_stack_trace_call_frame;
        }
        if (!m.body_hoisted) {
            try machine.hoistVarNames(m.items);
            m.body_hoisted = true;
        }
        while (m.eval_index < m.items.len) {
            const item = m.items[m.eval_index];
            if (try self.trySuspendModuleItem(machine, m, item)) return;
            _ = machine.eval(item) catch |err| return self.finishModuleError(machine, m, err);
            m.eval_index += 1;
        }
        try self.finishModuleSuccess(machine, m);
    }

    fn trySuspendModuleItem(self: *Context, machine: *interp.Interpreter, m: *Module, item: *ast.Node) interp.EvalError!bool {
        switch (item.*) {
            .expr_stmt => |expr| if (expr.* == .await_expr) {
                try self.suspendModuleAwait(machine, m, expr.await_expr.argument, .discard);
                return true;
            },
            .var_decl => |v| if (v.init) |init| if (init.* == .await_expr) {
                try self.suspendModuleAwait(machine, m, init.await_expr.argument, .{ .binding = .{ .name = v.name, .kind = v.kind } });
                return true;
            },
            .export_decl => |e| {
                if (e.default_expr) |dx| if (dx.* == .await_expr) {
                    try self.suspendModuleAwait(machine, m, dx.await_expr.argument, .default_export);
                    return true;
                };
                if (e.declaration) |decl| if (decl.* == .var_decl) {
                    const v = decl.var_decl;
                    if (v.init) |init| if (init.* == .await_expr) {
                        try self.suspendModuleAwait(machine, m, init.await_expr.argument, .{ .binding = .{ .name = v.name, .kind = v.kind } });
                        return true;
                    };
                };
            },
            else => {},
        }
        return false;
    }

    fn suspendModuleAwait(self: *Context, machine: *interp.Interpreter, m: *Module, arg: *ast.Node, kind: ModuleAwait) interp.EvalError!void {
        const awaited_value = try machine.eval(arg);
        const wrapped = interp.promiseResolveValue(machine, awaited_value) catch |err| return self.finishModuleError(machine, m, err);
        const p = promise.promiseOf(wrapped).?;
        const onf = try gc_mod.allocObj(self.arena());
        const fdata = try self.arena().create(ModuleAwaitResume);
        fdata.* = .{ .ctx = self, .module = m, .rejected = false };
        onf.* = .{ .native = moduleAwaitResume, .private_data = @ptrCast(fdata) };
        try interp.installNativeProps(self.arena(), machine.root_shape, onf, "", 1);
        const onr = try gc_mod.allocObj(self.arena());
        const rdata = try self.arena().create(ModuleAwaitResume);
        rdata.* = .{ .ctx = self, .module = m, .rejected = true };
        onr.* = .{ .native = moduleAwaitResume, .private_data = @ptrCast(rdata) };
        try interp.installNativeProps(self.arena(), machine.root_shape, onr, "", 1);
        m.pending_await = kind;
        m.async_suspended = true;
        _ = try promise.then(machine, p, Value.obj(onf), Value.obj(onr));
    }

    fn moduleAwaitResume(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
        _ = this;
        const machine: *interp.Interpreter = @ptrCast(@alignCast(ctx));
        const data: *ModuleAwaitResume = @ptrCast(@alignCast(machine.active_native.?.private_data.?));
        const value_arg = if (args.len > 0) args[0] else Value.undef();
        try data.ctx.resumeModuleAwait(machine, data.module, data.rejected, value_arg);
        return Value.undef();
    }

    fn resumeModuleAwait(self: *Context, machine: *interp.Interpreter, m: *Module, rejected: bool, value_arg: Value) interp.EvalError!void {
        if (m.evaluated) return;
        m.async_suspended = false;
        if (rejected) {
            machine.exception = value_arg;
            m.eval_error = value_arg;
            self.exception = value_arg;
            m.evaluated = true;
            try self.rejectModuleNamespaceWaiters(machine, m, value_arg);
            if (m.completion_promise) |p| try promise.reject(machine, p, value_arg);
            try self.rejectModuleParents(machine, m, value_arg);
            return;
        }
        try self.completeModuleAwait(machine, m, value_arg);
        m.pending_await = .none;
        m.eval_index += 1;
        try self.evalModuleBody(machine, m);
    }

    fn completeModuleAwait(self: *Context, machine: *interp.Interpreter, m: *Module, value_arg: Value) interp.EvalError!void {
        _ = self;
        switch (m.pending_await) {
            .none, .discard => {},
            .binding => |b| switch (b.kind) {
                .@"const" => try m.env.putConst(b.name, value_arg),
                else => try m.env.put(b.name, value_arg),
            },
            .default_export => try m.env.put("*default*", value_arg),
        }
        _ = machine;
    }

    fn drainUntilModuleSettled(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!void {
        var rounds: usize = 0;
        while (!m.evaluated and rounds < 10_000) : (rounds += 1) {
            if (m.eval_error) |err| {
                machine.exception = err;
                self.exception = err;
                return error.Throw;
            }
            const before = self.microtaskPendingLen(machine);
            if (before == 0 and !m.async_suspended) return;
            try machine.drainMicrotasks();
            machine.settleAsyncWaiters();
            const after = self.microtaskPendingLen(machine);
            if (after == 0 and before == 0) return;
        }
        if (m.eval_error) |err| {
            machine.exception = err;
            self.exception = err;
            return error.Throw;
        }
    }

    fn microtaskPendingLen(self: *Context, machine: *interp.Interpreter) usize {
        _ = self;
        const q = machine.microtasks orelse return 0;
        machine.lockMicrotasks();
        defer machine.unlockMicrotasks();
        return q.pendingLen();
    }

    /// Build (or return) the namespace exotic object for `module`. Created empty
    /// at link time and filled after the module evaluates.
    fn namespaceObject(self: *Context, module: *Module) RunError!*value.Object {
        if (module.ns) |ns| return ns;
        const a = self.arena();
        const ns = try gc_mod.allocObj(a);
        ns.* = .{};
        module.ns = ns;
        // Build the live Module Namespace exotic data now (at link time): the
        // bindings are read lazily on access, so this is valid before the module
        // has evaluated (and the namespace may be observed during evaluation).
        var machine = self.interpreter();
        try self.fillNamespace(&machine, module, ns);
        return ns;
    }

    /// Build (or return) the *deferred* namespace exotic object for `module`
    /// (`import defer * as ns`): a distinct, cached object whose string-keyed
    /// accesses lazily trigger `module`'s evaluation (via `defer_trigger`).
    fn deferredNamespaceObject(self: *Context, module: *Module) RunError!*value.Object {
        if (module.deferred_ns) |ns| return ns;
        const a = self.arena();
        const ns = try gc_mod.allocObj(a);
        ns.* = .{};
        module.deferred_ns = ns;
        var machine = self.interpreter();
        try self.fillNamespace(&machine, module, ns);
        const modns: *interp.ModuleNs = @ptrCast(@alignCast(ns.moduleNs().?));
        modns.deferred = true;
        modns.defer_module = module;
        return ns;
    }

    fn gatherDeferredAsyncDependencies(self: *Context, module: *Module, seen: *std.ArrayListUnmanaged(*Module), out: *std.ArrayListUnmanaged(*Module)) !void {
        for (seen.items) |m| if (m == module) return;
        try self.appendModuleList(seen, module);
        if (module.evaluated or module.eval_started) return;
        if (module.has_tla) {
            for (out.items) |m| if (m == module) return;
            try self.appendModuleList(out, module);
            return;
        }
        for (module.items) |item| switch (item.*) {
            .import_decl => |imp| {
                if (imp.entries.len == 1 and isSourceImport(imp.entries[0])) continue;
                try self.gatherDeferredAsyncDependencies(module.deps.get(imp.specifier).?, seen, out);
            },
            .export_decl => |e| if (e.from.len > 0) {
                try self.gatherDeferredAsyncDependencies(module.deps.get(e.from).?, seen, out);
            },
            else => {},
        };
    }

    fn evalDeferredAsyncDependencies(self: *Context, machine: *interp.Interpreter, module: *Module) interp.EvalError!void {
        var seen: std.ArrayListUnmanaged(*Module) = .empty;
        var deps: std.ArrayListUnmanaged(*Module) = .empty;
        try self.gatherDeferredAsyncDependencies(module, &seen, &deps);
        for (deps.items) |dep| {
            if (try self.moduleHasPendingStartedDependency(dep)) {
                try self.appendUniqueModule(&self.deferred_async_queue, dep);
            } else {
                try self.evalModule(machine, dep);
                try self.appendUniqueModule(&self.deferred_async_started, dep);
            }
        }
    }

    fn appendUniqueModule(self: *Context, list: *std.ArrayListUnmanaged(*Module), module: *Module) !void {
        for (list.items) |m| if (m == module) return;
        try self.appendModuleList(list, module);
    }

    fn appendModuleList(self: *Context, list: *std.ArrayListUnmanaged(*Module), module: *Module) !void {
        if (list.capacity == list.items.len) {
            try list.ensureTotalCapacity(self.arena(), list.items.len + module_queue_reserve_granularity);
        }
        list.appendAssumeCapacity(module);
    }

    fn moduleHasPendingStartedDependency(self: *Context, module: *Module) interp.EvalError!bool {
        var seen: std.ArrayListUnmanaged(*Module) = .empty;
        return self.moduleHasPendingStartedDependencyInner(module, &seen);
    }

    fn moduleHasPendingStartedDependencyInner(self: *Context, module: *Module, seen: *std.ArrayListUnmanaged(*Module)) interp.EvalError!bool {
        for (seen.items) |m| if (m == module) return false;
        try self.appendModuleList(seen, module);
        for (module.items) |item| switch (item.*) {
            .import_decl => |imp| {
                if (imp.deferred) continue;
                if (imp.entries.len == 1 and isSourceImport(imp.entries[0])) continue;
                const dep = module.deps.get(imp.specifier).?;
                if (dep.eval_started and !dep.evaluated) return true;
                if (try self.moduleHasPendingStartedDependencyInner(dep, seen)) return true;
            },
            .export_decl => |e| if (e.from.len > 0) {
                const dep = module.deps.get(e.from).?;
                if (dep.eval_started and !dep.evaluated) return true;
                if (try self.moduleHasPendingStartedDependencyInner(dep, seen)) return true;
            },
            else => {},
        };
        return false;
    }

    fn resumeModuleParents(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!void {
        self.parent_resume_depth += 1;
        for (m.async_parents.items) |parent| {
            if (parent.evaluated) continue;
            parent.waiting_on_deps = false;
            if (try self.waitModuleDependencies(machine, parent)) {
                try self.evalModuleBody(machine, parent);
            }
        }
        m.async_parents.clearRetainingCapacity();
        self.parent_resume_depth -= 1;
        if (self.parent_resume_depth == 0) {
            while (self.completed_parent_queue_head < self.completed_parent_queue.items.len) {
                const completed = self.completed_parent_queue.items[self.completed_parent_queue_head];
                self.completed_parent_queue_head += 1;
                try self.resumeModuleParents(machine, completed);
            }
            self.clearCompletedParentQueue();
        }
    }

    fn clearCompletedParentQueue(self: *Context) void {
        self.completed_parent_queue.clearRetainingCapacity();
        self.completed_parent_queue_head = 0;
    }

    fn rejectModuleParents(self: *Context, machine: *interp.Interpreter, m: *Module, reason: Value) interp.EvalError!void {
        for (m.async_parents.items) |parent| {
            if (parent.evaluated) continue;
            parent.eval_error = reason;
            parent.evaluated = true;
            try self.rejectModuleNamespaceWaiters(machine, parent, reason);
            if (parent.completion_promise) |p| try promise.reject(machine, p, reason);
            try self.rejectModuleParents(machine, parent, reason);
        }
        m.async_parents.clearRetainingCapacity();
    }

    fn appendModuleNamespaceWaiter(self: *Context, m: *Module, capability: *promise.Promise, ns: *value.Object) interp.EvalError!void {
        if (m.dynamic_waiters.capacity == m.dynamic_waiters.items.len) {
            try m.dynamic_waiters.ensureTotalCapacity(self.arena(), m.dynamic_waiters.items.len + module_namespace_waiter_reserve_granularity);
        }
        m.dynamic_waiters.appendAssumeCapacity(.{ .capability = capability, .namespace = ns });
    }

    fn resolveModuleNamespaceWaiters(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!void {
        _ = self;
        for (m.dynamic_waiters.items) |w| try promise.resolve(machine, w.capability, Value.obj(w.namespace));
        m.dynamic_waiters.clearRetainingCapacity();
    }

    fn rejectModuleNamespaceWaiters(self: *Context, machine: *interp.Interpreter, m: *Module, reason: Value) interp.EvalError!void {
        _ = self;
        for (m.dynamic_waiters.items) |w| try promise.reject(machine, w.capability, reason);
        m.dynamic_waiters.clearRetainingCapacity();
    }

    fn ensureModuleCompletionPromise(self: *Context, machine: *interp.Interpreter, m: *Module) interp.EvalError!*promise.Promise {
        _ = self;
        if (m.completion_promise) |p| return p;
        const obj = try promise.newPromise(machine);
        const p = promise.promiseOf(Value.obj(obj)).?;
        m.completion_promise = p;
        if (m.evaluated) {
            if (m.eval_error) |err| try promise.reject(machine, p, err) else try promise.resolve(machine, p, Value.undef());
        }
        return p;
    }

    fn moduleNamespaceResume(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
        _ = this;
        _ = args;
        const machine: *interp.Interpreter = @ptrCast(@alignCast(ctx));
        const fnobj = machine.active_native orelse return Value.undef();
        return fnobj.getOwn("\x00moduleNamespace") orelse Value.undef();
    }

    fn moduleNamespaceAfterCompletion(self: *Context, machine: *interp.Interpreter, m: *Module, ns: *value.Object) interp.EvalError!Value {
        const p = try self.ensureModuleCompletionPromise(machine, m);
        const onf = try gc_mod.allocObj(self.arena());
        onf.* = .{ .native = moduleNamespaceResume };
        try interp.installNativeProps(self.arena(), machine.root_shape, onf, "", 0);
        try onf.setOwn(self.arena(), machine.root_shape, "\x00moduleNamespace", Value.obj(ns));
        return try promise.then(machine, p, Value.obj(onf), Value.undef());
    }

    fn resolveModuleNamespaceAfterCompletion(self: *Context, machine: *interp.Interpreter, m: *Module, ns: *value.Object, capability: *promise.Promise) interp.EvalError!void {
        const p = try self.ensureModuleCompletionPromise(machine, m);
        const onf = try gc_mod.allocObj(self.arena());
        onf.* = .{ .native = moduleNamespaceResume };
        try interp.installNativeProps(self.arena(), machine.root_shape, onf, "", 0);
        try onf.setOwn(self.arena(), machine.root_shape, "\x00moduleNamespace", Value.obj(ns));
        try promise.performThenResult(machine, p, Value.obj(onf), Value.undef(), capability);
    }

    fn drainDeferredAsyncWork(self: *Context, machine: *interp.Interpreter) interp.EvalError!void {
        while (self.deferred_async_queue.items.len > 0) {
            var progressed = false;
            var i: usize = 0;
            while (i < self.deferred_async_queue.items.len) {
                const dep = self.deferred_async_queue.items[i];
                if (try self.moduleHasPendingStartedDependency(dep)) {
                    i += 1;
                    continue;
                }
                _ = self.deferred_async_queue.orderedRemove(i);
                try self.evalModule(machine, dep);
                try self.appendUniqueModule(&self.deferred_async_started, dep);
                progressed = true;
            }
            if (progressed) continue;
            if (self.microtaskPendingLen(machine) == 0) break;
            try machine.drainMicrotasks();
            machine.settleAsyncWaiters();
        }
        for (self.deferred_async_started.items) |dep| {
            try self.drainUntilModuleSettled(machine, dep);
        }
        self.deferred_async_started.clearRetainingCapacity();
    }

    fn readyForSyncExecution(module: *Module, seen: *std.ArrayListUnmanaged(*Module), a: std.mem.Allocator) !bool {
        for (seen.items) |m| if (m == module) return true;
        try seen.append(a, module);
        if (module.evaluated) return true;
        if (module.eval_started) return false;
        var dit = module.deps.valueIterator();
        while (dit.next()) |dep| {
            if (!try readyForSyncExecution(dep.*, seen, a)) return false;
        }
        return true;
    }

    /// `defer_trigger` hook: evaluate the `import defer` module on first
    /// string-keyed access of its deferred namespace (idempotent via `evaluated`).
    fn deferTriggerHook(ctx: *anyopaque, machine: *interp.Interpreter, module: *anyopaque) interp.EvalError!void {
        const self: *Context = @ptrCast(@alignCast(ctx));
        const m: *Module = @ptrCast(@alignCast(module));
        // EnsureDeferredNamespaceEvaluation / ReadyForSyncExecution: a deferred
        // module cannot be triggered while it, or any of its transitive required
        // modules, is still evaluating.
        var seen: std.ArrayListUnmanaged(*Module) = .empty;
        if (!try readyForSyncExecution(m, &seen, self.arena()))
            return machine.throwError("TypeError", "Cannot trigger evaluation of a module that is already evaluating");
        try self.evalModule(machine, m);
    }

    /// Runtime `import(specifier)` driver (wired into the interpreter as
    /// `dyn_import`): resolve the specifier relative to `referrer`, then load,
    /// link, and evaluate the target module, writing its namespace into `out`.
    /// Returns `.failure` (leaving the reason in `machine.exception`) on any
    /// failure, so the caller rejects the dynamic-import promise.
    fn dynImportHook(ctx: *anyopaque, machine: *interp.Interpreter, referrer: []const u8, specifier: []const u8, phase: []const u8, module_type: []const u8, out: *value.Value, capability: ?*promise.Promise) interp.DynamicImportResult {
        const self: *Context = @ptrCast(@alignCast(ctx));
        if (std.mem.eql(u8, phase, "source"))
            return self.dynImportFailKind(machine, "SyntaxError", "source phase dynamic import is not available");
        const host = self.mod_host orelse return self.dynImportFail(machine, "dynamic import is not available");
        const cache = self.mod_cache orelse return self.dynImportFail(machine, "dynamic import is not available");
        var dep_path: []const u8 = "";
        const src = host.load(host.ctx, referrer, specifier, &dep_path) orelse
            return self.dynImportFail(machine, "Cannot resolve module specifier");
        const dep = if (isSyntheticModuleType(module_type))
            self.loadSyntheticModule(dep_path, src, module_type, cache) catch return self.surfaceFail(machine)
        else
            self.loadModule(dep_path, src, host, cache) catch return self.surfaceFail(machine);
        self.linkModule(dep) catch return self.surfaceFail(machine);
        // `import.defer(x)`: resolve the promise with the deferred namespace
        // without evaluating — evaluation is triggered lazily on first access.
        if (std.mem.eql(u8, phase, "defer")) {
            self.evalDeferredAsyncDependencies(machine, dep) catch return self.surfaceFail(machine);
            const dns = self.deferredNamespaceObject(dep) catch return self.surfaceFail(machine);
            out.* = Value.obj(dns);
            return .success;
        }
        self.evalModule(machine, dep) catch return self.surfaceFail(machine);
        if (!dep.evaluated) {
            const ns = self.namespaceObject(dep) catch return self.surfaceFail(machine);
            if (capability) |cap| {
                self.appendModuleNamespaceWaiter(dep, cap, ns) catch return self.surfaceFail(machine);
                return .pending;
            }
            out.* = self.moduleNamespaceAfterCompletion(machine, dep, ns) catch return self.surfaceFail(machine);
            return .success;
        }
        const ns = self.namespaceObject(dep) catch return self.surfaceFail(machine);
        self.fillNamespace(machine, dep, ns) catch return self.surfaceFail(machine);
        out.* = Value.obj(ns);
        return .success;
    }

    fn dynImportFail(self: *Context, machine: *interp.Interpreter, msg: []const u8) interp.DynamicImportResult {
        return self.dynImportFailKind(machine, "TypeError", msg);
    }

    fn dynImportFailKind(self: *Context, machine: *interp.Interpreter, kind: []const u8, msg: []const u8) interp.DynamicImportResult {
        _ = self;
        machine.throwError(kind, msg) catch {};
        return .failure;
    }

    /// A load/link/eval step already threw; surface its reason for rejection.
    fn surfaceFail(self: *Context, machine: *interp.Interpreter) interp.DynamicImportResult {
        if (self.exception) |ex| {
            machine.exception = ex;
        } else {
            machine.throwError("SyntaxError", "Cannot parse module") catch {};
        }
        return .failure;
    }

    /// A module namespace binding behind a live accessor: reads `name` in module
    /// environment `env` on each property access (so mutations of the exporting
    /// binding are observed through the namespace, per spec).
    const NsBinding = struct { env: *interp.Environment, name: []const u8 };

    fn nsGetter(ctx: *anyopaque, this: value.Value, args: []const value.Value) value.HostError!value.Value {
        _ = this;
        _ = args;
        const machine: *interp.Interpreter = @ptrCast(@alignCast(ctx));
        const fnobj = machine.active_native orelse return Value.undef();
        const b: *NsBinding = @ptrCast(@alignCast(fnobj.private_data.?));
        return b.env.get(b.name) orelse Value.undef();
    }

    /// Wire a module's exported bindings onto its namespace object as live
    /// accessor properties. The namespace exposes every export name (plus those
    /// reachable through `export *`), with `@@toStringTag` "Module".
    fn fillNamespace(self: *Context, machine: *interp.Interpreter, module: *Module, ns: *value.Object) interp.EvalError!void {
        const a = self.arena();
        // Collect every resolvable export name (own exports + `export *` sources,
        // default excluded from `*`), with its live binding.
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        var envs: std.ArrayListUnmanaged(*interp.Environment) = .empty;
        var locals: std.ArrayListUnmanaged([]const u8) = .empty;
        var ambiguous: std.ArrayListUnmanaged([]const u8) = .empty;
        const add = struct {
            fn contains(list: []const []const u8, name: []const u8) bool {
                for (list) |existing| if (std.mem.eql(u8, existing, name)) return true;
                return false;
            }

            fn sameObjectBinding(env: *interp.Environment, local: []const u8, res: interp.Environment.Alias) bool {
                const left = env.get(local) orelse return false;
                const right = res.env.get(res.name) orelse return false;
                return left.isObject() and right.isObject() and left.asObj() == right.asObj();
            }

            fn f(
                aa: std.mem.Allocator,
                nm: *std.ArrayListUnmanaged([]const u8),
                ev: *std.ArrayListUnmanaged(*interp.Environment),
                lo: *std.ArrayListUnmanaged([]const u8),
                amb: *std.ArrayListUnmanaged([]const u8),
                name: []const u8,
                res: interp.Environment.Alias,
            ) !void {
                if (contains(amb.items, name)) return;
                for (nm.items, 0..) |existing, i| {
                    if (!std.mem.eql(u8, existing, name)) continue;
                    if ((ev.items[i] == res.env and std.mem.eql(u8, lo.items[i], res.name)) or
                        sameObjectBinding(ev.items[i], lo.items[i], res))
                        return;
                    try amb.append(aa, name);
                    return;
                }
                try nm.append(aa, name);
                try ev.append(aa, res.env);
                try lo.append(aa, res.name);
            }
        }.f;
        var it = module.exports.iterator();
        while (it.next()) |e| {
            switch (self.resolveExport(module, e.key_ptr.*, 0)) {
                .found => |res| try add(a, &names, &envs, &locals, &ambiguous, e.key_ptr.*, res),
                .not_found, .ambiguous => {},
            }
        }
        for (module.star_sources.items) |src| {
            var sit = src.exports.iterator();
            while (sit.next()) |e| {
                const name = e.key_ptr.*;
                if (std.mem.eql(u8, name, "default")) continue;
                if (module.exports.contains(name)) continue;
                switch (self.resolveExport(src, name, 0)) {
                    .found => |res| try add(a, &names, &envs, &locals, &ambiguous, name, res),
                    .not_found, .ambiguous => {},
                }
            }
        }
        var write_i: usize = 0;
        for (names.items, 0..) |name, read_i| {
            var is_ambiguous = false;
            for (ambiguous.items) |ambiguous_name| {
                if (std.mem.eql(u8, ambiguous_name, name)) {
                    is_ambiguous = true;
                    break;
                }
            }
            if (is_ambiguous) continue;
            names.items[write_i] = name;
            envs.items[write_i] = envs.items[read_i];
            locals.items[write_i] = locals.items[read_i];
            write_i += 1;
        }
        names.items.len = write_i;
        envs.items.len = write_i;
        locals.items.len = write_i;
        // [[OwnPropertyKeys]] returns the string names sorted by code unit.
        const N = names.items.len;
        var order = try a.alloc(usize, N);
        for (0..N) |i| order[i] = i;
        std.sort.block(usize, order, names.items, struct {
            fn lt(ctx: []const []const u8, x: usize, y: usize) bool {
                return std.mem.lessThan(u8, ctx[x], ctx[y]);
            }
        }.lt);
        const sorted_names = try a.alloc([]const u8, N);
        const sorted_envs = try a.alloc(*interp.Environment, N);
        const sorted_locals = try a.alloc([]const u8, N);
        for (order, 0..) |src_i, dst_i| {
            sorted_names[dst_i] = names.items[src_i];
            sorted_envs[dst_i] = envs.items[src_i];
            sorted_locals[dst_i] = locals.items[src_i];
        }
        const modns = try gc_mod.allocModuleNs(a);
        modns.* = .{
            .names = sorted_names,
            .envs = sorted_envs,
            .locals = sorted_locals,
            .tag_key = machine.wellKnownSymbolKey("toStringTag") orelse "@@toStringTag",
        };
        try ns.setModuleNs(a, @ptrCast(modns));
        ns.proto = null; // a module namespace has a null [[Prototype]]
        ns.setExtensible(false);
    }
};

const ModuleFixture = struct {
    path: []const u8,
    source: []const u8,
};

fn evaluateModuleWithFixtures(source: []const u8, fixtures: []const ModuleFixture) !void {
    const ctx = try Context.create(std.testing.allocator);
    defer ctx.destroy();

    try evaluateModuleWithFixturesInContext(ctx, source, fixtures);
}

fn evaluateModuleWithFixturesInContext(ctx: *Context, source: []const u8, fixtures: []const ModuleFixture) !void {
    const Host = struct {
        source: []const u8,
        fixtures: []const ModuleFixture,

        fn load(ctx_ptr: *anyopaque, _: []const u8, specifier: []const u8, out_path: *[]const u8) ?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx_ptr));
            const path = if (std.mem.startsWith(u8, specifier, "./")) specifier[2..] else specifier;
            if (std.mem.eql(u8, path, "entry.js")) {
                out_path.* = "entry.js";
                return self.source;
            }
            for (self.fixtures) |fixture| {
                if (std.mem.eql(u8, path, fixture.path)) {
                    out_path.* = fixture.path;
                    return fixture.source;
                }
            }
            return null;
        }
    };

    var host_state = Host{ .source = source, .fixtures = fixtures };
    const mh = Context.ModuleHost{ .ctx = &host_state, .load = Host.load };
    _ = try ctx.evaluateModule("entry.js", source, mh);
}

fn evaluateSelfModule(source: []const u8) !void {
    try evaluateModuleWithFixtures(source, &.{});
}

test "runtime module graph installs and retains secure table contexts" {
    const ctx = try Context.create(std.testing.allocator);
    defer ctx.destroy();
    try std.testing.expect(ctx.module_registry.context == null);
    try std.testing.expect(ctx.module_loader_sources.context == null);

    _ = try ctx.provideModuleLoaderSource("provided.js", "export const supplied = 1;");
    const loader_seed = ctx.module_loader_sources.context.?.seed;
    try std.testing.expect(ctx.module_registry.context == null);
    _ = try ctx.provideModuleLoaderSource("second.js", "export const supplied = 2;");
    try std.testing.expectEqual(loader_seed, ctx.module_loader_sources.context.?.seed);

    try evaluateModuleWithFixturesInContext(
        ctx,
        "import { value } from './dep.js'; export { value as result };",
        &.{.{ .path = "dep.js", .source = "export const value = 42;" }},
    );
    const registry_seed = ctx.module_registry.context.?.seed;
    const entry = ctx.module_registry.get("entry.js") orelse return error.TestUnexpectedResult;
    const dependency = ctx.module_registry.get("dep.js") orelse return error.TestUnexpectedResult;
    try std.testing.expect(entry.deps.context != null);
    try std.testing.expect(entry.exports.context != null);
    try std.testing.expect(dependency.deps.context == null);
    try std.testing.expect(dependency.exports.context != null);

    ctx.clearModuleRegistry();
    try std.testing.expectEqual(@as(usize, 0), ctx.module_registry.count());
    try std.testing.expectEqual(@as(usize, 0), ctx.module_loader_sources.count());
    try std.testing.expectEqual(registry_seed, ctx.module_registry.context.?.seed);
    try std.testing.expectEqual(loader_seed, ctx.module_loader_sources.context.?.seed);
}

test "modules reserve internal queue capacity chunks" {
    const ctx = try Context.create(std.testing.allocator);
    defer ctx.destroy();

    var list: std.ArrayListUnmanaged(*Context.Module) = .empty;
    var first_module = Context.Module{ .path = "m0", .items = &.{}, .env = &ctx.env };
    try ctx.appendModuleList(&list, &first_module);
    try std.testing.expect(list.capacity >= module_queue_reserve_granularity);

    const first_capacity = list.capacity;
    var modules = try ctx.arena().alloc(Context.Module, first_capacity + 1);
    var i: usize = 0;
    while (i < modules.len) : (i += 1) {
        modules[i] = .{ .path = "m", .items = &.{}, .env = &ctx.env };
    }

    try ctx.appendUniqueModule(&list, &first_module);
    try std.testing.expectEqual(@as(usize, 1), list.items.len);
    try std.testing.expectEqual(first_capacity, list.capacity);

    i = 0;
    while (list.items.len < first_capacity) : (i += 1) {
        try ctx.appendUniqueModule(&list, &modules[i]);
    }
    try std.testing.expectEqual(first_capacity, list.items.len);
    try std.testing.expectEqual(first_capacity, list.capacity);

    try ctx.appendUniqueModule(&list, &modules[i]);
    try std.testing.expectEqual(first_capacity + 1, list.items.len);
    try std.testing.expect(list.capacity > first_capacity);

    var waiter_module = Context.Module{ .path = "waiters", .items = &.{}, .env = &ctx.env };
    var first_promise = promise.Promise{};
    var first_namespace = value.Object{};
    try ctx.appendModuleNamespaceWaiter(&waiter_module, &first_promise, &first_namespace);
    try std.testing.expect(waiter_module.dynamic_waiters.capacity >= module_namespace_waiter_reserve_granularity);

    const first_waiter_capacity = waiter_module.dynamic_waiters.capacity;
    var promises = try ctx.arena().alloc(promise.Promise, first_waiter_capacity + 1);
    var namespaces = try ctx.arena().alloc(value.Object, first_waiter_capacity + 1);
    @memset(promises, .{});
    @memset(namespaces, .{});

    i = 0;
    while (waiter_module.dynamic_waiters.items.len < first_waiter_capacity) : (i += 1) {
        try ctx.appendModuleNamespaceWaiter(&waiter_module, &promises[i], &namespaces[i]);
    }
    try std.testing.expectEqual(first_waiter_capacity, waiter_module.dynamic_waiters.items.len);
    try std.testing.expectEqual(first_waiter_capacity, waiter_module.dynamic_waiters.capacity);

    try ctx.appendModuleNamespaceWaiter(&waiter_module, &promises[i], &namespaces[i]);
    try std.testing.expectEqual(first_waiter_capacity + 1, waiter_module.dynamic_waiters.items.len);
    try std.testing.expect(waiter_module.dynamic_waiters.capacity > first_waiter_capacity);

    var completed_a = Context.Module{ .path = "completed-a", .items = &.{}, .env = &ctx.env };
    var completed_b = Context.Module{ .path = "completed-b", .items = &.{}, .env = &ctx.env };
    try ctx.appendUniqueModule(&ctx.completed_parent_queue, &completed_a);
    try ctx.appendUniqueModule(&ctx.completed_parent_queue, &completed_b);
    const completed_capacity = ctx.completed_parent_queue.capacity;
    try std.testing.expect(completed_capacity >= module_queue_reserve_granularity);
    try std.testing.expectEqual(@as(usize, 0), ctx.completed_parent_queue_head);
    try std.testing.expectEqual(&completed_a, ctx.completed_parent_queue.items[ctx.completed_parent_queue_head]);
    ctx.completed_parent_queue_head += 1;
    try std.testing.expectEqual(&completed_b, ctx.completed_parent_queue.items[ctx.completed_parent_queue_head]);
    ctx.completed_parent_queue_head += 1;
    ctx.clearCompletedParentQueue();
    try std.testing.expectEqual(@as(usize, 0), ctx.completed_parent_queue.items.len);
    try std.testing.expectEqual(@as(usize, 0), ctx.completed_parent_queue_head);
    try std.testing.expectEqual(completed_capacity, ctx.completed_parent_queue.capacity);
}

test "modules initialize default and var exports for self imports" {
    try evaluateSelfModule(
        \\try {
        \\  typeof C;
        \\  throw new Error("missing default class TDZ");
        \\} catch (e) {
        \\  if (!(e instanceof ReferenceError)) throw e;
        \\}
        \\import C from "./entry.js";
        \\export default class {};
    );

    try evaluateSelfModule(
        \\import f from "./entry.js";
        \\if (f() !== 23) throw new Error("bad default function value");
        \\if (f.name !== "default") throw new Error("bad default function name");
        \\export default function() { return 23; }
    );

    try evaluateSelfModule(
        \\import { test262 as imp } from "./entry.js";
        \\if (test262 !== undefined) throw new Error("exported var was not hoisted");
        \\if (imp !== undefined) throw new Error("imported var was not hoisted");
        \\export var test262 = 23;
        \\if (test262 !== 23 || imp !== 23) throw new Error("exported var did not update");
    );
}

test "modules expose namespace re-exports and evaluate dependencies in source order" {
    try evaluateModuleWithFixtures(
        \\import * as ns from "./entry.js";
        \\export * as "All" from "./dep.js";
        \\if (ns.All["not-id"] !== globalThis.mark) throw new Error("missing namespace re-export");
    , &.{
        .{ .path = "dep.js", .source = "export { mark as \"not-id\" }; function mark() {} globalThis.mark = mark;" },
    });

    try evaluateSelfModule(
        \\var x = "ok";
        \\export { x as "*" };
        \\import { "*" as y } from "./entry.js";
        \\if (y !== "ok") throw new Error("missing string star export");
    );

    try evaluateModuleWithFixtures(
        \\if (globalThis.order !== "123") throw new Error(globalThis.order);
        \\import "./one.js";
        \\export {} from "./two.js";
        \\import "./three.js";
    , &.{
        .{ .path = "one.js", .source = "globalThis.order = '1';" },
        .{ .path = "two.js", .source = "globalThis.order += '2';" },
        .{ .path = "three.js", .source = "globalThis.order += '3';" },
    });

    try evaluateModuleWithFixtures(
        \\import val from "./dep.js";
        \\if (val() !== 1) throw new Error("bad call");
        \\if (val !== 2) throw new Error("default binding did not update");
    , &.{
        .{ .path = "dep.js", .source = "export default function fn() { fn = 2; return 1; }" },
    });
}

