        \\globalThis.genericMovingResult = Array.prototype.map.call(
        \\  genericMovingProxy,
        \\  function (value, index) { if (index === 2) gc(); return value + index; }
        \\);
        \\globalThis.genericMovingDiscard = [];
        \\for (var i = 0; i < 4096; i++) genericMovingDiscard.push({ index: i, dead: true });
        \\genericMovingDiscard = null;
        \\globalThis.genericMovingRelocated = Array.prototype.map.call(
        \\  { length: 3, 0: 11, 2: 13 },
        \\  function (value, index) { return value + index; }
        \\);
    );
    // The trap/callback collections above prove the borrowed key is safe across
    // re-entrant GC. Promote the surviving graph, then compact it explicitly so
    // the stored result/property graph is also verified after relocation.
    ctx.collectGarbage();
    const before = ctx.global_object.getOwn("genericMovingRelocated").?.asObj();
    const moved = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, moved.status);
    const after = ctx.global_object.getOwn("genericMovingRelocated").?.asObj();
    try std.testing.expect(before != after);
    try std.testing.expect((try ctx.evaluate(
        \\genericMovingResult.length === 5 && genericMovingResult[0] === 3 &&
        \\  !(1 in genericMovingResult) && genericMovingResult[2] === 7 &&
        \\  !(3 in genericMovingResult) && genericMovingResult[4] === 11 &&
        \\  genericMovingTarget[4] === 7 && genericMovingRelocated.length === 3 &&
        \\  genericMovingRelocated[0] === 11 && !(1 in genericMovingRelocated) && genericMovingRelocated[2] === 15
    )).asBool());
}

test "parallel_js generic Array index keys remain invocation local" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .parallel_gc = true,
        .enable_threads = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    const result = try ctx.evaluate(
        \\function genericArrayLane(lane) {
        \\  var input = { length: 256 };
        \\  for (var i = lane; i < input.length; i += 4) input[i] = i + lane;
        \\  var checksum = 0;
        \\  for (var round = 0; round < 4; round++) {
        \\    Array.prototype.forEach.call(input, function (value, index, source) {
        \\      if (source !== input) throw new Error("wrong callback source");
        \\      checksum += value + index + round;
        \\    });
        \\  }
        \\  return checksum;
        \\}
        \\var genericArrayThreads = [];
        \\for (var lane = 0; lane < 4; lane++) genericArrayThreads.push(new Thread(genericArrayLane, lane));
        \\var genericArrayTotal = 0;
        \\for (var lane = 0; lane < 4; lane++) genericArrayTotal += genericArrayThreads[lane].join();
        \\genericArrayTotal;
    );
    try std.testing.expectEqual(@as(f64, 264192), result.asNum());
}

test "parallel_js: sparse Array hole index serializes disjoint deletion and fill" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .parallel_gc = true,
        .enable_threads = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    const result = try ctx.evaluate(
        \\globalThis.sharedHoleArray = [];
        \\for (var i = 0; i < 256; i++) sharedHoleArray.push(i);
        \\function sharedHoleLane(lane) {
        \\  var checksum = 0;
        \\  for (var round = 0; round < 32; round++) {
        \\    for (var i = lane; i < sharedHoleArray.length; i += 4) {
        \\      if (!delete sharedHoleArray[i]) throw new Error("delete failed");
        \\      if (i in sharedHoleArray) throw new Error("deleted index remained present");
        \\      sharedHoleArray[i] = i + round;
        \\      if (!(i in sharedHoleArray) || sharedHoleArray[i] !== i + round)
        \\        throw new Error("filled index was not published");
        \\      checksum += sharedHoleArray[i];
        \\    }
        \\  }
        \\  return checksum;
        \\}
        \\var sharedHoleThreads = [];
        \\for (var lane = 0; lane < 4; lane++) sharedHoleThreads.push(new Thread(sharedHoleLane, lane));
        \\var sharedHoleTotal = 0;
        \\for (var lane = 0; lane < 4; lane++) sharedHoleTotal += sharedHoleThreads[lane].join();
        \\for (var i = 0; i < 256; i++) {
        \\  if (!(i in sharedHoleArray) || sharedHoleArray[i] !== i + 31)
        \\    throw new Error("final dense value mismatch");
        \\}
        \\sharedHoleTotal;
    );
    try std.testing.expectEqual(@as(f64, 1_171_456), result.asNum());
}

test "array instances inherit from Array.prototype (incl. holes)" {
    try std.testing.expect((try evalIn("Object.getPrototypeOf([]) === Array.prototype")).asBool());
    try std.testing.expect((try evalIn("[].map === Array.prototype.map")).asBool());
    // A hole reads through the prototype chain (inherited index), so an
    // accessor installed on Array.prototype is seen by index access + iteration.
    try std.testing.expectEqual(@as(f64, 11), (try evalIn(
        \\Object.defineProperty(Array.prototype, "0", { get: function () { return 11; }, configurable: true });
        \\[, , ,][0]
    )).asNum());
    try std.testing.expect((try evalIn(
        \\Object.defineProperty(Array.prototype, "0", { get: function () { return 11; }, configurable: true });
        \\var r = false; [, , ,].forEach(function (v, i) { if (i === 0) r = (v === 11); }); r
    )).asBool());
    // Ordinary arrays are unaffected: a real hole with no inherited index is undefined.
    try std.testing.expect((try evalIn("[1, , 3][1] === undefined")).asBool());
    try std.testing.expectEqual(@as(f64, 2), (try evalIn("[1, 2, 3][1]")).asNum());
    try std.testing.expect((try evalIn(
        \\var hit = 0;
        \\try {
        \\  Object.defineProperty(Array.prototype, "0", { set: function (v) { hit = v; }, configurable: true });
        \\  var a = [];
        \\  a[0] = 7;
        \\  hit === 7 && a.length === 0 && !Object.prototype.hasOwnProperty.call(a, "0");
        \\} finally {
        \\  delete Array.prototype[0];
        \\}
    )).asBool());
    try expectEvalStr("0|false|1",
        \\try {
        \\  Object.defineProperty(Array.prototype, "0", { value: 1, writable: false, configurable: true });
        \\  var a = [];
        \\  a[0] = 7;
        \\  a.length + "|" + Object.prototype.hasOwnProperty.call(a, "0") + "|" + a[0];
        \\} finally {
        \\  delete Array.prototype[0];
        \\}
    );
    try expectEvalStr("seed|1|true|local",
        \\var proto = ["seed"];
        \\var a = [];
        \\Object.setPrototypeOf(a, proto);
        \\var before = a[0];
        \\a[0] = "local";
        \\before + "|" + a.length + "|" + Object.prototype.hasOwnProperty.call(a, "0") + "|" + a[0];
    );
}

