        \\const boxedDirect = JSON.stringify(new String(key)) === '"caf\u00e9\u00ff"';
        \\const primitive = JSON.stringify(source, [key]) === '{"caf\u00e9\u00ff":17}';
        \\const boxed = JSON.stringify(source, [new String(key)]) === '{"caf\u00e9\u00ff":17}';
        \\const numberBox = new Number(0);
        \\numberBox.toString = () => key;
        \\const overridden = JSON.stringify(source, [numberBox]) === '{"caf\u00e9\u00ff":17}';
        \\const gap = JSON.stringify({ a: 1 }, null, new String("\u00e9")) === '{\n\u00e9"a": 1\n}';
        \\const rawText = '"caf\u00e9\u00ff"';
        \\const raw = JSON.stringify(JSON.rawJSON(rawText)) === rawText;
        \\direct && boxedDirect && primitive && boxed && overridden && gap && raw
    )).asBool());
}

test "JSON stringify deep cycle membership preserves forced execution tiers" {
    const source =
        \\function stringifyTierWitness() {
        \\  "use strict";
        \\  var leaf = { marker: 7 };
        \\  var deep = leaf;
        \\  for (var i = 0; i < 96; i = i + 1) deep = { next: deep };
        \\  var encoded = JSON.stringify({ deep: deep, aliases: [leaf, leaf] });
        \\  return encoded.indexOf('"marker":7') >= 0 &&
        \\    encoded.indexOf('"aliases":[{"marker":7},{"marker":7}]}') >= 0;
        \\}
        \\stringifyTierWitness();
    ;
    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    var results: [modes.len]u64 = undefined;

    for (modes, 0..) |mode, index| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();

        results[index] = (try ctx.evaluate(source)).rawBits();
        const inventory = ctx.bytecodeAdmissionSnapshot();
        switch (mode) {
            .tree_walker => try std.testing.expectEqual(@as(u64, 1), inventory.count(.plain_forced_tree_walker)),
            .required => {
                try std.testing.expectEqual(@as(u64, 1), inventory.count(.template_plain_compiled));
                try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
            },
            .automatic => unreachable,
        }
    }
    try std.testing.expectEqual(results[0], results[1]);
    try std.testing.expect(Value.fromRawBits(results[0]).asBool());
}

test "enable_gc: JSON stringify active index survives a callback collection request" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();
    const collections_before = ctx.gc.?.collections;

    const result = try ctx.evaluate(
        \\let gcLeaf = { marker: 7 };
        \\let gcDeep = gcLeaf;
        \\for (let i = 0; i < 96; i++) gcDeep = { next: gcDeep };
        \\let gcWide = "safe";
        \\for (let i = 0; i < 12; i++) gcWide += gcWide;
        \\let gcCalls = 0;
        \\globalThis.gcJsonResult = JSON.stringify({ deep: gcDeep, aliases: [gcLeaf, gcLeaf], wide: gcWide }, function (key, value) {
        \\  if (++gcCalls === 64) gc();
        \\  return value;
        \\});
        \\gcJsonResult.indexOf('"marker":7') >= 0 &&
        \\  gcJsonResult.indexOf('"aliases":[{"marker":7},{"marker":7}]') >= 0 &&
        \\  gcJsonResult.indexOf('"wide":"safesafe') >= 0;
    );
    try std.testing.expect(result.asBool());
    try std.testing.expect(ctx.gc.?.collections > collections_before);

    // The callback's request is serviced at the evaluate-tail quiescent point.
    // A subsequent moving collection must retain the published output through
    // the Context root after the invocation-local identity index is released.
    const compacted = ctx.compactGarbage();
    try std.testing.expect(compacted.status == .compacted or compacted.status == .no_candidates);
    try std.testing.expect((try ctx.evaluate(
        \\gcJsonResult.indexOf('"marker":7') >= 0 &&
        \\  gcJsonResult.indexOf('"aliases":[{"marker":7},{"marker":7}]') >= 0 &&
        \\  gcJsonResult.indexOf('"wide":"safesafe') >= 0
    )).asBool());
}

test "heap_limit_bytes: JSON stringify direct object output fails atomically" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
