        \\let jsonSource = { omittedFirst: undefined };
        \\for (let i = 0; i < 8; i++) jsonSource["field" + i] = jsonChunk;
        \\jsonSource.omittedLast = function () {};
        \\let jsonCallbacks = 0;
        \\globalThis.jsonPublished = "sentinel";
        \\let jsonCaught = false;
