        \\  var date = new Date(0);
        \\  for (var i = 0; i < 2048; i++)
        \\    date.setUTCHours((i + lane) % 24, (i * 3) % 60, (i * 7) % 60, (i * 17) % 1000, extra);
        \\  return calls === 0 && date.getUTCMilliseconds() === (2047 * 17) % 1000 ? 1 : 0;
