    try std.testing.expect((try evalIn("typeof new Object() === 'object'")).asBool());
}

test "Function.prototype: call / apply / bind" {
    try std.testing.expectEqual(@as(f64, 7), (try evalIn(
        \\function add(a, b) { return a + b; }
