        \\count
    )).asNum());
    try std.testing.expectEqual(@as(f64, 1), (try evalIn(
        \\var set = new Set(['foo', 'bar']);
        \\var count = 0;
        \\set.forEach(function(value) { if (count === 0) set.delete('bar'); count++; });
        \\count
    )).asNum());
    try expectEvalStr("1,2,3,1|3|2,3,1",
