    )).asNum());
}

test "Map and Set size use the exact live count after historical churn" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    const result = try ctx.evaluate(
        \\globalThis.__sizeMap = new Map();
        \\globalThis.__sizeSet = new Set();
        \\for (let i = 0; i < 4096; i++) {
        \\  __sizeMap.set(i, i);
        \\  __sizeSet.add(i);
        \\  __sizeMap.delete(i);
        \\  __sizeSet.delete(i);
        \\}
        \\for (let i = 0; i < 64; i++) {
        \\  __sizeMap.set(i, i * 2);
        \\  __sizeSet.add(i);
        \\}
        \\__sizeMap.size * 1000 + __sizeSet.size
    );
    try std.testing.expectEqual(@as(f64, 64064), result.asNum());

    const map = ctx.global_object.getOwn("__sizeMap").?.asObj();
    const set = ctx.global_object.getOwn("__sizeSet").?.asObj();
    try std.testing.expectEqual(@as(usize, 64), map.collectionState().?.coll_live_count);
    try std.testing.expectEqual(@as(usize, 64), set.collectionState().?.coll_live_count);
    // Deletion compacts in-place whenever tombstones dominate a historical
    // list of at least 64 slots. This exact churn empties each 64-slot window,
    // so only the final live entries remain.
    try std.testing.expectEqual(@as(usize, 64), map.elementsLen());
    try std.testing.expectEqual(@as(usize, 64), set.elementsLen());
    for ([_]*value.Object{ map, set }) |collection| {
        const state = collection.collectionState().?;
        try std.testing.expect(collection.elementsState().?.list.capacity <= 128);
        try std.testing.expect(state.coll_serials.capacity <= 128);
        try std.testing.expect(state.coll_next.capacity <= 128);
        try std.testing.expect(state.coll_index.capacity() <= 128);
    }

    _ = try ctx.evaluate("__sizeMap.clear(); __sizeSet.clear(); 0");
    for ([_]*value.Object{ map, set }) |collection| {
        const state = collection.collectionState().?;
        try std.testing.expectEqual(@as(usize, 0), collection.elementsState().?.list.capacity);
        try std.testing.expectEqual(@as(usize, 0), state.coll_serials.capacity);
        try std.testing.expectEqual(@as(usize, 0), state.coll_next.capacity);
        try std.testing.expectEqual(@as(u32, 0), state.coll_index.capacity());
    }
    const never_populated = (try ctx.evaluate("globalThis.__emptyMap = new Map(); __emptyMap.clear(); __emptyMap")).asObj();
    try std.testing.expect(never_populated.elementsState() == null);
    try std.testing.expect(!never_populated.backingFlagsSnapshot().elements);
}

test "Map logical cursors survive moving GC and tombstone compaction" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    try std.testing.expectEqual(@as(f64, 0), (try ctx.evaluate(
        \\globalThis.__cursorMap = new Map();
        \\for (let i = 0; i <= 128; i++) __cursorMap.set(i, i);
        \\globalThis.__cursor = __cursorMap.keys();
        \\__cursor.next().value
    )).asNum());

    // The iterator's internal [[IteratedMap]] edge must relocate with the map.
    ctx.collectGarbage();
    const result = try ctx.evaluate(
        \\for (let i = 1; i <= 65; i++) __cursorMap.delete(i);
        \\__cursorMap.set(2, 200);
        \\let remaining = [];
        \\for (let step = __cursor.next(); !step.done; step = __cursor.next()) remaining.push(step.value);
        \\let walked = [];
        \\let second = new Map();
        \\for (let i = 0; i <= 128; i++) second.set(i, i);
        \\second.forEach(function(value, key) {
        \\  walked.push(key);
        \\  if (key === 0) for (let i = 1; i <= 65; i++) second.delete(i);
        \\});
        \\remaining.length === 64 && remaining[0] === 66 && remaining[63] === 2 &&
        \\walked.length === 64 && walked[0] === 0 && walked[1] === 66 && walked[63] === 128
    );
    try std.testing.expect(result.asBool());
    try std.testing.expectEqual(@as(usize, 65), ctx.global_object.getOwn("__cursorMap").?.asObj().elementsLen());
}

