        \\var ordinaryKeys = Reflect.ownKeys(ordinary);
        \\var sparse = [];
        \\sparse[4096] = 1;
        \\sparse[3] = 2;
        \\sparse.named = 3;
        \\var sparseKeys = Reflect.ownKeys(sparse);
        \\var fixed = {};
