test "deleted Object.prototype.toString is not synthesized" {
    try std.testing.expect((try evalIn(
        \\var f = Object.prototype.toString;
        \\var deleted = delete Object.prototype.toString;
        \\var threw = false;
        \\try { Object.prototype.toString(); } catch (e) { threw = e instanceof TypeError; }
        \\Object.defineProperty(Object.prototype, "toString", { value: f, writable: true, configurable: true });
        \\deleted && threw
    )).asBool());
}

test "Object.keys/values/entries enumerate array indices" {
    try expectEvalStr("0,1,2", "Object.keys([10, 20, 30]).join(',')");
    try std.testing.expectEqual(@as(f64, 60), (try evalIn("Object.values([10, 20, 30]).reduce(function(a,b){return a+b;}, 0)")).asNum());
    try std.testing.expectEqual(@as(f64, 2), (try evalIn("Object.entries([7, 8]).length")).asNum());
    try expectEvalStr("0,7", "Object.entries([7, 8])[0].join(',')");
    // A non-enumerable index is skipped.
    try expectEvalStr("1", "var a = [10, 20]; Object.defineProperty(a, 0, { enumerable: false }); Object.keys(a).join(',')");
}

test "Object.fromEntries uses a strict captured iterator record" {
    try std.testing.expect((try evalIn(
        \\let manualCalls = 0;
        \\const manual = { next() { manualCalls += 1; return { done: true }; } };
        \\let manualError = false;
        \\try { Object.fromEntries(manual); } catch (error) { manualError = error instanceof TypeError; }
        \\let gets = 0;
        \\let calls = 0;
        \\const iterator = {
        \\  get next() {
        \\    gets += 1;
        \\    return function () {
        \\      calls += 1;
        \\      if (calls === 1) {
        \\        Object.defineProperty(iterator, "next", {
        \\          value() { throw new Error("replacement must not run"); },
        \\          configurable: true,
        \\        });
        \\        return { value: ["a", 1], done: false };
        \\      }
        \\      if (calls === 2) return { value: ["b", 2], done: false };
        \\      return { done: true };
        \\    };
        \\  },
        \\};
        \\const result = Object.fromEntries({ [Symbol.iterator]() { return iterator; } });
        \\manualError && manualCalls === 0 && gets === 1 && calls === 3 &&
        \\result.a === 1 && result.b === 2;
    )).asBool());

    try std.testing.expect((try evalIn(
        \\let closed = 0;
        \\const iterator = {
        \\  next() { return { value: Symbol("entry"), done: false }; },
        \\  return() { closed += 1; throw new Error("close error must not win"); },
        \\};
        \\let typeError = false;
        \\try { Object.fromEntries({ [Symbol.iterator]() { return iterator; } }); }
        \\catch (error) { typeError = error instanceof TypeError; }
        \\typeError && closed === 1;
    )).asBool());
}

test "String exotic wrappers expose immutable indices and length" {
    try expectEvalStr("0,1,2,20,-20", "var s = new String('abc'); s[-20] = 1; s[20] = 2; Object.keys(s).join(',')");
    try expectEvalStr("0,1,2,20,length,-20", "var s = new String('abc'); s[-20] = 1; s[20] = 2; Object.getOwnPropertyNames(s).join(',')");
    try std.testing.expect((try evalIn(
        \\var s = new String("abc");
        \\var d0 = Object.getOwnPropertyDescriptor(s, "0");
        \\var dl = Object.getOwnPropertyDescriptor(s, "length");
        \\d0.value === "a" && d0.enumerable === true && d0.writable === false && d0.configurable === false &&
        \\dl.value === 3 && dl.enumerable === false && dl.writable === false && dl.configurable === false
    )).asBool());
}

test "String exotic reflection uses UTF-16 code units across representations" {
    try std.testing.expect((try evalIn(
        \\var astral = String.fromCodePoint(0x1F4A9);
        \\var high = String.fromCharCode(0xD83D);
        \\var low = String.fromCharCode(0xDCA9);
        \\var primitive = "\u00E9" + astral + high;
        \\var boxed = new String(primitive);
        \\var d0 = Object.getOwnPropertyDescriptor(boxed, "0");
        \\var d1 = Object.getOwnPropertyDescriptor(boxed, "1");
        \\var d2 = Object.getOwnPropertyDescriptor(boxed, "2");
        \\var d3 = Object.getOwnPropertyDescriptor(boxed, "3");
        \\var dl = Object.getOwnPropertyDescriptor(boxed, "length");
        \\var primitiveD2 = Object.getOwnPropertyDescriptor(primitive, "2");
        \\var flat = "\u00E9".repeat(20);
        \\var flatLast = Object.getOwnPropertyDescriptor(flat, "19");
        \\var flatSpread = { ...flat };
        \\var spread = { ...primitive };
        \\var { ...rest } = primitive;
        \\d0.value === "\u00E9" && d1.value === high && d2.value === low && d3.value === high &&
        \\d0.enumerable === true && d0.writable === false && d0.configurable === false &&
        \\dl.value === 4 && dl.enumerable === false && dl.writable === false && dl.configurable === false &&
        \\primitiveD2.value === low && flatLast.value === "\u00E9" && flatSpread[19] === "\u00E9" &&
        \\Object.getOwnPropertyDescriptor(flat, "length").value === 20 &&
        \\Reflect.defineProperty(boxed, "1", { value: boxed[1] }) === true &&
        \\Reflect.defineProperty(boxed, "1", { value: "x" }) === false &&
        \\spread[0] === "\u00E9" && spread[1] === high && spread[2] === low && spread[3] === high &&
        \\rest[0] === "\u00E9" && rest[1] === high && rest[2] === low && rest[3] === high
    )).asBool());
}

test "String result builders canonicalize physical storage" {
    try std.testing.expect((try evalIn(
        \\const text = "caf\u00e9\u00ff";
        \\let rawCalls = 0;
        \\const rawSub = { toString() { rawCalls++; return text; } };
        \\const raw = String.raw({ raw: ["<", ">"] }, rawSub) === "<caf\u00e9\u00ff>" && rawCalls === 1;
        \\let separatorCalls = 0;
        \\const separator = { toString() { separatorCalls++; return text; } };
        \\const joined = new Uint8Array([1, 2]).join(separator) === "1caf\u00e9\u00ff2" && separatorCalls === 1;
        \\const oldNumberLocale = Number.prototype.toLocaleString;
        \\let localeCalls = 0;
        \\Number.prototype.toLocaleString = function() { localeCalls++; return text; };
        \\let localized;
        \\try {
        \\  localized = [1, 2].toLocaleString() === "caf\u00e9\u00ff,caf\u00e9\u00ff" &&
        \\    new Uint8Array([1, 2]).toLocaleString() === "caf\u00e9\u00ff,caf\u00e9\u00ff" && localeCalls === 4;
        \\} finally {
        \\  Number.prototype.toLocaleString = oldNumberLocale;
        \\}
        \\raw && joined && localized
    )).asBool());
}

test "Annex B CreateHTML attributes canonicalize physical storage" {
    try std.testing.expect((try evalIn(
        \\const text = "caf\u00e9\"\u00ff";
        \\const escaped = "caf\u00e9&quot;\u00ff";
        \\let calls = 0;
        \\const attr = { toString() { calls++; return text; } };
        \\const wrappers = "x".anchor(attr) === '<a name="' + escaped + '">x</a>' &&
        \\  "x".fontcolor(attr) === '<font color="' + escaped + '">x</font>' &&
        \\  "x".fontsize(attr) === '<font size="' + escaped + '">x</font>' &&
        \\  "x".link(attr) === '<a href="' + escaped + '">x</a>' && calls === 4;
        \\const order = [];
        \\const ordered = String.prototype.anchor.call(
        \\  { toString() { order.push("receiver"); return "x"; } },
        \\  { toString() { order.push("attribute"); return text; } }
        \\) === '<a name="' + escaped + '">x</a>';
        \\wrappers && ordered && order.join(",") === "receiver,attribute"
    )).asBool());
}

test "borrowed Array mutators throw on String exotic length writes" {
    try std.testing.expect((try evalIn(
        \\function throws(fn) {
        \\  try { fn(); } catch (e) { return e instanceof TypeError; }
        \\  return false;
        \\}
        \\throws(function() { Array.prototype.push.call("abc", 1); }) &&
        \\throws(function() { Array.prototype.push.call("", 1); }) &&
        \\throws(function() { Array.prototype.push.call(""); }) &&
        \\throws(function() { Array.prototype.unshift.call("abc"); }) &&
        \\throws(function() { Array.prototype.pop.call(""); })
    )).asBool());
}

