        \\const mmBox = { ready: false, payload: null };
        \\const mmConsumer = new Thread(() => {
        \\  let observed;
        \\  mmLock.hold(() => {
        \\    while (!mmBox.ready) mmCondition.wait(mmLock);
        \\    observed = mmBox.payload;
        \\  });
        \\  return observed;
        \\});
        \\const mmProducer = new Thread(() => {
        \\  mmLock.hold(() => {
        \\    mmBox.payload = { marker: 41, nested: { complete: true } };
        \\    mmBox.ready = true;
        \\    mmCondition.notify();
        \\  });
        \\});
