test "named deletion sidecars survive moving GC relocation" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    _ = try ctx.evaluate(
        \\globalThis.namedDeletionDiscard = [];
        \\for (let i = 0; i < 4096; i++) namedDeletionDiscard.push({ i: i, dead: true });
        \\namedDeletionDiscard = null;
        \\globalThis.namedDeletionGc = {};
        \\for (let i = 0; i < 128; i++) namedDeletionGc["field-" + i] = i;
        \\Object.defineProperty(namedDeletionGc, "accessor", { get: function () { return 900; }, enumerable: true, configurable: true });
        \\for (let i = 0; i < 96; i++) delete namedDeletionGc["field-" + i];
        \\Object.defineProperty(namedDeletionGc, "field-0", { value: 1000, writable: false, enumerable: false, configurable: true });
    );
    ctx.collectGarbage();
    const compacted = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, compacted.status);
    try std.testing.expect(compacted.moved_cells > 0);

    const result = try ctx.evaluate(
        \\var keys = Reflect.ownKeys(namedDeletionGc);
        \\var descriptor = Object.getOwnPropertyDescriptor(namedDeletionGc, "field-0");
        \\keys.length === 34 && keys[0] === "field-96" && keys[31] === "field-127" &&
        \\keys[32] === "accessor" && keys[33] === "field-0" &&
        \\namedDeletionGc.accessor === 900 && namedDeletionGc["field-127"] === 127 &&
        \\descriptor.value === 1000 && !descriptor.writable && !descriptor.enumerable && descriptor.configurable
    );
    try std.testing.expect(result.asBool());
}

test "deep shape indexes survive bounded allocation and moving GC" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .heap_limit_bytes = 32 * 1024 * 1024,
    });
    defer ctx.destroy();
    ctx.collectGarbage();

    _ = try ctx.evaluate(
        \\globalThis.deepShapeDiscard = [];
        \\for (var i = 0; i < 4096; i++) deepShapeDiscard.push({ index: i, dead: true });
        \\globalThis.deepShapeIndexed = {};
        \\for (var i = 0; i < 4096; i++) deepShapeIndexed["property-" + i] = i;
        \\deepShapeDiscard = null;
    );
    ctx.collectGarbage();
    const before = ctx.global_object.getOwn("deepShapeIndexed").?.asObj();
    const moved = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, moved.status);
    const after = ctx.global_object.getOwn("deepShapeIndexed").?.asObj();
    try std.testing.expect(before != after);

    const result = try ctx.evaluate(
        \\var deepShapeChecksum = 0;
        \\for (var i = 0; i < 4096; i++) {
        \\  if ((i & 511) === 0) gc();
        \\  deepShapeChecksum += deepShapeIndexed["property-" + i];
        \\}
        \\deepShapeChecksum;
    );
    try std.testing.expectEqual(@as(f64, 8386560), result.asNum());
    const stats = ctx.heapBudgetStats().?;
    try std.testing.expect(stats.peak_bytes <= stats.limit_bytes);
    try std.testing.expect(stats.used_bytes < stats.limit_bytes);
}

test "parallel_js deep shape lookup and transition publication converge" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .parallel_gc = true,
        .enable_threads = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    const result = try ctx.evaluate(
        \\function deepShapeLane(lane) {
        \\  var total = 0;
        \\  for (var round = 0; round < 4; round++) {
        \\    var object = { anchor: lane };
        \\    for (var i = 0; i < 256; i++) object["shared-property-" + i] = i + lane;
        \\    for (var i = 0; i < 256; i++) total += object["shared-property-" + i];
        \\  }
        \\  for (var round = 0; round < 64; round++) {
        \\    var branch = { fanoutAnchor: true };
        \\    var key = "lane-" + lane + "-round-" + round;
        \\    branch[key] = lane + round;
        \\    total += branch[key];
        \\  }
        \\  return total;
        \\}
        \\var deepShapeThreads = [];
        \\for (var lane = 0; lane < 4; lane++) deepShapeThreads.push(new Thread(deepShapeLane, lane));
        \\var deepShapeTotal = 0;
        \\for (var lane = 0; lane < 4; lane++) deepShapeTotal += deepShapeThreads[lane].join();
        \\deepShapeTotal;
    );
    try std.testing.expectEqual(@as(f64, 536832), result.asNum());
}

test "parallel_js named deletion serializes shape slots descriptors and compaction" {
    if (builtin.single_threaded) return error.SkipZigTest;

    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    const result = try ctx.evaluate(
        \\globalThis.namedDeleteShared = { anchor: 7 };
        \\for (let i = 0; i < 128; i++) namedDeleteShared["field-" + i] = i;
        \\function churnNamedDelete(lane) {
        \\  for (let round = 0; round < 16; round++) {
        \\    for (let i = lane; i < 128; i += 4) {
        \\      let key = "field-" + i;
        \\      if (!delete namedDeleteShared[key]) throw new Error("delete failed");
        \\      Object.defineProperty(namedDeleteShared, key, {
        \\        value: round * 1000 + i, writable: false, enumerable: false, configurable: true
        \\      });
        \\    }
        \\  }
        \\  return lane;
        \\}
        \\var namedDeleteThreads = [];
        \\for (let lane = 0; lane < 4; lane++) namedDeleteThreads.push(new Thread(churnNamedDelete, lane));
        \\var joined = 0;
        \\for (let thread of namedDeleteThreads) joined += thread.join();
        \\var exact = namedDeleteShared.anchor === 7 && joined === 6 && Reflect.ownKeys(namedDeleteShared).length === 129;
        \\for (let i = 0; i < 128; i++) {
        \\  let descriptor = Object.getOwnPropertyDescriptor(namedDeleteShared, "field-" + i);
        \\  exact = exact && descriptor.value === 15000 + i && !descriptor.writable &&
        \\    !descriptor.enumerable && descriptor.configurable;
        \\}
        \\exact;
    );
    try std.testing.expect(result.asBool());

    const object = ctx.global_object.getOwn("namedDeleteShared").?.asObj();
    const live = object.shape.?.live_count;
    try std.testing.expect(object.shape.?.depth <= @max(@as(u32, 64), live *| 2 +| 8));
    try std.testing.expect(object.keyOrder().?.items.len <= @max(@as(usize, 64), @as(usize, live) *| 2 +| 8));
}

test "Context threads run parallel by default; gil option opts into serialized mode" {
    // Default: enable_threads => true-parallel (no GIL), GC-managed cells.
    {
        const ctx = try Context.createWith(std.testing.allocator, .{ .enable_threads = true });
        defer ctx.destroy();
        const v = try ctx.evaluate("let s = 0; for (let i = 0; i < 100; i++) s += i; s");
        try std.testing.expectEqual(@as(f64, 4950), v.asNum());
        try std.testing.expect(ctx.parallel_js); // parallel is the default
        try std.testing.expect(ctx.gc.?.parallel);
        try std.testing.expect(ctx.gc_cell_backing.?.parallel);
        try std.testing.expect(ctx.host_allocator_lock != null);
    }
    // Opt-out: gil => the serialized (GIL) path.
    {
        const ctx = try Context.createWith(std.testing.allocator, .{ .enable_threads = true, .gil = true });
        defer ctx.destroy();
        const v = try ctx.evaluate("1 + 2");
        try std.testing.expectEqual(@as(f64, 3), v.asNum());
        try std.testing.expect(!ctx.parallel_js); // GIL serializes instead
        try std.testing.expect(ctx.host_allocator_lock == null);
    }
    // No threads => single-threaded, neither path engaged.
    {
        const ctx = try Context.createWith(std.testing.allocator, .{});
        defer ctx.destroy();
        try std.testing.expect(!ctx.parallel_js);
        try std.testing.expect(ctx.host_allocator_lock == null);
    }
}

