test "Context native observability captures published function identity" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWith(std.testing.allocator, .{ .native_observability = true });
    defer ctx.destroy();
    const result = try ctx.evaluate(
        \\function observedNative(n) {
        \\  var total = 0;
        \\  var i = 0;
        \\  while (i < n) { total = total + i; i = i + 1; }
        \\  return total;
        \\}
        \\observedNative(100); observedNative(100); observedNative(100);
        \\observedNative(100); observedNative(100); observedNative(100);
        \\observedNative(100); observedNative(100); observedNative(100);
        \\observedNative(100)
    );
    try std.testing.expectEqual(@as(f64, 4950), result.asNum());
    const function_value = ctx.global_object.getOwn("observedNative") orelse return error.TestUnexpectedResult;
    const raw_function = function_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const function: *interp.Function = @ptrCast(@alignCast(raw_function));
    const chunk = function.chunk orelse return error.TestUnexpectedResult;
    const code = chunk.tier.loadCode() orelse
        chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    var snapshot = (try ctx.jit_owner.lookupNativeCode(
        std.testing.allocator,
        @intFromPtr(code.memory.executableBytes().ptr),
    )) orelse return error.TestUnexpectedResult;
    defer snapshot.deinit();
    try std.testing.expectEqualStrings("observedNative", snapshot.function_name);
    try std.testing.expectEqual(@intFromPtr(function), snapshot.function_identity);
    try std.testing.expect(snapshot.script_id != 0);
    try std.testing.expectEqual(@as(usize, 0), snapshot.source_byte_offset);
    try std.testing.expectEqual(@as(usize, 1), snapshot.source_line);
    try std.testing.expectEqual(@as(usize, 1), snapshot.source_column);
    try std.testing.expect(snapshot.bytecode_offset == null);
    try std.testing.expect(!snapshot.source_is_exact);

    const pc_map = code.native_pc_map orelse return error.TestUnexpectedResult;
    for (pc_map.entries) |entry| {
        const bytecode_offset = entry.bytecode_offset orelse continue;
        const instruction: usize = bytecode_offset;
        if (instruction >= chunk.debug_nodes.len) continue;
        const node = chunk.debug_nodes[instruction] orelse continue;
        const inspector_location = ctx.debug_statement_locations.get(node) orelse continue;
        var exact = (try ctx.jit_owner.lookupNativeCode(
            std.testing.allocator,
            @intFromPtr(code.memory.executableBytes().ptr) + entry.native_offset,
        )) orelse return error.TestUnexpectedResult;
        defer exact.deinit();
        try std.testing.expectEqual(bytecode_offset, exact.bytecode_offset.?);
        try std.testing.expect(exact.source_is_exact);
        try std.testing.expectEqual(inspector_location.script_id, exact.script_id);
        try std.testing.expectEqualStrings(inspector_location.source_url, exact.source_url);
        try std.testing.expectEqual(inspector_location.location.byte_offset, exact.source_byte_offset);
        try std.testing.expectEqual(inspector_location.location.line, exact.source_line);
        try std.testing.expectEqual(inspector_location.location.column, exact.source_column);
        var signal_symbol: [256]u8 = undefined;
        var signal_function: [256]u8 = undefined;
        var signal_source: [256]u8 = undefined;
        const signal_exact = (try ctx.lookupNativeCodeSignalSafe(
            @intFromPtr(code.memory.executableBytes().ptr) + entry.native_offset,
            .{
                .symbol_name = &signal_symbol,
                .function_name = &signal_function,
                .source_url = &signal_source,
            },
        )) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(exact.artifact_id, signal_exact.artifact_id);
        try std.testing.expectEqualStrings(exact.symbol_name, signal_exact.symbol_name);
        try std.testing.expectEqualStrings(exact.function_name, signal_exact.function_name);
        try std.testing.expectEqualStrings(exact.source_url, signal_exact.source_url);
        try std.testing.expectEqual(exact.bytecode_offset, signal_exact.bytecode_offset);
        try std.testing.expect(signal_exact.source_is_exact);
        try std.testing.expectEqual(exact.source_line, signal_exact.source_line);
        try std.testing.expectEqual(exact.source_column, signal_exact.source_column);
        break;
    } else return error.TestUnexpectedResult;

    const optimized = chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(jit.CodeKind.optimizer, optimized.kind);
    const optimizer_map = optimized.native_pc_map orelse return error.TestUnexpectedResult;
    for (optimizer_map.entries) |entry| {
        const bytecode_offset = entry.bytecode_offset orelse continue;
        const instruction: usize = bytecode_offset;
        if (instruction >= chunk.debug_nodes.len) continue;
        const node = chunk.debug_nodes[instruction] orelse continue;
        const inspector_location = ctx.debug_statement_locations.get(node) orelse continue;
        var exact = (try ctx.jit_owner.lookupNativeCode(
            std.testing.allocator,
            @intFromPtr(optimized.memory.executableBytes().ptr) + entry.native_offset,
        )) orelse return error.TestUnexpectedResult;
        defer exact.deinit();
        try std.testing.expectEqual(jit.CodeKind.optimizer, exact.kind);
        try std.testing.expectEqual(bytecode_offset, exact.bytecode_offset.?);
        try std.testing.expect(exact.source_is_exact);
        try std.testing.expectEqual(inspector_location.script_id, exact.script_id);
        try std.testing.expectEqualStrings(inspector_location.source_url, exact.source_url);
        try std.testing.expectEqual(inspector_location.location.byte_offset, exact.source_byte_offset);
        try std.testing.expectEqual(inspector_location.location.line, exact.source_line);
        try std.testing.expectEqual(inspector_location.location.column, exact.source_column);
        break;
    } else return error.TestUnexpectedResult;
}

