    const cases = [_]Case{
        .{ .source = "new Intl.DisplayNames('en',{type:'language',style:'narrow'}).resolvedOptions().style", .expected = "narrow", .cell = strcell.staticCell("narrow") },
        .{ .source = "new Intl.DisplayNames('en',{type:'language',style:'short'}).resolvedOptions().style", .expected = "short", .cell = strcell.staticCell("short") },
        .{ .source = "new Intl.DisplayNames('en',{type:'language',style:'long'}).resolvedOptions().style", .expected = "long", .cell = strcell.staticCell("long") },
        .{ .source = "new Intl.DisplayNames('en',{type:'language'}).resolvedOptions().type", .expected = "language", .cell = strcell.staticCell("language") },
        .{ .source = "new Intl.DisplayNames('en',{type:'region'}).resolvedOptions().type", .expected = "region", .cell = strcell.staticCell("region") },
        .{ .source = "new Intl.DisplayNames('en',{type:'script'}).resolvedOptions().type", .expected = "script", .cell = strcell.staticCell("script") },
        .{ .source = "new Intl.DisplayNames('en',{type:'currency'}).resolvedOptions().type", .expected = "currency", .cell = strcell.staticCell("currency") },
        .{ .source = "new Intl.DisplayNames('en',{type:'calendar'}).resolvedOptions().type", .expected = "calendar", .cell = strcell.staticCell("calendar") },
        .{ .source = "new Intl.DisplayNames('en',{type:'dateTimeField'}).resolvedOptions().type", .expected = "dateTimeField", .cell = strcell.staticCell("dateTimeField") },
        .{ .source = "new Intl.DisplayNames('en',{type:'region',fallback:'code'}).resolvedOptions().fallback", .expected = "code", .cell = strcell.staticCell("code") },
        .{ .source = "new Intl.DisplayNames('en',{type:'region',fallback:'none'}).resolvedOptions().fallback", .expected = "none", .cell = strcell.staticCell("none") },
        .{ .source = "new Intl.DisplayNames('en',{type:'language',languageDisplay:'dialect'}).resolvedOptions().languageDisplay", .expected = "dialect", .cell = strcell.staticCell("dialect") },
        .{ .source = "new Intl.DisplayNames('en',{type:'language',languageDisplay:'standard'}).resolvedOptions().languageDisplay", .expected = "standard", .cell = strcell.staticCell("standard") },
    };

    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
    });
    defer ctx.destroy();
    var last: Value = Value.undef();
    for (cases) |case| {
        last = try ctx.evaluate(case.source);
        try std.testing.expectEqualStrings(case.expected, last.asStr());
        try std.testing.expectEqual(case.cell, last.asStringCell());
        try std.testing.expect(!last.asStringCell().isGcManaged());
    }
    const dynamic_locale = try ctx.evaluate("new Intl.DisplayNames('de',{type:'language'}).resolvedOptions().locale");
    try std.testing.expect(dynamic_locale.asStringCell().isGcManaged());
    ctx.collectGarbage();
    try std.testing.expectEqualStrings("standard", last.asStr());
}

test "Intl.DisplayNames reclaims compound-tag scratch under a heap limit" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .heap_limit_bytes = 32 * 1024 * 1024,
        .step_budget = std.math.maxInt(u64),
    });
    defer ctx.destroy();
    const before = ctx.heapBudgetStats().?.used_bytes;

    const result = try ctx.evaluate(
        \\const languages = new Intl.DisplayNames("en", {
        \\  type: "language",
        \\  languageDisplay: "standard",
        \\  fallback: "code"
        \\});
        \\const currencies = new Intl.DisplayNames("en", { type: "currency" });
        \\const language = "en-Latn-US-variant1-variant2-variant3";
        \\let checksum = 0;
        \\for (let index = 0; index < 4096; index++) {
        \\  checksum = (checksum + languages.of(language).length + currencies.of(index & 1 ? "usd" : "eur").length) % 1000003;
        \\}
        \\checksum > 0;
    );
    try std.testing.expect(result.asBool());
    const stats = ctx.heapBudgetStats().?;
    try std.testing.expect(stats.used_bytes -| before < 4 * 1024 * 1024);
    try std.testing.expect(stats.used_bytes < stats.limit_bytes);
    try std.testing.expect(stats.peak_bytes <= stats.limit_bytes);
}

test "Context step_budget keeps the default runaway guard and honours an override" {
    // The guard still fires for an ordinary embedding: `evaluate` must return
    // rather than spin forever on a runaway script.
    {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .step_budget = 200_000 });
        defer ctx.destroy();
        try std.testing.expectError(error.Throw, ctx.evaluate("while (true) {}"));
        const exception = ctx.exception orelse return error.TestUnexpectedResult;
        try std.testing.expect(exception.isObject());
        try std.testing.expectEqualStrings("RangeError", exception.asObj().errorName());
    }
    // A harness that deliberately runs long scripts can lift it. The PR-249
    // corpus runner does exactly this, because the JSC shell those files were
    // written against has no step budget at all — without it they fail for
    // running long rather than for being wrong (#429).
    {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .step_budget = std.math.maxInt(u64),
        });
        defer ctx.destroy();
        const result = try ctx.evaluate(
            \\let n = 0;
            \\for (let i = 0; i < 400000; ++i) n += i;
            \\n;
        );
        try std.testing.expectEqual(@as(f64, 79999800000), result.asNum());
    }
}

test "Context heap_limit_bytes names an escaping top-level OOM" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .heap_limit_bytes = 4 * 1024 * 1024 });
    defer ctx.destroy();

    // No enclosing `try`, so the failure escapes the host entry as an allocator
    // error rather than a JS throw. It must still name itself: a runner that can
    // only report "exception=<missing>" hides the exact semantic failure (#100).
    try std.testing.expectError(error.OutOfMemory, ctx.evaluate(
        \\var keep = [];
        \\for (var i = 0; i < 20000; i = i + 1)
        \\  keep.push({ i: i, nested: { j: i + 1 } });
        \\keep.length;
    ));
    const exception = ctx.exception orelse return error.TestUnexpectedResult;
    try std.testing.expect(exception.isObject());
    const obj = exception.asObj();
    try std.testing.expect(obj.behavior.is_error);
    try std.testing.expectEqualStrings("OutOfMemoryError", obj.errorName());
    const message = obj.getOwn("message") orelse return error.TestUnexpectedResult;
    try std.testing.expect(message.isString());
    try std.testing.expectEqualStrings("Context heap limit exceeded", message.asStr());

    // The reserved bootstrap object itself, not a fresh one: the failed path
    // cannot allocate, which is the whole reason it is prebuilt.
    try std.testing.expectEqual(ctx.reserved_thread_oom_error.?.bits, exception.bits);
}

test "Context bounded collection preserves reuse tails only with refill headroom" {
    try std.testing.expect(!Context.shouldReleaseEmptyCellTails(null, .ordinary_collection));
    try std.testing.expect(Context.shouldReleaseEmptyCellTails(null, .allocation_failure));
    const limit = 4 * 1024 * 1024;
    const protected = limit / 16;
    const healthy_used = limit - protected;
    try std.testing.expect(!Context.shouldReleaseEmptyCellTails(.{
        .limit_bytes = limit,
        .used_bytes = healthy_used,
        .peak_bytes = healthy_used,
        .remaining_bytes = protected,
    }, .ordinary_collection));
    try std.testing.expect(Context.shouldReleaseEmptyCellTails(.{
        .limit_bytes = limit,
        .used_bytes = healthy_used + 1,
        .peak_bytes = healthy_used + 1,
        .remaining_bytes = protected - 1,
    }, .ordinary_collection));
}

test "Context heap_limit_bytes never publishes a torn object under recovery pressure" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .heap_limit_bytes = 4 * 1024 * 1024,
    });
    defer ctx.destroy();

    // A live hoard drives the budget through allocation-failure recovery. Hold
    // an exact-shape reserve live across that boundary, then release it from a
    // separate evaluation and collect only after that native frame returns.
    // Collecting inside the creation frame is not an exact release boundary:
    // conservative stack scanning may legally retain stale reserve pointers
    // even after its JS binding becomes null (#657). The quiescent host boundary
    // guarantees a reclamation window under the unchanged 4 MiB cap without
    // weakening stack soundness. An allocation that survives that boundary must
    // be complete: the PR-249 OOM witness fails outright on a successfully
    // returned but torn object (#100). The counts stay small deliberately; this
    // is a correctness witness, not a stress run.
    const full_collections_before = ctx.runtimeHeapAccounting().full_collections;
    const pressure_result = try ctx.evaluate(
        \\globalThis.recoveryReserve = [];
        \\for (let i = 0; i < 128; ++i)
        \\  recoveryReserve.push({ idx: -i, arr: new Array(64).fill(i), s: "reserve_" + i });
        \\globalThis.recoveryHoard = [];
        \\let pressureOoms = 0;
        \\try { for (let i = 0; i < 50000; ++i) recoveryHoard.push({ i: i, j: i + 1 }); } catch (e) { ++pressureOoms; }
        \\pressureOoms;
    );
    const pressure_ooms: usize = @intFromFloat(pressure_result.asNum());
    try std.testing.expect(pressure_ooms > 0); // the cap actually bit

    _ = try ctx.evaluate("globalThis.recoveryReserve = null; 0;");
    ctx.collectGarbage();

    const result = try ctx.evaluate(
        \\let torn = 0, made = 0, ooms = 0;
        // Keep the recovery probe's loop control predeclared: the body `try`
        // deliberately scores complete Object publication, not an unrelated
        // per-iteration lexical-key allocation outside that catch boundary.
        \\for (var r = 0; r < 500; ++r) {
        \\  try {
        \\    const o = { idx: r, arr: new Array(64).fill(r), s: "small_" + r };
        \\    if (o.idx !== r || o.arr[63] !== r || o.s.length < 7) ++torn;
        \\    ++made;
        \\  } catch (e) { ++ooms; }
        \\}
        \\if (torn !== 0) throw new Error("torn " + torn + " of " + made + " (ooms " + ooms + ")");
        \\made * 1000 + ooms;
    );
    const encoded: usize = @intFromFloat(result.asNum());
    const made = encoded / 1_000;
    try std.testing.expect(made > 0); // at least one post-recovery object was validated
    try std.testing.expect(ctx.runtimeHeapAccounting().full_collections > full_collections_before);
}

test "Context whole-array fill leaves no unreclaimable per-element residue" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .heap_limit_bytes = 32 * 1024 * 1024,
    });
    defer ctx.destroy();

    // One warm-up fill first, so one-off arena growth is already paid for and
    // the delta below measures only per-round residue. Collect before reading
    // the baseline, and again before the final reading, so the comparison is
    // between two *reclaimed* heaps rather than between accumulated garbage.
    _ = try ctx.evaluate("(function () { const a = new Array(1 << 16).fill(1); return a[0]; })(); gc();");
    const before = ctx.heapBudgetStats().?.used_bytes;

    // Each element of a whole-array `fill` used to leave a formatted index key
    // in the realm arena, which is never reclaimed within a Context: ~64 Ki keys
    // per round, retained forever, with no collection able to win them back.
    // That is what makes a capped heap's OOM state sticky and breaks the PR-249
    // OOM witness's post-storm allocation (#100). Every round's array is
    // dropped, so the budget must come back to roughly where it started.
    _ = try ctx.evaluate(
        \\for (let round = 0; round < 12; ++round) {
        \\  const a = new Array(1 << 16).fill(round);
        \\  if (a[(1 << 16) - 1] !== round) throw new Error("fill did not cover the array");
        \\}
        \\gc();
    );
    const after = ctx.heapBudgetStats().?.used_bytes;
    // Twelve rounds of retained keys ran to several megabytes that no collection
    // could win back; the collected arrays themselves leave nothing behind.
    try std.testing.expect(after -| before < 2 * 1024 * 1024);
}

test "Context generic Array traversal leaves no unreclaimable index-key residue" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .heap_limit_bytes = 32 * 1024 * 1024,
    });
    defer ctx.destroy();

    // The source intentionally has no indexed properties: HasProperty must still
    // observe every logical index, but the workload does not retain callback
    // results or object mutations that could obscure temporary key ownership.
    // Warm up once before the collected baseline so only repeated traversal is
    // measured below.
    _ = try ctx.evaluate(
        \\globalThis.genericBoundedSource = { length: 1 << 16 };
        \\Array.prototype.forEach.call(genericBoundedSource, function () { throw new Error("hole visited"); });
        \\gc();
    );
    const before = ctx.heapBudgetStats().?.used_bytes;

    _ = try ctx.evaluate(
        \\for (var round = 0; round < 12; round++)
        \\  Array.prototype.forEach.call(genericBoundedSource, function () { throw new Error("hole visited"); });
        \\gc();
    );
    const stats = ctx.heapBudgetStats().?;
    try std.testing.expect(stats.used_bytes -| before < 2 * 1024 * 1024);
    try std.testing.expect(stats.peak_bytes <= stats.limit_bytes);
}

