test "Thread blocking APIs respect the main can-block gate" {
    var ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .main_can_block = false,
    });
    defer ctx.destroy();

    const Expect = struct {
        fn typeError(context: *Context, src: []const u8, expected_message: []const u8) !void {
            if (context.evaluate(src)) |_| {
                try std.testing.expect(false);
            } else |err| {
                if (err != error.Throw) return err;
            }
            const thrown = context.exception orelse {
                try std.testing.expect(false);
                return;
            };
            try std.testing.expect(thrown.isObject());
            const obj = thrown.asObj();
            try std.testing.expectEqualStrings("TypeError", obj.errorName());
            const message = obj.getOwn("message") orelse {
                try std.testing.expect(false);
                return;
            };
            try std.testing.expect(message.isString());
            try std.testing.expectEqualStrings(expected_message, message.asStr());
        }
    };

    _ = try ctx.evaluate(
        \\globalThis.lockA = new Lock();
        \\if (lockA.hold(() => "ok") !== "ok") throw new Error("uncontended hold");
        \\lockA.asyncHold();
        \\if (!lockA.locked) throw new Error("asyncHold did not grant synchronously");
    );
    try Expect.typeError(ctx, "lockA.hold(() => 0)", "Lock.prototype.hold cannot block the current thread");

    _ = try ctx.evaluate(
        \\globalThis.lockB = new Lock();
        \\globalThis.condB = new Condition();
    );
    try Expect.typeError(ctx, "lockB.hold(() => condB.wait(lockB))", "Condition.prototype.wait cannot block the current thread");
    _ = try ctx.evaluate(
        \\if (lockB.locked) throw new Error("gated wait leaked lock hold");
        \\if (condB.notify() !== 0) throw new Error("gated wait enqueued waiter");
    );

    _ = try ctx.evaluate(
        \\globalThis.o = { k: 0 };
        \\if (Atomics.wait(o, "k", 1) !== "not-equal") throw new Error("wait fast path");
    );
    try Expect.typeError(ctx, "Atomics.wait(o, \"k\", 0)", "Atomics.wait cannot be called from the current thread.");

    // `api/blocking-gate.js` covers join gating separately because no-GIL
    // scheduling can legitimately turn a short join into a non-blocking fast
    // path, and failed top-level cleanup may race the worker's own termination.
}

test "enable_gc: object-heavy program runs and tears down clean (no leaks)" {
    // The Phase-7 M1 foundation: with the GC on, `newObject` allocates cells
    // through the collector instead of the arena. Collection is teardown-only
    // for now, so behavior matches the arena engine; this asserts correctness
    // and — under the testing allocator — that `destroy` reclaims every GC cell
    // (the heap's `deinit` frees them) with no leak.
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();
    try std.testing.expect(ctx.gc != null);

    const result = try ctx.evaluate(
        \\let acc = 0;
        \\for (let i = 0; i < 200; i++) {
        \\  const o = { a: i, b: { c: i * 2 }, arr: [i, i + 1, i + 2] };
        \\  acc += o.a + o.b.c + o.arr[2];
        \\}
        \\const obj = Object.assign({}, { x: 1 }, { y: 2 });
        \\acc + obj.x + obj.y;
    );
    // sum_{i=0..199}(i + 2i + (i+2)) = sum(4i+2) = 80000, plus obj.x+obj.y = 3.
    try std.testing.expectEqual(@as(f64, 80003), result.asNum());
}

test "enable_gc: collector scratch allocator follows the context concurrency policy" {
    const Identity = struct {
        fn expect(actual: std.mem.Allocator, expected: std.mem.Allocator) !void {
            try std.testing.expectEqual(expected.ptr, actual.ptr);
            try std.testing.expectEqual(expected.vtable, actual.vtable);
        }
    };

    {
        const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
        defer ctx.destroy();
        try Identity.expect(ctx.gc.?.aux, std.testing.allocator);
    }
    {
        const ctx = try Context.createWith(std.testing.allocator, .{
            .enable_gc = true,
            .concurrent_gc = true,
        });
        defer ctx.destroy();
        try Identity.expect(ctx.gc.?.aux, std.heap.page_allocator);
    }
    {
        const ctx = try Context.createWith(std.testing.allocator, .{
            .enable_threads = true,
            .enable_gc = true,
            .gil = true,
        });
        defer ctx.destroy();
        try Identity.expect(ctx.gc.?.aux, std.heap.page_allocator);
    }
}

test "GC compaction is fail-closed, rewrites a protected graph, and reaches a dense fixed point" {
    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .wasm_features = .{ .reference_types = true },
    });
    defer ctx.destroy();

    // Put the representative graph in tail chunks behind a reclaimable batch,
    // so the placement-aware policy has useful evacuation work to perform.
    _ = try ctx.evaluate(
        \\globalThis.compactDiscard = [];
        \\for (let i = 0; i < 4096; i++) compactDiscard.push({ i, dead: true });
        \\compactDiscard = null;
    );

    var boxed = try ctx.evaluate(
        \\(() => {
        \\  globalThis.compactClosure = (() => {
        \\    const captured = { value: 40 };
        \\    return () => captured.value + 2;
        \\  })();
        \\  globalThis.compactPromise = Promise.resolve(9);
        \\  globalThis.compactGenerator = (function* () { yield 7; })();
        \\  globalThis.compactDynamicString = "move".repeat(25);
        \\  globalThis.compactWeakKey = { weak: "key" };
        \\  globalThis.compactWeakValue = { weak: "value" };
        \\  globalThis.compactWeakMap = new WeakMap([[compactWeakKey, compactWeakValue]]);
        \\  globalThis.compactWeakSet = new WeakSet([compactWeakKey]);
        \\  globalThis.compactLiveWeakRef = new WeakRef(compactWeakKey);
        \\  globalThis.compactFinalized = [];
        \\  globalThis.compactRegistry = new FinalizationRegistry(
        \\    held => compactFinalized.push(held)
        \\  );
        \\  let deadWeakTarget = { weak: "dead" };
        \\  globalThis.compactDeadWeakRef = new WeakRef(deadWeakTarget);
        \\  compactRegistry.register(deadWeakTarget, "held");
        \\  deadWeakTarget = null;
        \\  globalThis.compactWasmTable = new WebAssembly.Table({ element: "externref", initial: 1 });
        \\  compactWasmTable.set(0, compactWeakKey);
        \\  globalThis.compactWasmGlobal = new WebAssembly.Global(
        \\    { value: "externref", mutable: true }, compactWeakValue
        \\  );
        \\  const root = { name: "root" };
        \\  const peer = { name: "peer" };
        \\  root.peer = peer;
        \\  root.alias = peer;
        \\  peer.root = root;
        \\  return root;
        \\})()
    );
    try ctx.reserveCApiHandlesLocked(1);
    ctx.c_api_handles.appendAssumeCapacity(.{ .ref = &boxed, .count = 1 });
    defer ctx.c_api_handles.clearRetainingCapacity();
    const c_handle_address = @intFromPtr(&ctx.c_api_handles.items[0]);

    var private_strong = Context.PrivateStrongRoot{ .value = boxed };
    try ctx.private_strong_roots.append(ctx.gpa, &private_strong);
    defer ctx.private_strong_roots.clearRetainingCapacity();
    const private_strong_address = @intFromPtr(&private_strong);
    var private_live_weak = Context.PrivateWeakRoot{};
    private_live_weak.target.store(boxed.asObj().getOwn("peer").?.asObj(), .release);
    var orphan = try ctx.evaluate("({ orphan: true })");
    var private_dead_weak = Context.PrivateWeakRoot{};
    private_dead_weak.target.store(orphan.asObj(), .release);
    orphan = Value.undef();
    try ctx.private_weak_roots.append(ctx.gpa, &private_live_weak);
    try ctx.private_weak_roots.append(ctx.gpa, &private_dead_weak);
    defer ctx.private_weak_roots.clearRetainingCapacity();
    const private_live_weak_address = @intFromPtr(&private_live_weak);

    // Each live or conservatively described execution boundary refuses movement without even
    // entering the collector's compaction phase.
    ctx.gc_scan_native_stack = true;
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.unsupported, ctx.compactGarbage().status);
    ctx.gc_scan_native_stack = false;
    var active = ctx.interpreter();
    try ctx.pushActiveInterpreter(&active);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.unsupported, ctx.compactGarbage().status);
    ctx.popActiveInterpreter(&active);

    // Stabilize liveness first so before/after accounting measures relocation,
    // not unrelated garbage reclaimed from evaluation setup.
    ctx.collectGarbage();
    try std.testing.expectEqual(@as(?*anyopaque, null), private_dead_weak.target.load(.acquire));
    const before = ctx.gc.?.accounting();
    const backing_before = ctx.gc_cell_backing.?.stats();
    try std.testing.expect(backing_before.chunks > 1);
    const verifications_before = gc_mod.relocationVerificationsForTesting();
    const old_root_address = @intFromPtr(boxed.asObj());
    const old_peer_address = @intFromPtr(boxed.asObj().getOwn("peer").?.asObj());

    const first = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, first.status);
    try std.testing.expect(first.moved_cells > 0 and first.moved_cells < before.live_cells);
    try std.testing.expect(first.moved_bytes > 0 and first.moved_bytes < before.live_bytes);
    try std.testing.expect(old_root_address != @intFromPtr(boxed.asObj()));
    const first_root = boxed.asObj();
    const first_peer = first_root.getOwn("peer").?.asObj();
    try std.testing.expect(old_peer_address != @intFromPtr(first_peer));
    try std.testing.expectEqual(first_peer, first_root.getOwn("alias").?.asObj());
    try std.testing.expectEqual(first_root, first_peer.getOwn("root").?.asObj());
    try std.testing.expectEqual(c_handle_address, @intFromPtr(&ctx.c_api_handles.items[0]));
    try std.testing.expectEqual(private_strong_address, @intFromPtr(ctx.private_strong_roots.items[0]));
    try std.testing.expectEqual(first_root, private_strong.value.asObj());
    try std.testing.expectEqual(private_live_weak_address, @intFromPtr(ctx.private_weak_roots.items[0]));
    try std.testing.expectEqual(@as(?*anyopaque, first_peer), private_live_weak.target.load(.acquire));
    const after_first = ctx.gc.?.accounting();
    const backing_after_first = ctx.gc_cell_backing.?.stats();
    try std.testing.expectEqual(before.live_cells, after_first.live_cells);
    try std.testing.expectEqual(before.live_bytes, after_first.live_bytes);
    try std.testing.expect(backing_after_first.chunks < backing_before.chunks);
    try std.testing.expect(backing_after_first.capacity_bytes < backing_before.capacity_bytes);
    try std.testing.expectEqual(backing_before.live_slots, backing_after_first.live_slots);
    const moved_weak_map = ctx.global_object.getOwn("compactWeakMap").?.asObj().collectionState().?;
    const moved_weak_set = ctx.global_object.getOwn("compactWeakSet").?.asObj().collectionState().?;
    try std.testing.expectEqual(@as(usize, 1), moved_weak_map.weak_entries.items.len);
    try std.testing.expectEqual(@as(usize, 1), moved_weak_map.weak_index.count());
    try std.testing.expectEqual(@as(usize, 1), moved_weak_set.weak_index.count());

    const first_root_address = @intFromPtr(first_root);
    const second = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.no_candidates, second.status);
    try std.testing.expectEqual(@as(usize, 0), second.moved_cells);
    try std.testing.expectEqual(first_root_address, @intFromPtr(boxed.asObj()));
    const second_root = boxed.asObj();
    const second_peer = second_root.getOwn("peer").?.asObj();
    try std.testing.expectEqual(second_peer, second_root.getOwn("alias").?.asObj());
    try std.testing.expectEqual(second_root, second_peer.getOwn("root").?.asObj());
    try std.testing.expectEqual(second_root, private_strong.value.asObj());
    try std.testing.expectEqual(@as(?*anyopaque, second_peer), private_live_weak.target.load(.acquire));
    const after_second = ctx.gc.?.accounting();
    const backing_after_second = ctx.gc_cell_backing.?.stats();
    try std.testing.expectEqual(before.live_cells, after_second.live_cells);
    try std.testing.expectEqual(before.live_bytes, after_second.live_bytes);
    try std.testing.expectEqual(backing_after_first, backing_after_second);
    try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
    try std.testing.expect(gc_mod.relocationVerificationsForTesting() > verifications_before);

    // These values were all created before the move. Running them only now
    // proves the Function/Environment/Promise/Generator/String representatives,
    // not just the directly inspected Object cycle, survived compaction and the
    // subsequent dense no-op pass.
    _ = try ctx.evaluate(
        "compactPromise.then(value => { globalThis.compactPromiseValue = value; })",
    );
    const representatives = try ctx.evaluate(
        "compactClosure() + compactGenerator.next().value + compactDynamicString.length + compactPromiseValue",
    );
    try std.testing.expectEqual(@as(f64, 158), representatives.asNum());
    _ = try ctx.evaluate("0"); // drain the ready FinalizationRegistry cleanup job
    const boundaries = try ctx.evaluate(
        \\+(compactLiveWeakRef.deref() === compactWeakKey) * 1 +
        \\+(compactDeadWeakRef.deref() === undefined) * 2 +
        \\+(compactWeakMap.get(compactWeakKey) === compactWeakValue) * 4 +
        \\+(compactWeakSet.has(compactWeakKey)) * 8 +
        \\+(compactFinalized.length === 1 && compactFinalized[0] === "held") * 16 +
        \\+(compactWasmTable.get(0) === compactWeakKey) * 32 +
        \\+(compactWasmGlobal.value === compactWeakValue) * 64
    );
    try std.testing.expectEqual(@as(f64, 127), boundaries.asNum());

    // Planning scratch must succeed before any destination/root/edge mutation.
    // Replacing only the collector scratch allocator deterministically fails
    // the first plan-capacity reservation while leaving cell backing available.
    ctx.collectGarbage();
    const before_failure = ctx.gc.?.accounting();
    const backing_before_failure = ctx.gc_cell_backing.?.stats();
    const verifications_before_failure = gc_mod.relocationVerificationsForTesting();
    const root_before_failure = boxed.asObj();
    var no_scratch: [1]u8 = undefined;
    var fixed = std.heap.FixedBufferAllocator.init(&no_scratch);
    const saved_aux = ctx.gc.?.aux;
    ctx.gc.?.aux = fixed.allocator();
    const failed = ctx.compactGarbage();
    ctx.gc.?.aux = saved_aux;
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.out_of_memory, failed.status);
    try std.testing.expectEqual(root_before_failure, boxed.asObj());
    const after_failure = ctx.gc.?.accounting();
    try std.testing.expectEqual(before_failure.live_cells, after_failure.live_cells);
    try std.testing.expectEqual(before_failure.live_bytes, after_failure.live_bytes);
    try std.testing.expectEqual(backing_before_failure, ctx.gc_cell_backing.?.stats());
    try std.testing.expectEqual(verifications_before_failure, gc_mod.relocationVerificationsForTesting());
    try std.testing.expectEqual(
        boxed.asObj().getOwn("peer").?.asObj(),
        boxed.asObj().getOwn("alias").?.asObj(),
    );
}

test "GC compaction preserves quiescent pointer-free baseline JIT tiers" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = true,
    });
    defer ctx.destroy();
    // This test constructs tail fragmentation for an explicit full compaction;
    // keep automatic nursery policy from relocating its witness first.
    ctx.gc.?.nursery_threshold_bytes = std.math.maxInt(usize);

    // Keep dead Object and Function cells live until the next evaluation has
    // started. The target function and witness are then allocated behind them,
    // leaving both size classes with useful tail-evacuation work after sweep.
    _ = try ctx.evaluate(
        \\globalThis.compactJitDiscardFunctions = [];
        \\globalThis.compactJitDiscardObjects = [];
        \\for (var i = 0; i < 2048; i = i + 1) {
        \\  compactJitDiscardFunctions.push(function deadJitCell() { return i; });
        \\  compactJitDiscardObjects.push({ dead: i });
        \\}
    );
    const first_result = try ctx.evaluate(
        \\compactJitDiscardFunctions = null;
        \\compactJitDiscardObjects = null;
        \\function compactJitSum(n) {
        \\  var total = 0;
        \\  var i = 0;
        \\  while (i < n) { total = total + i; i = i + 1; }
        \\  return total;
        \\}
        \\globalThis.compactJitWitness = { marker: 358 };
        \\compactJitSum(100);
    );
    try std.testing.expectEqual(@as(f64, 4950), first_result.asNum());

    const function_value_before = ctx.global_object.getOwn("compactJitSum").?;
    const function_object_before = function_value_before.asObj();
    const function_before: *interp.Function = @ptrCast(@alignCast(function_object_before.jsFunction().?));
    const chunk_before = function_before.chunk.?;
    try std.testing.expectEqual(jit.TierState.ready, chunk_before.tier.loadState());
    const native_before = chunk_before.tier.loadCode().?;
    try std.testing.expect(native_before.manages_steps);

    const handle = try ctx.protectValue(ctx.global_object.getOwn("compactJitWitness").?);
    defer std.debug.assert(ctx.unprotectValue(handle));
    const handle_address = @intFromPtr(handle);

    ctx.collectGarbage();
    const backing_before = ctx.gc_cell_backing.?.stats();
    try std.testing.expect(backing_before.chunks > 1);
    const compacted = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, compacted.status);
    try std.testing.expect(compacted.moved_cells > 0 and compacted.moved_bytes > 0);

    try std.testing.expectEqual(handle_address, @intFromPtr(handle));
    try std.testing.expectEqual(@as(f64, 358), handle.get().asObj().getOwn("marker").?.asNum());

    const function_value_after = ctx.global_object.getOwn("compactJitSum").?;
    const function_object_after = function_value_after.asObj();
    const function_after: *interp.Function = @ptrCast(@alignCast(function_object_after.jsFunction().?));
    // Placement-aware compaction may move another eligible tail cell instead
    // of this function. `moved_cells` proves relocation occurred; preserving
    // the exact tier/code identity and executing it proves JIT state survives.
    try std.testing.expectEqual(chunk_before, function_after.chunk.?);
    try std.testing.expectEqual(jit.TierState.ready, function_after.chunk.?.tier.loadState());
    try std.testing.expectEqual(native_before, function_after.chunk.?.tier.loadCode().?);

    const native_hits_before = vm.nativeDirectCallHitsForTesting();
    const second_result = try ctx.evaluate("compactJitSum(100)");
    try std.testing.expectEqual(@as(f64, 4950), second_result.asNum());
    try std.testing.expect(vm.nativeDirectCallHitsForTesting() > native_hits_before);
}

test "GC requested compaction resumes the same baseline tier from a precise native safepoint" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = true,
    });
    defer ctx.destroy();
    // Preserve the deliberate pre-compaction placement independently of the
    // production nursery threshold.
    ctx.gc.?.nursery_threshold_bytes = std.math.maxInt(usize);

    _ = try ctx.evaluate(
        \\globalThis.preciseDiscardFunctions = [];
        \\globalThis.preciseDiscardObjects = [];
        \\for (var i = 0; i < 2048; i = i + 1) {
        \\  preciseDiscardFunctions.push(function deadPreciseCell() { return i; });
        \\  preciseDiscardObjects.push({ dead: i });
        \\}
    );
    const warm_result = try ctx.evaluate(
        \\preciseDiscardFunctions = null;
        \\preciseDiscardObjects = null;
        \\function preciseCompactSum(n) {
        \\  var total = 0;
        \\  var i = 0;
        \\  while (i < n) { total = total + i; i = i + 1; }
        \\  return total;
        \\}
        \\globalThis.preciseCompactWitness = { marker: 359 };
        \\preciseCompactSum(4096);
    );
    try std.testing.expectEqual(@as(f64, 8_386_560), warm_result.asNum());

    const function_object_before = ctx.global_object.getOwn("preciseCompactSum").?.asObj();
    const function_before: *interp.Function = @ptrCast(@alignCast(function_object_before.jsFunction().?));
    const chunk_before = function_before.chunk.?;
    try std.testing.expectEqual(jit.TierState.ready, chunk_before.tier.loadState());
    const native_before = chunk_before.tier.loadCode().?;
    try std.testing.expect(native_before.manages_steps);

    const handle = try ctx.protectValue(ctx.global_object.getOwn("preciseCompactWitness").?);
    defer std.debug.assert(ctx.unprotectValue(handle));
    ctx.collectGarbage();
    const backing_before = ctx.gc_cell_backing.?.stats();
    try std.testing.expect(backing_before.chunks > 1);

    try std.testing.expect(ctx.requestGarbageCompaction());
    try std.testing.expect(ctx.gc_compaction_requested.load(.acquire));
    // A checkpoint that is precise enough for marking still cannot consume the
    // request when its Zig helper may resume with raw pointers. Only the native
    // checkpoint's stronger moving declaration below can.
    var marking_precise = ctx.interpreter();
    marking_precise.gc_precise_safepoint = true;
    try ctx.pushActiveInterpreter(&marking_precise);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.unsupported, ctx.compactGarbage().status);
    try std.testing.expect(ctx.gc_compaction_requested.load(.acquire));
    Context.collectMidScript(ctx, &marking_precise);
    ctx.popActiveInterpreter(&marking_precise);
    try std.testing.expect(ctx.gc_compaction_requested.load(.acquire));

    const precise_compactions_before = ctx.gc_moving_safepoint_compactions.load(.monotonic);
    const native_hits_before = vm.nativeDirectCallHitsForTesting();
    const result = try ctx.evaluate("preciseCompactSum(20000)");
    try std.testing.expectEqual(@as(f64, 199_990_000), result.asNum());
    try std.testing.expect(!ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expectEqual(precise_compactions_before + 1, ctx.gc_moving_safepoint_compactions.load(.monotonic));
    try std.testing.expect(vm.nativeDirectCallHitsForTesting() > native_hits_before);
    try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));

    try std.testing.expectEqual(@as(f64, 359), handle.get().asObj().getOwn("marker").?.asNum());
    const function_object_after = ctx.global_object.getOwn("preciseCompactSum").?.asObj();
    const function_after: *interp.Function = @ptrCast(@alignCast(function_object_after.jsFunction().?));
    try std.testing.expectEqual(chunk_before, function_after.chunk.?);
    try std.testing.expectEqual(native_before, function_after.chunk.?.tier.loadCode().?);
    try std.testing.expect(ctx.gc_cell_backing.?.stats().chunks < backing_before.chunks);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.no_candidates, ctx.compactGarbage().status);
}

test "variadic String concat roots pending arguments across moving nursery" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = true,
    });
    defer ctx.destroy();
    _ = try ctx.evaluate(
        \\function concatMovingLoop(n) {
        \\  var total = 0;
        \\  var i = 0;
        \\  while (i < n) { total = total + i; i = i + 1; }
        \\  return total;
        \\}
        \\for (var warm = 0; warm < 10; warm = warm + 1) concatMovingLoop(4096);
    );

    const loop_object = ctx.global_object.getOwn("concatMovingLoop").?.asObj();
    const loop: *interp.Function = @ptrCast(@alignCast(loop_object.jsFunction().?));
    const chunk = loop.chunk.?;
    try std.testing.expectEqual(jit.TierState.ready, chunk.tier.loadState());
    try std.testing.expect(chunk.tier.loadCode().?.manages_steps);

    // Start a fresh nursery generation so every value that concat must retain
    // is eligible for the exact moving checkpoint in the trigger below.
    ctx.collectGarbage();
    const heap = ctx.gc.?;
    heap.nursery_threshold_bytes = std.math.maxInt(usize);
    _ = try ctx.evaluate(
        \\globalThis.concatMovingNative = String.prototype.concat;
        \\globalThis.concatMovingReceiverText = "recv".repeat(2);
        \\globalThis.concatMovingFirstText = "first".repeat(2);
        \\globalThis.concatMovingMiddleText = "middle".repeat(2);
        \\globalThis.concatMovingLastText = "last".repeat(2);
        \\globalThis.concatMovingReceiver = {
        \\  toString() { return concatMovingReceiverText; }
        \\};
        \\globalThis.concatMovingFirst = {
        \\  toString() { return concatMovingFirstText; }
        \\};
        \\globalThis.concatMovingTrigger = {
        \\  toString() { concatMovingLoop(20000); return concatMovingMiddleText; }
        \\};
        \\globalThis.concatMovingLast = {
        \\  toString() { return concatMovingLastText; }
        \\};
    );

    const receiver_before = ctx.global_object.getOwn("concatMovingReceiverText").?.asStringCell();
    const first_text_before = ctx.global_object.getOwn("concatMovingFirstText").?.asStringCell();
    const last_argument_before = ctx.global_object.getOwn("concatMovingLast").?.asObj();

    const gc_saved = gc_mod.setActiveContext(ctx);
    defer gc_mod.restoreActiveContext(gc_saved);
    const sa_saved = strcell.setActiveArena(ctx.arena());
    defer _ = strcell.setActiveArena(sa_saved);
    const ss_saved = stack_scan.enter(@frameAddress());
    defer stack_scan.leave(ss_saved);
    var machine = ctx.interpreter();
    try ctx.pushActiveInterpreter(&machine);
    defer ctx.popActiveInterpreter(&machine);
    const ai_saved = gc_mod.setActiveInterpreter(&machine);
    defer _ = gc_mod.setActiveInterpreter(ai_saved);

    const concat = ctx.global_object.getOwn("concatMovingNative").?;
    const receiver = ctx.global_object.getOwn("concatMovingReceiver").?;
    const args = [_]Value{
        ctx.global_object.getOwn("concatMovingFirst").?,
        ctx.global_object.getOwn("concatMovingTrigger").?,
        ctx.global_object.getOwn("concatMovingLast").?,
    };
    heap.nursery_threshold_bytes = 1;
    ctx.movingCheckpointRequest().store(true, .release);
    const moving_before = heap.accounting().moving_minor_collections;
    const result = try machine.callValueWithThis(concat, &args, receiver);

    try std.testing.expectEqualStrings(
        "recvrecvfirstfirstmiddlemiddlelastlast",
        try result.asWtf8(ctx.gpa),
    );
    try std.testing.expectEqual(
        moving_before + 1,
        heap.accounting().moving_minor_collections,
    );
    try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));

    // Global roots provide stable after-pointers for the same cells; concat's
    // temporary roots must rewrite its receiver, completed piece, and pending
    // argument while the nested JIT frame evacuates their nursery generation.
    const receiver_after = ctx.global_object.getOwn("concatMovingReceiverText").?.asStringCell();
    const first_text_after = ctx.global_object.getOwn("concatMovingFirstText").?.asStringCell();
    const last_argument_after = ctx.global_object.getOwn("concatMovingLast").?.asObj();
    try std.testing.expect(receiver_before != receiver_after);
    try std.testing.expect(first_text_before != first_text_after);
    try std.testing.expect(last_argument_before != last_argument_after);
}

test "deferred class captures retain live defining bindings in both tiers" {
    const cases = [_]struct { name: []const u8, source: []const u8, expected: []const u8 }{
        .{ .name = "late_eval_no_slot", .source = "(function(){class Box{read(){return later;}}eval('var later=7');return new Box().read();})()", .expected = "7" },
        .{ .name = "late_outer_eval", .source = "(function(){var Box=(function(){return class{read(){return later;}};})();eval('var later=7');return new Box().read();})()", .expected = "7" },
        .{ .name = "late_parameter_eval", .source = "(function(maker=()=>{return class{read(){return later;}};},Box=maker(),x=eval('var later=7')){return new Box().read();})()", .expected = "7" },
        .{ .name = "eval_self_collision", .source = "(function(){var Box=class Self{read(){return Self;}};eval('var Self=7');return new Box().read()===Box;})()", .expected = "true" },
        .{ .name = "mutable", .source = "(function(seed){class Box{read(){return seed;}write(n){seed=n;}}var b=new Box();seed=7;b.write(9);return b.read()*10+seed;})(1)", .expected = "99" },
        .{ .name = "escaped", .source = "(function(){function make(seed){class Box{read(){return seed;}write(n){seed=n;}}return [Box,()=>seed];}var pair=make(3),box=new pair[0]();box.write(8);return box.read()*10+pair[1]();})()", .expected = "88" },
        .{ .name = "instance_field", .source = "(function(seed){class Box{field=seed;read(){return seed;}}seed=7;var a=new Box();seed=8;return a.field*10+new Box().field;})(1)", .expected = "78" },
        .{ .name = "static_order", .source = "(function(seed){var log='';class Box{[(log+='k','m')](){return seed;}static field=(log+='f',++seed);static{log+='b';seed+=2;}}return log+':'+Box.field+':'+new Box().m();})(3)", .expected = "kfb:4:6" },
        .{ .name = "nested_frame", .source = "(function(outer){return (function(inner){class Box{read(){return outer+inner;}write(){outer++;inner+=2;}}var b=new Box();b.write();return b.read();})(4);})(3)", .expected = "10" },
        .{ .name = "nested_escape", .source = "(function(){function make(outer){return function(inner){return class{read(){return outer+inner;}write(){outer++;inner++;}};};}var Box=make(3)(4),a=new Box();a.write();return a.read();})()", .expected = "9" },
        .{ .name = "lexical_shadow", .source = "(function(seed){let Box;{let seed=7;Box=class{read(){return seed;}write(){seed++;}};}var b=new Box();b.write();return b.read()*10+seed;})(3)", .expected = "83" },
        .{ .name = "with_shadow", .source = "(function(seed){var Box;with({seed:8}){Box=class{read(){return seed;}write(){seed++;}};}var b=new Box();b.write();return b.read()*10+seed;})(3)", .expected = "93" },
        .{ .name = "inside_with_lexical", .source = "(function(seed){var Box;with({seed:8}){let seed=7;Box=class{read(){return seed;}write(){seed++;}};}var b=new Box();b.write();return b.read()*10+seed;})(3)", .expected = "83" },
        .{ .name = "class_self", .source = "(function(Self){var Box=class Self{read(){return Self;}static read(){return Self;}};return new Box().read()===Box&&Box.read()===Box;})(1)", .expected = "true" },
        .{ .name = "class_self_const", .source = "(function(seed){class Box{read(){try{Box=seed;}catch(e){return e instanceof TypeError;}}}return new Box().read();})(3)", .expected = "true" },
        .{ .name = "tdz", .source = "(function(){try{class Box{static field=seed;}let seed=7;}catch(e){return e instanceof ReferenceError;}return false;})()", .expected = "true" },
        .{ .name = "const_write", .source = "(function(){const seed=7;class Box{write(){seed=9;}}try{new Box().write();}catch(e){return e instanceof TypeError;}return false;})()", .expected = "true" },
        .{ .name = "mapped_arguments", .source = "(function(seed){var args=arguments;class Box{read(){return seed;}write(){seed++;}}args[0]=6;var b=new Box();b.write();return args[0]*10+b.read();})(3)", .expected = "77" },
        .{ .name = "method_eval", .source = "(function(seed){class Box{read(){return eval('seed');}write(){eval('seed += 2');}}var b=new Box();b.write();return b.read()+seed;})(3)", .expected = "10" },
        .{ .name = "static_eval", .source = "(function(seed){class Box{static{eval('seed += 2');}read(){return seed;}}return new Box().read();})(3)", .expected = "5" },
        .{ .name = "body_eval", .source = "(function(seed){class Box{read(){return seed;}}eval('seed=7');return new Box().read();})(3)", .expected = "7" },
        .{ .name = "late_eval_binding", .source = "(function(seed){class Box{read(){return late+seed;}}eval('var late=4');return new Box().read();})(3)", .expected = "7" },
        .{ .name = "parameter_body", .source = "(function(seed=3,maker=()=>{class Box{read(){return seed;}}return Box;}){var seed=7;var Box=maker();return new Box().read()*10+seed;})()", .expected = "37" },
        .{ .name = "constructor_default", .source = "(function(seed){class Box{constructor(n=seed){this.n=n;}read(){return this.n+seed;}}seed=7;return new Box().read();})(3)", .expected = "14" },
        .{ .name = "private", .source = "(function(seed){class Box{#x=seed;read(){return this.#x+seed;}write(){seed++;}}var b=new Box();b.write();return b.read();})(3)", .expected = "7" },
        .{ .name = "super", .source = "(function(seed){class Base{read(){return seed;}}class Box extends Base{read(){return super.read()+seed;}}seed=7;return new Box().read();})(3)", .expected = "14" },
        .{ .name = "eager_keys", .source = "(function(seed){var log='';class Box extends (log+='h',Object){[(log+='k',seed)](){return seed;}static x=(log+='s',seed);}seed=7;return log+':'+new Box()[3]()+':'+Box.x;})(3)", .expected = "hks:7:3" },
        .{ .name = "catch_shadow", .source = "(function(seed){var Box;try{throw 8;}catch(seed){Box=class{read(){return seed;}};}return new Box().read()*10+seed;})(3)", .expected = "83" },
        .{ .name = "repeated_classes", .source = "(function(seed){var out=[];for(let i=0;i<3;i++){class Box{read(){return seed+i;}}out.push(new Box());}seed=7;return out[0].read()+out[1].read()+out[2].read();})(3)", .expected = "24" },
        .{ .name = "method_parameter", .source = "(function(seed){class Box{read(seed){return seed;}other(){return seed;}}var b=new Box();return b.read(7)*10+b.other();})(3)", .expected = "73" },
        .{ .name = "nested_class", .source = "(function(seed){class Outer{make(){return class{read(){return seed;}};}}seed=7;var Box=new Outer().make();return new Box().read();})(3)", .expected = "7" },
        .{ .name = "abrupt_static", .source = "(function(seed){var caught;try{class Box{static{seed++;throw 9;}}}catch(e){caught=e;}return caught*10+seed;})(3)", .expected = "94" },
    };
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_gc = true,
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        for (cases) |case| {
            errdefer std.debug.print("deferred class {s} ({s})\n", .{ case.name, @tagName(mode) });
            const source = try std.fmt.allocPrint(std.testing.allocator, "String({s})", .{case.source});
            defer std.testing.allocator.free(source);
            try std.testing.expectEqualStrings(case.expected, (try ctx.evaluate(source)).asStr());
        }
        if (mode == .required)
            try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
    }
}

