test "deferred class captures isolate concurrent no-GIL defining frames" {
    if (builtin.single_threaded) return error.SkipZigTest;
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_threads = true,
            .enable_gc = true,
            .enable_jit = false,
            .parallel_gc = true,
            .parallel_js = true,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        const result = try ctx.evaluate(
            \\function makeClass(seed) {
            \\  let value = seed;
            \\  return class Box {
            \\    read() { return value; }
            \\    write(next) { value = next; }
            \\  };
            \\}
            \\function classLane(Box) {
            \\  if ($vm.useThreadGIL() !== false) throw new Error('GIL held');
            \\  var box = new Box();
            \\  var Local = makeClass(box.read()), local = new Local();
            \\  for (var i=0;i<32;i++) {
            \\    box.write(box.read()+1);
            \\    local.write(local.read()+1);
            \\  }
            \\  return box.read()+local.read();
            \\}
            \\var classes=[],lanes=[],sum=0;
            \\for(var i=0;i<4;i++) classes.push(makeClass(i));
            \\for(var i=0;i<4;i++) lanes.push(new Thread(classLane,classes[i]));
            \\for(var i=0;i<4;i++) sum+=lanes[i].join()+new classes[i]().read();
            \\sum
        );
        try std.testing.expectEqual(@as(f64, 402), result.asNum());
        if (mode == .required)
            try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
    }
}

test "deferred class captures retain exact identities through moving nursery" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;
    const Host = struct {
        fn arm(raw: *anyopaque, _: Value, _: []const Value) value.HostError!Value {
            const machine: *interp.Interpreter = @ptrCast(@alignCast(raw));
            const ctx: *Context = @ptrCast(@alignCast(machine.gc_realm_context.?));
            ctx.gc.?.nursery_threshold_bytes = 1;
            ctx.gc_moving_checkpoint_requested.store(true, .release);
            return Value.undef();
        }
    };
    const cases = [_]struct { name: []const u8, setup: []const u8, run: []const u8 }{
        .{ .name = "ordinary_body", .setup = "function Box(){classMovingLoop(20000);this.field=classSubject;}", .run = "new Box().field===classSubject" },
        .{ .name = "explicit_object", .setup = "class Box{constructor(){classMovingLoop(20000);return classSubject;}}", .run = "new Box()===classSubject" },
        .{ .name = "escaped_method", .setup = "function make(seed){return class{read(){classMovingLoop(20000);return seed;}};}globalThis.Box=make(classSubject);", .run = "new Box().read()===classSubject" },
        .{ .name = "active_factory", .setup = "function make(seed){class Box{read(){return seed;}}classMovingLoop(20000);return Box;}", .run = "new (make(classSubject))().read()===classSubject" },
        .{ .name = "static_block", .setup = "function make(seed){return class Box{static{globalThis.createdClass=this;classMovingLoop(20000);}read(){return seed;}};}", .run = "make(classSubject)===createdClass&&new createdClass().read()===classSubject" },
        .{ .name = "static_field", .setup = "function make(seed){return class Box{static field=(globalThis.createdClass=this,classMovingLoop(20000),seed);static next=this.field;read(){return seed;}};}", .run = "make(classSubject)===createdClass&&createdClass.field===classSubject&&createdClass.next===classSubject" },
        .{ .name = "heritage", .setup = "function Base(){}globalThis.baseProxy=new Proxy(Base,{get(t,k,r){if(k==='prototype')classMovingLoop(20000);return Reflect.get(t,k,r);}});function make(seed){return class Box extends baseProxy{read(){return seed;}};}", .run = "new (make(classSubject))().read()===classSubject" },
        .{ .name = "instance_field", .setup = "function make(seed){return class{field=(classMovingLoop(20000),seed);};}globalThis.Box=make(classSubject);", .run = "new Box().field===classSubject" },
        .{ .name = "computed_key", .setup = "function make(seed){return class{[(classMovingLoop(20000),'read')](){return seed;}};}", .run = "new (make(classSubject))().read()===classSubject" },
        .{ .name = "nested_frame", .setup = "function outer(seed){return function inner(extra){return class{read(){classMovingLoop(20000);return seed===extra?seed:null;}};};}globalThis.Box=outer(classSubject)(classSubject);", .run = "new Box().read()===classSubject" },
    };
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        for (cases) |case| {
            const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = true });
            defer ctx.destroy();
            {
                const saved = gc_mod.setActiveContext(ctx);
                defer gc_mod.restoreActiveContext(saved);
                const arm = try gc_mod.allocObj(ctx.arena());
                arm.* = .{ .native = Host.arm };
                try ctx.global_object.setOwn(ctx.arena(), ctx.root_shape, "classArm", Value.obj(arm));
                try ctx.env.put("classArm", Value.obj(arm));
            }
            _ = try ctx.evaluate(
                \\function classMovingLoop(n){var total=0,i=0;while(i<n){total=total+i;i=i+1;}return total;}
                \\for(var warm=0;warm<10;warm=warm+1)classMovingLoop(4096);
            );
            const loop: *interp.Function = @ptrCast(@alignCast(ctx.global_object.getOwn("classMovingLoop").?.asObj().jsFunction().?));
            try std.testing.expectEqual(jit.TierState.ready, loop.chunk.?.tier.loadState());
            try std.testing.expect(loop.chunk.?.tier.loadCode().?.manages_steps);
            ctx.collectGarbage();
            ctx.gc.?.nursery_threshold_bytes = std.math.maxInt(usize);
            ctx.setBytecodeExecutionModeForTesting(mode);
            _ = try ctx.evaluate("globalThis.classSubject={marker:37};");
            _ = try ctx.evaluate(case.setup);
            const before = ctx.global_object.getOwn("classSubject").?.asObj();
            const moving_before = ctx.gc.?.accounting().moving_minor_collections;
            const source = try std.fmt.allocPrint(std.testing.allocator, "classArm();{s}", .{case.run});
            defer std.testing.allocator.free(source);
            errdefer std.debug.print("moving class capture {s} ({s})\n", .{ case.name, @tagName(mode) });
            try std.testing.expect((try ctx.evaluate(source)).toBoolean());
            try std.testing.expectEqual(moving_before + 1, ctx.gc.?.accounting().moving_minor_collections);
            try std.testing.expect(before != ctx.global_object.getOwn("classSubject").?.asObj());
            try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
            if (mode == .required)
                try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
        }
    }
}

test "reentrant property references preserve coercion and target order" {
    const cases = [_]struct { name: []const u8, source: []const u8, expected: []const u8 }{
        .{ .name = "plain_order", .source = "var log='', box={set x(v){log+='set'+v;}}, key={toString(){log+='key';return 'x';}};function rhs(){log+='rhs';return 4;}var n=(box[key]=rhs());var result=n+':'+log;", .expected = "4:rhskeyset4" },
        .{ .name = "compound_order", .source = "var log='',box={get x(){log+='get';return {valueOf(){log+='left';return 3;}};},set x(v){log+='set'+v;}},key={toString(){log+='key';return 'x';}};function rhs(){log+='rhs';return {valueOf(){log+='right';return 4;}};}var result=(box[key]+=rhs())+':'+log;", .expected = "7:keygetrhsleftrightset7" },
        .{ .name = "logical_short", .source = "var log='',box={get x(){log+='get';return 3;},set x(v){log+='set';}},key={toString(){log+='key';return 'x';}};function rhs(){log+='rhs';return 4;}var result=(box[key]||=rhs())+':'+log;", .expected = "3:keyget" },
        .{ .name = "array_rest_order", .source = "var log='',box={},key={toString(){log+='key';return 'x';}},it={[Symbol.iterator](){return this;},next(){log+='next';return {done:true};}};[...box[key]]=it;var result=box.x.length+':'+log;", .expected = "0:nextkey" },
        .{ .name = "object_target_order", .source = "var log='',box={},key={toString(){log+='key';return 'x';}},source={get v(){log+='get';return 4;}};function target(){log+='base';return box;}({v:target()[key]}=source);var result=box.x+':'+log;", .expected = "4:basegetkey" },
        .{ .name = "object_rest_order", .source = "var log='',box={},key={toString(){log+='key';return 'x';}},source={get v(){log+='get';return 4;}};function target(){log+='base';return box;}({...target()[key]}=source);var result=box.x.v+':'+log;", .expected = "4:basegetkey" },
        .{ .name = "super_base_order", .source = "var log='',key={toString(){log+='key';return 'x';}};class A{set x(v){log+='A';this.saved=v;}}class B{set x(v){log+='B';this.saved=v;}}class C extends A{run(){return super[(log+='expr',Object.setPrototypeOf(C.prototype,B.prototype),key)]=(log+='rhs',Object.setPrototypeOf(C.prototype,A.prototype),4);}}var c=new C();var n=c.run();var result=n+':'+c.saved+':'+log;", .expected = "4:4:exprrhskeyB" },
        .{ .name = "super_pattern_base", .source = "var log='';class A{set x(v){log+='A';this.saved=v;}}class B{set x(v){log+='B';this.saved=v;}}class C extends A{run(){({v:super.x}={get v(){Object.setPrototypeOf(C.prototype,B.prototype);return 4;}});}}var c=new C();c.run();var result=c.saved+':'+log;", .expected = "4:A" },
        .{ .name = "abrupt_key", .source = "var log='',box={set x(v){log+='set';}},key={toString(){log+='key';throw 7;}};function rhs(){log+='rhs';return 4;}var result;try{box[key]=rhs();result='miss';}catch(e){result=e+':'+log;}", .expected = "7:rhskey" },
        .{ .name = "symbol_key", .source = "var key=Symbol('x'),box={[key]:3};var result=(box[key]+=4)+':'+box[key];", .expected = "7:7" },
    };
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_gc = true,
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        for (cases) |case| {
            // A block scope isolates class declarations while retaining
            // both program execution tiers. Function-scoped class admission is
            // independently tracked by #465, not a property-Reference oracle.
            const source = try std.fmt.allocPrint(std.testing.allocator, "{{{s}result;}}", .{case.source});
            defer std.testing.allocator.free(source);
            errdefer std.debug.print("property reference {s} ({s})\n", .{ case.name, @tagName(mode) });
            try std.testing.expectEqualStrings(case.expected, (try ctx.evaluate(source)).asStr());
        }
        if (mode == .required)
            try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
    }
}

test "reentrant coercion roots isolate shared no-GIL calls" {
    if (builtin.single_threaded) return error.SkipZigTest;
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_threads = true,
            .enable_gc = true,
            .enable_jit = false,
            .parallel_gc = true,
            .parallel_js = true,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        const result = try ctx.evaluate(
            \\function rootShared(n) {
            \\  var box = {x: {get valueOf() {return function() {return n;};}}};
            \\  box.x += 2;
            \\  var receiver = {set item(v) {this.saved = v;}};
            \\  receiver.item ??= box.x;
            \\  var out = {}, key = {toString() {return 'x';}};
            \\  [out[key]] = [receiver.saved];
            \\  return out.x;
            \\}
            \\function rootLane() {
            \\  if ($vm.useThreadGIL() !== false) throw new Error('GIL held');
            \\  var sum = 0;
            \\  for (var i = 0; i < 32; i++) sum += rootShared(i);
            \\  return sum;
            \\}
            \\var lanes = [], sum = 0;
            \\for (var i = 0; i < 4; i++) lanes.push(new Thread(rootLane));
            \\for (var i = 0; i < 4; i++) sum += lanes[i].join();
            \\sum
        );
        try std.testing.expectEqual(@as(f64, 2240), result.asNum());
        if (mode == .required)
            try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
    }
}

test "reentrant coercion and assignment roots survive moving nursery" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;
    const Host = struct {
        fn arm(raw: *anyopaque, _: Value, _: []const Value) value.HostError!Value {
            const machine: *interp.Interpreter = @ptrCast(@alignCast(raw));
            const ctx: *Context = @ptrCast(@alignCast(machine.gc_realm_context.?));
            ctx.gc.?.nursery_threshold_bytes = 1;
            ctx.gc_moving_checkpoint_requested.store(true, .release);
            return Value.undef();
        }
        fn finish(_: *value.CApiObjectOwner) void {}
        fn convert(raw: *anyopaque, object: *value.Object, _: value.HostClassConvertHint) value.HostError!Value {
            const machine: *interp.Interpreter = @ptrCast(@alignCast(raw));
            const expected = machine.global_object.?.getOwn("rootSubject").?.asObj();
            return Value.num(if (object == expected) 37 else -1);
        }
        const hooks: value.HostClassHooks = .{ .convert = convert };
    };
    const cases = [_]struct { name: []const u8, setup: []const u8, run: []const u8, expected: f64, tree_only: bool = false }{
        .{ .name = "object_destructure", .setup = "globalThis.rootSubject={};globalThis.rootKey={toString(){rootMovingLoop(20000);return 'x';}};", .run = "rootArm();({v:rootSubject[rootKey]}={v:4});rootSubject.x", .expected = 4 },
        .{ .name = "object_source_getter", .setup = "globalThis.rootSubject={};globalThis.rootSource={get v(){rootMovingLoop(20000);return 4;}};", .run = "rootArm();({v:rootSubject.x}=rootSource);rootSubject.x", .expected = 4 },
        .{ .name = "object_rest_key", .setup = "globalThis.rootSubject={};globalThis.rootKey={toString(){rootMovingLoop(20000);return 'x';}};", .run = "rootArm();({...rootSubject[rootKey]}={v:4});rootSubject.x.v", .expected = 4 },
        .{ .name = "object_rest_getter", .setup = "globalThis.rootSubject={};globalThis.rootSource={get v(){rootMovingLoop(20000);return 4;},w:7};", .run = "rootArm();({...rootSubject.x}=rootSource);rootSubject.x.v+rootSubject.x.w", .expected = 11 },
        .{ .name = "array_rest_key", .setup = "globalThis.rootSubject={};globalThis.rootKey={toString(){rootMovingLoop(20000);return 'x';}};", .run = "rootArm();[...rootSubject[rootKey]]=[4];rootSubject.x[0]", .expected = 4 },
        .{ .name = "array_later_element", .setup = "globalThis.rootSubject={};globalThis.rootKey={toString(){rootMovingLoop(20000);return 'x';}};", .run = "rootArm();[rootSubject[rootKey],rootSubject.y]=[4,7];rootSubject.x+rootSubject.y", .expected = 11 },
        .{ .name = "pending_parameter", .setup = "globalThis.rootSubject={marker:37};function rootRead(a=(rootMovingLoop(20000),0),b){return b===rootSubject?37:-1;}", .run = "rootArm();rootRead(undefined,rootSubject)", .expected = 37 },
        .{ .name = "pending_rest_parameter", .setup = "globalThis.rootSubject={marker:37};function rootRead(a=(rootMovingLoop(20000),0),...rest){return rest[0]===rootSubject?37:-1;}", .run = "rootArm();rootRead(undefined,rootSubject)", .expected = 37 },
        .{ .name = "caller_this", .setup = "globalThis.rootSubject={run(){rootOther();return this===rootSubject?37:-1;}};function rootOther(){rootMovingLoop(20000);}", .run = "rootArm();rootSubject.run()", .expected = 37 },
        .{ .name = "caller_scope", .setup = "globalThis.rootSubject={marker:37};function rootRead(){let local=rootSubject;rootOther();return local===rootSubject?37:-1;}function rootOther(){rootMovingLoop(20000);}", .run = "rootArm();rootRead()", .expected = 37 },
        .{ .name = "legacy_arguments", .setup = "globalThis.rootSubject={marker:37};function rootRead(value){rootMovingLoop(20000);return rootRead.arguments[0]===rootSubject?37:-1;}", .run = "rootArm();rootRead(rootSubject)", .expected = 37, .tree_only = true },
        .{ .name = "compound_getter", .setup = "globalThis.rootSubject={get x(){rootMovingLoop(20000);return 3;},set x(v){this.saved=v;}};", .run = "rootArm();rootSubject.x+=4;rootSubject.saved", .expected = 7 },
        .{ .name = "exotic_method", .setup = "globalThis.rootSubject={[Symbol.toPrimitive](){rootMovingLoop(20000);return this===rootSubject?37:-1;}};", .run = "rootArm();+rootSubject", .expected = 37 },
        .{ .name = "exotic_getter", .setup = "globalThis.rootSubject={get [Symbol.toPrimitive](){rootMovingLoop(20000);return function(){return this===rootSubject?37:-1;};}};", .run = "rootArm();+rootSubject", .expected = 37 },
        .{ .name = "ordinary_getter", .setup = "globalThis.rootSubject={get valueOf(){rootMovingLoop(20000);return function(){return this===rootSubject?37:-1;};}};", .run = "rootArm();+rootSubject", .expected = 37 },
        .{ .name = "object_result", .setup = "globalThis.rootSubject={valueOf(){rootMovingLoop(20000);return {};},toString(){return this===rootSubject?'37':'-1';}};", .run = "rootArm();+rootSubject", .expected = 37 },
        .{ .name = "string_getter", .setup = "globalThis.rootSubject={get toString(){rootMovingLoop(20000);return function(){return this===rootSubject?'37':'-1';};}};", .run = "rootArm();Number(String(rootSubject))", .expected = 37 },
        .{ .name = "proxy_getter", .setup = "globalThis.rootSubject=new Proxy({}, {get(t,k,r){if(k===Symbol.toPrimitive){rootMovingLoop(20000);return function(){return this===rootSubject?37:-1;};}}});", .run = "rootArm();+rootSubject", .expected = 37 },
        .{ .name = "wrapper_fallthrough", .setup = "globalThis.rootSubject=new Number(37);Object.defineProperty(rootSubject,'valueOf',{get(){rootMovingLoop(20000);return undefined;}});", .run = "rootArm();+rootSubject", .expected = 37 },
        .{ .name = "compound_receiver", .setup = "globalThis.rootSubject={x:3};function rootSide(){rootMovingLoop(20000);return 4;}", .run = "rootArm();rootSubject.x+=rootSide();rootSubject.x", .expected = 7 },
        .{ .name = "logical_receiver", .setup = "globalThis.rootSubject={x:0};function rootSide(){rootMovingLoop(20000);return 4;}", .run = "rootArm();rootSubject.x||=rootSide();rootSubject.x", .expected = 4 },
        .{ .name = "simple_receiver", .setup = "globalThis.rootSubject={x:0};function rootSide(){rootMovingLoop(20000);return 4;}", .run = "rootArm();rootSubject.x=rootSide();rootSubject.x", .expected = 4 },
        .{ .name = "computed_compound", .setup = "globalThis.rootKey='x'.repeat(32);globalThis.rootSubject={[rootKey]:3};function rootSide(){rootMovingLoop(20000);return 4;}", .run = "rootArm();rootSubject[rootKey]+=rootSide();rootSubject[rootKey]", .expected = 7 },
        .{ .name = "key_coercion", .setup = "globalThis.rootSubject={};globalThis.rootKey={toString(){rootMovingLoop(20000);return 'x';}};", .run = "rootArm();rootSubject[rootKey]=4;rootSubject.x", .expected = 4 },
        .{ .name = "old_value", .setup = "globalThis.rootSubject={x:{valueOf(){return this===rootSubject.x?3:-1;}}};function rootSide(){rootMovingLoop(20000);return 4;}", .run = "rootArm();rootSubject.x+=rootSide();rootSubject.x", .expected = 7 },
        .{ .name = "setter_result", .setup = "globalThis.rootSubject={marker:37};globalThis.rootBox={set x(v){rootMovingLoop(20000);}};", .run = "rootArm();(rootBox.x=rootSubject)===rootSubject?37:-1", .expected = 37 },
        .{ .name = "logical_setter_result", .setup = "globalThis.rootSubject={marker:37};globalThis.rootBox={get x(){return null;},set x(v){rootMovingLoop(20000);}};", .run = "rootArm();(rootBox.x??=rootSubject)===rootSubject?37:-1", .expected = 37 },
        .{ .name = "identifier_setter_result", .setup = "globalThis.rootSubject={marker:37};Object.defineProperty(globalThis,'rootTarget',{set(v){rootMovingLoop(20000);},configurable:true});", .run = "rootArm();(rootTarget=rootSubject)===rootSubject?37:-1", .expected = 37 },
        .{ .name = "super_compound", .setup = "class RootBase{get x(){return 3;}set x(v){this.saved=v;}}class RootChild extends RootBase{run(){return super.x+=rootSide();}}globalThis.rootSubject=new RootChild();function rootSide(){rootMovingLoop(20000);return 4;}", .run = "rootArm();rootSubject.run();rootSubject.saved", .expected = 7 },
        .{ .name = "super_key", .setup = "class RootBase{set x(v){this.saved=v;}}class RootChild extends RootBase{run(){return super[rootKey]=4;}}globalThis.rootSubject=new RootChild();globalThis.rootKey={toString(){rootMovingLoop(20000);return 'x';}};", .run = "rootArm();rootSubject.run();rootSubject.saved", .expected = 4 },
        .{ .name = "destructure_target", .setup = "globalThis.rootSubject={};globalThis.rootKey={toString(){rootMovingLoop(20000);return 'x';}};", .run = "rootArm();[rootSubject[rootKey]]=[4];rootSubject.x", .expected = 4 },
        .{ .name = "host_convert", .setup = "globalThis.rootSubject={marker:37,get [Symbol.toPrimitive](){rootMovingLoop(20000);return undefined;}};", .run = "rootArm();+rootSubject", .expected = 37 },
    };
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        for (cases) |case| {
            // #802 independently tracks missing VM legacy introspection even
            // without GC. This case exercises the existing tree-walker view.
            if (case.tree_only and mode != .tree_walker) continue;
            const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = true });
            defer ctx.destroy();
            {
                const saved = gc_mod.setActiveContext(ctx);
                defer gc_mod.restoreActiveContext(saved);
                const object = try gc_mod.allocObj(ctx.arena());
                object.* = .{ .native = Host.arm };
                try ctx.global_object.setOwn(ctx.arena(), ctx.root_shape, "rootArm", Value.obj(object));
                try ctx.env.put("rootArm", Value.obj(object));
            }
            _ = try ctx.evaluate(
                \\function rootMovingLoop(n){var total=0,i=0;while(i<n){total=total+i;i=i+1;}return total;}
                \\for(var warm=0;warm<10;warm=warm+1)rootMovingLoop(4096);
            );
            const loop_object = ctx.global_object.getOwn("rootMovingLoop").?.asObj();
            const loop: *interp.Function = @ptrCast(@alignCast(loop_object.jsFunction().?));
            try std.testing.expectEqual(jit.TierState.ready, loop.chunk.?.tier.loadState());
            try std.testing.expect(loop.chunk.?.tier.loadCode().?.manages_steps);
            ctx.collectGarbage();
            ctx.gc.?.nursery_threshold_bytes = std.math.maxInt(usize);
            // The warmed loop keeps its native artifact. The expression under
            // test and newly created methods use the selected execution mode.
            ctx.setBytecodeExecutionModeForTesting(mode);
            errdefer std.debug.print("moving root case {s} ({s})\n", .{ case.name, @tagName(mode) });
            _ = try ctx.evaluate(case.setup);
            if (std.mem.eql(u8, case.name, "host_convert")) {
                const subject = ctx.global_object.getOwn("rootSubject").?.asObj();
                const owner = try ctx.createCApiObjectOwner(@ptrCast(ctx), Host.finish);
                try subject.setCApiObjectClass(ctx.arena(), owner, &Host.hooks);
            }
            const before = ctx.global_object.getOwn("rootSubject").?.asObj();
            const moving_before = ctx.gc.?.accounting().moving_minor_collections;
            const result = try ctx.evaluate(case.run);
            try std.testing.expectEqual(case.expected, result.asNum());
            try std.testing.expectEqual(moving_before + 1, ctx.gc.?.accounting().moving_minor_collections);
            try std.testing.expect(before != ctx.global_object.getOwn("rootSubject").?.asObj());
            try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
            if (mode == .required)
                try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
        }
    }
}

test "binary coercion roots pending and completed operands across moving nursery" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const Harness = struct {
        fn create() !*Context {
            const ctx = try Context.createWith(std.testing.allocator, .{
                .enable_gc = true,
                .enable_jit = true,
            });
            errdefer ctx.destroy();
            _ = try ctx.evaluate(
                \\function binaryMovingLoop(n) {
                \\  var total = 0;
                \\  var i = 0;
                \\  while (i < n) { total = total + i; i = i + 1; }
                \\  return total;
                \\}
                \\for (var warm = 0; warm < 10; warm = warm + 1) binaryMovingLoop(4096);
            );
            const loop_object = ctx.global_object.getOwn("binaryMovingLoop").?.asObj();
            const loop: *interp.Function = @ptrCast(@alignCast(loop_object.jsFunction().?));
            const chunk = loop.chunk.?;
            try std.testing.expectEqual(jit.TierState.ready, chunk.tier.loadState());
            try std.testing.expect(chunk.tier.loadCode().?.manages_steps);
            ctx.collectGarbage();
            ctx.gc.?.nursery_threshold_bytes = std.math.maxInt(usize);
            return ctx;
        }
    };

    // The left conversion evacuates the nursery while the original right
    // object has not yet been converted. Its precise operand root must be
    // rewritten before the right-side ToPrimitive begins.
    {
        const ctx = try Harness.create();
        defer ctx.destroy();
        _ = try ctx.evaluate(
            \\globalThis.binaryMovingLeft = {
            \\  valueOf() { binaryMovingLoop(20000); return 7; }
            \\};
            \\globalThis.binaryMovingRight = { valueOf() { return 9; } };
        );
        const right_before = ctx.global_object.getOwn("binaryMovingRight").?.asObj();

        const gc_saved = gc_mod.setActiveContext(ctx);
        defer gc_mod.restoreActiveContext(gc_saved);
        const sa_saved = strcell.setActiveArena(ctx.arena());
        defer _ = strcell.setActiveArena(sa_saved);
        const ss_saved = stack_scan.enter(@frameAddress());
        defer stack_scan.leave(ss_saved);
        var machine = ctx.interpreter();
        try ctx.pushActiveInterpreter(&machine);
        defer ctx.popActiveInterpreter(&machine);
        const ai_saved = gc_mod.setActiveInterpreter(&machine);
        defer _ = gc_mod.setActiveInterpreter(ai_saved);

        const heap = ctx.gc.?;
        heap.nursery_threshold_bytes = 1;
        ctx.movingCheckpointRequest().store(true, .release);
        const moving_before = heap.accounting().moving_minor_collections;
        const result = try machine.applyBinary(
            .add,
            ctx.global_object.getOwn("binaryMovingLeft").?,
            ctx.global_object.getOwn("binaryMovingRight").?,
        );
        try std.testing.expectEqual(@as(f64, 16), result.asNum());
        try std.testing.expectEqual(moving_before + 1, heap.accounting().moving_minor_collections);
        try std.testing.expect(right_before != ctx.global_object.getOwn("binaryMovingRight").?.asObj());
        try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
    }

    // The left conversion completes first. The right conversion then evacuates
    // the returned young StringData, proving that the completed primitive
    // replaced the original left-object root before observable right-side code.
    {
        const ctx = try Harness.create();
        defer ctx.destroy();
        _ = try ctx.evaluate(
            \\globalThis.binaryMovingLeftText = "left".repeat(2);
            \\globalThis.binaryMovingLeft = {
            \\  valueOf() { return binaryMovingLeftText; }
            \\};
            \\globalThis.binaryMovingRight = {
            \\  valueOf() { binaryMovingLoop(20000); return "right".repeat(2); }
            \\};
        );
        const left_text_before = ctx.global_object.getOwn("binaryMovingLeftText").?.asStringCell();

        const gc_saved = gc_mod.setActiveContext(ctx);
        defer gc_mod.restoreActiveContext(gc_saved);
        const sa_saved = strcell.setActiveArena(ctx.arena());
        defer _ = strcell.setActiveArena(sa_saved);
        const ss_saved = stack_scan.enter(@frameAddress());
        defer stack_scan.leave(ss_saved);
        var machine = ctx.interpreter();
        try ctx.pushActiveInterpreter(&machine);
        defer ctx.popActiveInterpreter(&machine);
        const ai_saved = gc_mod.setActiveInterpreter(&machine);
        defer _ = gc_mod.setActiveInterpreter(ai_saved);

        const heap = ctx.gc.?;
        heap.nursery_threshold_bytes = 1;
        ctx.movingCheckpointRequest().store(true, .release);
        const moving_before = heap.accounting().moving_minor_collections;
        const result = try machine.applyBinary(
            .add,
            ctx.global_object.getOwn("binaryMovingLeft").?,
            ctx.global_object.getOwn("binaryMovingRight").?,
        );
        try std.testing.expectEqualStrings("leftleftrightright", try result.asWtf8(ctx.gpa));
        try std.testing.expectEqual(moving_before + 1, heap.accounting().moving_minor_collections);
        try std.testing.expect(left_text_before != ctx.global_object.getOwn("binaryMovingLeftText").?.asStringCell());
        try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
    }
}

test "GC requested compaction rewrites active Promise job native roots" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = true,
    });
    defer ctx.destroy();
    ctx.gc.?.nursery_threshold_bytes = std.math.maxInt(usize);

    _ = try ctx.evaluate(
        \\globalThis.promiseMovingDiscard = [];
        \\for (var i = 0; i < 2048; i = i + 1) {
        \\  promiseMovingDiscard.push({ dead: i, child: { value: i + 1 } });
        \\}
        \\function promiseMovingLoop(n) {
        \\  var total = 0;
        \\  var i = 0;
        \\  while (i < n) { total = total + i; i = i + 1; }
        \\  return total;
        \\}
        \\function promiseMovingThenGetter() {
        \\  promiseMovingLoop(20000);
        \\  return function (resolve) { resolve(this.marker); };
        \\}
        \\function promiseMovingHandler(value) {
        \\  var thenable = { marker: value.marker };
        \\  Object.defineProperty(thenable, "then", { get: promiseMovingThenGetter });
        \\  return thenable;
        \\}
        \\for (var warm = 0; warm < 10; warm = warm + 1) {
        \\  promiseMovingLoop(64);
        \\  promiseMovingThenGetter.call({ marker: warm });
        \\}
        \\globalThis.promiseMovingWitness = { marker: 511 };
        \\globalThis.promiseMovingResult = 0;
        \\promiseMovingDiscard = null;
    );
    ctx.collectGarbage();
    const compactions_before = ctx.gc_moving_safepoint_compactions.load(.monotonic);

    try std.testing.expect(ctx.requestGarbageCompaction());
    _ = try ctx.evaluate(
        \\Promise.resolve(promiseMovingWitness)
        \\  .then(promiseMovingHandler)
        \\  .then(function (value) { promiseMovingResult = value; });
        \\0
    );

    try std.testing.expectEqual(
        @as(f64, 511),
        (try ctx.evaluate("promiseMovingResult")).asNum(),
    );
    try std.testing.expectEqual(
        compactions_before + 1,
        ctx.gc_moving_safepoint_compactions.load(.monotonic),
    );
    try std.testing.expect(!ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
}

fn verifyOptimizerLiveSafepointRelocation(options: Context.TestingOptions) !void {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWithTestingOptions(std.testing.allocator, options);
    defer ctx.destroy();

    _ = try ctx.evaluate(
        \\globalThis.optimizerCompactDiscard = [];
        \\for (var i = 0; i < 4096; i = i + 1)
        \\  optimizerCompactDiscard.push({ dead: i, child: { value: i + 1 } });
        \\function optimizerCompactKeep(n, held) {
        \\  var cursor = 0;
        \\  while (cursor < n) cursor = cursor + 1;
        \\  return held.marker;
        \\}
        \\globalThis.optimizerCompactWitness = { marker: 362 };
        \\for (var warm = 0; warm < 10; warm = warm + 1)
        \\  optimizerCompactKeep(6, optimizerCompactWitness);
        \\optimizerCompactDiscard = null;
    );

    const function_object = ctx.global_object.getOwn("optimizerCompactKeep").?.asObj();
    const function: *interp.Function = @ptrCast(@alignCast(function_object.jsFunction().?));
    const chunk = function.chunk.?;
    const artifact = chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(jit.CodeKind.optimizer, artifact.kind);
    try std.testing.expect(!artifact.entry_enabled and artifact.has_side_exits);
    try std.testing.expectEqual(@as(u64, 0b101), artifact.required_numeric_slots);
    const osr = artifact.osr orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), osr.entries.len);
    const entry = osr.entries[0];
    const held_import = osr.imports[entry.first_import + 1];
    try std.testing.expectEqual(jit.OsrImportSource.frame_slot, held_import.source);
    try std.testing.expectEqual(@as(u16, 1), held_import.source_index);
    const entry_map = artifact.stack_maps.?.forDeopt(0) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 0), entry_map.frame_pointer_slots);
    try std.testing.expectEqual(@as(u128, 1) << @intCast(held_import.destination), entry_map.scratch_pointer_slots);

    const handle = try ctx.protectValue(ctx.global_object.getOwn("optimizerCompactWitness").?);
    defer std.debug.assert(ctx.unprotectValue(handle));
    ctx.collectGarbage();
    const backing_before = ctx.gc_cell_backing.?.stats();
    try std.testing.expect(backing_before.chunks > 1);
    const witness_before = @intFromPtr(handle.get().asObj());
    const compactions_before = ctx.gc_moving_safepoint_compactions.load(.monotonic);

    try std.testing.expect(ctx.requestGarbageCompaction());
    const result = try ctx.evaluate("optimizerCompactKeep(20000, optimizerCompactWitness)");
    try std.testing.expectEqual(@as(f64, 362), result.asNum());
    try std.testing.expect(!ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expectEqual(compactions_before + 1, ctx.gc_moving_safepoint_compactions.load(.monotonic));
    try std.testing.expect(witness_before != @intFromPtr(handle.get().asObj()));
    try std.testing.expectEqual(@as(f64, 362), handle.get().asObj().getOwn("marker").?.asNum());
    try std.testing.expectEqual(artifact, chunk.optimizer_tier.loadArtifact(jit.CompiledCode).?);
    try std.testing.expect(ctx.gc_cell_backing.?.stats().chunks < backing_before.chunks);
}

test "JIT Class-A invalidation waits for the shared GC conductor" {
    if (builtin.single_threaded) return error.SkipZigTest;

    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
    });
    defer ctx.destroy();
    const owner = ctx.shared_jit_owner orelse &ctx.jit_owner;
    const generation_before = owner.invalidation_generation.load(.acquire);
    const Shared = struct {
        context: *Context,
        started: std.atomic.Value(bool) = .init(false),
        finished: std.atomic.Value(bool) = .init(false),

        fn invalidate(shared: *@This()) void {
            shared.started.store(true, .release);
            shared.context.clearJitCode();
            shared.finished.store(true, .release);
        }
    };

    ctx.enterJitGcConductor();
    var shared = Shared{ .context = ctx };
    var invalidator = try std.Thread.spawn(.{}, Shared.invalidate, .{&shared});
    while (!shared.started.load(.acquire)) std.atomic.spinLoopHint();
    while (ctx.jitGcConductor().waiting_threads.load(.acquire) == 0) std.atomic.spinLoopHint();
    try std.testing.expect(!shared.finished.load(.acquire));
    try std.testing.expectEqual(generation_before, owner.invalidation_generation.load(.acquire));
    ctx.leaveJitGcConductor();
    invalidator.join();

    try std.testing.expect(shared.finished.load(.acquire));
    try std.testing.expectEqual(generation_before + 1, owner.invalidation_generation.load(.acquire));
    try std.testing.expectEqual(@as(u64, 1), ctx.jitGcConductor().class_a_stops.load(.acquire));
    try std.testing.expectEqual(@as(u64, 0), ctx.jitGcConductor().waiting_threads.load(.acquire));
    try std.testing.expect(ctx.jitGcConductor().wait_iterations.load(.acquire) != 0);
}

/// A warmed *inherited* named read publishes only shape/slot assumptions. A
/// value-only mutation of the holder must therefore preserve the artifact and
/// the next read must load the new value from the guarded slot (#471).
///
/// The read feeds arithmetic, matching the PR-249 witnesses' own shape. A
/// property node is typed `.other`, so the `add` has no Number-specialized
/// form and lowers through the runtime operation ABI while the rest of the
/// function stays native — which is only possible because the graph now gives
/// that binary an effect frame state to stage a descriptor against.
fn verifyInheritedValueMutation(options: Context.TestingOptions) !void {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWithTestingOptions(std.testing.allocator, options);
    defer ctx.destroy();
    _ = try ctx.evaluate(
        \\globalThis.classAProto = { y: 1 };
        \\globalThis.classAObject = Object.create(classAProto);
        \\function classARead(o) { return o.y + 1; }
        \\for (let warm = 0; warm < 64; warm = warm + 1) classARead(classAObject);
    );
    const owner = ctx.shared_jit_owner orelse &ctx.jit_owner;
    try std.testing.expect(owner.hasPublishedArtifacts());
    const generation_before = owner.invalidation_generation.load(.acquire);

    try std.testing.expectEqual(@as(f64, 2), (try ctx.evaluate("classARead(classAObject)")).asNum());
    _ = try ctx.evaluate("classAProto.y = 4");

    try std.testing.expectEqual(generation_before, owner.invalidation_generation.load(.acquire));
    try std.testing.expectEqual(@as(u64, 0), ctx.jitGcConductor().class_a_stops.load(.acquire));
    try std.testing.expect(owner.hasPublishedArtifacts());
    try std.testing.expectEqual(@as(f64, 5), (try ctx.evaluate("classARead(classAObject)")).asNum());
}

test "parallel_js: a block-scoped binding survives concurrent collection" {
    if (builtin.single_threaded) return error.SkipZigTest;

    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    const collections_before = ctx.gc.?.collections;

    // Attempted reduction of the `dw2-marklistset-storm.js` no-GIL failure,
    // which throws `ReferenceError: threads` on a block-scoped `const`
    // initialised two statements earlier, with allocation-heavy main-thread
    // work in between.
    //
    // This shape does NOT reproduce it — recorded deliberately, because the
    // obvious explanation (a block Environment going unrooted across a
    // mid-script parallel collection) is therefore not sufficient on its own,
    // and the next person should not spend the same hour rediscovering that.
    // Whatever dw2 needs is more than a block binding plus peers plus GC
    // pressure. An explicit request makes the collection deterministic while
    // all three peers and the block Environment are live; ten thousand churn
    // iterations retain allocation-heavy work without making this reduction
    // dominate the complete unit suite. The collection is asserted below.
    const result = try ctx.evaluate(
        \\function churn(seed) {
        \\  let sum = 0;
        \\  for (let i = 0; i < 10000; ++i) {
        \\    const cell = { a: i, b: [i, i + 1], c: { d: i } };
        \\    sum += cell.a + cell.b[0] + cell.c.d;
        \\  }
        \\  return sum + seed;
        \\}
        \\let outcome = "unset";
        \\{
        \\  const peers = [];
        \\  for (let i = 0; i < 3; ++i) peers.push(new Thread(churn, i));
        \\  $vm.gc();
        \\  const mainCheck = churn(99);
        \\  let joined = 0;
        \\  for (const p of peers) joined += p.join();
        \\  outcome = (typeof peers === "undefined") ? "binding-lost"
        \\    : (joined > 0 && mainCheck > 0 ? "ok" : "bad-values");
        \\}
        \\outcome;
    );
    try std.testing.expect(result.isString());
    try std.testing.expectEqualStrings("ok", result.asStr());
    try std.testing.expect(ctx.gc.?.collections > collections_before);
}

test "parallel_js: targeted Class-A invalidation preserves unrelated artifact" {
    if (builtin.single_threaded) return error.SkipZigTest;
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .enable_jit = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    _ = try ctx.evaluate(
        \\globalThis.watchedProto = { y: 1 };
        \\globalThis.watchedObject = Object.create(watchedProto);
        \\globalThis.unrelated = { a: 1, b: 2, c: 3 };
        \\globalThis.survivorObject = { survivor: 7, distinct: 8 };
        \\function watchedRead(o) { return o.y; }
        \\function survivorRead(o) { return o.survivor; }
        \\for (let warm = 0; warm < 64; warm = warm + 1) {
        \\  watchedRead(watchedObject);
        \\  survivorRead(survivorObject);
        \\}
    );
    const owner = ctx.shared_jit_owner orelse &ctx.jit_owner;
    try std.testing.expect(owner.hasPublishedArtifacts());
    const generation_before = owner.invalidation_generation.load(.acquire);
    const watched_raw = ctx.global_object.getOwn("watchedRead").?.asObj().jsFunction() orelse
        return error.TestUnexpectedResult;
    const watched_function: *interp.Function = @ptrCast(@alignCast(watched_raw));
    const watched_chunk = watched_function.chunk orelse return error.TestUnexpectedResult;
    const watched_artifact = watched_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    const survivor_raw = ctx.global_object.getOwn("survivorRead").?.asObj().jsFunction() orelse
        return error.TestUnexpectedResult;
    const survivor_function: *interp.Function = @ptrCast(@alignCast(survivor_raw));
    const survivor_chunk = survivor_function.chunk orelse return error.TestUnexpectedResult;
    const survivor_artifact = survivor_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;

    // No published artifact speculates on `unrelated`'s shape, so mutating it
    // must not jettison the warmed tier (#457).
    _ = try ctx.evaluate("unrelated.a = 99;");
    try std.testing.expectEqual(generation_before, owner.invalidation_generation.load(.acquire));
    try std.testing.expect(owner.hasPublishedArtifacts());

    // Adding a key changes the watched holder's shape and retains the current
    // compile/link Class-A boundary. Value-only stores above do not.
    _ = try ctx.evaluate("watchedProto.extra = 4;");
    try std.testing.expectEqual(generation_before + 1, owner.invalidation_generation.load(.acquire));
    try std.testing.expect(watched_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) == null);
    try std.testing.expectEqual(survivor_artifact, survivor_chunk.optimizer_tier.loadArtifact(jit.CompiledCode).?);
    try std.testing.expect(watched_artifact != survivor_artifact);
    try std.testing.expectEqual(@as(f64, 1), (try ctx.evaluate("watchedRead(watchedObject)")).asNum());
    try std.testing.expectEqual(@as(f64, 7), (try ctx.evaluate("survivorRead(survivorObject)")).asNum());
    const stats = owner.stats();
    try std.testing.expectEqual(@as(u64, 1), stats.shape_invalidation_events);
    try std.testing.expectEqual(@as(u64, 1), stats.shape_retired_artifacts);
    try std.testing.expect(stats.shape_survivor_artifacts >= 1);
}

test "parallel_js: delete and descriptor changes retire only affected artifacts" {
    if (builtin.single_threaded) return error.SkipZigTest;
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .enable_jit = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    _ = try ctx.evaluate(
        \\globalThis.deletedObject = { doomed: 1, deleteShape: 2 };
        \\globalThis.redefinedObject = { value: 3, redefineShape: 4 };
        \\globalThis.valueOnlyObject = { stable: 5, valueShape: 6 };
        \\globalThis.lockedObject = {};
        \\Object.defineProperty(lockedObject, "locked", { value: 8, configurable: false });
        \\globalThis.survivorObject = { survivor: 7, survivorShape: 8 };
        \\function deletedRead(o) { return o.doomed; }
        \\function redefinedRead(o) { return o.value; }
        \\function valueOnlyRead(o) { return o.stable; }
        \\function lockedRead(o) { return o.locked; }
        \\function survivorRead(o) { return o.survivor; }
        \\for (let warm = 0; warm < 64; warm = warm + 1) {
        \\  deletedRead(deletedObject);
        \\  redefinedRead(redefinedObject);
        \\  valueOnlyRead(valueOnlyObject);
        \\  lockedRead(lockedObject);
        \\  survivorRead(survivorObject);
        \\}
    );

    const ArtifactRef = struct {
        chunk: *bc.Chunk,
        artifact: *const jit.CompiledCode,

        fn fromGlobal(context: *Context, name: []const u8) !@This() {
            const raw = context.global_object.getOwn(name).?.asObj().jsFunction() orelse
                return error.TestUnexpectedResult;
            const function: *interp.Function = @ptrCast(@alignCast(raw));
            const chunk = function.chunk orelse return error.TestUnexpectedResult;
            return .{
                .chunk = chunk,
                .artifact = chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
                    return error.TestUnexpectedResult,
            };
        }

        fn remainsPublished(self: @This()) bool {
            return self.chunk.optimizer_tier.loadArtifact(jit.CompiledCode) == self.artifact;
        }
    };

    const deleted = try ArtifactRef.fromGlobal(ctx, "deletedRead");
    const redefined = try ArtifactRef.fromGlobal(ctx, "redefinedRead");
    const value_only = try ArtifactRef.fromGlobal(ctx, "valueOnlyRead");
    const locked = try ArtifactRef.fromGlobal(ctx, "lockedRead");
    const survivor = try ArtifactRef.fromGlobal(ctx, "survivorRead");
    const owner = ctx.shared_jit_owner orelse &ctx.jit_owner;
    const generation_before = owner.invalidation_generation.load(.acquire);

    // A value-only DefineOwnProperty preserves the live data slot and does not
    // materialize an attributes sidecar. An empty descriptor and a failed
    // non-configurable delete are also representation no-ops.
    try std.testing.expectEqual(@as(f64, 9), (try ctx.evaluate(
        \\Object.defineProperty(valueOnlyObject, "stable", { value: 9 });
        \\Object.defineProperty(valueOnlyObject, "stable", {});
        \\Reflect.deleteProperty(lockedObject, "locked");
        \\valueOnlyRead(valueOnlyObject);
    )).asNum());
    try std.testing.expectEqual(generation_before, owner.invalidation_generation.load(.acquire));
    try std.testing.expect(value_only.remainsPublished());
    try std.testing.expect(locked.remainsPublished());

    try std.testing.expect((try ctx.evaluate("delete deletedObject.doomed;")).toBoolean());
    try std.testing.expect(deleted.chunk.optimizer_tier.loadArtifact(jit.CompiledCode) == null);
    try std.testing.expect(redefined.remainsPublished());
    try std.testing.expect(value_only.remainsPublished());
    try std.testing.expect(locked.remainsPublished());
    try std.testing.expect(survivor.remainsPublished());

    try std.testing.expectEqual(@as(f64, 11), (try ctx.evaluate(
        \\Object.defineProperty(redefinedObject, "value", {
        \\  get() { return 11; }, configurable: true
        \\});
        \\redefinedRead(redefinedObject);
    )).asNum());
    try std.testing.expect(redefined.chunk.optimizer_tier.loadArtifact(jit.CompiledCode) == null);
    try std.testing.expect(value_only.remainsPublished());
    try std.testing.expect(locked.remainsPublished());
    try std.testing.expect(survivor.remainsPublished());

    const stats = owner.stats();
    try std.testing.expectEqual(generation_before + 2, owner.invalidation_generation.load(.acquire));
    try std.testing.expectEqual(@as(u64, 2), stats.shape_invalidation_events);
    try std.testing.expectEqual(@as(u64, 2), stats.shape_retired_artifacts);
    try std.testing.expect(stats.shape_survivor_artifacts >= 7);
}

test "parallel_js: optimized reads race delete redefine and prototype replacement" {
    if (builtin.single_threaded) return error.SkipZigTest;
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .enable_jit = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    const result = ctx.evaluate(
        \\const deleteTarget = { value: 1, deleteMarker: 0 };
        \\const redefineTarget = { value: 2, redefineMarker: 0 };
        \\const protoA = { inherited: 3 };
        \\const protoB = { inherited: 4 };
        \\const protoTarget = Object.create(protoA);
        \\const gate = { ready: 0, stop: 0 };
        \\function deleteRead(o) { return o.value; }
        \\function redefineRead(o) { return o.value; }
        \\function inheritedRead(o) { return o.inherited; }
        \\function six() { return 6; }
        \\for (let warm = 0; warm < 64; ++warm) {
        \\  deleteRead(deleteTarget);
        \\  redefineRead(redefineTarget);
        \\  inheritedRead(protoTarget);
        \\}
        \\const reader = new Thread(() => {
        \\  let checks = 0;
        \\  Atomics.store(gate, "ready", 1);
        \\  while (Atomics.load(gate, "stop") === 0) {
        \\    const deleted = deleteRead(deleteTarget);
        \\    if (deleted !== undefined && deleted !== 1)
        \\      throw new Error("stale delete read: " + deleted);
        \\    const redefined = redefineRead(redefineTarget);
        \\    if (redefined !== undefined && redefined !== 2 && redefined !== 6)
        \\      throw new Error("stale redefine read: " + redefined);
        \\    const inherited = inheritedRead(protoTarget);
        \\    if (inherited !== 3 && inherited !== 4)
        \\      throw new Error("stale prototype read: " + inherited);
        \\    ++checks;
        \\  }
        \\  return checks;
        \\});
        \\while (Atomics.load(gate, "ready") === 0) {}
        \\for (let round = 0; round < 64; ++round) {
        \\  delete deleteTarget.value;
        \\  deleteTarget.value = 1;
        \\  Object.defineProperty(redefineTarget, "value", {
        \\    get: six, enumerable: true, configurable: true
        \\  });
        \\  Object.defineProperty(redefineTarget, "value", {
        \\    value: 2, writable: true, enumerable: true, configurable: true
        \\  });
        \\  Object.setPrototypeOf(protoTarget, (round & 1) === 0 ? protoB : protoA);
        \\}
        \\Atomics.store(gate, "stop", 1);
        \\reader.join();
    ) catch |err| {
        if (ctx.exception) |exception| {
            if (exception.isObject()) {
                const message = exception.asObj().getOwn("message") orelse Value.undef();
                if (message.isString()) std.debug.print("property mutation race: {s}: {s}\n", .{
                    exception.asObj().errorName(), message.asStr(),
                });
            }
        }
        return err;
    };
    try std.testing.expect(result.isNumber());
    try std.testing.expect(result.asNum() > 0);
}

