test "optimizer packed index and property regions match bytecode and survive a moving GC checkpoint" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;
    const original_parallel = bc.ic_seqlock_enabled.swap(false, .monotonic);
    defer bc.ic_seqlock_enabled.store(original_parallel, .monotonic);

    const source =
        \\globalThis.optimizerPropertyDiscard = [];
        \\for (var dead = 0; dead < 4096; dead = dead + 1)
        \\  optimizerPropertyDiscard.push({ dead, child: { value: dead + 1 } });
        \\function optimizerPropertyMove(n, target, held) {
        \\  var cursor = 0;
        \\  while (cursor < n) {
        \\    target.value = held;
        \\    held = target.value;
        \\    cursor = cursor + 1;
        \\  }
        \\  return target.value.marker + held.marker;
        \\}
        \\function optimizerPropertyPoly(object, held) {
        \\  object.value = held;
        \\  return object.value.marker;
        \\}
        \\function optimizerIndexMove(n, target, held) {
        \\  var cursor = 0;
        \\  while (cursor < n) {
        \\    target[0] = held;
        \\    held = target[0];
        \\    cursor = cursor + 1;
        \\  }
        \\  return target[0].marker + held.marker;
        \\}
        \\function optimizerPropertyArithmetic(jobs, lane) {
        \\  var total = 0;
        \\  for (var job = 0; job < jobs; job = job + 1) {
        \\    var object = { a: lane + job, b: 1, c: 2, d: 3 };
        \\    for (var index = 0; index < 25000; index = index + 1) {
        \\      object.a = (object.a + index) % 1000003;
        \\      object.b = object.b + 1;
        \\      object.c = object.a + object.b;
        \\      object.d = object.c - object.b;
        \\    }
        \\    total = total + object.a + object.b + object.c + object.d;
        \\  }
        \\  return total;
        \\}
        \\globalThis.optimizerPropertyHeld = { marker: 3 };
        \\globalThis.optimizerPropertyTarget = { value: optimizerPropertyHeld };
        \\globalThis.optimizerIndexTarget = [optimizerPropertyHeld];
        \\globalThis.optimizerPropertyObjects = [
        \\  { value: optimizerPropertyHeld, a: 1 },
        \\  { b: 1, value: optimizerPropertyHeld },
        \\  { c: 1, d: 2, value: optimizerPropertyHeld },
        \\  { e: 1, f: 2, g: 3, value: optimizerPropertyHeld }
        \\];
        \\for (var warm = 0; warm < 10; warm = warm + 1) {
        \\  optimizerPropertyMove(8, optimizerPropertyTarget, optimizerPropertyHeld);
        \\  optimizerPropertyPoly(optimizerPropertyObjects[0], optimizerPropertyHeld);
        \\  optimizerPropertyPoly(optimizerPropertyObjects[1], optimizerPropertyHeld);
        \\  optimizerPropertyPoly(optimizerPropertyObjects[2], optimizerPropertyHeld);
        \\  optimizerPropertyPoly(optimizerPropertyObjects[3], optimizerPropertyHeld);
        \\  optimizerIndexMove(8, optimizerIndexTarget, optimizerPropertyHeld);
        \\  optimizerPropertyArithmetic(1, warm);
        \\}
        \\optimizerPropertyDiscard = null;
    ;

    const native_ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = true,
    });
    defer native_ctx.destroy();
    const bytecode_ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
    });
    defer bytecode_ctx.destroy();

    _ = try native_ctx.evaluate(source);
    _ = try bytecode_ctx.evaluate(source);
    const function_object = native_ctx.global_object.getOwn("optimizerPropertyMove").?.asObj();
    const function: *interp.Function = @ptrCast(@alignCast(function_object.jsFunction().?));
    const chunk = function.chunk.?;
    const artifact = chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(jit.CodeKind.optimizer, artifact.kind);
    try std.testing.expect(artifact.osr != null and artifact.has_side_exits and artifact.native_operations != null);
    const index_object = native_ctx.global_object.getOwn("optimizerIndexMove").?.asObj();
    const index_function: *interp.Function = @ptrCast(@alignCast(index_object.jsFunction().?));
    const index_chunk = index_function.chunk.?;
    const index_artifact = index_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(index_artifact.osr != null and index_artifact.native_operations != null);
    var saw_index_read = false;
    var saw_index_write = false;
    for (index_artifact.native_operations.?.descriptors) |descriptor| {
        saw_index_read = saw_index_read or descriptor.bytecode_op == @backingInt(bc.Op.get_index);
        saw_index_write = saw_index_write or descriptor.bytecode_op == @backingInt(bc.Op.set_index);
    }
    try std.testing.expect(saw_index_read and saw_index_write);
    const arithmetic_object = native_ctx.global_object.getOwn("optimizerPropertyArithmetic").?.asObj();
    const arithmetic_function: *interp.Function = @ptrCast(@alignCast(arithmetic_object.jsFunction().?));
    const arithmetic_chunk = arithmetic_function.chunk.?;
    const arithmetic_artifact = arithmetic_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(arithmetic_artifact.osr != null and arithmetic_artifact.native_operations != null);
    var rooted_high_input = false;
    for (arithmetic_artifact.native_operations.?.descriptors) |descriptor| {
        if (descriptor.first_input < 64) continue;
        const map = arithmetic_artifact.stack_maps.?.forDeopt(descriptor.deopt_index) orelse
            return error.TestUnexpectedResult;
        for (descriptor.first_input..descriptor.first_input + descriptor.input_count) |slot|
            try std.testing.expect(map.scratch_pointer_slots & (@as(u128, 1) << @intCast(slot)) != 0);
        rooted_high_input = true;
    }
    try std.testing.expect(rooted_high_input);

    native_ctx.collectGarbage();
    bytecode_ctx.collectGarbage();
    const target_before = @intFromPtr(native_ctx.global_object.getOwn("optimizerPropertyTarget").?.asObj());
    const index_target_before = @intFromPtr(native_ctx.global_object.getOwn("optimizerIndexTarget").?.asObj());
    const held_before = @intFromPtr(native_ctx.global_object.getOwn("optimizerPropertyHeld").?.asObj());
    const property_stats_before = vm.optimizerNativePropertyStatsForTesting();
    const index_stats_before = vm.optimizerNativeIndexStatsForTesting();
    try std.testing.expect(native_ctx.requestGarbageCompaction());

    const native_indexed = try native_ctx.evaluate(
        "optimizerIndexMove(20000, optimizerIndexTarget, optimizerPropertyHeld)",
    );
    const bytecode_indexed = try bytecode_ctx.evaluate(
        "optimizerIndexMove(20000, optimizerIndexTarget, optimizerPropertyHeld)",
    );
    try std.testing.expectEqual(bytecode_indexed.rawBits(), native_indexed.rawBits());
    try std.testing.expectEqual(@as(f64, 6), native_indexed.asNum());
    try std.testing.expect(!native_ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expect(index_target_before != @intFromPtr(native_ctx.global_object.getOwn("optimizerIndexTarget").?.asObj()));
    try std.testing.expect(held_before != @intFromPtr(native_ctx.global_object.getOwn("optimizerPropertyHeld").?.asObj()));

    const native_monomorphic = try native_ctx.evaluate(
        "optimizerPropertyMove(20000, optimizerPropertyTarget, optimizerPropertyHeld)",
    );
    const bytecode_monomorphic = try bytecode_ctx.evaluate(
        "optimizerPropertyMove(20000, optimizerPropertyTarget, optimizerPropertyHeld)",
    );
    try std.testing.expectEqual(bytecode_monomorphic.rawBits(), native_monomorphic.rawBits());
    try std.testing.expectEqual(@as(f64, 6), native_monomorphic.asNum());
    try std.testing.expect(target_before != @intFromPtr(native_ctx.global_object.getOwn("optimizerPropertyTarget").?.asObj()));

    const native_polymorphic = try native_ctx.evaluate(
        \\optimizerPropertyPoly(optimizerPropertyObjects[0], optimizerPropertyHeld) +
        \\optimizerPropertyPoly(optimizerPropertyObjects[1], optimizerPropertyHeld) +
        \\optimizerPropertyPoly(optimizerPropertyObjects[2], optimizerPropertyHeld) +
        \\optimizerPropertyPoly(optimizerPropertyObjects[3], optimizerPropertyHeld)
    );
    const bytecode_polymorphic = try bytecode_ctx.evaluate(
        \\optimizerPropertyPoly(optimizerPropertyObjects[0], optimizerPropertyHeld) +
        \\optimizerPropertyPoly(optimizerPropertyObjects[1], optimizerPropertyHeld) +
        \\optimizerPropertyPoly(optimizerPropertyObjects[2], optimizerPropertyHeld) +
        \\optimizerPropertyPoly(optimizerPropertyObjects[3], optimizerPropertyHeld)
    );
    try std.testing.expectEqual(bytecode_polymorphic.rawBits(), native_polymorphic.rawBits());
    try std.testing.expectEqual(@as(f64, 12), native_polymorphic.asNum());

    const osr_before_arithmetic = vm.optimizerOsrEntriesForTesting();
    const native_arithmetic = try native_ctx.evaluate("optimizerPropertyArithmetic(2, 7)");
    const bytecode_arithmetic = try bytecode_ctx.evaluate("optimizerPropertyArithmetic(2, 7)");
    try std.testing.expectEqual(bytecode_arithmetic.rawBits(), native_arithmetic.rawBits());
    try std.testing.expect(vm.optimizerOsrEntriesForTesting() > osr_before_arithmetic);
    try std.testing.expectEqual(property_stats_before, vm.optimizerNativePropertyStatsForTesting());
    try std.testing.expectEqual(index_stats_before, vm.optimizerNativeIndexStatsForTesting());
}

test "optimizer allocating array loops match bytecode and survive moving GC" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;
    const original_parallel = bc.ic_seqlock_enabled.swap(false, .monotonic);
    defer bc.ic_seqlock_enabled.store(original_parallel, .monotonic);

    const source =
        \\globalThis.optimizerArrayDiscard = [];
        \\for (var dead = 0; dead < 4096; dead = dead + 1)
        \\  optimizerArrayDiscard.push({ dead, child: { value: dead + 1 } });
        \\function optimizerArrayGrow(n, target, held) {
        \\  var i = 0;
        \\  while (i < n) {
        \\    if (i >= 0) target.push(held);
        \\    i = i + 1;
        \\  }
        \\  return target.length + target[n - 1].marker;
        \\}
        \\function optimizerArrayBuild(n, held) {
        \\  var i = 0; var total = 0;
        \\  while (i < n) {
        \\    if (i >= 0) { var pair = [i, held]; total = total + i; }
        \\    i = i + 1;
        \\  }
        \\  return total;
        \\}
        \\globalThis.optimizerArrayHeld = { marker: 7 };
        \\globalThis.optimizerArrayTarget = [];
        \\for (var warm = 0; warm < 10; warm = warm + 1) {
        \\  optimizerArrayGrow(4, [], optimizerArrayHeld);
        \\  optimizerArrayBuild(4, optimizerArrayHeld);
        \\}
        \\optimizerArrayDiscard = null;
    ;

    const native_ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = true,
    });
    defer native_ctx.destroy();
    const bytecode_ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
    });
    defer bytecode_ctx.destroy();

    _ = try native_ctx.evaluate(source);
    _ = try bytecode_ctx.evaluate(source);
    const grow_object = native_ctx.global_object.getOwn("optimizerArrayGrow").?.asObj();
    const grow_function: *interp.Function = @ptrCast(@alignCast(grow_object.jsFunction().?));
    const grow_chunk = grow_function.chunk.?;
    const grow_artifact = grow_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    var saw_push_call = false;
    for (grow_artifact.native_operations.?.descriptors) |descriptor|
        saw_push_call = saw_push_call or descriptor.bytecode_op == @backingInt(bc.Op.call_with_this);
    try std.testing.expect(grow_artifact.osr != null and saw_push_call);

    const build_object = native_ctx.global_object.getOwn("optimizerArrayBuild").?.asObj();
    const build_function: *interp.Function = @ptrCast(@alignCast(build_object.jsFunction().?));
    const build_chunk = build_function.chunk.?;
    const build_artifact = build_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    var saw_new_array = false;
    var saw_array_append = false;
    for (build_artifact.native_operations.?.descriptors) |descriptor| {
        saw_new_array = saw_new_array or descriptor.bytecode_op == @backingInt(bc.Op.new_array);
        saw_array_append = saw_array_append or descriptor.bytecode_op == @backingInt(bc.Op.array_append);
    }
    try std.testing.expect(build_artifact.osr != null and saw_new_array and saw_array_append);

    native_ctx.collectGarbage();
    bytecode_ctx.collectGarbage();
    const target_before = @intFromPtr(native_ctx.global_object.getOwn("optimizerArrayTarget").?.asObj());
    const held_before = @intFromPtr(native_ctx.global_object.getOwn("optimizerArrayHeld").?.asObj());
    try std.testing.expect(native_ctx.requestGarbageCompaction());

    const osr_before = vm.optimizerOsrEntriesForTesting();
    const grow_stats_before = vm.optimizerNativeArrayAppendStatsForTesting();
    const native_grow = try native_ctx.evaluate(
        "optimizerArrayGrow(20000, optimizerArrayTarget, optimizerArrayHeld)",
    );
    const bytecode_grow = try bytecode_ctx.evaluate(
        "optimizerArrayGrow(20000, optimizerArrayTarget, optimizerArrayHeld)",
    );
    try std.testing.expectEqual(bytecode_grow.rawBits(), native_grow.rawBits());
    try std.testing.expectEqual(@as(f64, 20007), native_grow.asNum());
    try std.testing.expect(!native_ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expect(target_before != @intFromPtr(native_ctx.global_object.getOwn("optimizerArrayTarget").?.asObj()));
    try std.testing.expect(held_before != @intFromPtr(native_ctx.global_object.getOwn("optimizerArrayHeld").?.asObj()));
    try std.testing.expect(vm.optimizerOsrEntriesForTesting() > osr_before);
    const grow_stats_after = vm.optimizerNativeArrayAppendStatsForTesting();
    try std.testing.expect(grow_stats_after.direct > grow_stats_before.direct);
    try std.testing.expect(grow_stats_after.growth_callbacks > grow_stats_before.growth_callbacks);
    std.debug.print(
        "optimizer-array-attribution\titerations=20000\tdirect={d}\tnarrow={d}\tgrowth={d}\tgeneral={d}\n",
        .{
            grow_stats_after.direct - grow_stats_before.direct,
            grow_stats_after.narrow_callbacks - grow_stats_before.narrow_callbacks,
            grow_stats_after.growth_callbacks - grow_stats_before.growth_callbacks,
            grow_stats_after.callbacks - grow_stats_before.callbacks,
        },
    );
    try std.testing.expectEqual(grow_artifact, grow_chunk.optimizer_tier.loadArtifact(jit.CompiledCode).?);

    const append_stats_before = vm.optimizerNativeArrayAppendStatsForTesting();
    const native_build = try native_ctx.evaluate("optimizerArrayBuild(2000, optimizerArrayHeld)");
    const bytecode_build = try bytecode_ctx.evaluate("optimizerArrayBuild(2000, optimizerArrayHeld)");
    try std.testing.expectEqual(bytecode_build.rawBits(), native_build.rawBits());
    try std.testing.expectEqual(@as(f64, 1999000), native_build.asNum());
    const append_stats_after = vm.optimizerNativeArrayAppendStatsForTesting();
    try std.testing.expect(append_stats_after.direct > append_stats_before.direct);
    try std.testing.expect(append_stats_after.callbacks > append_stats_before.callbacks);
    try std.testing.expectEqual(build_artifact, build_chunk.optimizer_tier.loadArtifact(jit.CompiledCode).?);
}

test "GC compaction rewrites public Zig protected handles" {
    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
    });
    defer ctx.destroy();
    const foreign = try Context.create(std.testing.allocator);
    defer foreign.destroy();

    const raw = try ctx.evaluate(
        \\(() => {
        \\  globalThis.zigHandleDiscard = [];
        \\  for (let i = 0; i < 4096; i++)
        \\    zigHandleDiscard.push({ dead: i, child: { value: i + 1 } });
        \\  const survivor = { tag: 357, nested: { live: true } };
        \\  globalThis.zigHandleKeep = survivor;
        \\  return survivor;
        \\})()
    );
    const handle = try ctx.protectValue(raw);
    const handle_address = @intFromPtr(handle);
    const old_payload = @intFromPtr(raw.asObj());
    _ = try ctx.evaluate("zigHandleDiscard = null; zigHandleKeep = null");

    const moved = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, moved.status);
    try std.testing.expect(moved.moved_cells > 0 and moved.moved_bytes > 0);
    try std.testing.expectEqual(handle_address, @intFromPtr(handle));
    const current = handle.get();
    try std.testing.expect(old_payload != @intFromPtr(current.asObj()));
    try std.testing.expectEqual(@as(f64, 357), current.asObj().getOwn("tag").?.asNum());
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.no_candidates, ctx.compactGarbage().status);
    try std.testing.expect(!foreign.unprotectValue(handle));
    try std.testing.expect(ctx.unprotectValue(handle));
}

test "enable_gc automatic quiescent compaction follows full-GC slab pressure" {
    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
    });
    defer ctx.destroy();
    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);

    _ = try ctx.evaluate(
        \\globalThis.autoCompactDiscard = [];
        \\for (let i = 0; i < 8192; i++)
        \\  autoCompactDiscard.push({ dead: i, child: { value: i + 1 } });
        \\globalThis.autoCompactKeep = { marker: 363, child: { live: true } };
        \\0;
    );
    ctx.collectGarbage();
    const keep_before = @intFromPtr(ctx.global_object.getOwn("autoCompactKeep").?.asObj());
    _ = try ctx.evaluate("autoCompactDiscard = null; 0");
    const backing_before = ctx.gc_cell_backing.?.stats();
    const stats_before = ctx.automaticGcCompactionStats();

    heap.threshold_bytes = 1;
    ctx.collectQuiescentGarbage();

    const stats_after = ctx.automaticGcCompactionStats();
    try std.testing.expectEqual(stats_before.requests + 1, stats_after.requests);
    try std.testing.expectEqual(stats_before.attempts + 1, stats_after.attempts);
    try std.testing.expectEqual(stats_before.compacted + 1, stats_after.compacted);
    try std.testing.expect(stats_after.moved_cells > stats_before.moved_cells);
    try std.testing.expect(stats_after.moved_bytes > stats_before.moved_bytes);
    try std.testing.expect(!ctx.gc_compaction_requested.load(.acquire));
    const keep_after = ctx.global_object.getOwn("autoCompactKeep").?.asObj();
    try std.testing.expect(keep_before != @intFromPtr(keep_after));
    try std.testing.expectEqual(@as(f64, 363), keep_after.getOwn("marker").?.asNum());
    const backing_after = ctx.gc_cell_backing.?.stats();
    try std.testing.expect(backing_after.chunks < backing_before.chunks);
    try std.testing.expect(backing_after.capacity_bytes < backing_before.capacity_bytes);
}

test "automatic compaction concurrent-marker conflict is observable and retryable" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .concurrent_gc = true,
    });
    defer ctx.destroy();
    const heap = ctx.gc.?;

    _ = try ctx.evaluate(
        \\globalThis.concurrentCompactDiscard = [];
        \\for (let i = 0; i < 8192; i++)
        \\  concurrentCompactDiscard.push({ dead: i, child: { value: i + 1 } });
        \\globalThis.concurrentCompactKeep = { marker: 367, child: { live: true } };
        \\0;
    );
    ctx.collectGarbage();
    const handle = try ctx.protectValue(ctx.global_object.getOwn("concurrentCompactKeep").?);
    defer std.debug.assert(ctx.unprotectValue(handle));
    const keep_before = handle.get().asObj();
    _ = try ctx.evaluate("concurrentCompactDiscard = null; 0");
    ctx.collectGarbage();

    const stats_before = ctx.automaticGcCompactionStats();
    try std.testing.expect(ctx.scheduleAutomaticCompactionIfNeeded());
    try std.testing.expect(ctx.gc_auto_compaction_pending.load(.acquire));
    try std.testing.expect(ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expectEqual(stats_before.requests + 1, ctx.automaticGcCompactionStats().requests);

    // This is a real concurrent mark cycle, not a synthetic flag. Movement at
    // an otherwise exact checkpoint must leave every address and request
    // unchanged until the marker closes.
    heap.beginConcurrentMark();
    try std.testing.expect(heap.concurrent.load(.acquire));
    var machine = ctx.interpreter();
    machine.gc_precise_safepoint = true;
    machine.gc_moving_safepoint = true;
    try ctx.pushActiveInterpreter(&machine);
    const blocked = ctx.compactGarbageAtMovingSafepoint(&machine);
    ctx.popActiveInterpreter(&machine);

    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.unsupported, blocked.status);
    const stats_blocked = ctx.automaticGcCompactionStats();
    try std.testing.expectEqual(stats_before.attempts + 1, stats_blocked.attempts);
    try std.testing.expectEqual(stats_before.unsupported + 1, stats_blocked.unsupported);
    try std.testing.expectEqual(keep_before, handle.get().asObj());
    try std.testing.expect(ctx.gc_auto_compaction_pending.load(.acquire));
    try std.testing.expect(ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));

    heap.finishConcurrentMark();
    try std.testing.expect(!heap.concurrent.load(.acquire));
    const retried = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, retried.status);
    try std.testing.expect(retried.moved_cells > 0 and retried.moved_bytes > 0);
    const stats_after = ctx.automaticGcCompactionStats();
    try std.testing.expectEqual(stats_before.attempts + 2, stats_after.attempts);
    try std.testing.expectEqual(stats_before.unsupported + 1, stats_after.unsupported);
    try std.testing.expectEqual(stats_before.compacted + 1, stats_after.compacted);
    try std.testing.expect(keep_before != handle.get().asObj());
    try std.testing.expectEqual(@as(f64, 367), handle.get().asObj().getOwn("marker").?.asNum());
    try std.testing.expect(!ctx.gc_auto_compaction_pending.load(.acquire));
    try std.testing.expect(!ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
}

test "parallel_js moving stop rejects a peer parked outside a moving safepoint" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .enable_jit = false,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    var collector = ctx.interpreter();
    var peer = ctx.interpreter();
    try ctx.pushActiveInterpreter(&collector);
    defer ctx.popActiveInterpreter(&collector);
    try ctx.pushActiveInterpreter(&peer);
    defer ctx.popActiveInterpreter(&peer);

    collector.gc_precise_safepoint = true;
    collector.gc_moving_safepoint = true;
    peer.gc_published_gen.store(79, .release);
    peer.gc_parked.store(true, .release);
    defer peer.gc_parked.store(false, .release);

    try std.testing.expect(!ctx.allCooperativePeersAtMovingSafepoint(79, &collector));
    peer.gc_moving_parked.store(true, .release);
    defer peer.gc_moving_parked.store(false, .release);
    try std.testing.expect(ctx.allCooperativePeersAtMovingSafepoint(79, &collector));
}

test "parallel_js automatic compaction relocates at a shared moving stop" {
    if (builtin.single_threaded or !jit.supported or builtin.cpu.arch != .aarch64)
        return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    ctx.gc_cooperative_tranche_bytes = 1024 * 1024;

    _ = try ctx.evaluate(
        \\var sharedAutoCompactWarmDiscard = [];
        \\for (var dead = 0; dead < 4096; dead = dead + 1)
        \\  sharedAutoCompactWarmDiscard.push({ dead, child: { value: dead + 1 } });
        \\var sharedAutoCompactWitness = { marker: 364, child: { live: true } };
        \\var sharedAutoCompactGate = new Int32Array(new SharedArrayBuffer(4));
        \\function sharedAutoCompactSpin(limit, held) {
        \\  var cursor = 0;
        \\  while (cursor < limit) cursor = cursor + 1;
        \\  return held.marker;
        \\}
        \\sharedAutoCompactWarmDiscard = null;
        \\function sharedAutoCompactLane(lane) {
        \\  var ring = [];
        \\  for (var i = 0; i < 64; i = i + 1)
        \\    ring.push({ value: i, lane: lane, prior: 0 });
        \\  for (var i = 0; i < 12000; i = i + 1) {
        \\    var index = i & 63;
        \\    var old = ring[index];
        \\    ring[index] = { value: old.value + i + lane, lane: lane, prior: old.value };
        \\  }
        \\  Atomics.add(sharedAutoCompactGate, 0, 1);
        \\  while (Atomics.load(sharedAutoCompactGate, 0) !== 3) {}
        \\  return sharedAutoCompactSpin(2000000, sharedAutoCompactWitness) + lane;
        \\}
        \\0;
    );
    _ = try ctx.evaluate(
        \\for (var warm = 0; warm < 10; warm = warm + 1)
        \\  sharedAutoCompactSpin(6, sharedAutoCompactWitness);
    );
    const spin_object = ctx.global_object.getOwn("sharedAutoCompactSpin").?.asObj();
    const spin_function: *interp.Function = @ptrCast(@alignCast(spin_object.jsFunction().?));
    try std.testing.expect(spin_function.chunk != null);

    const handle = try ctx.protectValue(ctx.global_object.getOwn("sharedAutoCompactWitness").?);
    defer std.debug.assert(ctx.unprotectValue(handle));
    const witness_before = @intFromPtr(handle.get().asObj());
    const stats_before = ctx.automaticGcCompactionStats();
    const moving_before = ctx.gc_moving_safepoint_compactions.load(.monotonic);

    const result = try ctx.evaluate(
        \\var sharedAutoCompactFirst = new Thread(sharedAutoCompactLane, 1);
        \\var sharedAutoCompactSecond = new Thread(sharedAutoCompactLane, 2);
        \\var sharedAutoCompactMain = sharedAutoCompactLane(3);
        \\sharedAutoCompactMain + sharedAutoCompactFirst.join() + sharedAutoCompactSecond.join();
    );
    try std.testing.expect(result.isNumber());

    const stats_after = ctx.automaticGcCompactionStats();
    try std.testing.expect(stats_after.requests > stats_before.requests);
    try std.testing.expect(stats_after.attempts > stats_before.attempts);
    try std.testing.expect(stats_after.shared_attempts > stats_before.shared_attempts);
    try std.testing.expect(stats_after.compacted > stats_before.compacted);
    try std.testing.expect(stats_after.moved_cells > stats_before.moved_cells);
    try std.testing.expect(stats_after.moved_bytes > stats_before.moved_bytes);
    try std.testing.expect(stats_after.shared_rendezvous_ns_total > stats_before.shared_rendezvous_ns_total);
    try std.testing.expect(stats_after.shared_rendezvous_ns_max > stats_before.shared_rendezvous_ns_max);
    try std.testing.expect(stats_after.shared_pause_ns_total > stats_before.shared_pause_ns_total);
    try std.testing.expect(stats_after.shared_pause_ns_max > stats_before.shared_pause_ns_max);
    try std.testing.expect(ctx.gc_moving_safepoint_compactions.load(.monotonic) > moving_before);
    try std.testing.expect(!ctx.gc_auto_compaction_pending.load(.acquire));
    try std.testing.expect(!ctx.gc_compaction_requested.load(.acquire));
    try std.testing.expect(witness_before != @intFromPtr(handle.get().asObj()));
    try std.testing.expectEqual(@as(f64, 364), handle.get().asObj().getOwn("marker").?.asNum());
    try std.testing.expectEqual(@as(u64, 0), ctx.gc_par_request.load(.acquire));
    try std.testing.expectEqual(@as(?*interp.Interpreter, null), ctx.gc_par_collector.load(.acquire));
}

test "enable_gc nursery: quick object replacement keeps exact-managed children" {
    const old_parallel = bc.ic_seqlock_enabled.load(.monotonic);
    defer bc.ic_seqlock_enabled.store(old_parallel, .monotonic);
    bc.ic_seqlock_enabled.store(false, .monotonic);

    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();

    _ = try ctx.evaluate(
        \\var items = [
        \\  { seed: 1, mark: 0, prior: 0 }, { seed: 2, mark: 0, prior: 0 },
        \\  { seed: 3, mark: 0, prior: 0 }, { seed: 4, mark: 0, prior: 0 },
        \\  { seed: 5, mark: 0, prior: 0 }, { seed: 6, mark: 0, prior: 0 },
        \\  { seed: 7, mark: 0, prior: 0 }, { seed: 8, mark: 0, prior: 0 }
        \\];
    );
    ctx.collectGarbage();
    const heap = ctx.gc.?;
    heap.nursery_threshold_bytes = 1;
    const minor_before = heap.minor_collections;
    const hits_before = vm.quickObjectAllocationLoopHitsForTesting();

    const result = try ctx.evaluate(
        \\function allocate(items, limit, extra) {
        \\  var total = 0;
        \\  var cursor = 0;
        \\  while (cursor < limit) {
        \\    var selected = cursor & 7;
        \\    var old = items[selected];
        \\    var next = (old.seed + cursor + extra) % 1009;
        \\    var replacement = { seed: next, mark: cursor & 3, prior: old.seed };
        \\    items[selected] = replacement;
        \\    total = total + ((replacement.seed + replacement.mark + replacement.prior) & 31);
        \\    cursor = cursor + 1;
        \\  }
        \\  return total;
        \\}
        \\allocate(items, 4096, 2)
    );

    var seeds = [_]i32{ 1, 2, 3, 4, 5, 6, 7, 8 };
    var expected: i32 = 0;
    for (0..4096) |cursor| {
        const selected = cursor & 7;
        const old = seeds[selected];
        const next = @mod(old + @as(i32, @intCast(cursor)) + 2, 1009);
        expected += (next + @as(i32, @intCast(cursor & 3)) + old) & 31;
        seeds[selected] = next;
    }
    try std.testing.expectEqual(@as(f64, @floatFromInt(expected)), result.asNum());
    try std.testing.expect(vm.quickObjectAllocationLoopHitsForTesting() > hits_before);
    try std.testing.expect(heap.minor_collections > minor_before);

    heap.collectYoung();
    const retained = try ctx.evaluate("items[0].seed + items[7].seed");
    try std.testing.expectEqual(@as(f64, @floatFromInt(seeds[0] + seeds[7])), retained.asNum());
}

test "quick object replacement checks a restricted receiver before fused mutation" {
    const old_parallel = bc.ic_seqlock_enabled.load(.monotonic);
    defer bc.ic_seqlock_enabled.store(old_parallel, .monotonic);
    bc.ic_seqlock_enabled.store(false, .monotonic);

    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();

    _ = try ctx.evaluate(
        \\function allocate(items, limit) {
        \\  var total = 0;
        \\  var cursor = 0;
        \\  while (cursor < limit) {
        \\    var selected = cursor & 7;
        \\    var old = items[selected];
        \\    var next = (old.seed + cursor + 2) % 1009;
        \\    var replacement = { seed: next, mark: cursor & 3, prior: old.seed };
        \\    items[selected] = replacement;
        \\    total = total + ((replacement.seed + replacement.mark + replacement.prior) & 31);
        \\    cursor = cursor + 1;
        \\  }
        \\  return total;
        \\}
        \\var items = [
        \\  { seed: 1, mark: 0, prior: 0 }, { seed: 2, mark: 0, prior: 0 },
        \\  { seed: 3, mark: 0, prior: 0 }, { seed: 4, mark: 0, prior: 0 },
        \\  { seed: 5, mark: 0, prior: 0 }, { seed: 6, mark: 0, prior: 0 },
        \\  { seed: 7, mark: 0, prior: 0 }, { seed: 8, mark: 0, prior: 0 }
        \\];
        \\allocate(items, 96);
    );
    const items = ctx.global_object.getOwn("items").?.asObj();
    const first_before = items.elementAt(0).?.asObj();
    const current: u64 = @intCast(std.Thread.getCurrentId());
    try std.testing.expect(items.coldState() == null);
    try std.testing.expect(first_before.storageState() == null); // three-property literal stays wrapper-free
    try std.testing.expect(first_before.coldState() == null); // three-property literal stays common-layout-only
    try std.testing.expect(first_before.slotsState() == null);
    try std.testing.expect(first_before.elementsState() == null);
    var restricted_cold = value.ObjectColdState{};
    const items_storage = items.storageState().?;
    items_storage.cold.store(&restricted_cold, .release);
    defer items_storage.cold.store(null, .release);
    restricted_cold.restricted_to.store(if (current == std.math.maxInt(u64)) current - 1 else current + 1, .release);

    for ([_]bool{ false, true }) |parallel| {
        bc.ic_seqlock_enabled.store(parallel, .monotonic);
        // A zero-iteration loop never performs an internal method on the receiver.
        try std.testing.expectEqual(@as(f64, 0), (try ctx.evaluate("allocate(items, 0)")).asNum());
        const hits_before = vm.quickObjectAllocationLoopHitsForTesting();
        try std.testing.expect((try ctx.evaluate(
            \\var restrictedCaught = false;
            \\try { allocate(items, 1); }
            \\catch (error) { restrictedCaught = true; }
            \\restrictedCaught;
        )).asBool());
        try std.testing.expectEqual(first_before, items.elementAt(0).?.asObj());
        try std.testing.expectEqual(hits_before, vm.quickObjectAllocationLoopHitsForTesting());
    }
}

test "enable_gc: collectGarbage reclaims unreachable objects, keeps reachable" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();

    // Create a large throwaway graph (unreachable after the statement) plus one
    // object retained on globalThis.
    _ = try ctx.evaluate(
        \\globalThis.keep = { kept: 1, nested: { deep: [1, 2, 3] } };
        \\for (let i = 0; i < 500; i++) { const tmp = { a: i, b: [i, i + 1, i + 2] }; }
        \\0
    );
    const before = ctx.gc.?.live_cells;

    // Quiescent collection (no JS running): the 500 temporaries and their arrays
    // are unreachable from the Context roots and are reclaimed; the retained
    // graph survives.
    ctx.collectGarbage();
    const after = ctx.gc.?.live_cells;
    try std.testing.expect(after < before); // real reclamation happened
    try std.testing.expect(ctx.gc.?.collections >= 1);

    // The retained object is intact and usable after collection.
    const r = try ctx.evaluate("globalThis.keep.kept + globalThis.keep.nested.deep[2]");
    try std.testing.expectEqual(@as(f64, 4), r.asNum()); // 1 + 3
}

test "enable_gc: persistent bytecode string constants survive collection" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();

    _ = try ctx.evaluate(
        \\globalThis.persistentBytecodeLiteral = function persistentBytecodeLiteral(depth) {
        \\  "use strict";
        \\  if (depth === 0) return "en-US";
        \\  return persistentBytecodeLiteral(depth - 1);
        \\};
    );
    const function_value = ctx.global_object.getOwn("persistentBytecodeLiteral") orelse
        return error.TestUnexpectedResult;
    const function = interp.Interpreter.funcOf(function_value) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(function.chunk != null);

    // The Function is globally reachable while its compiled string literal is
    // reachable only through the arena-owned Chunk. Reclaim first, then churn
    // StringCell storage so a missing chunk edge cannot pass by stale-address
    // luck before the function runs again.
    ctx.collectGarbage();
    _ = try ctx.evaluate(
        \\for (let i = 0; i < 2000; ++i) globalThis.bytecodeGcChurn = "replacement-" + i;
    );
    try std.testing.expectEqualStrings(
        "en-US",
        (try ctx.evaluate("persistentBytecodeLiteral(4)")).asStr(),
    );
}

test "enable_gc nursery: quiescent minor collection reclaims young garbage" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();
    ctx.collectGarbage(); // tenure bootstrap roots and establish the full threshold

    const heap = ctx.gc.?;
    heap.nursery_threshold_bytes = 1;
    const full_before = heap.full_collections;
    const minor_before = heap.minor_collections;
    _ = try ctx.evaluate(
        \\(function () {
        \\  for (let i = 0; i < 32; i++) ({ index: i, nested: { value: i } });
        \\})()
    );
    try std.testing.expect(heap.young_cells > 0);

    ctx.collectQuiescentGarbage();
    try std.testing.expectEqual(@as(usize, 0), heap.young_cells);
    try std.testing.expectEqual(minor_before + 1, heap.minor_collections);
    try std.testing.expectEqual(full_before, heap.full_collections);
}

test "enable_gc: quiescent promotion debt reclaims a transient tenured burst" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    const debt_target = @max(
        Context.GcHeap.min_nursery_threshold_bytes,
        ctx.gc_state.?.quiescent_full_live_bytes,
    );
    const saved = gc_mod.setActiveContext(ctx);
    defer gc_mod.restoreActiveContext(saved);

    var head = ctx.global_object;
    while (heap.young_bytes < debt_target) {
        const object = try heap.create(value.Object, .object);
        object.* = .{ .proto = head };
        object.initInlineSlots();
        head = object;
    }
    const handle = try ctx.protectValue(Value.obj(head));
    var protected = true;
    defer if (protected) std.debug.assert(ctx.unprotectValue(handle));

    for (0..runtime_gc_tenuring_age) |_| heap.collectYoung();
    try std.testing.expect(heap.total_minor_promoted_bytes -| ctx.gc_state.?.quiescent_full_promoted_bytes >= debt_target);
    try std.testing.expectEqual(@as(usize, 0), heap.young_bytes);

    std.debug.assert(ctx.unprotectValue(handle));
    protected = false;
    heap.threshold_bytes = std.math.maxInt(usize);
    const full_before = heap.full_collections;
    const live_before = heap.live_cells;
    ctx.collectQuiescentGarbage();
    try std.testing.expect(heap.full_collections > full_before);
    try std.testing.expect(heap.live_cells < live_before);
    try std.testing.expectEqual(heap.total_minor_promoted_bytes, ctx.gc_state.?.quiescent_full_promoted_bytes);
    try std.testing.expectEqual(heap.bytes_live, ctx.gc_state.?.quiescent_full_live_bytes);
}

test "moving nursery rewrites persistent roots across staggered age promotion" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    heap.nursery_threshold_bytes = std.math.maxInt(usize);
    const moving_before = heap.accounting().moving_minor_collections;
    _ = try ctx.evaluate("globalThis.movingParent = { marker: 40 };");
    const parent_handle = try ctx.protectValue(ctx.global_object.getOwn("movingParent").?);
    defer std.debug.assert(ctx.unprotectValue(parent_handle));
    const first_parent = parent_handle.get().asObj();
    const parent_id = heap.cellMetadata(first_parent).?.id;
    var c_handle_value = Value.obj(first_parent);
    try ctx.reserveCApiHandlesLocked(1);
    ctx.c_api_handles.appendAssumeCapacity(.{ .ref = &c_handle_value, .count = 1 });
    defer ctx.c_api_handles.clearRetainingCapacity();

    const first = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, first.status);
    const second_parent = parent_handle.get().asObj();
    try std.testing.expect(first_parent != second_parent);
    try std.testing.expectEqual(parent_id, heap.cellMetadata(second_parent).?.id);
    try std.testing.expectEqual(second_parent, c_handle_value.asObj());

    _ = try ctx.evaluate(
        \\movingParent.child = { marker: 2 };
        \\globalThis.movingWeak = new WeakRef(movingParent.child);
    );
    const first_child = parent_handle.get().asObj().getOwn("child").?.asObj();
    const child_id = heap.cellMetadata(first_child).?.id;
    var private_weak = Context.PrivateWeakRoot{};
    private_weak.target.store(first_child, .release);
    try ctx.private_weak_roots.append(ctx.gpa, &private_weak);
    defer ctx.private_weak_roots.clearRetainingCapacity();

    const second = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, second.status);
    const third_parent = parent_handle.get().asObj();
    const second_child = third_parent.getOwn("child").?.asObj();
    try std.testing.expect(second_parent != third_parent);
    try std.testing.expect(first_child != second_child);
    try std.testing.expectEqual(child_id, heap.cellMetadata(second_child).?.id);
    try std.testing.expectEqual(@as(?*anyopaque, second_child), private_weak.target.load(.acquire));
    try std.testing.expectEqual(third_parent, c_handle_value.asObj());

    const third = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, third.status);
    const promoted_parent = parent_handle.get().asObj();
    const third_child = promoted_parent.getOwn("child").?.asObj();
    try std.testing.expect(third_parent != promoted_parent);
    try std.testing.expect(second_child != third_child);
    try std.testing.expectEqual(parent_id, heap.cellMetadata(promoted_parent).?.id);
    try std.testing.expectEqual(child_id, heap.cellMetadata(third_child).?.id);
    try std.testing.expectEqual(promoted_parent, c_handle_value.asObj());

    // The parent promoted one cycle before the child. Its promotion-created
    // remembered card is now the child's only strong old-generation frontier.
    const fourth = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, fourth.status);
    const promoted_child = parent_handle.get().asObj().getOwn("child").?.asObj();
    try std.testing.expect(third_child != promoted_child);
    try std.testing.expectEqual(child_id, heap.cellMetadata(promoted_child).?.id);
    try std.testing.expectEqual(@as(?*anyopaque, promoted_child), private_weak.target.load(.acquire));
    try std.testing.expectEqual(parent_handle.get().asObj(), c_handle_value.asObj());
    try std.testing.expect((try ctx.evaluate(
        "movingWeak.deref() === movingParent.child && movingParent.marker + movingParent.child.marker === 42",
    )).asBool());

    const accounting = heap.accounting();
    try std.testing.expectEqual(moving_before + 4, accounting.moving_minor_collections);
    try std.testing.expect(accounting.total_minor_moved_cells > 4);
    try std.testing.expect(accounting.total_minor_moved_bytes > 0);
    try std.testing.expectEqual(@as(usize, 0), accounting.minor_move_failures);
    try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
}

test "moving nursery preserves seeded Map and Set indexes for object and Symbol keys" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    heap.nursery_threshold_bytes = std.math.maxInt(usize);
    const count = 1024;
    const expected: f64 = count * count;
    const setup = try ctx.evaluate(
        \\globalThis.__indexedKeys = [];
        \\globalThis.__indexedMap = new Map();
        \\globalThis.__indexedSet = new Set();
        \\for (let i = 0; i < 1024; i++) {
        \\  const objectKey = { i };
        \\  const symbolKey = Symbol("k" + i);
        \\  __indexedKeys.push(objectKey, symbolKey);
        \\  __indexedMap.set(objectKey, i);
        \\  __indexedMap.set(symbolKey, i + 1);
        \\  __indexedSet.add(objectKey);
        \\  __indexedSet.add(symbolKey);
        \\}
        \\__indexedMap.size + __indexedSet.size
    );
    try std.testing.expectEqual(@as(f64, 4 * count), setup.asNum());

    const map_before = ctx.global_object.getOwn("__indexedMap").?.asObj();
    const set_before = ctx.global_object.getOwn("__indexedSet").?.asObj();
    const map_state = map_before.collectionState().?;
    const set_state = set_before.collectionState().?;
    try std.testing.expect(!map_state.coll_unindexed);
    try std.testing.expect(!set_state.coll_unindexed);
    try std.testing.expectEqual(@as(usize, 2 * count), map_state.coll_next.items.len);
    try std.testing.expectEqual(@as(usize, 2 * count), set_state.coll_next.items.len);

    const moved = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, moved.status);
    const map_after = ctx.global_object.getOwn("__indexedMap").?.asObj();
    const set_after = ctx.global_object.getOwn("__indexedSet").?.asObj();
    try std.testing.expect(map_before != map_after);
    try std.testing.expect(set_before != set_after);
    try std.testing.expectEqual(map_state, map_after.collectionState().?);
    try std.testing.expectEqual(set_state, set_after.collectionState().?);

    interp.resetCollectionKeyComparisonsForTesting();
    const checksum = try ctx.evaluate(
        \\let total = 0;
        \\for (let i = 0; i < __indexedKeys.length; i++) {
        \\  const key = __indexedKeys[i];
        \\  if (!__indexedSet.has(key)) throw new Error("moving Set index lost a key");
        \\  total += __indexedMap.get(key);
        \\}
        \\total
    );
    try std.testing.expectEqual(expected, checksum.asNum());
    // Successful lookups need at least one exact check each. Allow one extra
    // check per operation for a legitimate seeded-hash collision while still
    // bounding growth linearly; the former object/Symbol path scanned ordered
    // prefixes and performs millions of checks at this size.
    const comparisons = interp.collectionKeyComparisonsForTesting();
    try std.testing.expect(comparisons >= 4 * count);
    try std.testing.expect(comparisons <= 8 * count);
    try std.testing.expect(!map_after.collUnindexed());
    try std.testing.expect(!set_after.collUnindexed());
}

test "moving nursery rewrites strings held only by suspended captured VM frames" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .bytecode_execution_mode = .required,
    });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    heap.nursery_threshold_bytes = std.math.maxInt(usize);
    _ = try ctx.evaluate(
        \\function captureFrameValue(value) {
        \\  return function readCapturedFrameValue() { return value; };
        \\}
        \\for (let i = 0; i < 12; i++)
        \\  globalThis.movingCapturedFrame = captureFrameValue("captured-" + i);
    );

    const closure_value = ctx.global_object.getOwn("movingCapturedFrame") orelse
        return error.TestUnexpectedResult;
    const closure = interp.Interpreter.funcOf(closure_value) orelse
        return error.TestUnexpectedResult;
    const frame: *vm.Frame = if (closure.frame) |raw|
        @ptrCast(@alignCast(raw))
    else
        return error.TestUnexpectedResult;
    var captured_slot: ?usize = null;
    for (frame.slots, 0..) |slot, index| {
        if (slot.isString() and slot.asStringCell().isGcManaged()) {
            captured_slot = index;
            break;
        }
    }
    const slot_index = captured_slot orelse return error.TestUnexpectedResult;
    const original_string = frame.slots[slot_index].asStringCell();
    const stable_id = heap.cellMetadata(@constCast(original_string)).?.id;
    try std.testing.expect(!original_string.hasCachedContentHash());

    // The closure Function is the only owner of this arena frame while it is
    // suspended. Moving the string must therefore rewrite the Function.frame
    // edge before the old payload/header is released.
    const first = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, first.status);
    const first_string = frame.slots[slot_index].asStringCell();
    try std.testing.expect(original_string != first_string);
    try std.testing.expectEqual(stable_id, heap.cellMetadata(@constCast(first_string)).?.id);
    try std.testing.expect(!first_string.hasCachedContentHash());
    try std.testing.expect(first_string.eql(strcell.staticCell("captured-11")));
    try std.testing.expect(first_string.hasCachedContentHash());
    try std.testing.expectEqualStrings(
        "captured-11",
        (try ctx.evaluate("movingCapturedFrame()")).asStr(),
    );

    // Re-entering the closure makes the captured frame an active VM ancestor.
    // A second moving collection used to encounter the stale first address and
    // fail the strict GC-header check from the shared/JIT benchmark path.
    const second = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, second.status);
    const second_string = frame.slots[slot_index].asStringCell();
    try std.testing.expect(first_string != second_string);
    try std.testing.expectEqual(stable_id, heap.cellMetadata(@constCast(second_string)).?.id);
    try std.testing.expect(second_string.hasCachedContentHash());
    try std.testing.expect(second_string.eql(strcell.staticCell("captured-11")));
    try std.testing.expectEqualStrings(
        "captured-11",
        (try ctx.evaluate("movingCapturedFrame()")).asStr(),
    );
}

test "moving nursery preserves live ephemerons and clears weak finalization state" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    heap.nursery_threshold_bytes = std.math.maxInt(usize);
    _ = try ctx.evaluate(
        \\globalThis.movingWeakMap = new WeakMap();
        \\globalThis.movingCleanup = [];
        \\globalThis.movingRegistry = new FinalizationRegistry(
        \\  held => movingCleanup.push(held)
        \\);
        \\globalThis.movingKey = { marker: 40 };
        \\globalThis.movingValue = { marker: 2 };
        \\movingWeakMap.set(movingKey, movingValue);
        \\globalThis.movingValueRef = new WeakRef(movingValue);
        \\globalThis.movingDeadRef = new WeakRef({ marker: 99 });
        \\movingRegistry.register({}, 7);
        \\movingValue = undefined;
    );

    const first = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, first.status);
    _ = try ctx.evaluate("$drainFinalizationCleanup()");
    try std.testing.expect((try ctx.evaluate(
        "movingWeakMap.get(movingKey).marker === 2",
    )).asBool());
    try std.testing.expect((try ctx.evaluate(
        "movingValueRef.deref().marker === 2",
    )).asBool());
    try std.testing.expect((try ctx.evaluate(
        "movingDeadRef.deref() === undefined",
    )).asBool());
    try std.testing.expect((try ctx.evaluate(
        "movingCleanup.length === 1 && movingCleanup[0] === 7",
    )).asBool());

    _ = try ctx.evaluate("movingKey = undefined");
    const second = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, second.status);
    try std.testing.expect((try ctx.evaluate(
        "movingValueRef.deref() === undefined",
    )).asBool());
    try std.testing.expectEqual(@as(usize, 0), heap.accounting().minor_move_failures);
}

test "moving nursery pins a conservative checkpoint and moves at an exact checkpoint" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    _ = try ctx.evaluate("globalThis.movingCheckpointRoot = { marker: 42 };");
    const handle = try ctx.protectValue(ctx.global_object.getOwn("movingCheckpointRoot").?);
    defer std.debug.assert(ctx.unprotectValue(handle));
    const original = handle.get().asObj();
    const stable_id = heap.cellMetadata(original).?.id;

    var machine = ctx.interpreter();
    try ctx.pushActiveInterpreter(&machine);
    defer ctx.popActiveInterpreter(&machine);
    heap.nursery_threshold_bytes = 1;
    const moving_before = heap.accounting().moving_minor_collections;
    try std.testing.expect(ctx.collectYoungMidScriptIfNeeded(heap, &machine));
    try std.testing.expectEqual(original, handle.get().asObj());
    try std.testing.expectEqual(moving_before, heap.accounting().moving_minor_collections);

    heap.nursery_threshold_bytes = 1;
    machine.gc_precise_safepoint = true;
    machine.gc_moving_safepoint = true;
    try std.testing.expect(ctx.collectYoungMidScriptIfNeeded(heap, &machine));
    const moved = handle.get().asObj();
    try std.testing.expect(original != moved);
    try std.testing.expectEqual(stable_id, heap.cellMetadata(moved).?.id);
    try std.testing.expectEqual(moving_before + 1, heap.accounting().moving_minor_collections);
    try std.testing.expectEqual(@as(f64, 42), moved.getOwn("marker").?.asNum());
}

test "moving nursery scratch OOM preserves survivor addresses and stable identities" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    heap.nursery_threshold_bytes = std.math.maxInt(usize);
    _ = try ctx.evaluate(
        "globalThis.movingOomRoot = { child: { marker: 42 } };",
    );
    const root_before = ctx.global_object.getOwn("movingOomRoot").?.asObj();
    const child_before = root_before.getOwn("child").?.asObj();
    const root_id = heap.cellMetadata(root_before).?.id;
    const child_id = heap.cellMetadata(child_before).?.id;
    const failures_before = heap.accounting().minor_move_failures;

    var no_scratch: [1]u8 = undefined;
    var fixed = std.heap.FixedBufferAllocator.init(&no_scratch);
    const saved_aux = heap.aux;
    heap.aux = fixed.allocator();
    const result = ctx.collectYoungAfterRootValidation(heap);
    heap.aux = saved_aux;

    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.out_of_memory, result.status);
    const root_after = ctx.global_object.getOwn("movingOomRoot").?.asObj();
    const child_after = root_after.getOwn("child").?.asObj();
    try std.testing.expectEqual(root_before, root_after);
    try std.testing.expectEqual(child_before, child_after);
    try std.testing.expectEqual(root_id, heap.cellMetadata(root_after).?.id);
    try std.testing.expectEqual(child_id, heap.cellMetadata(child_after).?.id);
    try std.testing.expectEqual(failures_before + 1, heap.accounting().minor_move_failures);
    try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
}

