test "for(let) per-iteration binding: reuse fast path preserves closure-capture semantics" {
    // Perf (#2 GC maturity): a `for (let …)` loop reuses one per-iteration
    // environment across iterations when nothing captures it (removing the
    // per-iteration GC-cell allocation — ~3× on a tree-walked tight loop), but
    // must still give each iteration a fresh binding when a closure captures it.
    // The `arguments` reference forces the tree-walker (where the per-iteration
    // env lives; the VM uses a reused frame slot). Guards the correctness of the
    // `Environment.captured` reuse decision.
    const ctx = try Context.createWith(std.testing.allocator, .{});
    defer ctx.destroy();
    const v = try ctx.evaluate(
        \\function run() {
        \\  var _tw = arguments.length; // force the tree-walker
        \\  var caps = [];
        \\  for (let i = 0; i < 5; i++) caps.push(function(){ return i; }); // captured: distinct per iter
        \\  var captured = caps.map(function(f){ return f(); }).join(",");
        \\  var sum = 0;
        \\  for (let j = 0; j < 1000; j++) sum += j; // uncaptured: reuse fast path
        \\  var fromInit;
        \\  for (let head = (fromInit = function(){ return head; }, 7); head < 8; head++) {} // captured initializer: copy before condition
        \\  var nested = [];
        \\  for (let k = 0; k < 3; k++) { { nested.push(() => k); } } // capture through a nested block
        \\  return captured + "|" + sum + "|" + fromInit() + "|" + nested.map(g => g()).join(",");
        \\}
        \\run();
    );
    try std.testing.expect(v.isString());
    try std.testing.expectEqualStrings("0,1,2,3,4|499500|7|0,1,2", v.asStr());
}

test "for-of/for-in per-iteration binding: reuse fast path preserves closure-capture semantics" {
    // Perf (#2): the same per-iteration-env reuse extended to `for-of`/`for-in`.
    // These restore `self.env` to the outer scope each iteration, so a reused env
    // is rooted in `gc_env_roots` to survive a mid-iteration collection; once an
    // iteration's env is captured the loop stops reusing it so the captured
    // binding keeps its value. `arguments` forces the tree-walker.
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();
    const v = try ctx.evaluate(
        \\function run() {
        \\  var _tw = arguments.length; // force the tree-walker
        \\  var a = []; for (let x of [10, 20, 30]) a.push(() => x);          // let capture: distinct
        \\  var b = []; for (const y of [1, 2, 3]) b.push(() => y);           // const capture: distinct
        \\  var s = 0; for (const z of [1, 2, 3, 4, 5]) s += z;               // uncaptured: reuse fast path
        \\  var o = { p: 1, q: 2, r: 3 }; var k = []; for (let key in o) k.push(() => key); // for-in capture
        \\  var m = []; for (let i of [0, 1, 2, 3]) { if (i % 2 === 0) m.push(() => i); }    // mixed capture
        \\  return a.map(f=>f()).join(",") + "|" + b.map(f=>f()).join(",") + "|" + s + "|" +
        \\         k.map(f=>f()).sort().join(",") + "|" + m.map(f=>f()).join(",");
        \\}
        \\run();
    );
    try std.testing.expect(v.isString());
    try std.testing.expectEqualStrings("10,20,30|1,2,3|15|p,q,r|0,2", v.asStr());
}

test "block scope: no env allocated when a block binds nothing at its own scope" {
    // Perf (#2): `evalBlockScope` skips the per-entry env allocation for a block
    // that declares no block-scoped binding (only `var`/expressions/nested
    // constructs), running its statements in the current scope — common in hot
    // loop bodies. `let`/`const`/`class`/block-functions/`using` still get their
    // own env. This checks the fast path stays observationally identical:
    // var-hoisting, let shadowing, block-scoped functions, TDZ, and closure
    // capture of a block `let` all remain correct. `arguments` forces the
    // tree-walker (where block envs live).
    const ctx = try Context.createWith(std.testing.allocator, .{});
    defer ctx.destroy();
    const v = try ctx.evaluate(
        \\function run() {
        \\  var _tw = arguments.length; // force the tree-walker
        \\  var out = [];
        \\  var x = 1; { var y = 2; out.push(x + y); }               // fast path; var hoists -> 3
        \\  out.push(typeof y);                                       // "number" (y visible outside block)
        \\  let a = 10; { let a = 20; out.push(a); } out.push(a);     // slow path; shadow -> 20, 10
        \\  { function f() { return 42; } out.push(f()); }            // block-scoped function -> 42
        \\  let fns = []; { let z = 99; fns.push(() => z); } out.push(fns[0]()); // capture -> 99
        \\  let s = 0; for (let i = 0; i < 100; i++) { s += i; } out.push(s);    // fast-path body -> 4950
        \\  return out.join(",");
        \\}
        \\run();
    );
    try std.testing.expect(v.isString());
    try std.testing.expectEqualStrings("3,number,20,10,42,99,4950", v.asStr());
}

test "block scope: uncaptured lexical environments reuse bounded owned storage" {
    // #634: a fresh block Environment is semantically observable only when a
    // closure captures it. Keep uncaptured repeated blocks allocation-bounded,
    // but retain distinct cells for captured entries. The explicit gc() request
    // sits between two reusable blocks; gc.zig's root-container test directly
    // witnesses moving relocation of the cached pointer.
    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .profile_execution_tiers = true,
    });
    defer ctx.destroy();
    const allocations_before = ctx.tierAttributionSnapshot().execution.count(.environment_allocations);
    const result = try ctx.evaluate(
        \\function run() {
        \\  var _tw = arguments.length;
        \\  var sum = 0;
        \\  for (let i = 0; i < 2000; ++i) { let x = i; const y = x + 1; sum += y; }
        \\  { let beforeMove = 7; sum += beforeMove; }
        \\  gc();
        \\  { let afterMove = 11; sum += afterMove; }
        \\  var captured = [];
        \\  for (let i = 0; i < 3; ++i) { let x = i; captured.push(() => x); }
        \\  return sum + "|" + captured.map(f => f()).join(",");
        \\}
        \\run();
    );
    try std.testing.expect(result.isString());
    try std.testing.expectEqualStrings("2001018|0,1,2", result.asStr());
    const allocations_after = ctx.tierAttributionSnapshot().execution.count(.environment_allocations);
    // Without reuse the first loop alone allocates 2,000 block environments.
    // Captured iterations deliberately retain distinct cells, so use a generous
    // constant ceiling rather than coupling the witness to bootstrap details.
    try std.testing.expect(allocations_after - allocations_before < 64);
}

test "function calls: completed private activations reuse bounded owned storage" {
    // #653: a completed tree-walker call activation is observable only through
    // a closure or mapped arguments object. Reuse the uncaptured hot-call cell,
    // while retaining distinct bindings for both observable controls. The
    // try/finally keeps `hot` on the tree walker without allocating arguments.
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .profile_execution_tiers = true,
        .bytecode_execution_mode = .tree_walker,
    });
    defer ctx.destroy();
    const allocations_before = ctx.tierAttributionSnapshot().execution.count(.environment_allocations);
    const result = try ctx.evaluate(
        \\function hot(i) { try { return (i * 7 + 13) & 255; } finally {} }
        \\var sum = 0;
        \\for (var i = 0; i < 2000; ++i) sum += hot(i);
        \\function mapped(x) { return arguments; }
        \\var firstArgs = mapped(3), secondArgs = mapped(7);
        \\function capture(x) { return () => x; }
        \\var firstClosure = capture(5), secondClosure = capture(9);
        \\sum + "|" + firstArgs[0] + "," + secondArgs[0] + "|" + firstClosure() + "," + secondClosure();
    );
    try std.testing.expect(result.isString());
    try std.testing.expectEqualStrings("254136|3,7|5,9", result.asStr());
    const snapshot = ctx.tierAttributionSnapshot();
    try std.testing.expect(snapshot.execution.count(.tree_walker_entries) > 2000);
    const allocations_after = snapshot.execution.count(.environment_allocations);
    // The 2,000 uncaptured calls share one completed activation. Captured and
    // mapped-arguments controls deliberately retain their own cells.
    try std.testing.expect(allocations_after - allocations_before < 32);
}

test "catch scope: optional catch binding skips the catch-scope env, params still bind" {
    // Perf (allocation-elision family): `evalTry` allocates a dedicated catch
    // environment only when a catch parameter is present. An ES2019 optional
    // catch binding (`catch { ... }`) binds nothing, so the env is elided and
    // the catch block runs in the enclosing scope — its own lexical decls still
    // get an isolated block scope, so nothing leaks. This checks the elided path
    // and the retained param/destructuring paths stay observationally identical.
    // `arguments` forces the tree-walker (where catch envs live).
    const ctx = try Context.createWith(std.testing.allocator, .{});
    defer ctx.destroy();
    const v = try ctx.evaluate(
        \\function run() {
        \\  var _tw = arguments.length; // force the tree-walker
        \\  var out = [];
        \\  try { throw 1; } catch { out.push("bind-less"); }          // elided env
        \\  let leak = "outer";
        \\  try { throw 2; } catch { let leak = "inner"; out.push(leak); } // block scope isolates
        \\  out.push(leak);                                             // outer let untouched -> "outer"
        \\  try { throw 7; } catch (e) { out.push(e * 2); }            // param still binds -> 14
        \\  try { throw { a: 3, b: 4 }; } catch ({ a, b }) { out.push(a + b); } // destructuring -> 7
        \\  let cap; try { throw 9; } catch { let z = 99; cap = () => z; } out.push(cap()); // capture in bind-less catch
        \\  return out.join(",");
        \\}
        \\run();
    );
    try std.testing.expect(v.isString());
    try std.testing.expectEqualStrings("bind-less,inner,outer,14,7,99", v.asStr());
}

test "vm trampoline: deep VM recursion is heap-bounded, lifting past the native stack" {
    // A simple recursive VM-compiled function (no try/catch in the body, so the
    // compiler keeps it on the bytecode VM) recurses far past the native-stack
    // ceiling: runDriver pushes each JS→JS call onto an explicit heap activation
    // stack instead of the OS stack, so depth is bounded by max_call_depth /
    // heap, not the thread stack. The program-scope try/catch catches the
    // eventual RangeError; the global counter records the depth reached. On an
    // 8 MiB thread a purely native path caps in the hundreds; the trampoline
    // reaches into the thousands (toward the 16384 logical ceiling).
    if (builtin.single_threaded) return error.SkipZigTest;
    const Runner = struct {
        result: f64 = -1,
        ok: bool = false,
        fn run(self: *@This()) void {
            const ctx = Context.createWith(std.testing.allocator, .{}) catch return;
            defer ctx.destroy();
            // VM-compilable (ternary/arith/recursion only — no try/catch, let, or
            // global store, which fall back to the tree-walker). r(8000) recurses
            // 8000 deep and returns 0. On an 8 MiB thread a native VM path
            // RangeErrors well before 8000; the trampoline pushes each JS→JS call
            // onto the heap activation stack, reaching 8000 (< the 16384 cap).
            const v = ctx.evaluate(
                \\function r(n) { return n <= 0 ? 0 : r(n - 1); }
                \\r(8000)
            ) catch return; // a native RangeError would leave ok=false → test fails
            if (v.isNumber()) {
                self.result = v.asNum();
                self.ok = true;
            }
        }
    };
    var r = Runner{};
    const t = try std.Thread.spawn(.{ .stack_size = 8 << 20 }, Runner.run, .{&r});
    t.join();
    try std.testing.expect(r.ok); // reached depth 8000 without a native RangeError
    try std.testing.expectEqual(@as(f64, 0), r.result);
}

test "vm trampoline: safe sloppy functions can use heap-bounded recursion" {
    // A tree-walked script (because of the top-level catch) can still create a
    // simple named self-recursive sloppy function whose body is safe for
    // per-function bytecode. That function must run on the VM trampoline when
    // called from the tree-walker so PR-249-style helper probes can burn
    // thousands of JS frames without consuming the host stack.
    if (builtin.single_threaded) return error.SkipZigTest;
    const Runner = struct {
        result: f64 = -1,
        ok: bool = false,
        fn run(self: *@This()) void {
            const ctx = Context.createWith(std.testing.allocator, .{}) catch return;
            defer ctx.destroy();
            const v = ctx.evaluate(
                \\function depth(n) { return n === 0 ? 0 : 1 + depth(n - 1); }
                \\try { var marker = 1; } catch (e) {}
                \\depth(2000)
            ) catch return;
            if (v.isNumber()) {
                self.result = v.asNum();
                self.ok = true;
            }
        }
    };
    var r = Runner{};
    const t = try std.Thread.spawn(.{ .stack_size = 8 << 20 }, Runner.run, .{&r});
    t.join();
    try std.testing.expect(r.ok);
    try std.testing.expectEqual(@as(f64, 2000), r.result);
}

test "vm admission: safe sloppy loops and dynamic calls tier safely" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_jit = true });
    defer ctx.destroy();

    const indexed = try ctx.evaluate(
        \\function indexedSum(a, spins) {
        \\  let s = 0;
        \\  for (let i = 0; i < spins; ++i) s += a[i & 1];
        \\  return s;
        \\}
        \\try { var marker = 1; } catch (e) {}
        \\indexedSum
    );
    const indexed_raw = indexed.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const indexed_func: *interp.Function = @ptrCast(@alignCast(indexed_raw));
    try std.testing.expect(indexed_func.chunk != null);
    try std.testing.expectEqual(@as(f64, 9), (try ctx.evaluate("indexedSum([1, 2], 6)")).asNum());

    const caller = try ctx.evaluate(
        \\function indexedCall(a) { return String(a[0]); }
        \\try { var marker = 1; } catch (e) {}
        \\indexedCall
    );
    const caller_raw = caller.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const caller_func: *interp.Function = @ptrCast(@alignCast(caller_raw));
    try std.testing.expect(caller_func.chunk != null);
    try std.testing.expectEqualStrings("3", (try ctx.evaluate("indexedCall([3])")).asStr());

    const dynamic = try ctx.evaluate(
        \\globalThis.dynamicTarget = function (x) { return x + 1; };
        \\globalThis.dynamicCall = Function("c", "x", '"use strict"; const result = c(x); return result;');
        \\for (let i = 0; i < 64; ++i) dynamicCall(dynamicTarget, i);
        \\dynamicCall
    );
    const dynamic_raw = dynamic.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const dynamic_func: *interp.Function = @ptrCast(@alignCast(dynamic_raw));
    try std.testing.expect(dynamic_func.chunk != null);
    if (jit.supported and builtin.cpu.arch == .aarch64) {
        try std.testing.expectEqual(jit.OptimizerTierState.ready, dynamic_func.chunk.?.optimizer_tier.state.load(.acquire));
        try std.testing.expectEqual(@as(u64, 1), dynamic_func.chunk.?.optimizer_tier.compileCount());
        try std.testing.expectEqual(@as(u64, 1), ctx.jit_owner.optimizerPublications());
    }
}

test "bytecode admission inventory retains exact runtime reasons" {
    const ctx = try Context.create(std.testing.allocator);
    defer ctx.destroy();

    const before = ctx.bytecodeAdmissionSnapshot();
    try std.testing.expectEqual(@as(f64, 3), (try ctx.evaluate("1 + 2")).asNum());

    _ = try ctx.evaluate(
        \\let marker = { x: 1 };
        \\globalThis.admitted = function admitted(p) { "use strict"; return p.x; };
        \\globalThis.computedTagged = function computedTagged(holder, key, value) { "use strict"; return holder[key]`a${value}b`; };
        \\globalThis.withArguments = function withArguments() { return arguments[0]; };
        \\globalThis.notCandidate = function notCandidate() { return 1; };
        \\globalThis.shadowed = function shadowed(p) { "use strict"; { let p = 2; } return marker.x; };
        \\globalThis.generatorCompiled = function* generatorCompiled() { yield 1; };
        \\globalThis.generatorLogical = function* generatorLogical() { var holder = {}; yield (holder.value ??= 1); };
        \\globalThis.generatorCompound = function* generatorCompound() { var holder = { value: 1 }; yield (holder.value += 1); };
        \\globalThis.generatorUpdate = function* generatorUpdate() { var holder = { value: 1 }; return holder[yield "key"]++; };
        \\globalThis.generatorTagged = function* generatorTagged(holder) { return holder[yield "key"]`a${yield "value"}b`; };
        \\globalThis.generatorHeritage = function* generatorHeritage() { return class extends Base {}; };
        \\globalThis.generatorDisposal = function* generatorDisposal() { for (using x of []) break; };
        \\globalThis.asyncCompiled = async function asyncCompiled() { return await 1; };
        \\globalThis.asyncLogical = async function asyncLogical() { var holder = {}; return holder.value ??= 1; };
        \\globalThis.asyncCompound = async function asyncCompound() { var holder = { value: 1 }; return holder.value += 1; };
        \\globalThis.asyncUpdate = async function asyncUpdate() { var holder = { value: 1 }; return ++holder[await Promise.resolve("value")]; };
        \\globalThis.asyncTagged = async function asyncTagged(holder) { return holder[await Promise.resolve("tag")]`a${await Promise.resolve(1)}b`; };
        \\globalThis.asyncHeritage = async function asyncHeritage() { return class extends Base {}; };
        \\globalThis.asyncDisposal = async function asyncDisposal() { for (using x of []) break; };
    );
    _ = try ctx.evaluate(
        \\globalThis.templateDefault = function templateDefault(value = 1) { return value; };
        \\globalThis.templateAccessor = function templateAccessor() {
        \\  return ({ get x() { return 1; } }).x;
        \\};
    );

    const expected = [_]struct { name: []const u8, reason: interp.BytecodeAdmissionReason }{
        .{ .name = "admitted", .reason = .plain_compiled },
        .{ .name = "computedTagged", .reason = .plain_compiled },
        .{ .name = "withArguments", .reason = .plain_compiled },
        .{ .name = "notCandidate", .reason = .plain_policy_not_candidate },
        .{ .name = "shadowed", .reason = .plain_compiled },
        .{ .name = "generatorCompiled", .reason = .generator_compiled },
        .{ .name = "generatorLogical", .reason = .generator_compiled },
        .{ .name = "generatorCompound", .reason = .generator_compiled },
        .{ .name = "generatorUpdate", .reason = .generator_compiled },
        .{ .name = "generatorTagged", .reason = .generator_compiled },
        .{ .name = "generatorHeritage", .reason = .generator_compiled },
        .{ .name = "generatorDisposal", .reason = .generator_compiled },
        .{ .name = "asyncCompiled", .reason = .async_compiled },
        .{ .name = "asyncLogical", .reason = .async_compiled },
        .{ .name = "asyncCompound", .reason = .async_compiled },
        .{ .name = "asyncUpdate", .reason = .async_compiled },
        .{ .name = "asyncTagged", .reason = .async_compiled },
        .{ .name = "asyncHeritage", .reason = .async_compiled },
        .{ .name = "asyncDisposal", .reason = .async_compiled },
    };
    for (expected) |entry| {
        const function_value = ctx.global_object.getOwn(entry.name) orelse return error.TestUnexpectedResult;
        const raw = function_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
        const function: *interp.Function = @ptrCast(@alignCast(raw));
        try std.testing.expectEqual(entry.reason, function.bytecode_admission_reason);
    }
    const template_expected = [_]struct { name: []const u8, reason: interp.BytecodeAdmissionReason }{
        .{ .name = "templateDefault", .reason = .template_plain_compiled },
        .{ .name = "templateAccessor", .reason = .template_plain_compiled },
    };
    for (template_expected) |entry| {
        const function_value = ctx.global_object.getOwn(entry.name) orelse return error.TestUnexpectedResult;
        const raw = function_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
        const function: *interp.Function = @ptrCast(@alignCast(raw));
        try std.testing.expectEqual(entry.reason, function.bytecode_admission_reason);
    }

    const after = ctx.bytecodeAdmissionSnapshot();
    try std.testing.expectEqual(before.count(.program_compiled) + 2, after.count(.program_compiled));
    try std.testing.expectEqual(before.count(.program_policy_lexical_declaration) + 1, after.count(.program_policy_lexical_declaration));
    try std.testing.expectEqual(before.count(.plain_compiled) + 4, after.count(.plain_compiled));
    try std.testing.expectEqual(before.count(.generator_compiled) + 7, after.count(.generator_compiled));
    try std.testing.expectEqual(before.count(.async_compiled) + 7, after.count(.async_compiled));
    for (expected) |entry| {
        if (entry.reason == .plain_compiled or entry.reason == .generator_compiled or entry.reason == .async_compiled) continue;
        try std.testing.expectEqual(before.count(entry.reason) + 1, after.count(entry.reason));
    }
    try std.testing.expectEqual(before.count(.template_plain_compiled) + 2, after.count(.template_plain_compiled));
    try std.testing.expectEqual(before.count(.program_source_policy), after.count(.program_source_policy));
    try std.testing.expectEqual(before.count(.template_plain_fallback), after.count(.template_plain_fallback));
    try std.testing.expectEqual(before.count(.template_generator_fallback), after.count(.template_generator_fallback));
    try std.testing.expectEqual(before.count(.template_async_fallback), after.count(.template_async_fallback));
}

test "bytecode admission source policies retain causal reasons" {
    const cases = [_]struct { source: []const u8, reason: ?interp.BytecodeAdmissionReason }{
        .{ .source = "let value = 1", .reason = .program_policy_lexical_declaration },
        .{ .source = "const value = 1", .reason = .program_policy_lexical_declaration },
        .{ .source = "try {} catch (error) {}", .reason = .program_policy_catch },
        .{ .source = "switch (value) {}", .reason = .program_policy_switch },
        .{ .source = "label: while (false) {}", .reason = .program_policy_label },
        .{ .source = "function arguments() {}", .reason = .program_policy_arguments_function },
        .{ .source = "fn.caller", .reason = .program_policy_legacy_caller },
        .{ .source = "fn.arguments", .reason = .program_policy_legacy_arguments },
        .{ .source = "\n    function nested() {}", .reason = .program_policy_nested_function_declaration },
        .{ .source = "var value = 1", .reason = null },
    };
    for (cases) |case| try std.testing.expectEqual(case.reason, Context.scriptTreeWalkPolicy(case.source));
}

test "forced tree-walker and required bytecode preserve exact observable state" {
    const source =
        \\globalThis.tierTrace = [];
        \\function tierDifferential(seed) {
        \\  "use strict";
        \\  var box = { value: seed };
        \\  var trace = [];
        \\  function bump(value) {
        \\    box.value = box.value + value;
        \\    trace.push(box.value);
        \\    return box.value;
        \\  }
        \\  var sum = 0;
        \\  for (var i = 0; i < 16; i = i + 1)
        \\    sum = sum + bump((i & 3) + 1);
        \\  globalThis.tierTrace = trace.join(",");
        \\  globalThis.tierBox = box.value;
        \\  return sum + box.value;
        \\}
        \\tierDifferential(7);
    ;

    const tree_ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = false,
        .bytecode_execution_mode = .tree_walker,
    });
    defer tree_ctx.destroy();
    const bytecode_ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = false,
        .bytecode_execution_mode = .required,
    });
    defer bytecode_ctx.destroy();

    const tree_result = try tree_ctx.evaluate(source);
    const bytecode_result = try bytecode_ctx.evaluate(source);
    try std.testing.expectEqual(tree_result.rawBits(), bytecode_result.rawBits());
    try std.testing.expectEqualStrings(
        (try tree_ctx.evaluate("tierTrace + '|' + tierBox")).asStr(),
        (try bytecode_ctx.evaluate("tierTrace + '|' + tierBox")).asStr(),
    );

    const tree = tree_ctx.bytecodeAdmissionSnapshot();
    try std.testing.expectEqual(@as(u64, 2), tree.count(.program_forced_tree_walker));
    try std.testing.expectEqual(@as(u64, 2), tree.count(.plain_forced_tree_walker));
    try std.testing.expectEqual(@as(u64, 0), tree.count(.program_compiled));

    const bytecode = bytecode_ctx.bytecodeAdmissionSnapshot();
    try std.testing.expectEqual(@as(u64, 2), bytecode.count(.program_compiled));
    try std.testing.expectEqual(@as(u64, 2), bytecode.count(.template_plain_compiled));
    try std.testing.expectEqual(@as(u64, 0), bytecode.count(.program_forced_tree_walker));
    try std.testing.expectEqual(@as(u64, 0), bytecode.count(.template_plain_fallback));
}

test "forced tree-walker and required bytecode agree on simple-frame direct eval" {
    const source =
        \\function directEvalSloppy(value) {
        \\  var local = 1;
        \\  eval("value += 1; arguments[0] += 2; var dynamic = 3; local += dynamic;");
        \\  eval("dynamic += 1; local += dynamic;");
        \\  return value * 1000 + arguments[0] * 100 + local * 10 + dynamic;
        \\}
        \\function directEvalStrict(value) {
        \\  "use strict";
        \\  let lexical = 2;
        \\  const fixed = 3;
        \\  var local = 1;
        \\  var first = eval("local += value; lexical += 1; var hidden = 9; local + lexical + fixed + arguments[0]");
        \\  return first * 100 + local * 10 + lexical + (typeof hidden === "undefined" ? 1 : 0);
        \\}
        \\function directEvalShadow(eval, value) { return eval(value); }
        \\function directEvalOuter(seed) {
        \\  var outer = seed;
        \\  function inner(step) {
        \\    var inner = step;
        \\    eval("outer += inner; var dynamic = outer;");
        \\    eval("dynamic += 1; inner += dynamic;");
        \\    return outer * 100 + inner * 10 + dynamic;
        \\  }
        \\  return inner(2);
        \\}
        \\function directEvalIndirect() {
        \\  "use strict";
        \\  var local = 1;
        \\  return (0, eval)("typeof local") === "undefined" ? 1 : 0;
        \\}
        \\directEvalSloppy(5) * 1000000 + directEvalStrict(5) * 1000 +
        \\  directEvalOuter(3) * 10 + directEvalShadow(Math.abs, -4) + directEvalIndirect();
    ;
    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    var results: [modes.len]u64 = undefined;

    for (modes, 0..) |mode, index| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        results[index] = (try ctx.evaluate(source)).rawBits();
        if (mode == .required) {
            const inventory = ctx.bytecodeAdmissionSnapshot();
            try std.testing.expect(inventory.count(.template_plain_compiled) >= 6);
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.plain_rejected_unsupported_lowering));
        }
    }
    try std.testing.expectEqual(results[0], results[1]);
    try std.testing.expectEqual(@as(f64, 8_885_769_865), Value.fromRawBits(results[0]).asNum());
}

test "forced tree-walker and required bytecode retain escaping direct eval contexts" {
    const source =
        \\function directEvalThis(value) { return eval("this.base + value"); }
        \\function DirectEvalTarget() { this.matches = eval("new.target === DirectEvalTarget"); }
        \\var directEvalNamed = function self(value) { return eval("self === directEvalNamed ? value : 0"); };
        \\function directEvalArrow(value) { return (() => eval("value + arguments[0]"))(); }
        \\function directEvalClosure(value) {
        \\  var offset = 2;
        \\  var closure = eval("(function(step) { return value + offset + step; })");
        \\  value += 10;
        \\  offset += 20;
        \\  return closure;
        \\}
        \\function directEvalTdz() {
        \\  var name = "";
        \\  try { eval("later"); } catch (error) { name = error.name; }
        \\  let later = 1;
        \\  return name === "ReferenceError" ? 1 : 0;
        \\}
        \\globalThis.directEvalDiscard = [];
        \\for (var i = 0; i < 4096; i++) directEvalDiscard.push({ dead: i, nested: { value: i } });
        \\directEvalDiscard = null;
        \\var escapedDirectEvalClosure = directEvalClosure(5);
        \\$262.evalScript("globalThis.evalScriptEscaped = function evalScriptEscaped(value) { return value + 4; };");
        \\var retainedShadowRealm = new ShadowRealm();
        \\var shadowEscaped = retainedShadowRealm.evaluate("(function shadowEscaped(value) { return value + 6; })");
    ;
    const probes = [_]struct { source: []const u8, expected: f64 }{
        .{ .source = "directEvalThis.call({ base: 7 }, 3)", .expected = 10 },
        .{ .source = "(new DirectEvalTarget()).matches ? 1 : 0", .expected = 1 },
        .{ .source = "directEvalNamed(7)", .expected = 7 },
        .{ .source = "directEvalArrow(5)", .expected = 10 },
        .{ .source = "escapedDirectEvalClosure(3)", .expected = 40 },
        .{ .source = "directEvalTdz()", .expected = 1 },
        .{ .source = "evalScriptEscaped(5)", .expected = 9 },
        .{ .source = "shadowEscaped(5)", .expected = 11 },
        .{ .source = "retainedShadowRealm.evaluate('6 + 6')", .expected = 12 },
    };
    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    var results: [modes.len][probes.len]u64 = undefined;

    for (modes, 0..) |mode, index| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_gc = true,
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        _ = try ctx.evaluate(source);
        try std.testing.expectEqual(@as(f64, 40), (try ctx.evaluate("escapedDirectEvalClosure(3)")).asNum());
        const compacted = ctx.compactGarbage();
        try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, compacted.status);
        try std.testing.expect(compacted.moved_cells > 0);
        for (probes, 0..) |probe, probe_index| {
            const result = ctx.evaluate(probe.source) catch |err| {
                std.debug.print("direct eval context probe failed in {s}: {s}", .{ @tagName(mode), probe.source });
                if (ctx.exception) |exception| if (exception.isObject()) {
                    const message = exception.asObj().getOwn("message") orelse Value.undef();
                    if (message.isString()) std.debug.print(" ({s}: {s})", .{
                        exception.asObj().errorName(), message.asStr(),
                    });
                };
                std.debug.print("\n", .{});
                return err;
            };
            results[index][probe_index] = result.rawBits();
            if (!result.isNumber() or result.asNum() != probe.expected)
                std.debug.print("direct eval context probe mismatch in {s}: {s} (expected {d}, found {})\n", .{
                    @tagName(mode), probe.source, probe.expected, result,
                });
            try std.testing.expectEqual(probe.expected, result.asNum());
        }
        if (mode == .required) {
            const inventory = ctx.bytecodeAdmissionSnapshot();
            try std.testing.expect(inventory.count(.template_plain_compiled) >= 7);
            try std.testing.expect(inventory.count(.plain_compiled) >= 3);
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.plain_rejected_unsupported_lowering));
        }
    }
    try std.testing.expectEqual(results[0], results[1]);
}

test "forced tree-walker and required bytecode interleave captured direct eval records" {
    const source =
        \\function directEvalWithOuter(seed, holder) {
        \\  var outer = seed;
        \\  var closure;
        \\  with (holder) {
        \\    closure = function inner(step) {
        \\      var inner = step;
        \\      return eval("outer += inner; value += outer; inner += value; outer + ':' + value + ':' + inner");
        \\    };
        \\  }
        \\  return closure;
        \\}
        \\function directEvalLoopOuter(seed) {
        \\  var outer = seed;
        \\  for (let captured = 1; captured < 2; captured++) {
        \\    return function inner(step) {
        \\      return eval("outer += step; captured += outer; outer + ':' + captured");
        \\    };
        \\  }
        \\}
        \\function directEvalNamedOuter(seed, holder) {
        \\  var outer = seed;
        \\  var closure;
        \\  with (holder) {
        \\    closure = function self(step) {
        \\      return eval("self === closure ? outer + value + step : -1");
        \\    };
        \\  }
        \\  return closure;
        \\}
        \\function directEvalShadowedOuter(holder) {
        \\  var closure;
        \\  with (holder) {
        \\    let value = 2;
        \\    closure = function inner() { eval("value += 1"); return eval("value"); };
        \\  }
        \\  return closure;
        \\}
        \\function directEvalNestedOuter(first, second) {
        \\  var closure;
        \\  with (first) {
        \\    let one = 11;
        \\    with (second) {
        \\      let two = 22;
        \\      closure = function inner() { return eval("one + ':' + two + ':' + value"); };
        \\    }
        \\  }
        \\  return closure;
        \\}
        \\function directEvalThrowValue() { throw 7; }
        \\function directEvalCatchOuter(holder) {
        \\  var closure;
        \\  with (holder) {
        \\    try { directEvalThrowValue(); } catch (value) {
        \\      closure = function inner() { return eval("value"); };
        \\    }
        \\  }
        \\  return closure;
        \\}
        \\function directEvalDeepOuter(first) {
        \\  var outer = 1;
        \\  var make;
        \\  with (first) {
        \\    let lexical = 7;
        \\    make = function middle(second) {
        \\      var middle = 2;
        \\      var closure;
        \\      with (second) {
        \\        let local = 5;
        \\        closure = function inner() { return eval("outer + middle + left + right + lexical + local"); };
        \\      }
        \\      return closure;
        \\    };
        \\  }
        \\  return make;
        \\}
        \\function directEvalEscapeOuter(holder) {
        \\  var outer = 31;
        \\  var make;
        \\  with (holder) {
        \\    make = function inner() { return eval("(function escaped() { return outer + value; })"); };
        \\  }
        \\  return make();
        \\}
        \\globalThis.directEvalWithHolder = { value: 5 };
        \\globalThis.directEvalWithClosure = directEvalWithOuter(2, directEvalWithHolder);
        \\globalThis.directEvalLoopClosure = directEvalLoopOuter(3);
        \\globalThis.directEvalNamedHolder = { value: 7 };
        \\globalThis.directEvalNamedClosure = directEvalNamedOuter(11, directEvalNamedHolder);
        \\globalThis.directEvalShadowedClosure = directEvalShadowedOuter({ value: 3 });
        \\globalThis.directEvalNestedClosure = directEvalNestedOuter({ one: 101, two: 102, value: 103 }, { one: 201, two: 202, value: 203 });
        \\globalThis.directEvalCatchClosure = directEvalCatchOuter({ value: 99 });
        \\globalThis.directEvalDeepClosure = directEvalDeepOuter({ left: 3, middle: 20 })({ right: 4, lexical: 70 });
        \\globalThis.directEvalRuntimeEscaped = directEvalEscapeOuter({ value: 5 });
        \\globalThis.directEvalInterleaveRetained = [];
        \\globalThis.directEvalInterleaveDiscarded = [];
        \\for (var index = 0; index < 4096; index++) {
        \\  directEvalInterleaveRetained.push({ index: index, nested: { value: index } });
        \\  directEvalInterleaveDiscarded.push({ index: index, nested: { value: index } });
        \\}
        \\directEvalInterleaveDiscarded = null;
    ;
    const probes = [_]struct { source: []const u8, expected: []const u8 }{
        .{ .source = "directEvalWithClosure(3)", .expected = "5:10:13" },
        .{ .source = "directEvalLoopClosure(2)", .expected = "5:6" },
        .{ .source = "String(directEvalNamedClosure(4))", .expected = "22" },
        .{ .source = "directEvalWithClosure(1)", .expected = "6:16:17" },
        .{ .source = "directEvalLoopClosure(1)", .expected = "6:12" },
        .{ .source = "String(directEvalShadowedClosure())", .expected = "3" },
        .{ .source = "String(directEvalShadowedClosure())", .expected = "4" },
        .{ .source = "directEvalNestedClosure()", .expected = "201:22:203" },
        .{ .source = "String(directEvalCatchClosure())", .expected = "7" },
        .{ .source = "String(directEvalDeepClosure())", .expected = "85" },
        .{ .source = "String(directEvalRuntimeEscaped())", .expected = "36" },
    };
    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    var results: [modes.len][probes.len][]const u8 = undefined;
    var result_counts: [modes.len]usize = @splat(0);
    defer for (&results, 0..) |*mode_results, mode_index|
        for (mode_results[0..result_counts[mode_index]]) |result| std.testing.allocator.free(result);

    for (modes, 0..) |mode, mode_index| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_gc = true,
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        _ = try ctx.evaluate(source);
        for (probes[0..3], 0..) |probe, probe_index| {
            const result = try ctx.evaluate(probe.source);
            try std.testing.expect(result.isString());
            try std.testing.expectEqualStrings(probe.expected, result.asStr());
            results[mode_index][probe_index] = try std.testing.allocator.dupe(u8, result.asStr());
            result_counts[mode_index] += 1;
        }
        const compacted = ctx.compactGarbage();
        try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, compacted.status);
        try std.testing.expect(compacted.moved_cells > 0);
        for (probes[3..], 3..) |probe, probe_index| {
            const result = try ctx.evaluate(probe.source);
            try std.testing.expect(result.isString());
            try std.testing.expectEqualStrings(probe.expected, result.asStr());
            results[mode_index][probe_index] = try std.testing.allocator.dupe(u8, result.asStr());
            result_counts[mode_index] += 1;
        }
        if (mode == .required) {
            const inventory = ctx.bytecodeAdmissionSnapshot();
            try std.testing.expect(inventory.count(.template_plain_compiled) >= 18);
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.plain_rejected_unsupported_lowering));
        }
    }
    for (results[0], results[1]) |tree_result, bytecode_result|
        try std.testing.expectEqualStrings(tree_result, bytecode_result);
}

