            try std.testing.expect((try ctx.evaluate(case.source)).toBoolean());
        }
    }
}

test "a sealed object whose properties are all accessors is frozen" {
    // TestIntegrityLevel only consults [[Writable]] on data descriptors.
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    try std.testing.expect((try ctx.evaluate(
        \\var o = { get foo() { return 17; } };
        \\Object.seal(o);
        \\var mixed = { get a() { return 1; }, b: 2 };
        \\Object.seal(mixed);
        \\Object.isSealed(o) && Object.isFrozen(o) && Object.isSealed(mixed) && !Object.isFrozen(mixed) &&
        \\  (Object.freeze(mixed), Object.isFrozen(mixed))
    )).toBoolean());
}

test "a direct native call installs the callee's closure environment" {
    // The optimizer's direct-call fast path skips building an activation. A
    // closure created inside a generator (or async body) keeps its captured
    // bindings in an Environment Record, not in frame slots, so its
    // `load_var`s resolve through `vm.env` — which must be the closure's
    // defining scope, not the caller's. The 8th plain call of the yielded
    // function used to throw "Can't find variable: i"; method calls, `.call`
    // and arrows never took the fast path and hid the defect.
    for ([_]interp.BytecodeExecutionMode{ .automatic, .required }) |mode| {
        for ([_]struct { name: []const u8, source: []const u8 }{
            .{ .name = "plain_call_of_generator_closure", .source = "function* gen(n){for(var i=0;i<n;i++){yield function(){return i;};}} var s=0;for(var f of gen(20))s+=f();s===190" },
            .{ .name = "closure_over_generator_parameter", .source = "function* gen(n){for(var i=0;i<n;i++){yield function(){return n;};}} var s=0;for(var f of gen(20))s+=f();s===400" },
            .{ .name = "called_through_helper", .source = "function* gen(n){for(var i=0;i<n;i++){yield function(){return i;};}} function callIt(g){return g();} var s=0;for(var f of gen(20))s+=callIt(f);s===190" },
            .{ .name = "collected_then_called", .source = "function* gen(n){for(var i=0;i<n;i++){yield function(){return i;};}} var fs=[];var it=gen(20),r;while(!(r=it.next()).done)fs.push(r.value);var s=0;for(var f of fs)s+=f();s===400" },
            .{ .name = "detached_during_argument_coercion", .source = "function* mk(n){for(var i=0;i<n;i++){var ta=new Int32Array(1);var b=ta.buffer;yield {ta:ta,detach:function(){b.transfer();}};}} var thrown=0;for(var o of mk(12)){var start={valueOf:function(){o.detach();return 0;}};var f=function(){return o.ta.slice(start,1);};var r=0;try{f();}catch(e){r=e instanceof TypeError?1:0;}thrown+=r;} thrown===12" },
        }) |case| {
            errdefer std.debug.print("direct native call {s} ({s})\n", .{ case.name, @tagName(mode) });
            const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
                .enable_gc = true,
                .enable_jit = true,
                .bytecode_execution_mode = mode,
            });
            defer ctx.destroy();
            try std.testing.expect((try ctx.evaluate(case.source)).toBoolean());
        }
    }
}

test "a var loop binding is resolved like an assignment" {
    // ForIn/OfBodyEvaluation step 6.d: a `var` ForBinding is ResolveBinding +
    // PutValue, so it writes whatever `x` names at the loop — the catch
    // parameter that Annex B.3.4 lets it redeclare, or a `with` object that
    // provides `x` — never the hoisted `var` directly.
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        for ([_]struct { name: []const u8, source: []const u8 }{
            .{ .name = "catch_param_for_in", .source = "var b,d,a;try{throw 'ex';}catch(err){b=err;for(var err in {p:null}){d=err;}a=err;}b==='ex'&&d==='p'&&a==='p'&&typeof err==='undefined'" },
            .{ .name = "catch_param_for_of", .source = "var b,d,a;try{throw 'ex';}catch(err){b=err;for(var err of [2]){d=err;}a=err;}b==='ex'&&d===2&&a===2&&typeof err==='undefined'" },
            .{ .name = "catch_param_for_var_init_in", .source = "var b,d,a;try{throw 'ex';}catch(err){b=err;for(var err=7 in {p:null}){d=err;}a=err;}b==='ex'&&d==='p'&&a==='p'&&typeof err==='undefined'" },
            .{ .name = "with_object_for_in", .source = "var o={x:0},d;with(o){for(var x in {p:null}){d=x;}}d==='p'&&o.x==='p'&&typeof x==='undefined'" },
            .{ .name = "plain_for_in", .source = "for(var k in {p:null});k==='p'" },
        }) |case| {
            errdefer std.debug.print("var loop binding {s} ({s})\n", .{ case.name, @tagName(mode) });
            const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
                .enable_gc = true,
                .enable_jit = false,
                .bytecode_execution_mode = mode,
            });
            defer ctx.destroy();
            try std.testing.expect((try ctx.evaluate(case.source)).toBoolean());
        }
    }
}

test "a call expression as an assignment target is evaluated then rejected" {
    // Annex B runtime errors for function-call assignment targets: the call
    // runs, nothing on the right-hand side (or the loop value's coercions) is
    // touched, and the ReferenceError names the syntactic shape the way
    // JavaScriptCore does. The bytecode tier used to reject these programs
    // outright (`error.Unsupported`), so it never reached the tree walker's
    // ordering; both tiers now share `NotAReference`.
    const prelude = "var fc=0,vo=0,gc=0;function f(){fc++;return {valueOf(){vo++;return 1;}};}function g(){gc++;return 1;}function run(k){try{k();return 'nothrow';}catch(e){return e.constructor.name+': '+e.message;}}";
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        for ([_]struct { name: []const u8, source: []const u8 }{
            .{ .name = "assign", .source = "run(function(){f() = g();})==='ReferenceError: Left side of assignment is not a reference.'&&fc===1&&vo===0&&gc===0" },
            .{ .name = "compound", .source = "run(function(){f() += g();})==='ReferenceError: Left side of assignment is not a reference.'&&fc===1&&vo===0&&gc===0" },
            .{ .name = "postfix_inc", .source = "run(function(){f()++;})==='ReferenceError: Postfix ++ operator applied to value that is not a reference.'&&fc===1&&vo===0" },
            .{ .name = "postfix_dec", .source = "run(function(){f()--;})==='ReferenceError: Postfix -- operator applied to value that is not a reference.'&&fc===1&&vo===0" },
            .{ .name = "prefix_inc", .source = "run(function(){++f();})==='ReferenceError: Prefix ++ operator applied to value that is not a reference.'&&fc===1&&vo===0" },
            .{ .name = "prefix_dec", .source = "run(function(){--f();})==='ReferenceError: Prefix -- operator applied to value that is not a reference.'&&fc===1&&vo===0" },
            .{ .name = "for_in", .source = "run(function(){for (f() in [1]) {}})==='ReferenceError: Left side of for-in statement is not a reference.'&&fc===1&&vo===0" },
            .{ .name = "for_of_closes", .source = "var rc=0;var it={[Symbol.iterator](){return{next(){return{value:1,done:false};},return(){rc++;return{};}};}};run(function(){for (f() of it) {}})==='ReferenceError: Left side of for-of statement is not a reference.'&&fc===1&&vo===0&&rc===1" },
        }) |case| {
            errdefer std.debug.print("call target {s} ({s})\n", .{ case.name, @tagName(mode) });
            const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
                .enable_gc = true,
                .enable_jit = false,
                .bytecode_execution_mode = mode,
            });
            defer ctx.destroy();
            const source = try std.mem.concat(std.testing.allocator, u8, &.{ prelude, case.source });
            defer std.testing.allocator.free(source);
            try std.testing.expect((try ctx.evaluate(source)).toBoolean());
            if (mode == .required)
                try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
        }
    }
}

test "break and continue unwind exactly the handlers they exit" {
    // A `break`/`continue` that crosses a `finally` pops the handlers pushed
    // since its target was entered — running each finally among them — and no
    // more. Unbounded unwinding entered the target loop's own for-in/for-of
    // close handler (a for-in's close consumes its three-word operand-stack
    // state, which then crashed `enum_next`), popped enclosing catch handlers,
    // and ran a try/finally that lexically encloses the loop once per iteration.
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        for ([_]struct { name: []const u8, source: []const u8 }{
            .{ .name = "forin_finally_continue", .source = "(function(){var x,i=0;for(x in [1,2,3]){try{i++;}finally{continue;}}return i===3;})()" },
            .{ .name = "forin_try_continue", .source = "(function(){var x,i=0,f=0;for(x in [1,2,3]){try{i++;continue;}finally{f++;}}return i===3&&f===3;})()" },
            .{ .name = "forin_catch_break_finally_continue", .source = "(function(){var x,c=0,f=0;for(x in [1,2,3]){try{c++;break;}catch(e){}finally{f++;continue;}c=-1;}return c===3&&f===3;})()" },
            .{ .name = "outer_finally_continue", .source = "(function(){var L=[];try{for(var n=0;n<2;n++){try{}finally{L.push('f'+n);continue;}}L.push('a');}finally{L.push('o');}return L.join()==='f0,f1,a,o';})()" },
            .{ .name = "outer_finally_break", .source = "(function(){var L=[];try{for(var n=0;n<2;n++){try{}finally{L.push('f'+n);break;}}L.push('a');}finally{L.push('o');}return L.join()==='f0,a,o';})()" },
            .{ .name = "outer_finally_try_continue", .source = "(function(){var L=[];try{for(var n=0;n<2;n++){try{L.push('t'+n);continue;}finally{L.push('f'+n);}}L.push('a');}finally{L.push('o');}return L.join()==='t0,f0,t1,f1,a,o';})()" },
            .{ .name = "outer_finally_while_continue", .source = "(function(){var L=[],n=0;try{while(n<2){n++;try{}finally{L.push('f'+n);continue;}}L.push('a');}finally{L.push('o');}return L.join()==='f1,f2,a,o';})()" },
            .{ .name = "switch_break_in_finally", .source = "(function(){var L=[];try{switch(1){case 1:try{}finally{L.push('f');break;}L.push('n');}L.push('a');}finally{L.push('o');}return L.join()==='f,a,o';})()" },
            .{ .name = "labeled_block_break_in_finally", .source = "(function(){var L=[];try{b:{try{}finally{L.push('f');break b;}L.push('n');}L.push('a');}finally{L.push('o');}return L.join()==='f,a,o';})()" },
            .{ .name = "nested_active_finallys", .source = "(function(){var L=[];for(var n=0;n<2;n++){try{}finally{try{}finally{L.push('i'+n);continue;}}}return L.join()==='i0,i1';})()" },
            .{ .name = "forof_continue_keeps_outer_catch", .source = "(function(){var r='none';try{for(var x of [1,2]){try{}finally{continue;}}throw 'z';}catch(e){r=e;}return r==='z';})()" },
            .{ .name = "forof_continue_keeps_close_handler", .source = "(function(){var rc=0,r='';var o={[Symbol.iterator](){var n=0;return{next(){return n<3?{value:n++,done:false}:{done:true};},return(){rc++;return{done:true};}};}};try{for(var x of o){try{}finally{if(x===0)continue;}if(x===1)throw 'boom';}}catch(e){r=e;}return r==='boom'&&rc===1;})()" },
            .{ .name = "forof_generator_continue_from_finally", .source = "(function(){function* g(){yield 1;yield 1;}var i=0;for(var x of g()){try{throw 1;}catch(e){}finally{i++;continue;}}return i===2;})()" },
            .{ .name = "continue_pops_catch_handler", .source = "(function(){var r='none';try{for(var n=0;n<2;n++){try{if(n===0)continue;}catch(e){r='stale';}if(n===1)throw 'boom';}}catch(e){r=e;}return r==='boom';})()" },
            .{ .name = "labeled_break_through_catch_and_finally", .source = "(function(){var L=[],r='none';try{o:for(var a in {p:1,q:2}){try{try{break o;}catch(e){L.push('c');}}finally{L.push('f');}}throw 'z';}catch(e){r=e;}return L.join()==='f'&&r==='z';})()" },
            .{ .name = "break_and_return_still_close", .source = "(function(){var rc=0;var o={[Symbol.iterator](){var n=0;return{next(){return n<9?{value:n++,done:false}:{done:true};},return(){rc++;return{done:true};}};}};L:for(var x of o){try{break L;}finally{}}(function(){for(var y of o){try{return 1;}finally{}}})();return rc===2;})()" },
        }) |case| {
            errdefer std.debug.print("abrupt jump {s} ({s})\n", .{ case.name, @tagName(mode) });
            const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
                .enable_gc = true,
