test "Object reflection shared no-GIL callers retain invocation-local operands" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .enable_threads = true,
        .gil = false,
    });
    defer ctx.destroy();
    ctx.setBytecodeExecutionModeForTesting(.required);
    const result = try ctx.evaluate(
        \\var reflectionValue = {marker: 37};
        \\var reflectionSource = new Proxy({value: reflectionValue}, {
        \\  ownKeys(t) { return Reflect.ownKeys(t); },
        \\  getOwnPropertyDescriptor(t, k) { return Reflect.getOwnPropertyDescriptor(t, k); },
        \\  get(t, k, r) { return Reflect.get(t, k, r); }
        \\});
        \\function reflectionLane() {
        \\  var total = 0;
        \\  for (var i = 0; i < 64; i++) {
        \\    var descriptors = Object.getOwnPropertyDescriptors(reflectionSource);
        \\    var entries = Object.entries(reflectionSource);
        \\    var copy = Object.assign({}, reflectionSource);
        \\    var local = {};
        \\    Object.defineProperties(local, {a: {value: reflectionValue}, b: {value: i}});
        \\    Object.defineProperty(local, 'c', {value: reflectionValue});
        \\    if (Object.getOwnPropertyNames(reflectionSource)[0] !== 'value' ||
        \\        Object.keys(reflectionSource)[0] !== 'value' ||
        \\        Object.values(reflectionSource)[0] !== reflectionValue ||
        \\        entries[0][1] !== reflectionValue || descriptors.value.value !== reflectionValue ||
        \\        copy.value !== reflectionValue || local.a !== reflectionValue ||
        \\        local.b !== i || local.c !== reflectionValue || !Object.hasOwn(reflectionSource, 'value')) throw 99;
        \\    total += copy.value.marker;
        \\  }
        \\  return total;
        \\}
        \\var reflectionLanes = [];
        \\for (var lane = 0; lane < 4; lane++) reflectionLanes.push(new Thread(reflectionLane));
        \\var reflectionTotal = 0;
        \\for (var lane = 0; lane < 4; lane++) reflectionTotal += reflectionLanes[lane].join();
        \\reflectionTotal;
    );
    try std.testing.expectEqual(@as(f64, 4 * 64 * 37), result.asNum());
    try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
}

fn expectProxyMetadataMoving(setup: []const u8, expression: []const u8) !void {
    return expectProxyMetadataMovingOutcome(setup, expression, false);
}

fn expectProxyMetadataMovingOutcome(setup: []const u8, expression: []const u8, expect_abrupt: bool) !void {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;
    // Stable cell identity distinguishes all three cases without retaining a
    // root across host calls: an unmoved live Environment keeps its id, a moved
    // live Environment has the same id at its new address, and the stale old
    // address has no live-cell identity after relocation.
    const EnvProbe = struct {
        before: ?*interp.Environment = null,
        before_id: ?u64 = null,
        matched: ?bool = null,
    };
    const Host = struct {
        fn arm(raw: *anyopaque, _: Value, _: []const Value) value.HostError!Value {
            const machine: *interp.Interpreter = @ptrCast(@alignCast(raw));
            const ctx: *Context = @ptrCast(@alignCast(machine.gc_realm_context.?));
            ctx.gc.?.nursery_threshold_bytes = 1;
            ctx.gc_moving_checkpoint_requested.store(true, .release);
            return Value.undef();
        }

        fn captureEnv(raw: *anyopaque, _: Value, _: []const Value) value.HostError!Value {
            const machine: *interp.Interpreter = @ptrCast(@alignCast(raw));
            const native = machine.active_native orelse return Value.boolVal(false);
            const probe: *EnvProbe = @ptrCast(@alignCast(native.private_data orelse return Value.boolVal(false)));
            const current_id = gc_mod.stableCellIdentity(@ptrCast(machine.env));
            if (probe.before) |before| {
                const matched = if (probe.before_id) |before_id|
                    if (current_id) |id| id == before_id else false
                else
                    current_id == null and machine.env == before;
                probe.matched = matched;
                return Value.boolVal(matched);
            }
            probe.before = machine.env;
            probe.before_id = current_id;
            return Value.boolVal(false);
        }

        fn debuggerEval(raw: *anyopaque, _: Value, args: []const Value) value.HostError!Value {
            const machine: *interp.Interpreter = @ptrCast(@alignCast(raw));
            if (args.len == 0 or !args[0].isString())
                return machine.throwError("TypeError", "proxyDebuggerEval expects a string");
            return machine.evaluateForDebugger(args[0].asStr(), machine.env, machine.this_value, machine.strict);
        }
    };
    for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        errdefer std.debug.print("Proxy metadata mode {s}\n", .{@tagName(mode)});
        const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = true });
        defer ctx.destroy();
        var env_probe: EnvProbe = .{};
        {
            const saved = gc_mod.setActiveContext(ctx);
            defer gc_mod.restoreActiveContext(saved);
            const arm = try gc_mod.allocObj(ctx.arena());
            arm.* = .{ .native = Host.arm };
            try ctx.global_object.setOwn(ctx.arena(), ctx.root_shape, "proxyArm", Value.obj(arm));
            try ctx.env.put("proxyArm", Value.obj(arm));
            const capture_env = try gc_mod.allocObj(ctx.arena());
            capture_env.* = .{ .native = Host.captureEnv, .private_data = @ptrCast(&env_probe) };
            try ctx.global_object.setOwn(ctx.arena(), ctx.root_shape, "proxyCaptureEnv", Value.obj(capture_env));
            try ctx.env.put("proxyCaptureEnv", Value.obj(capture_env));
            const debugger_eval = try gc_mod.allocObj(ctx.arena());
            debugger_eval.* = .{ .native = Host.debuggerEval };
            try ctx.global_object.setOwn(ctx.arena(), ctx.root_shape, "proxyDebuggerEval", Value.obj(debugger_eval));
            try ctx.env.put("proxyDebuggerEval", Value.obj(debugger_eval));
        }
        _ = try ctx.evaluate(
            \\function proxyMovingLoop(n){var total=0,i=0;while(i<n){total=total+i;i=i+1;}return total;}
            \\for(var warm=0;warm<10;warm=warm+1)proxyMovingLoop(4096);
        );
        const loop: *interp.Function = @ptrCast(@alignCast(ctx.global_object.getOwn("proxyMovingLoop").?.asObj().jsFunction().?));
        try std.testing.expectEqual(jit.TierState.ready, loop.chunk.?.tier.loadState());
        try std.testing.expect(loop.chunk.?.tier.loadCode().?.manages_steps);
        ctx.collectGarbage();
        ctx.gc.?.nursery_threshold_bytes = std.math.maxInt(usize);
        ctx.setBytecodeExecutionModeForTesting(mode);
        _ = try ctx.evaluate("globalThis.proxySubject={marker:37};");
        _ = try ctx.evaluate(setup);
        const before = ctx.global_object.getOwn("proxySubject").?.asObj();
        const moving_before = ctx.gc.?.accounting().moving_minor_collections;
        const source = try std.fmt.allocPrint(std.testing.allocator, "proxyArm();{s}", .{expression});
        defer std.testing.allocator.free(source);
        if (expect_abrupt) {
            if (ctx.evaluate(source)) |_| {
                return error.TestUnexpectedResult;
            } else |err| {
                if (err != error.Throw) return err;
            }
            try std.testing.expect(env_probe.matched orelse false);
            const resumed = try ctx.evaluate("proxySubject.marker===37&&globalThis.proxySubject===proxySubject");
            try std.testing.expect(resumed.toBoolean());
        } else {
            const result = ctx.evaluate(source) catch |err| {
                if (ctx.exception) |exception| if (exception.isObject()) {
                    const message = exception.asObj().getOwn("message") orelse Value.undef();
                    if (message.isString()) std.debug.print("{s}: {s}\n", .{ exception.asObj().errorName(), message.asStr() });
                };
                return err;
            };
            try std.testing.expect(result.toBoolean());
        }
        try std.testing.expectEqual(moving_before + 1, ctx.gc.?.accounting().moving_minor_collections);
        try std.testing.expect(before != ctx.global_object.getOwn("proxySubject").?.asObj());
        try std.testing.expect(!ctx.gc_relocation_active.load(.acquire));
        if (mode == .required)
            try std.testing.expectEqual(@as(u64, 0), ctx.bytecodeAdmissionSnapshot().count(.template_plain_fallback));
    }
}

