test "parallel_js: shared destructuring/default-parameter chunk keeps lane-local prologues" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .enable_threads = true,
        .parallel_gc = true,
        .parallel_js = true,
        .enable_jit = false,
        .bytecode_execution_mode = .required,
    });
    defer ctx.destroy();
    _ = try ctx.evaluate(
        \\function sharedPattern([left, { right }], { bias, ...rest }, literal = 4 + 4) {
        \\  return left * 100 + right * 10 + bias + rest.extra + literal;
        \\}
        \\function sharedInvocation(receiver = this, args = arguments, copy = receiver, score = copy === receiver ? 10 : -1) { return receiver.bias * score + args.length; }
        \\function sharedProperty(input, named = input.bias, computed = input["bias"], nested = input.nested.value) { return named * 100 + computed * 10 + nested; }
        \\function sharedCall(input, value = input.read(input.bias)) { return value; }
        \\function SharedParameterBox(value) { this.value = value + 1; }
        \\function sharedConstruction(Ctor, input, value = new Ctor(input.bias)) { return value.value; }
        \\class SharedFieldBox { field = 13; constructor(input) { this.input = input.bias; } }
        \\function sharedFieldConstruction(input) { var instance = new SharedFieldBox(input); return instance.field + instance.input; }
        \\class SharedDerivedBase { constructor(input) { this.base = input.bias; } }
        \\class SharedDerivedBox extends SharedDerivedBase { field = 13; constructor(input) { super(input); } }
        \\function sharedDerivedConstruction(input) { var instance = new SharedDerivedBox(input); return instance.field + instance.base; }
        \\globalThis.sharedPatternInputs = [
        \\  [[1, { right: 2 }], { bias: 3, extra: 4, nested: { value: 9 }, read(value) { return this.nested.value + value; } }],
        \\  [[2, { right: 3 }], { bias: 4, extra: 5, nested: { value: 10 }, read(value) { return this.nested.value + value; } }],
        \\  [[3, { right: 4 }], { bias: 5, extra: 6, nested: { value: 11 }, read(value) { return this.nested.value + value; } }],
        \\  [[4, { right: 5 }], { bias: 6, extra: 7, nested: { value: 12 }, read(value) { return this.nested.value + value; } }]
        \\];
    );
    const function_value = try ctx.evaluate("sharedPattern");
    const raw_function = function_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const function: *interp.Function = @ptrCast(@alignCast(raw_function));
    const chunk = function.chunk orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(u32, &.{ 0, 1 }, chunk.destructuring_parameter_indices);
    try std.testing.expectEqualSlices(u32, &.{2}, chunk.default_parameter_indices);
    const invocation_value = try ctx.evaluate("sharedInvocation");
    const raw_invocation = invocation_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const invocation_function: *interp.Function = @ptrCast(@alignCast(raw_invocation));
    const invocation_chunk = invocation_function.chunk orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(u32, &.{ 0, 1, 2, 3 }, invocation_chunk.default_parameter_indices);
    try std.testing.expect(invocation_chunk.arguments_slot != null);
    const property_value = try ctx.evaluate("sharedProperty");
    const raw_property = property_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const property_function: *interp.Function = @ptrCast(@alignCast(raw_property));
    const property_chunk = property_function.chunk orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(u32, &.{ 1, 2, 3 }, property_chunk.default_parameter_indices);
    const call_value = try ctx.evaluate("sharedCall");
    const raw_call = call_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const call_function: *interp.Function = @ptrCast(@alignCast(raw_call));
    const call_chunk = call_function.chunk orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(u32, &.{1}, call_chunk.default_parameter_indices);
    const constructor_value = try ctx.evaluate("SharedParameterBox");
    if (constructor_value.asObj().jsFunction() == null) return error.TestUnexpectedResult;
    const construction_value = try ctx.evaluate("sharedConstruction");
    const raw_construction = construction_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const construction_function: *interp.Function = @ptrCast(@alignCast(raw_construction));
    const construction_chunk = construction_function.chunk orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(u32, &.{2}, construction_chunk.default_parameter_indices);
    const field_constructor_value = try ctx.evaluate("SharedFieldBox");
    const raw_field_constructor = field_constructor_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const field_constructor: *interp.Function = @ptrCast(@alignCast(raw_field_constructor));
    _ = field_constructor.chunk orelse return error.TestUnexpectedResult;
    const field_construction_value = try ctx.evaluate("sharedFieldConstruction");
    const raw_field_construction = field_construction_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const field_construction_function: *interp.Function = @ptrCast(@alignCast(raw_field_construction));
    const field_construction_chunk = field_construction_function.chunk orelse return error.TestUnexpectedResult;
    const derived_construction_value = try ctx.evaluate("sharedDerivedConstruction");
    const raw_derived_construction = derived_construction_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const derived_construction_function: *interp.Function = @ptrCast(@alignCast(raw_derived_construction));
    const derived_construction_chunk = derived_construction_function.chunk orelse return error.TestUnexpectedResult;
    const derived_constructor_value = try ctx.evaluate("SharedDerivedBox");
    const raw_derived_constructor = derived_constructor_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const derived_constructor: *interp.Function = @ptrCast(@alignCast(raw_derived_constructor));
    const derived_constructor_chunk = derived_constructor.chunk orelse return error.TestUnexpectedResult;
    try std.testing.expect(derived_constructor_chunk.is_derived_constructor);
    const input_value = try ctx.evaluate("sharedPatternInputs");
    const inputs = input_value.asObj();

    const lane_count = 4;
    const iterations = 64;
    const Worker = struct {
        ctx: *Context,
        function: *interp.Function,
        chunk: *@import("bytecode.zig").Chunk,
        invocation_function: *interp.Function,
        invocation_chunk: *@import("bytecode.zig").Chunk,
        property_function: *interp.Function,
        property_chunk: *@import("bytecode.zig").Chunk,
        call_function: *interp.Function,
        call_chunk: *@import("bytecode.zig").Chunk,
        constructor: Value,
        construction_function: *interp.Function,
        construction_chunk: *@import("bytecode.zig").Chunk,
        field_construction_function: *interp.Function,
        field_construction_chunk: *@import("bytecode.zig").Chunk,
        derived_construction_function: *interp.Function,
        derived_construction_chunk: *@import("bytecode.zig").Chunk,
        first: Value,
        second: Value,
        result: std.atomic.Value(i64) = .init(-1),

        fn run(worker: *@This()) void {
            const saved_heap = gc_mod.setActiveHeap(worker.ctx.gc);
            defer _ = gc_mod.setActiveHeap(saved_heap);
            const saved_arena = strcell.setActiveArena(worker.ctx.arena());
            defer _ = strcell.setActiveArena(saved_arena);
            var machine = worker.ctx.interpreter();
            worker.ctx.pushActiveInterpreter(&machine) catch return;
            defer worker.ctx.popActiveInterpreter(&machine);

            const arguments = [_]Value{ worker.first, worker.second };
            var sum: i64 = 0;
            for (0..iterations) |_| {
                const value_out = vm.runFunction(
                    &machine,
                    worker.function,
                    worker.chunk,
                    &arguments,
                    Value.undef(),
                    Value.undef(),
                ) catch return;
                if (!value_out.isNumber()) return;
                sum += @intFromFloat(value_out.asNum());
                const invocation_out = vm.runFunction(
                    &machine,
                    worker.invocation_function,
                    worker.invocation_chunk,
                    &.{},
                    worker.second,
                    Value.undef(),
                ) catch return;
                if (!invocation_out.isNumber()) return;
                sum += @intFromFloat(invocation_out.asNum());
                const property_out = vm.runFunction(
                    &machine,
                    worker.property_function,
                    worker.property_chunk,
                    &.{worker.second},
                    Value.undef(),
                    Value.undef(),
                ) catch return;
                if (!property_out.isNumber()) return;
                sum += @intFromFloat(property_out.asNum());
                const call_out = vm.runFunction(
                    &machine,
                    worker.call_function,
                    worker.call_chunk,
                    &.{worker.second},
                    Value.undef(),
                    Value.undef(),
                ) catch return;
                if (!call_out.isNumber()) return;
                sum += @intFromFloat(call_out.asNum());
                const construction_out = vm.runFunction(
                    &machine,
                    worker.construction_function,
                    worker.construction_chunk,
                    &.{ worker.constructor, worker.second },
                    Value.undef(),
                    Value.undef(),
                ) catch return;
                if (!construction_out.isNumber()) return;
                sum += @intFromFloat(construction_out.asNum());
                const field_construction_out = vm.runFunction(
                    &machine,
                    worker.field_construction_function,
                    worker.field_construction_chunk,
                    &.{worker.second},
                    Value.undef(),
                    Value.undef(),
                ) catch return;
                if (!field_construction_out.isNumber()) return;
                sum += @intFromFloat(field_construction_out.asNum());
                const derived_construction_out = vm.runFunction(
                    &machine,
                    worker.derived_construction_function,
                    worker.derived_construction_chunk,
                    &.{worker.second},
                    Value.undef(),
                    Value.undef(),
                ) catch return;
                if (!derived_construction_out.isNumber()) return;
                sum += @intFromFloat(derived_construction_out.asNum());
            }
            worker.result.store(sum, .release);
        }
    };
    var workers: [lane_count]Worker = undefined;
    for (&workers, 0..) |*worker, lane| {
        const entry = inputs.atomicDenseElementLoad(lane) orelse return error.TestUnexpectedResult;
        const pair = entry.asObj();
        worker.* = .{
            .ctx = ctx,
            .function = function,
            .chunk = chunk,
            .invocation_function = invocation_function,
            .invocation_chunk = invocation_chunk,
            .property_function = property_function,
            .property_chunk = property_chunk,
            .call_function = call_function,
            .call_chunk = call_chunk,
            .constructor = constructor_value,
            .construction_function = construction_function,
            .construction_chunk = construction_chunk,
            .field_construction_function = field_construction_function,
            .field_construction_chunk = field_construction_chunk,
            .derived_construction_function = derived_construction_function,
            .derived_construction_chunk = derived_construction_chunk,
            .first = pair.atomicDenseElementLoad(0) orelse return error.TestUnexpectedResult,
            .second = pair.atomicDenseElementLoad(1) orelse return error.TestUnexpectedResult,
        };
    }
    var threads: [lane_count]std.Thread = undefined;
    for (&threads, 0..) |*thread, lane|
        thread.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[lane]});
    for (&threads) |*thread| thread.join();
    for (&workers, 0..) |*worker, lane| {
        const expected: i64 = @intCast(iterations * (552 + 238 * lane));
        try std.testing.expectEqual(expected, worker.result.load(.acquire));
    }
}

test "forced tree-walker and required bytecode preserve sloppy mapped arguments frames" {
    const source =
        \\function basic(a, b) {
        \\  var out = [];
        \\  arguments[0] = 10; out.push(a, arguments[0]);
        \\  b = 20; out.push(b, arguments[1]);
        \\  Object.defineProperty(arguments, "0", { value: 30 }); out.push(a, arguments[0]);
        \\  Object.defineProperty(arguments, "0", { writable: false }); a = 40; out.push(a, arguments[0]);
        \\  Object.defineProperty(arguments, "1", { get: function () { return 50; }, configurable: true });
        \\  b = 60; out.push(b, arguments[1]);
        \\  return out.join(",");
        \\}
        \\function duplicate(a, a) {
        \\  var out = [arguments[0], arguments[1], a];
        \\  a = 3; out.push(arguments[1]);
        \\  arguments[0] = 4; out.push(a);
        \\  arguments[1] = 5; out.push(a, arguments[0]);
        \\  return out.join(",");
        \\}
        \\function missing(a, b) { b = 7; return arguments.length + ":" + arguments[1] + ":" + b; }
        \\function extra(a) { a = 4; arguments[1] = 8; return arguments.length + ":" + arguments[0] + ":" + arguments[1]; }
        \\function arrowOwner(a) { var arrow = () => { a += 2; return arguments[0]; }; return arrow(); }
        \\function nestedOwner(a) { function inner(a) { arguments[0] = 9; return a; } return a + ":" + arguments[0] + ":" + inner(4); }
        \\function pair(a) { return [arguments, () => a, function (value) { a = value; return a; }]; }
        \\function onlyArguments(a) { a = { tag: "retained" }; return arguments; }
        \\function recursive(value) { if (value === 0) return arguments.length; return arguments[0] + recursive(value - 1); }
        \\var holder = { tag: "holder", method(value) { arguments[0] = value + 1; return this.tag + ":" + value; } };
        \\function Box(value) { arguments[0] = { tag: "box" }; this.value = value; }
        \\function thrower(error) { arguments[0] = { tag: "thrown" }; throw error; }
        \\function tail(value, remaining) { arguments[0] = value + 1; if (remaining === 0) return value; return tail(value, remaining - 1); }
        \\var escaped = pair({ tag: "first" });
        \\var only = onlyArguments({ tag: "discarded" });
        \\$vm.gc();
        \\escaped[0][0] = { tag: "second" };
        \\var sharedRead = escaped[1]().tag;
        \\escaped[2]({ tag: "third" });
        \\var objectRead = escaped[0][0].tag;
        \\delete escaped[0][0];
        \\escaped[2]({ tag: "fourth" });
        \\$vm.gc();
        \\var thrownTag = "";
        \\try { thrower({ tag: "initial" }); } catch (error) { thrownTag = error.tag; }
        \\basic(1, 2) + "|" + duplicate(1, 2) + "|" + missing(1) + "|" + extra(1, 2) + "|" +
        \\  arrowOwner(6) + "|" + nestedOwner(3) + "|" + sharedRead + ":" + objectRead + ":" +
        \\  (escaped[0][0] === undefined) + ":" + escaped[1]().tag + "|" + only[0].tag + "|" +
        \\  recursive(3) + "|" + holder.method(4) + "|" + (new Box(1)).value.tag + "|" + thrownTag + "|" + tail(1, 5);
    ;
    const expected = "10,10,20,20,30,30,40,30,60,50|1,2,2,3,3,5,4|1:undefined:7|2:4:8|8|3:3:9|second:third:true:fourth|retained|7|holder:5|box|thrown|7";
    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    var actual: [modes.len][]const u8 = undefined;
    var actual_len: usize = 0;
    defer for (actual[0..actual_len]) |entry| std.testing.allocator.free(entry);

    for (modes, 0..) |mode, index| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_gc = true,
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        const result = try ctx.evaluate(source);
        try std.testing.expect(result.isString());
        actual[index] = try std.testing.allocator.dupe(u8, result.asStr());
        actual_len += 1;
        if (mode == .required) {
            const inventory = ctx.bytecodeAdmissionSnapshot();
            try std.testing.expectEqual(@as(u64, 1), inventory.count(.program_compiled));
            try std.testing.expect(inventory.count(.template_plain_compiled) >= 10);
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.plain_policy_arguments));
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
        }
    }
    try std.testing.expectEqualStrings(actual[0], actual[1]);
    try std.testing.expectEqualStrings(expected, actual[1]);
}

test "moving GC relocates live severed and recycled mapped arguments cells" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .bytecode_execution_mode = .required,
    });
    defer ctx.destroy();

    _ = try ctx.evaluate(
        \\globalThis.mappedMoveDiscard = [];
        \\for (var i = 0; i < 4096; ++i) mappedMoveDiscard.push({ dead: i, nested: { value: i } });
        \\mappedMoveDiscard = null;
        \\function mappedPair(value) {
        \\  var object = arguments;
        \\  return {
        \\    object: object,
        \\    read: () => value,
        \\    write: function (next) { value = next; },
        \\    sever: function () { delete object[0]; }
        \\  };
        \\}
        \\function onlyArguments(value) { value = { tag: "recycled" }; return arguments; }
        \\globalThis.mappedMoveLive = mappedPair({ tag: "live" });
        \\globalThis.mappedMoveSevered = mappedPair({ tag: "initial" });
        \\mappedMoveSevered.sever();
        \\mappedMoveSevered.write({ tag: "severed" });
        \\globalThis.mappedMoveRecycled = onlyArguments({ tag: "discarded" });
    );
    ctx.collectGarbage();
    const compacted = ctx.compactGarbage();
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, compacted.status);
    try std.testing.expect(compacted.moved_cells > 0);

    const result = try ctx.evaluate(
        \\var before = mappedMoveLive.object[0].tag + ":" + mappedMoveLive.read().tag;
        \\mappedMoveLive.object[0] = { tag: "from-object" };
        \\var objectToFrame = mappedMoveLive.read().tag;
        \\mappedMoveLive.write({ tag: "from-frame" });
        \\before + ":" + objectToFrame + ":" + mappedMoveLive.object[0].tag + "|" +
        \\  (mappedMoveSevered.object[0] === undefined) + ":" + mappedMoveSevered.read().tag + "|" +
        \\  mappedMoveRecycled[0].tag;
    );
    try std.testing.expect(result.isString());
    try std.testing.expectEqualStrings(
        "live:live:from-object:from-frame|true:severed|recycled",
        result.asStr(),
    );
    const inventory = ctx.bytecodeAdmissionSnapshot();
    try std.testing.expectEqual(@as(u64, 2), inventory.count(.program_compiled));
    try std.testing.expectEqual(@as(u64, 0), inventory.count(.plain_policy_arguments));
    try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
}

test "required bytecode lowers nested disposal in parameter initializers" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = false,
        .bytecode_execution_mode = .required,
    });
    defer ctx.destroy();

    const result = try ctx.evaluate(
        \\globalThis.disposals = 0;
        \\var source = { [Symbol.dispose]() { disposals++; } };
        \\function needsParameterPrologue(value = function(){ using resource = source; return 37; }) { return value(); }
        \\needsParameterPrologue() + ":" + disposals;
    );
    try std.testing.expect(result.isString());
    try std.testing.expectEqualStrings("37:1", result.asStr());
    const inventory = ctx.bytecodeAdmissionSnapshot();
    try std.testing.expectEqual(@as(u64, 1), inventory.count(.program_compiled));
    try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_rejected_parameter_prologue));
    try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
}

test "forced tree-walker and required bytecode preserve base class instance initialization" {
    const source =
        \\var baseFieldOuter = 4;
        \\var baseFieldKeyCount = 0;
        \\var baseFieldSetterCount = 0;
        \\var baseFieldSymbol = Symbol("field");
        \\Object.prototype.baseFieldSuper = 11;
        \\var baseFieldKey = { [Symbol.toPrimitive]() { baseFieldKeyCount += 1; return "computed"; } };
        \\class BaseFieldActivation {
        \\  order = ["field"];
        \\  shadow = baseFieldOuter;
        \\  [baseFieldSymbol];
        \\  [baseFieldKey] = function() {};
        \\  privateName = function() {};
        \\  #secret = 6;
        \\  #privateName = function() {};
        \\  accessor auto = 7;
        \\  methodBrand = this.#method();
        \\  arrowThis = () => this;
        \\  directTarget = eval("new.target");
        \\  arrowTarget = () => this.directTarget;
        \\  superValue = super.baseFieldSuper;
        \\  gcValue = ($vm.gc(), 9);
        \\  shadowed = 8;
        \\  #method() { return 10; }
        \\  constructor(baseFieldOuter = (this.order.push("param"), this.shadow + 1)) {
        \\    this.order.push("body");
        \\    this.parameter = baseFieldOuter;
        \\  }
        \\  summary() {
        \\    var order = this.order === undefined ? "order-undefined" : this.order.join(",");
        \\    var computed = this.computed === undefined ? "computed-undefined" : this.computed.name;
        \\    var publicName = this.privateName === undefined ? "public-name-undefined" : this.privateName.name;
        \\    var privateName = this.#privateName === undefined ? "private-name-undefined" : this.#privateName.name;
        \\    return order + ":" + this.shadow + ":" + Object.prototype.hasOwnProperty.call(this, baseFieldSymbol) + ":" + (this[baseFieldSymbol] === undefined) + ":" + computed + ":" + publicName + ":" + privateName + ":" + this.#secret + ":" + this.auto + ":" + this.methodBrand + ":" + (this.arrowThis() === this) + ":" + (this.arrowTarget() === undefined) + ":" + (this.directTarget === undefined) + ":" + this.superValue + ":" + this.gcValue + ":" + this.shadowed + ":" + this.parameter;
        \\  }
        \\}
        \\Object.defineProperty(BaseFieldActivation.prototype, "shadowed", { set(value) { baseFieldSetterCount += value; }, configurable: true });
        \\class BaseFieldEvalRestriction { value = eval("arguments"); }
        \\class BaseFieldNonExtensible { stop = Object.preventExtensions(this); after = 1; }
        \\function baseFieldSummary() {
        \\  var instance = new BaseFieldActivation();
        \\  var evalError = "";
        \\  try { new BaseFieldEvalRestriction(); } catch (error) { evalError = error.name; }
        \\  var extensibleError = "";
        \\  try { new BaseFieldNonExtensible(); } catch (error) { extensibleError = error.name; }
        \\  return instance.summary() + "|" + baseFieldKeyCount + ":" + baseFieldSetterCount + ":" + Object.prototype.hasOwnProperty.call(instance, "shadowed") + "|" + evalError + ":" + extensibleError;
        \\}
    ;
    const expected = "field,param,body:4:true:true:computed:privateName:#privateName:6:7:10:true:true:true:11:9:8:5|1:0:true|SyntaxError:TypeError";
    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    var actual: [modes.len][]const u8 = undefined;
    var actual_len: usize = 0;
    defer for (actual[0..actual_len]) |entry| std.testing.allocator.free(entry);

    for (modes, 0..) |mode, index| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_gc = true,
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        _ = try ctx.evaluate(source);
        ctx.collectGarbage();
        _ = ctx.compactGarbage();
        if (mode == .required) {
            const constructor = try ctx.evaluate("BaseFieldActivation");
            const raw = constructor.asObj().jsFunction() orelse return error.TestUnexpectedResult;
            const function: *interp.Function = @ptrCast(@alignCast(raw));
            try std.testing.expectEqual(interp.BytecodeAdmissionReason.plain_compiled, function.bytecode_admission_reason);
            const chunk = function.chunk orelse return error.TestUnexpectedResult;
            var entered: ?usize = null;
            var public_fields: usize = 0;
            var private_fields: usize = 0;
            var exited: ?usize = null;
            for (chunk.code.items, 0..) |instruction, instruction_index| switch (instruction.op) {
                .enter_field_initializers => entered = instruction_index,
                .init_class_field => {
                    try std.testing.expect(entered != null and exited == null);
                    public_fields += 1;
                },
                .init_private_field => {
                    try std.testing.expect(entered != null and exited == null);
                    private_fields += 1;
                },
                .exit_field_initializers => exited = instruction_index,
                else => {},
            };
            try std.testing.expect(entered != null and exited != null and entered.? < exited.?);
            try std.testing.expectEqual(@as(usize, 12), public_fields);
            // The third private initialization is the auto-accessor's hidden
            // backing slot; it follows the same one-time brand path.
            try std.testing.expectEqual(@as(usize, 3), private_fields);
        }
        const result = try ctx.evaluate("baseFieldSummary()");
        try std.testing.expect(result.isString());
        actual[index] = try std.testing.allocator.dupe(u8, result.asStr());
        actual_len += 1;
        if (mode == .required) {
            const inventory = ctx.bytecodeAdmissionSnapshot();
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.plain_policy_class_constructor_semantics));
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
        }
    }
    try std.testing.expectEqualStrings(actual[0], actual[1]);
    try std.testing.expectEqualStrings(expected, actual[1]);
}

test "forced tree-walker and required bytecode preserve derived constructor activations" {
    const source =
        \\var derivedEffects = [];
        \\var derivedKeyCount = 0;
        \\var derivedKey = { [Symbol.toPrimitive]() { derivedKeyCount += 1; return "computed"; } };
        \\class DerivedBase {
        \\  constructor(value) { derivedEffects.push("base:" + value); this.base = value; this.target = new.target.name; }
        \\  get inherited() { return this.base + 10; }
        \\}
        \\class DerivedActivation extends DerivedBase {
        \\  order = (derivedEffects.push("field"), ["field"]);
        \\  [derivedKey] = function() {};
        \\  #secret = 3;
        \\  accessor auto = 4;
        \\  brand = this.#method();
        \\  fieldTarget = eval("new.target");
        \\  superValue = super.inherited;
        \\  gcField = ($vm.gc(), this.base + 1);
        \\  #method() { return 5; }
        \\  constructor(value, adjusted = value + 1) {
        \\    var before = "";
        \\    try { this.base; } catch (error) { before = error.name; }
        \\    derivedEffects.push("body-before");
        \\    var invoke = function(callback) { return callback(); };
        \\    var result = invoke(() => super(adjusted));
        \\    derivedEffects.push("body-after");
        \\    this.same = result === this;
        \\    this.before = before;
        \\  }
        \\  summary() { return this.base + ":" + this.target + ":" + this.order.join(",") + ":" + this.computed.name + ":" + this.#secret + ":" + this.auto + ":" + this.brand + ":" + (this.fieldTarget === undefined) + ":" + this.superValue + ":" + this.gcField + ":" + this.same + ":" + this.before; }
        \\}
        \\class DefaultDerived extends DerivedBase {}
        \\class DynamicFirst { constructor(value) { this.which = "first:" + value; } }
        \\class DynamicSecond { constructor(value) { this.which = "second:" + value; } }
        \\class DynamicDerived extends DynamicFirst { constructor() { super((Object.setPrototypeOf(DynamicDerived, DynamicSecond), 1)); } }
        \\var repeatedBaseCount = 0;
        \\class RepeatedBase { marker = 0; constructor() { repeatedBaseCount += 1; } }
        \\class RepeatedDerived extends RepeatedBase { constructor() { super(); try { super(); } catch (error) { this.repeated = error.name + ":" + repeatedBaseCount; } } }
        \\var skippedDerivedFieldCount = 0;
        \\class ReturnObjectDerived extends DerivedBase { skipped = (skippedDerivedFieldCount += 1); constructor() { return { object: true }; } }
        \\class MissingSuperDerived extends DerivedBase { constructor() {} }
        \\class PrimitiveReturnDerived extends DerivedBase { constructor() { return 1; } }
        \\class CaughtPrimitiveReturnDerived extends DerivedBase { constructor() { try { return 1; } catch (error) { return { caught: error.name }; } } }
        \\var nullSuperEffects = 0;
        \\class NullSuperDerived extends null { constructor() { super(nullSuperEffects += 1); } }
        \\class AlternateObjectBase { marker = 0; constructor() { return { alternate: true }; } }
        \\class AlternateObjectDerived extends AlternateObjectBase { field = 9; }
        \\class FinallyDerived extends DerivedBase { constructor() { try { return super(2); } finally { this.finalized = true; } } }
        \\var spreadIteratorReads = 0;
        \\class SpreadDerived extends DerivedBase { spreadField = 12; constructor(values) { super(...values); } }
        \\class ParameterSuperDerived extends DerivedBase { parameterField = 16; constructor(bound = super(12)) { this.parameterSame = bound === this; } }
        \\class ReentrantBase { constructor(depth) { this.depth = depth; if (depth > 0) this.inner = new ReentrantDerived(depth - 1); } }
        \\class ReentrantDerived extends ReentrantBase { reentrantField = 17; constructor(depth) { super(depth); } }
        \\var taggedSuperBaseCount = 0;
        \\class TaggedSuperBase { constructor() { taggedSuperBaseCount += 1; } }
        \\class TaggedSuperDerived extends TaggedSuperBase { constructor() { super[super()]``; } }
        \\function derivedSummary() {
        \\  var value = new DerivedActivation(6);
        \\  var originalIterator = Array.prototype[Symbol.iterator];
        \\  var iteratorReads = 0;
        \\  Array.prototype[Symbol.iterator] = function() { iteratorReads += 1; return originalIterator.call(this); };
        \\  var defaultValue = new DefaultDerived(8);
        \\  Array.prototype[Symbol.iterator] = originalIterator;
        \\  var dynamicFirst = new DynamicDerived();
        \\  var dynamicSecond = new DynamicDerived();
        \\  var repeated = new RepeatedDerived();
        \\  var returned = new ReturnObjectDerived();
        \\  var missing = "";
        \\  try { new MissingSuperDerived(); } catch (error) { missing = error.name; }
        \\  var primitive = "";
        \\  try { new PrimitiveReturnDerived(); } catch (error) { primitive = error.name; }
        \\  var caughtPrimitive = "";
        \\  try { new CaughtPrimitiveReturnDerived(); } catch (error) { caughtPrimitive = error.name; }
        \\  var nullSuper = "";
        \\  try { new NullSuperDerived(); } catch (error) { nullSuper = error.name; }
        \\  var alternate = new AlternateObjectDerived();
        \\  var finalized = new FinallyDerived();
        \\  var spread = new SpreadDerived({ [Symbol.iterator]() { spreadIteratorReads += 1; return [11][Symbol.iterator](); } });
        \\  var parameterSuper = new ParameterSuperDerived();
        \\  var reentrant = new ReentrantDerived(1);
        \\  var taggedSuper = "";
        \\  try { new TaggedSuperDerived(); } catch (error) { taggedSuper = error.name; }
        \\  return value.summary() + "|" + derivedEffects.join(",") + "|" + derivedKeyCount + "|" +
        \\    defaultValue.base + ":" + iteratorReads + "|" + dynamicFirst.which + ":" + dynamicSecond.which + "|" +
        \\    repeated.repeated + "|" + returned.object + ":" + skippedDerivedFieldCount + "|" + missing + ":" + primitive + ":" + caughtPrimitive + "|" +
        \\    nullSuper + ":" + nullSuperEffects + "|" + alternate.alternate + ":" + alternate.field + "|" + finalized.base + ":" + finalized.finalized + "|" + spread.base + ":" + spread.spreadField + ":" + spreadIteratorReads + "|" +
        \\    parameterSuper.base + ":" + parameterSuper.parameterField + ":" + parameterSuper.parameterSame + "|" + reentrant.depth + ":" + reentrant.reentrantField + ":" + reentrant.inner.depth + ":" + reentrant.inner.reentrantField + "|" + taggedSuper + ":" + taggedSuperBaseCount;
        \\}
    ;
    const expected = "7:DerivedActivation:field:computed:3:4:5:true:17:8:true:ReferenceError|body-before,base:7,field,body-after,base:8,base:2,base:11,base:12|1|8:0|first:1:second:1|ReferenceError:2|true:0|ReferenceError:TypeError:TypeError|TypeError:1|true:9|2:true|11:12:1|12:16:true|1:17:0:17|ReferenceError:0";
    const configurations = [_]struct {
        mode: interp.BytecodeExecutionMode,
        parallel_js: bool = false,
    }{
        .{ .mode = .tree_walker },
        .{ .mode = .required },
        .{ .mode = .required, .parallel_js = true },
    };
    var actual: [configurations.len][]const u8 = undefined;
    var actual_len: usize = 0;
    defer for (actual[0..actual_len]) |entry| std.testing.allocator.free(entry);
