        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_gc = true,
            .enable_threads = configuration.parallel_js,
            .parallel_gc = configuration.parallel_js,
            .parallel_js = configuration.parallel_js,
            .enable_jit = false,
            .bytecode_execution_mode = configuration.mode,
        });
        defer ctx.destroy();
        _ = try ctx.evaluate(source);
        ctx.collectGarbage();
        _ = ctx.compactGarbage();
        const result = try ctx.evaluate("derivedSummary()");
        try std.testing.expect(result.isString());
        actual[index] = try std.testing.allocator.dupe(u8, result.asStr());
        actual_len += 1;
        if (configuration.mode == .required) {
            const constructor = try ctx.evaluate("DerivedActivation");
            const raw = constructor.asObj().jsFunction() orelse return error.TestUnexpectedResult;
            const function: *interp.Function = @ptrCast(@alignCast(raw));
            try std.testing.expectEqual(interp.BytecodeAdmissionReason.plain_compiled, function.bytecode_admission_reason);
            const chunk = function.chunk orelse return error.TestUnexpectedResult;
            try std.testing.expect(chunk.is_derived_constructor);
            const inventory = ctx.bytecodeAdmissionSnapshot();
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.plain_policy_class_constructor_semantics));
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
        }
    }
    try std.testing.expectEqualStrings(actual[0], actual[1]);
    try std.testing.expectEqualStrings(actual[1], actual[2]);
    try std.testing.expectEqualStrings(expected, actual[1]);

    // Direct eval in a derived constructor now enters bytecode with the exact
    // live super constructor and shared this-initialization cell. Keep this
    // automatic-mode witness alongside the broader required-mode differential
    // so a stale causal admission barrier cannot return unnoticed.
    const automatic = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .bytecode_execution_mode = .automatic,
    });
    defer automatic.destroy();
    _ = try automatic.evaluate(
        \\class EvalDerivedBase { constructor(value) { this.base = value; } }
        \\class EvalDerived extends EvalDerivedBase { field = 15; constructor(value) { eval("super(value)"); } }
    );
    automatic.collectGarbage();
    _ = automatic.compactGarbage();
    try std.testing.expectEqual(@as(f64, 28), (try automatic.evaluate("var evalDerived = new EvalDerived(13); evalDerived.base + evalDerived.field")).asNum());
    const eval_constructor = try automatic.evaluate("EvalDerived");
    const eval_raw = eval_constructor.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const eval_function: *interp.Function = @ptrCast(@alignCast(eval_raw));
    try std.testing.expectEqual(interp.BytecodeAdmissionReason.plain_compiled, eval_function.bytecode_admission_reason);
    try std.testing.expect(eval_function.chunk != null);
    const automatic_inventory = automatic.bytecodeAdmissionSnapshot();
    try std.testing.expectEqual(@as(u64, 0), automatic_inventory.count(.plain_policy_class_constructor_semantics));
    try std.testing.expectEqual(@as(u64, 0), automatic_inventory.count(.template_plain_fallback));
}

test "native tiers apply derived constructor completion at the activation boundary" {
    if (!jit.supported or builtin.cpu.arch != .aarch64) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = true,
        .bytecode_execution_mode = .required,
    });
    defer ctx.destroy();
    try std.testing.expectEqualStrings("ReferenceError:TypeError", (try ctx.evaluate(
        \\class NativeCompletionBase {}
        \\class NativeMissingSuper extends NativeCompletionBase { constructor() {} }
        \\class NativePrimitiveReturn extends NativeCompletionBase { constructor() { return 42; } }
        \\function nativeCompletionName(Constructor) { try { new Constructor(); } catch (error) { return error.name; } return "none"; }
        \\var nativeMissing = "";
        \\var nativePrimitive = "";
        \\for (var nativeIndex = 0; nativeIndex < 16; nativeIndex += 1) {
        \\  nativeMissing = nativeCompletionName(NativeMissingSuper);
        \\  nativePrimitive = nativeCompletionName(NativePrimitiveReturn);
        \\}
        \\nativeMissing + ":" + nativePrimitive;
    )).asStr());

    const primitive_value = try ctx.evaluate("NativePrimitiveReturn");
    const primitive_raw = primitive_value.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const primitive_function: *interp.Function = @ptrCast(@alignCast(primitive_raw));
    const primitive_chunk = primitive_function.chunk orelse return error.TestUnexpectedResult;
    try std.testing.expect(primitive_chunk.tier.loadCode() != null or
        primitive_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) != null);
}

test "forced tree-walker and required bytecode preserve class heritage ordering" {
    const source =
        \\var heritageLog = "";
        \\function HeritageBase() {}
        \\var HeritageProxy = new Proxy(HeritageBase, {
        \\  get: function(target, key) {
        \\    if (key === "prototype") heritageLog = heritageLog + "h";
        \\    return Reflect.get(target, key);
        \\  }
        \\});
        \\function heritageKey() { heritageLog = heritageLog + "k"; return "method"; }
        \\var ProgramDerived = class ProgramDerived extends HeritageProxy {
        \\  [heritageKey()]() { return 1; }
        \\  static { heritageLog = heritageLog + "s"; }
        \\};
        \\function makePlain(base) {
        \\  return class PlainDerived extends base {
        \\    [heritageKey()]() { return 2; }
        \\    static { heritageLog = heritageLog + "s"; }
        \\  };
        \\}
        \\function namedHeritageTdz(Named) {
        \\  try { return class Named extends Named {}; }
        \\  catch (error) { return error.name; }
        \\}
        \\function invalidHeritage() {
        \\  var invalid = new Proxy(function InvalidBase() {}, {
        \\    get: function(target, key) {
        \\      if (key === "prototype") { heritageLog = heritageLog + "b"; return 1; }
        \\      return Reflect.get(target, key);
        \\    }
        \\  });
        \\  try { return class extends invalid { [heritageKey()]() {} }; }
        \\  catch (error) { return error.name; }
        \\}
        \\function strictHeritage() {
        \\  try { return class extends (heritageUndeclared = 1, HeritageProxy) {}; }
        \\  catch (error) { return error.name + ":" + typeof heritageUndeclared; }
        \\}
        \\function* strictSuspendedHeritage() {
        \\  return class extends (yield HeritageBase) {
        \\    [((yield "strict"), heritageSuspendedUndeclared = 1, "method")]() {}
        \\  };
        \\}
        \\function strictSuspension() {
        \\  var iterator = strictSuspendedHeritage();
        \\  iterator.next();
        \\  iterator.next(HeritageBase);
        \\  try { iterator.next(); }
        \\  catch (error) { return error.name + ":" + typeof heritageSuspendedUndeclared; }
        \\}
        \\function nullHeritage() {
        \\  var NullDerived = class extends null {};
        \\  return Object.getPrototypeOf(NullDerived) === Function.prototype &&
        \\    Object.getPrototypeOf(NullDerived.prototype) === null;
        \\}
        \\function selfNamedClass(SelfNamed) {
        \\  return class SelfNamed { static self() { return SelfNamed; } };
        \\}
        \\var PlainDerived = makePlain(HeritageProxy);
        \\var SelfNamed = selfNamedClass(null);
        \\var heritageResult =
        \\  Object.getPrototypeOf(ProgramDerived) === HeritageProxy &&
        \\  Object.getPrototypeOf(ProgramDerived.prototype) === HeritageBase.prototype &&
        \\  Object.getPrototypeOf(PlainDerived) === HeritageProxy &&
        \\  Object.getPrototypeOf(PlainDerived.prototype) === HeritageBase.prototype &&
        \\  namedHeritageTdz(null) === "ReferenceError" &&
        \\  invalidHeritage() === "TypeError" &&
        \\  strictHeritage() === "ReferenceError:undefined" && nullHeritage() &&
        \\  strictSuspension() === "ReferenceError:undefined" &&
        \\  SelfNamed.self() === SelfNamed &&
        \\  heritageLog === "hkshksb";
        \\heritageResult + ":" + heritageLog;
    ;

    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    for (modes) |mode| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        try std.testing.expectEqualStrings("true:hkshksb", (try ctx.evaluate(source)).asStr());
        const inventory = ctx.bytecodeAdmissionSnapshot();
        if (mode == .required) {
            try std.testing.expect(inventory.count(.program_compiled) > 0);
            try std.testing.expect(inventory.count(.template_plain_compiled) >= 5);
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
            try std.testing.expect(inventory.count(.template_generator_compiled) > 0);
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_generator_fallback));
        }
    }
}

test "required bytecode keeps prepared class heritage rooted across suspension" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .bytecode_execution_mode = .required,
    });
    defer ctx.destroy();
    ctx.collectGarbage();

    try std.testing.expect((try ctx.evaluate(
        \\function* suspendedHeritage() {
        \\  return class SuspendedDerived extends (yield "heritage") {
        \\    [yield "key"]() { return 7; }
        \\    self() { return SuspendedDerived; }
        \\  };
        \\}
        \\function SuspendedBase() {}
        \\SuspendedBase.prototype.marker = 42;
        \\globalThis.suspendedHeritageGets = 0;
        \\globalThis.suspendedHeritageCandidate = new Proxy(SuspendedBase, {
        \\  get: function(target, key) {
        \\    if (key === "prototype") suspendedHeritageGets = suspendedHeritageGets + 1;
        \\    return Reflect.get(target, key);
        \\  }
        \\});
        \\suspendedHeritageCandidate.staticMarker = 99;
        \\globalThis.suspendedHeritageIterator = suspendedHeritage();
        \\suspendedHeritageIterator.next().value === "heritage" &&
        \\  suspendedHeritageIterator.next(suspendedHeritageCandidate).value === "key" &&
        \\  suspendedHeritageGets === 1;
    )).asBool());
    _ = try ctx.evaluate("suspendedHeritageCandidate = null; SuspendedBase = null;");

    const compacted = ctx.collectYoungAfterRootValidation(ctx.gc.?);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, compacted.status);
    try std.testing.expect(compacted.moved_cells > 0);
    try std.testing.expect((try ctx.evaluate(
        \\var suspendedHeritageResult = suspendedHeritageIterator.next("method");
        \\suspendedHeritageResult.done &&
        \\  suspendedHeritageGets === 1 &&
        \\  Object.getPrototypeOf(suspendedHeritageResult.value).staticMarker === 99 &&
        \\  Object.getPrototypeOf(suspendedHeritageResult.value.prototype).marker === 42 &&
        \\  suspendedHeritageResult.value.prototype.method() === 7 &&
        \\  suspendedHeritageResult.value.prototype.self() === suspendedHeritageResult.value;
    )).asBool());
    const inventory = ctx.bytecodeAdmissionSnapshot();
    try std.testing.expect(inventory.count(.template_generator_compiled) > 0);
    try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_generator_fallback));
}

test "forced tree-walker and required bytecode preserve exception and side effects" {
    const source =
        \\globalThis.tierBeforeThrow = 0;
        \\function tierThrow(seed) {
        \\  "use strict";
        \\  globalThis.tierBeforeThrow = seed * 2;
        \\  throw new TypeError("tier-boom");
        \\}
        \\tierThrow(9);
    ;
    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    var side_effects: [modes.len]u64 = undefined;

    for (modes, 0..) |mode, index| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();

        try std.testing.expectError(error.Throw, ctx.evaluate(source));
        const exception = ctx.exception orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("TypeError", exception.asObj().errorName());
        try std.testing.expectEqualStrings("tier-boom", exception.asObj().getOwn("message").?.asStr());
        side_effects[index] = (try ctx.evaluate("tierBeforeThrow")).rawBits();

        const inventory = ctx.bytecodeAdmissionSnapshot();
        switch (mode) {
            .tree_walker => {
                try std.testing.expectEqual(@as(u64, 2), inventory.count(.program_forced_tree_walker));
                try std.testing.expectEqual(@as(u64, 1), inventory.count(.plain_forced_tree_walker));
            },
            .required => {
                try std.testing.expectEqual(@as(u64, 2), inventory.count(.program_compiled));
                try std.testing.expectEqual(@as(u64, 1), inventory.count(.template_plain_compiled));
            },
            .automatic => unreachable,
        }
    }

    try std.testing.expectEqual(side_effects[0], side_effects[1]);
}

test "forced tree-walker and required bytecode preserve lexical TDZ and const semantics" {
    const cases = [_]struct {
        source: []const u8,
        exception_name: []const u8,
        state: []const u8,
    }{
        .{
            .source =
            \\globalThis.lexicalTrace = [];
            \\function directTdz() { "use strict"; lexicalTrace.push("before"); return value; let value = 1; }
            \\directTdz();
            ,
            .exception_name = "ReferenceError",
            .state = "before",
        },
        .{
            .source =
            \\globalThis.lexicalTrace = [];
            \\function capturedTdz() {
            \\  "use strict";
            \\  function read() { return value; }
            \\  lexicalTrace.push("captured");
            \\  read();
            \\  let value = 1;
            \\}
            \\capturedTdz();
            ,
            .exception_name = "ReferenceError",
            .state = "captured",
        },
        .{
            .source =
            \\globalThis.lexicalTrace = [];
            \\function capturedConstTdz() {
            \\  "use strict";
            \\  function write() { fixed = 4; }
            \\  lexicalTrace.push("captured-const-tdz");
            \\  write();
            \\  const fixed = 3;
            \\}
            \\capturedConstTdz();
            ,
            .exception_name = "ReferenceError",
            .state = "captured-const-tdz",
        },
        .{
            .source =
            \\globalThis.lexicalTrace = [];
            \\function assignmentTdz() { "use strict"; lexicalTrace.push("assign"); let value = (value = 1); }
            \\assignmentTdz();
            ,
            .exception_name = "ReferenceError",
            .state = "assign",
        },
        .{
            .source =
            \\globalThis.lexicalTrace = [];
            \\function typeofTdz() { "use strict"; lexicalTrace.push("typeof"); return typeof value; let value = 1; }
            \\typeofTdz();
            ,
            .exception_name = "ReferenceError",
            .state = "typeof",
        },
        .{
            .source =
            \\globalThis.lexicalTrace = [];
            \\function forOfHeadTdz() {
            \\  "use strict";
            \\  lexicalTrace.push("for-of-head");
            \\  for (let value of value) {}
            \\}
            \\forOfHeadTdz();
            ,
            .exception_name = "ReferenceError",
            .state = "for-of-head",
        },
        .{
            .source =
            \\globalThis.lexicalTrace = [];
            \\function constWrite() { "use strict"; const fixed = 3; lexicalTrace.push("initialized"); fixed = 4; }
            \\constWrite();
            ,
            .exception_name = "TypeError",
            .state = "initialized",
        },
        .{
            .source =
            \\globalThis.lexicalTrace = [];
            \\function capturedConstWrite() {
            \\  "use strict";
            \\  const fixed = 3;
            \\  function write() { fixed = 4; }
            \\  lexicalTrace.push("captured-const");
            \\  write();
            \\}
            \\capturedConstWrite();
            ,
            .exception_name = "TypeError",
            .state = "captured-const",
        },
    };

    for (cases) |case| {
        const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
        for (modes) |mode| {
            const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
                .enable_jit = false,
                .bytecode_execution_mode = mode,
            });
            defer ctx.destroy();

            try std.testing.expectError(error.Throw, ctx.evaluate(case.source));
            const exception = ctx.exception orelse return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings(case.exception_name, exception.asObj().errorName());
            try std.testing.expectEqualStrings(case.state, (try ctx.evaluate("lexicalTrace.join(',')")).asStr());
            if (mode == .required) {
                const inventory = ctx.bytecodeAdmissionSnapshot();
                try std.testing.expect(inventory.count(.template_plain_compiled) > 0);
                try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
            }
        }
    }

    try verifyForcedPlainDifferential(
        \\globalThis.lexicalTrace = [];
        \\function repeatedTdz() {
        \\  "use strict";
        \\  for (var i = 0; i < 2; i = i + 1) {
        \\    try { lexicalTrace.push(typeof value); }
        \\    catch (error) { lexicalTrace.push(error.name); }
        \\    let value = i;
        \\  }
        \\  return lexicalTrace.length;
        \\}
        \\repeatedTdz();
    , "lexicalTrace.join(',')");

    try verifyForcedPlainDifferential(
        \\globalThis.lexicalTrace = [];
        \\function mutableAfterTdz() {
        \\  "use strict";
        \\  try { value; } catch (error) { lexicalTrace.push(error.name); }
        \\  let value = 1;
        \\  value = 2;
        \\  lexicalTrace.push(value);
        \\  return value;
        \\}
        \\mutableAfterTdz();
    , "lexicalTrace.join(',')");
}

test "block functions preserve lexical and Annex B identity in required bytecode" {
    const cases = [_]struct { source: []const u8, expected: []const u8 }{
        .{
            .source =
            \\(function () {
            \\  "use strict";
            \\  var read, initial;
            \\  { initial = f(); function f() { return 3; } read = function () { return f; }; f = 9; }
            \\  return initial + ":" + read() + ":" + typeof f;
            \\})();
            ,
            .expected = "3:9:undefined",
        },
        .{
            .source =
            \\(function () {
            \\  var read;
            \\  { f = 6; function f() {} read = function () { return f; }; f = 7; }
            \\  return f + ":" + read();
            \\})();
            ,
            .expected = "6:7",
        },
        .{
            .source =
            \\(function () {
            \\  var read, inside;
            \\  { read = f; function f() { return 1; } f = 9; function f() { return 2; } inside = f; }
            \\  return read() + ":" + inside + ":" + f;
            \\})();
            ,
            .expected = "2:9:9",
        },
        .{
            .source =
            \\(function () {
            \\  var first, second;
            \\  { function f() { return f.value; } f.value = 1; first = f; }
            \\  { function f() { return f.value; } f.value = 2; second = f; }
            \\  return first() + ":" + second() + ":" + (first !== second);
            \\})();
            ,
            .expected = "1:2:true",
        },
        .{
            .source =
            \\(function () {
            \\  var f = 17, seen;
            \\  switch (f) {
            \\    case (seen = f(), 17): function f() { return 1; } f = 4;
            \\    default: function f() { return 2; }
            \\  }
            \\  return seen + ":" + f;
            \\})();
            ,
            .expected = "2:4",
        },
        .{
            .source = "(function () { switch (8) { case 0: function hidden() {} } return typeof hidden; })();",
            .expected = "undefined",
        },
        .{
            .source =
            \\(function (f) {
            \\  var before = f;
            \\  { function f() { return 3; } if (f() !== 3) throw 1; }
            \\  return before + ":" + f;
            \\})(12);
            ,
            .expected = "12:12",
        },
        .{
            .source =
            \\(function () {
            \\  let unused, { f } = { f: 11 };
            \\  { function f() { return 3; } if (f() !== 3) throw 1; }
            \\  return "" + f;
            \\})();
            ,
            .expected = "11",
        },
        .{
            .source = "(function () { var before = arguments; { function arguments() {} } return '' + (before === arguments); })(1);",
            .expected = "true",
        },
        .{
            .source =
            \\(function () {
            \\  var before = outer();
            \\  label: function outer() { return 2; }
            \\  { innerLabel: function inner() { return 3; } }
            \\  if (false) function absent() {}
            \\  if (true) function present() { return 4; }
            \\  return before + ":" + inner() + ":" + present() + ":" + typeof absent;
            \\})();
            ,
            .expected = "2:3:4:undefined",
        },
        .{
            .source =
            \\(function () {
            \\  var object = { f: 23 }, seen, read;
            \\  with (object) {
            \\    { function f() { return 3; } seen = f(); read = function () { return f; }; f = 8; }
            \\  }
            \\  return seen + ":" + f() + ":" + read() + ":" + object.f;
            \\})();
            ,
            .expected = "3:3:8:23",
        },
        .{
            .source =
            \\(function () {
            \\  var outer = { value: 20 }, inner = { value: 30 }, result;
            \\  with (outer) { let value = 2; var read = function () { return value; };
            \\    with (inner) { value += 1; }
            \\    value += 3; result = value + ":" + read() + ":" + (delete value);
            \\  }
            \\  return result + ":" + outer.value + ":" + inner.value;
            \\})();
            ,
            .expected = "5:5:false:20:31",
        },
        .{
            .source =
            \\(function () {
            \\  var reads = [];
            \\  for (var i = 0; i < 4; i++) {
            \\    function f() { return f.value; }
            \\    f.value = i;
            \\    reads.push(f);
            \\    if (i === 1) continue;
            \\  }
            \\  return reads.map(function (read) { return read(); }).join(":");
            \\})();
            ,
            .expected = "0:1:2:3",
        },
        .{
            .source =
            \\(function () {
            \\  var reads = [];
            \\  for (var i = 0; i < 3; i++) {
            \\    try { throw i; } catch (caught) {
            \\      { function f() { return caught; } reads.push(f); }
            \\    } finally { function finished() { return 7; } }
            \\  }
            \\  return reads.map(function (read) { return read(); }).join(":") + ":" + finished();
            \\})();
            ,
            .expected = "0:1:2:7",
        },
        .{
            .source =
            \\(function () {
            \\  var read;
            \\  { function f() { return 1; } read = eval("(function () { return f; })"); eval("f = 8"); }
            \\  return f() + ":" + read();
            \\})();
            ,
            .expected = "1:8",
        },
    };
    for (cases) |case| for ([_]interp.BytecodeExecutionMode{ .tree_walker, .required }) |mode| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();
        const result = ctx.evaluate(case.source) catch |err| {
            std.debug.print("block-function case ({s}): {s}\n", .{ @tagName(mode), case.source });
            return err;
        };
        try std.testing.expect(result.isString());
        std.testing.expectEqualStrings(case.expected, result.asStr()) catch |err| {
            std.debug.print("block-function case ({s}): {s}\n", .{ @tagName(mode), case.source });
            return err;
        };
        if (mode == .required) {
            const inventory = ctx.bytecodeAdmissionSnapshot();
            try std.testing.expectEqual(@as(u64, 1), inventory.count(.program_compiled));
            try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
        }
    };
}

