    try std.testing.expectEqual(@as(f64, 17), result.asNum());
    _ = try ctx.evaluate("globalThis.compiledNestedFromHost = compiledHostHelper();");
    const nested_value = ctx.global_object.getOwn("compiledNestedFromHost") orelse return error.TestUnexpectedResult;
    const nested: *interp.Function = @ptrCast(@alignCast(nested_value.asObj().jsFunction() orelse return error.TestUnexpectedResult));
    try std.testing.expectEqual(interp.BytecodeExecutionMode.automatic, nested.bytecode_execution_mode);
    try std.testing.expectEqual(@as(f64, 23), (try ctx.evaluate("compiledNestedFromHost();")).asNum());
}

fn verifyForcedPlainDifferential(source: []const u8, state_expression: []const u8) !void {
    const modes = [_]interp.BytecodeExecutionMode{ .tree_walker, .required };
    var results: [modes.len]u64 = undefined;
    var states: [modes.len]?[]u8 = @splat(null);
    defer for (states) |state| if (state) |owned| std.testing.allocator.free(owned);

    for (modes, 0..) |mode, index| {
        const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
            .enable_jit = false,
            .bytecode_execution_mode = mode,
        });
        defer ctx.destroy();

        results[index] = (try ctx.evaluate(source)).rawBits();
        states[index] = try std.testing.allocator.dupe(u8, (try ctx.evaluate(state_expression)).asStr());
        const inventory = ctx.bytecodeAdmissionSnapshot();
        switch (mode) {
            .tree_walker => {
                try std.testing.expectEqual(@as(u64, 2), inventory.count(.program_forced_tree_walker));
                try std.testing.expect(inventory.count(.plain_forced_tree_walker) > 0);
                try std.testing.expectEqual(@as(u64, 0), inventory.count(.program_compiled));
            },
            .required => {
                try std.testing.expectEqual(@as(u64, 2), inventory.count(.program_compiled));
                try std.testing.expectEqual(@as(u64, 0), inventory.count(.program_forced_tree_walker));
                try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
            },
            .automatic => unreachable,
        }
    }

    try std.testing.expectEqual(results[0], results[1]);
    try std.testing.expectEqualStrings(states[0].?, states[1].?);
}

test "forced tier differential covers catch, class, and method home-object scope" {
    try verifyForcedPlainDifferential(
        \\globalThis.catchTrace = [];
        \\function forcedCatch(seed) {
        \\  "use strict";
        \\  var total = 0;
        \\  try {
        \\    throw seed;
        \\  } catch (caught) {
        \\    total = caught + 1;
        \\    catchTrace.push("catch:" + caught);
        \\  } finally {
        \\    total = total + 3;
        \\    catchTrace.push("finally:" + total);
        \\  }
        \\  return total;
        \\}
        \\forcedCatch(7);
    , "catchTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.catchScopeTrace = [];
        \\function catchScopeAdmissionWitness() { return 1; }
        \\catchScopeAdmissionWitness();
        \\try { throw 5; } catch (scopedCatch) { catchScopeTrace.push("inside:" + scopedCatch); }
        \\try { scopedCatch; } catch (error) { catchScopeTrace.push("outside:" + error.name); }
    , "catchScopeTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.catchPatternTrace = [];
        \\function forcedCatchPatterns() {
        \\  "use strict";
        \\  var reads = [], keyCalls = 0;
        \\  function key() {
        \\    return { toString: function () { keyCalls++; return "code"; } };
        \\  }
        \\  for (var index = 0; index < 2; index++) {
        \\    try { throw {code: index, tail: index + 10}; }
        \\    catch ({[key()]: code = 7, missing: named = function () {}, nested: {value = code + 1} = {}, ...meta}) {
        \\      reads.push(function () { return code + ":" + named.name + ":" + value + ":" + meta.tail; });
        \\    } finally { catchPatternTrace.push("finally:" + index); }
        \\  }
        \\  catchPatternTrace.push(reads.map(function (read) { return read(); }).join(","));
        \\  catchPatternTrace.push("keys:" + keyCalls);
        \\}
        \\forcedCatchPatterns();
    , "catchPatternTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.catchPatternTrace = [];
        \\function catchPatternTdz() {
        \\  "use strict";
        \\  try {
        \\    try { throw {}; } catch ({left = right, right = 1}) {}
        \\  } catch (error) { catchPatternTrace.push("tdz:" + error.name); }
        \\}
        \\catchPatternTdz();
    , "catchPatternTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.catchPatternTrace = [];
        \\function failBinding() {
        \\  "use strict";
        \\  try {
        \\    try { throw {}; }
        \\    catch ({missing = doesNotExist()}) { catchPatternTrace.push("body"); }
        \\    finally { catchPatternTrace.push("binding-finally"); }
        \\  } catch (error) { catchPatternTrace.push("binding:" + error.name); }
        \\}
        \\failBinding();
    , "catchPatternTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.catchPatternTrace = [];
        \\function closeFailedCatchPattern() {
        \\  "use strict";
        \\  var iterable = {
        \\    [Symbol.iterator]: function () {
        \\      return {
        \\        next: function () { return {value: undefined, done: false}; },
        \\        return: function () { catchPatternTrace.push("close"); return {}; }
        \\      };
        \\    }
        \\  };
        \\  try {
        \\    try { throw iterable; }
        \\    catch ([value = missingCatchDefault()]) { catchPatternTrace.push("body"); }
        \\    finally { catchPatternTrace.push("iterator-finally"); }
        \\  } catch (error) { catchPatternTrace.push("iterator:" + error.name); }
        \\}
        \\closeFailedCatchPattern();
    , "catchPatternTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.catchPatternTrace = [];
        \\function abruptCatchPatterns() {
        \\  "use strict";
        \\  for (var index = 0; index < 4; index++) {
        \\    try { throw {value: index}; }
        \\    catch ({value}) {
        \\      catchPatternTrace.push("catch:" + value);
        \\      if (value === 0) continue;
        \\      if (value === 2) break;
        \\    } finally { catchPatternTrace.push("abrupt-finally:" + index); }
        \\  }
        \\}
        \\abruptCatchPatterns();
    , "catchPatternTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.catchPatternTrace = [];
        \\function returnThroughFinally() {
        \\  "use strict";
        \\  try { throw {value: 13}; }
        \\  catch ({value}) { return value; }
        \\  finally { catchPatternTrace.push("return-finally"); }
        \\}
        \\catchPatternTrace.push("return:" + returnThroughFinally());
    , "catchPatternTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.classTrace = [];
        \\function forcedClass(seed) {
        \\  "use strict";
        \\  class Box {
        \\    constructor(value) { this.value = value; classTrace.push("ctor:" + value); }
        \\    read() { classTrace.push("read:" + this.value); return this.value; }
        \\  }
        \\  var box = new Box(seed);
        \\  return box.read() + 1;
        \\}
        \\forcedClass(11);
    , "classTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\globalThis.privateTrace = [];
        \\function forcedPrivateClass(seed) {
        \\  "use strict";
        \\  class Secret {
        \\    constructor(value) { this.value = value; }
        \\    #value() { privateTrace.push("private:" + this.value); return this.value; }
        \\    read() { return this.#value() + 1; }
        \\  }
        \\  return new Secret(seed).read();
        \\}
        \\forcedPrivateClass(13);
    , "privateTrace.join('|')");

    try verifyForcedPlainDifferential(
        \\"use strict";
        \\globalThis.superTrace = [];
        \\globalThis.superBase = {
        \\  value: 4,
        \\  read(step) { superTrace.push("base:" + this.value); return this.value + step; }
        \\};
        \\globalThis.superObject = {
        \\  __proto__: superBase,
        \\  value: 9,
        \\  read(step) {
        \\    superTrace.push("derived:" + this.value);
        \\    return super.read(step) + super.read(1);
        \\  }
        \\};
        \\superObject.read(3);
    , "superTrace.join('|')");
}

test "required bytecode reads live configurable globals across realms" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = false,
        .bytecode_execution_mode = .required,
    });
    defer ctx.destroy();

    try std.testing.expect((try ctx.evaluate(
        \\var other = $262.createRealm().global;
        \\other.eval(`
        \\  var receiver = {};
        \\  var observed = false;
        \\  var target = {
        \\    set value(input) {
        \\      "use strict";
        \\      Math.abs(input);
        \\      observed = this === receiver;
        \\    }
        \\  };
        \\`);
        \\Reflect.set(other.target, "value", 1, other.receiver);
        \\var replacement = {};
        \\other.receiver = replacement;
        \\Reflect.set(other.target, "value", 2, replacement);
        \\other.observed;
    )).asBool());

    const inventory = ctx.bytecodeAdmissionSnapshot();
    try std.testing.expect(inventory.count(.plain_compiled) > 0);
    try std.testing.expectEqual(@as(u64, 0), inventory.count(.template_plain_fallback));
}

test "bytecode admission inventory merges concurrent realm records" {
    if (builtin.single_threaded) return error.SkipZigTest;
    var inventory = interp.BytecodeAdmissionInventory{};
    const Worker = struct {
        inventory: *interp.BytecodeAdmissionInventory,

        fn run(self: *@This()) void {
            for (0..10_000) |_| {
                self.inventory.record(.plain_compiled);
                self.inventory.record(.plain_rejected_temporal_dead_zone);
            }
        }
    };
    var workers: [4]Worker = undefined;
    var threads: [workers.len]std.Thread = undefined;
    for (&workers, &threads) |*worker, *thread| {
        worker.* = .{ .inventory = &inventory };
        thread.* = try std.Thread.spawn(.{}, Worker.run, .{worker});
    }
    for (threads) |thread| thread.join();

    const snapshot = inventory.snapshot();
    try std.testing.expectEqual(@as(u64, 40_000), snapshot.count(.plain_compiled));
    try std.testing.expectEqual(@as(u64, 40_000), snapshot.count(.plain_rejected_temporal_dead_zone));
    try std.testing.expectEqual(@as(u64, 0), snapshot.count(.program_compiled));
}

test "required bytecode quickens stable Number sites after the bounded threshold" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
