test "Number-specialized misses dequicken once without replaying coercion or throws" {
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = false,
        .profile_execution_tiers = true,
        .bytecode_execution_mode = .required,
    });
    defer ctx.destroy();
    _ = try ctx.evaluate(
        \\var quickEffects = 0;
        \\var quickCaught = 0;
        \\var quickAbrupt = { valueOf() { quickEffects = quickEffects + 1; throw 97; } };
        \\var quickOrdinary = { valueOf() { quickEffects = quickEffects + 1; return 42; } };
        \\function quickAddMiss(left, right) { return left + right; }
        \\function quickSubMiss(left, right) { return left - right; }
    );
    for (0..bc.QuickBinaryState.number_threshold) |_| {
        try std.testing.expectEqual(@as(f64, 42), (try ctx.evaluate("quickAddMiss(40, 2)")).asNum());
        try std.testing.expectEqual(@as(f64, 38), (try ctx.evaluate("quickSubMiss(40, 2)")).asNum());
    }

    try std.testing.expectEqual(@as(f64, 97), (try ctx.evaluate(
        "try { quickAddMiss(quickAbrupt, 2); } catch (error) { quickCaught = error; } quickCaught;",
    )).asNum());
    try std.testing.expectEqual(@as(f64, 40), (try ctx.evaluate("quickSubMiss(quickOrdinary, 2)")).asNum());
    try std.testing.expectEqual(@as(f64, 2), (try ctx.evaluate("quickEffects")).asNum());

    // Both sites are now terminal generic. Later Number inputs retain the
    // ordinary inline Number path but cannot republish specialization.
    try std.testing.expectEqual(@as(f64, 3), (try ctx.evaluate("quickAddMiss(1, 2)")).asNum());
    try std.testing.expectEqual(@as(f64, 3), (try ctx.evaluate("quickSubMiss(5, 2)")).asNum());
    const snapshot = ctx.tierAttributionSnapshot();
    try std.testing.expectEqual(@as(u64, 0), snapshot.quick_binary.count(.number_hits));
    try std.testing.expectEqual(@as(u64, 2), snapshot.quick_binary.count(.number_misses));
    try std.testing.expectEqual(@as(u64, 2), snapshot.quick_binary.count(.dequickenings));
}

test "tree walker and VM binary quickening modes preserve every operator and control" {
    const source =
        \\function qbAdd(a, b) { return a + b; }
        \\function qbSub(a, b) { return a - b; }
        \\function qbMul(a, b) { return a * b; }
        \\function qbDiv(a, b) { return a / b; }
        \\function qbMod(a, b) { return a % b; }
        \\function qbPow(a, b) { return a ** b; }
        \\function qbLt(a, b) { return a < b; }
        \\function qbLe(a, b) { return a <= b; }
        \\function qbGt(a, b) { return a > b; }
        \\function qbGe(a, b) { return a >= b; }
        \\function qbEq(a, b) { return a == b; }
        \\function qbNeq(a, b) { return a != b; }
        \\function qbStrictEq(a, b) { return a === b; }
        \\function qbStrictNeq(a, b) { return a !== b; }
        \\function qbAnd(a, b) { return a & b; }
        \\function qbOr(a, b) { return a | b; }
        \\function qbXor(a, b) { return a ^ b; }
        \\function qbShl(a, b) { return a << b; }
        \\function qbShr(a, b) { return a >> b; }
        \\function qbUshr(a, b) { return a >>> b; }
        \\function qbIn(a, b) { return a in b; }
        \\function qbWarm() {
        \\  var sink = 0;
        \\  for (var i = 0; i < 12; i = i + 1) {
        \\    sink = sink + qbAdd(13.5, 3) + qbSub(13.5, 3) + qbMul(13.5, 3);
        \\    sink = sink + qbDiv(13.5, 3) + qbMod(13.5, 3) + qbPow(2, 8);
        \\    sink = sink + Number(qbLt(13.5, 3)) + Number(qbLe(13.5, 3));
        \\    sink = sink + Number(qbGt(13.5, 3)) + Number(qbGe(13.5, 3));
        \\    sink = sink + Number(qbEq(13.5, 3)) + Number(qbNeq(13.5, 3));
        \\    sink = sink + Number(qbStrictEq(13.5, 3)) + Number(qbStrictNeq(13.5, 3));
        \\    sink = sink + qbAnd(13, 3) + qbOr(13, 3) + qbXor(13, 3);
        \\    sink = sink + qbShl(13, 3) + qbShr(13, 3) + qbUshr(13, 3);
        \\  }
        \\  return sink;
        \\}
        \\function qbProbe() {
        \\  var effects = 0;
        \\  var coerced = { valueOf() { effects = effects + 1; return 11; } };
        \\  var bigintError = "";
        \\  var symbolError = "";
        \\  try { qbAdd(1n, 1); } catch (error) { bigintError = error.name; }
        \\  try { qbMul(Symbol("quick"), 2); } catch (error) { symbolError = error.name; }
        \\  return String(qbAdd(13.5, 3)) + "|" + String(qbSub(13.5, 3)) + "|" +
        \\    String(qbMul(13.5, 3)) + "|" + String(qbDiv(13.5, 3)) + "|" +
        \\    String(qbMod(13.5, 3)) + "|" + String(qbPow(2, 8)) + "|" +
        \\    String(qbLt(13.5, 3)) + "|" + String(qbLe(13.5, 3)) + "|" +
        \\    String(qbGt(13.5, 3)) + "|" + String(qbGe(13.5, 3)) + "|" +
        \\    String(qbEq(13.5, 3)) + "|" + String(qbNeq(13.5, 3)) + "|" +
        \\    String(qbStrictEq(13.5, 3)) + "|" + String(qbStrictNeq(13.5, 3)) + "|" +
        \\    String(qbAnd(13, 3)) + "|" + String(qbOr(13, 3)) + "|" +
        \\    String(qbXor(13, 3)) + "|" + String(qbShl(13, 3)) + "|" +
        \\    String(qbShr(13, 3)) + "|" + String(qbUshr(13, 3)) + "|" +
        \\    String(qbIn("owned", { owned: true })) + "|" +
        \\    String(Object.is(qbAdd(-0, -0), -0)) + "|" +
        \\    String(qbDiv(1, -0) === -Infinity) + "|" +
        \\    String(Object.is(qbMod(-0, 3), -0)) + "|" +
        \\    String(Number.isNaN(qbPow(-1, Infinity))) + "|" +
        \\    qbAdd("quick", 2) + "|" + String(qbSub(coerced, 2)) + "|" +
        \\    bigintError + "|" + symbolError + "|" + String(effects);
        \\}
    ;

    const tree = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = false,
        .bytecode_execution_mode = .tree_walker,
    });
    defer tree.destroy();
    const ordinary = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = false,
        .profile_execution_tiers = true,
        .bytecode_execution_mode = .required,
        .bytecode_binary_quickening = false,
    });
    defer ordinary.destroy();
    const quick = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = false,
        .profile_execution_tiers = true,
        .bytecode_execution_mode = .required,
    });
    defer quick.destroy();

    _ = try tree.evaluate(source);
    _ = try ordinary.evaluate(source);
    _ = try quick.evaluate(source);
    const tree_warm = try tree.evaluate("qbWarm()");
    const ordinary_warm = try ordinary.evaluate("qbWarm()");
    const quick_warm = try quick.evaluate("qbWarm()");
    try std.testing.expectEqual(tree_warm.rawBits(), ordinary_warm.rawBits());
    try std.testing.expectEqual(tree_warm.rawBits(), quick_warm.rawBits());

    const tree_result = try tree.evaluate("qbProbe()");
    const ordinary_result = try ordinary.evaluate("qbProbe()");
    const quick_result = try quick.evaluate("qbProbe()");
    try std.testing.expectEqualStrings(tree_result.asStr(), ordinary_result.asStr());
    try std.testing.expectEqualStrings(tree_result.asStr(), quick_result.asStr());

    const ordinary_snapshot = ordinary.tierAttributionSnapshot();
    const quick_snapshot = quick.tierAttributionSnapshot();
    try std.testing.expectEqual(
        ordinary_snapshot.execution.count(.vm_dispatches),
        quick_snapshot.execution.count(.vm_dispatches),
    );
    try std.testing.expect(quick_snapshot.quick_binary.count(.number_hits) > 0);
    try std.testing.expectEqual(@as(u64, 3), quick_snapshot.quick_binary.count(.number_misses));
    try std.testing.expectEqual(@as(u64, 3), quick_snapshot.quick_binary.count(.dequickenings));
    inline for (comptime std.meta.tags(interp.QuickBinaryMetric)) |metric|
        try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.quick_binary.count(metric));
}

test "tier attribution is opt-in and separates execution runtime and host boundaries" {
    const ordinary = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ordinary.destroy();
    _ = try ordinary.evaluate(
        \\function ordinaryTree() { return arguments[0]; }
        \\try { ordinaryTree(1); } catch (error) {}
    );
    const ordinary_snapshot = ordinary.tierAttributionSnapshot();
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.tree_walker_entries));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.vm_entries));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.vm_dispatches));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.vm_quick_kernel_hits));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.baseline_entries));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.optimizer_entries));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.runtime_operation_calls));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.host_callbacks));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.wasm_dispatches));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.execution.count(.environment_allocations));
    inline for (comptime std.meta.tags(interp.QuickBinaryMetric)) |metric|
        try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.quick_binary.count(metric));
    inline for (comptime std.meta.fieldNames(interp.DebugRegistrySnapshot)) |name|
        try std.testing.expectEqual(@as(u64, 0), @field(ordinary_snapshot.debug_registry, name));
    inline for (comptime std.meta.fieldNames(interp.TierTimingSnapshot)) |name|
        try std.testing.expectEqual(@as(u64, 0), @field(ordinary_snapshot.timing, name));
    try std.testing.expectEqual(@as(u64, 0), ordinary_snapshot.runtime.allocation.backing_allocations);
    try std.testing.expectEqual(@as(usize, 0), ordinary_snapshot.runtime.minor_pauses.len);
    try std.testing.expectEqual(@as(usize, 0), ordinary_snapshot.runtime.full_pauses.len);

    const profiled_tree = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .profile_execution_tiers = true,
        .bytecode_execution_mode = .tree_walker,
    });
    defer profiled_tree.destroy();
    try std.testing.expectEqual(@as(f64, 4), (try profiled_tree.evaluate(
        \\function treeEntry() { return arguments[0]; }
        \\try { treeEntry(4); } catch (error) {}
    )).asNum());
    const tree_snapshot = profiled_tree.tierAttributionSnapshot();
    try std.testing.expect(tree_snapshot.execution.count(.tree_walker_entries) >= 2);
    try std.testing.expect(tree_snapshot.execution.count(.environment_allocations) > 0);
    try std.testing.expect(tree_snapshot.runtime.allocation.backing_allocations > 0);
    try std.testing.expect(tree_snapshot.runtime.allocation.backing_allocation_bytes > 0);
    try std.testing.expect(tree_snapshot.runtime.allocation.gc_cell_allocations > 0);
    try std.testing.expect(tree_snapshot.debug_registry.location_cache_misses > 0);
    try std.testing.expectEqual(
        tree_snapshot.heap.collections,
        tree_snapshot.runtime.minor_pauses.len + tree_snapshot.runtime.full_pauses.len,
    );

    const profiled_vm = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_jit = true,
        .enable_gc = true,
        .profile_execution_tiers = true,
        .bytecode_execution_mode = .required,
    });
    defer profiled_vm.destroy();
    try std.testing.expectEqual(@as(f64, 28_095_328), (try profiled_vm.evaluate(
        \\function hotPoint(point) {
        \\  "use strict";
        \\  let sum = 0;
        \\  for (let index = 0; index < 16; index = index + 1)
        \\    sum = sum + point.x + point.y;
        \\  return sum;
        \\}
        \\globalThis.profilePoint = { x: 4, y: 6 };
        \\var profileResult = 0;
        \\for (var warm = 0; warm < 10; warm = warm + 1)
        \\  profileResult = profileResult + hotPoint(profilePoint);
        \\function quickKernel() {
        \\  const object = { a: 0, b: 1, c: 2, d: 3 };
        \\  let i = 0;
        \\  while (i < 8) {
        \\    object.a = (object.a + i) % 1000003;
        \\    object.b = object.b + 1;
        \\    object.c = object.a + object.b;
        \\    object.d = object.c - object.b;
        \\    i = i + 1;
        \\  }
        \\  return object.a * 1000000 + object.b * 10000 + object.c * 100 + object.d;
        \\}
        \\profileResult + quickKernel();
    )).asNum());
    const snapshot = profiled_vm.tierAttributionSnapshot();
    try std.testing.expectEqual(@as(u64, 0), snapshot.execution.count(.tree_walker_entries));
    try std.testing.expect(snapshot.execution.count(.vm_entries) > 0);
    try std.testing.expect(snapshot.execution.count(.vm_dispatches) > 0);
    try std.testing.expect(snapshot.execution.count(.vm_quick_kernel_hits) > 0);
    try std.testing.expect(snapshot.heap.live_bytes > 0);
    try std.testing.expectEqual(snapshot.generated_code_bytes, snapshot.native_code.live_bytes);
    if (jit.supported and builtin.cpu.arch == .aarch64) {
        try std.testing.expect(snapshot.execution.count(.optimizer_entries) > 0);
        try std.testing.expect(snapshot.optimizer_publications > 0);
        try std.testing.expect(snapshot.generated_code_bytes > 0);
        try std.testing.expect(snapshot.native_code.live_artifacts > 0);
        try std.testing.expectEqual(snapshot.baseline_publications, snapshot.timing.baseline_tier_ups);
        try std.testing.expectEqual(snapshot.optimizer_publications, snapshot.timing.optimizer_tier_ups);
        try std.testing.expectEqual(
            snapshot.timing.baseline_attempts,
            snapshot.timing.baseline_tier_ups + snapshot.timing.baseline_failures,
        );
        try std.testing.expectEqual(
            snapshot.timing.optimizer_attempts,
            snapshot.timing.optimizer_tier_ups + snapshot.timing.optimizer_failures,
        );
        try std.testing.expect(snapshot.timing.baseline_tier_up_ns >= snapshot.timing.baseline_tier_up_ns_max);
        try std.testing.expect(snapshot.timing.optimizer_tier_up_ns >= snapshot.timing.optimizer_tier_up_ns_max);
    }

    const Host = struct {
        fn finish(_: *value.CApiObjectOwner) void {}
        fn callable(_: *const value.Object) bool {
            return true;
        }
        fn call(_: *anyopaque, _: *value.Object, _: Value, _: []const Value) value.HostError!Value {
            return Value.num(9);
        }
        const hooks: value.HostClassHooks = .{ .is_callable = callable, .call = call };
    };
    const profiled_host = try Context.createWith(std.testing.allocator, .{ .profile_execution_tiers = true });
    defer profiled_host.destroy();
    var host_machine = profiled_host.interpreter();
    const host_object = (try host_machine.newObject()).asObj();
    const host_owner = try profiled_host.createCApiObjectOwner(@ptrCast(profiled_host), Host.finish);
    try host_object.setCApiObjectClass(profiled_host.arena(), host_owner, &Host.hooks);
    try std.testing.expectEqual(@as(f64, 9), (try host_machine.callValue(Value.obj(host_object), &.{})).asNum());
    try std.testing.expectEqual(
        @as(u64, 1),
        profiled_host.tierAttributionSnapshot().execution.count(.host_callbacks),
    );
}

test "vm admission: strict named-property loops reach the optimizer" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_jit = true });
    defer ctx.destroy();

    const hot = try ctx.evaluate(
        \\function hotDot(p, spins) {
        \\  "use strict";
        \\  let s = 0;
        \\  let i = 0;
        \\  while (i < spins) {
        \\    s = s + p.x * p.x + p.y * p.y;
        \\    i = i + 1;
        \\  }
        \\  return s;
        \\}
        \\globalThis.hotPoint = { x: 3, y: 4 };
        \\for (let warm = 0; warm < 64; ++warm) hotDot(hotPoint, 32);
        \\hotDot
    );
    const hot_raw = hot.asObj().jsFunction() orelse return error.TestUnexpectedResult;
    const hot_func: *interp.Function = @ptrCast(@alignCast(hot_raw));
    try std.testing.expect(hot_func.chunk != null);
    if (jit.supported and builtin.cpu.arch == .aarch64) {
        try std.testing.expectEqual(jit.OptimizerTierState.ready, hot_func.chunk.?.optimizer_tier.state.load(.acquire));
        try std.testing.expectEqual(@as(u64, 1), hot_func.chunk.?.optimizer_tier.compileCount());
        try std.testing.expectEqual(@as(u64, 1), ctx.jit_owner.optimizerPublications());
    }
}

test "vm admission: live-length indexed loops reach the optimizer" {
    const source =
        \\function liveLengthRead(a) {
        \\  "use strict";
        \\  let acc = 0;
        \\  let i = 0;
        \\  let limit = 64;
        \\  while (i < limit) {
        \\    const length = a.length;
        \\    if (i >= length) break;
        \\    acc = acc + a[i];
        \\    i = i + 1;
        \\  }
        \\  return acc;
        \\}
        \\function liveLengthWrite(a) {
        \\  "use strict";
        \\  let i = 0;
        \\  let limit = 64;
        \\  while (i < limit) {
        \\    const length = a.length;
        \\    if (i >= length) break;
        \\    a[i] = 7;
        \\    i = i + 1;
        \\  }
        \\}
        \\globalThis.liveLengthArray = new Array(32);
        \\for (let i = 0; i < 32; ++i) liveLengthArray[i] = i;
        \\for (let warm = 0; warm < 64; ++warm) liveLengthRead(liveLengthArray);
        \\for (let warm = 0; warm < 64; ++warm) liveLengthWrite(liveLengthArray);
    ;

    var results: [2]f64 = undefined;
    for ([_]bool{ false, true }, 0..) |enable_jit, index| {
        const ctx = try Context.createWith(std.testing.allocator, .{ .enable_jit = enable_jit });
        defer ctx.destroy();
        _ = try ctx.evaluate(source);
        results[index] = (try ctx.evaluate("liveLengthRead(liveLengthArray) * 10000 + liveLengthArray.length * 100 + liveLengthArray[31]")).asNum();

        const reader = try ctx.evaluate("liveLengthRead");
        const reader_raw = reader.asObj().jsFunction() orelse return error.TestUnexpectedResult;
        const reader_func: *interp.Function = @ptrCast(@alignCast(reader_raw));
        try std.testing.expect(reader_func.chunk != null);
        const writer = try ctx.evaluate("liveLengthWrite");
        const writer_raw = writer.asObj().jsFunction() orelse return error.TestUnexpectedResult;
        const writer_func: *interp.Function = @ptrCast(@alignCast(writer_raw));
        try std.testing.expect(writer_func.chunk != null);

        if (enable_jit and jit.supported and builtin.cpu.arch == .aarch64) {
            try std.testing.expectEqual(jit.OptimizerTierState.ready, reader_func.chunk.?.optimizer_tier.state.load(.acquire));
            try std.testing.expectEqual(jit.OptimizerTierState.ready, writer_func.chunk.?.optimizer_tier.state.load(.acquire));
            try std.testing.expectEqual(@as(u64, 1), reader_func.chunk.?.optimizer_tier.compileCount());
            try std.testing.expectEqual(@as(u64, 1), writer_func.chunk.?.optimizer_tier.compileCount());
            try std.testing.expectEqual(@as(u64, 2), ctx.jit_owner.optimizerPublications());
        }
    }
    try std.testing.expectEqual(@as(f64, 2243207), results[0]);
    try std.testing.expectEqual(results[0], results[1]);
}

test "deep stack: main-realm non-tail recursion runs under the stack guard" {
    // Bounded witness for non-tail recursion on the main realm. Proper tail calls
    // now intentionally avoid native-stack growth for tail recursion, so the old
    // "recurse until RangeError and compare stack sizes" probe was both stale and
    // expensive. This keeps a fast guard-covered non-tail recursion smoke; the VM
    // trampoline test above covers very deep tail recursion.
    if (builtin.single_threaded) return error.SkipZigTest;
    const Runner = struct {
        result: f64 = 0,
        fn run(self: *@This()) void {
            const ctx = Context.createWith(std.testing.allocator, .{}) catch return;
            defer ctx.destroy();
            const v = ctx.evaluate(
                \\function depth(n) { return n >= 200 ? n : depth(n + 1) + 0; }
                \\depth(0)
            ) catch return;
            if (v.isNumber()) self.result = v.asNum();
        }
    };
    var r = Runner{};
    const t = try std.Thread.spawn(.{ .stack_size = 8 << 20 }, Runner.run, .{&r});
    t.join();
    try std.testing.expectEqual(@as(f64, 200), r.result);
}

test "deep stack: spawned JS threads run non-tail recursion on a registered native stack" {
    // Coverage (deep-stack witness): a spawned `Thread` registers its native
    // stack bounds before running JS, so non-tail recursion remains catchable and
    // stable in worker realms. Keep this bounded so Debug runs do not spend
    // minutes unwinding a huge stack.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_threads = true });
    defer ctx.destroy();
    const v = try ctx.evaluate(
        \\function depth(n) { return n >= 200 ? n : depth(n + 1) + 0; }
        \\var main_depth = depth(0);
        \\var t = new Thread(function () { return depth(0); });
        \\var thread_depth = t.join();
        \\(thread_depth === 200 && main_depth === 200) ? 1 : 0;
    );
    try std.testing.expectEqual(@as(f64, 1), v.asNum());
}

test "arguments elision: functions that never name arguments skip building it, others correct" {
    // Perf (#2): the tree-walker builds the `arguments` exotic object on every
    // non-arrow call; exact owner metadata now distinguishes an `arguments`
    // reference from direct eval, and skips creation only when neither can
    // observe the binding. This checks direct use, a nested arrow, direct eval,
    // sloppy mapped write-through, `arguments.callee`, and for-of — plus a
    // function that does not use it (skips creation).
    const ctx = try Context.createWith(std.testing.allocator, .{});
    defer ctx.destroy();
    const v = try ctx.evaluate(
        \\var out = [];
        \\function f(){ return arguments.length + ":" + arguments[0]; } out.push(f(7,8));   // 2:7
        \\function g(a,b){ return a+b; } out.push(g(3,4));                                   // 7 (skipped)
        \\function h(){ return eval("arguments.length"); } out.push(h(1,2,3));               // 3
        \\function k(){ return (() => arguments[1])(); } out.push(k("x","y"));               // y
        \\function m(a){ arguments[0]=99; return a; } out.push(m(1));                        // 99 (mapped)
        \\function c(){ return arguments.callee === c; } out.push(c());                      // true
        \\function it(){ var t=0; for (const x of arguments) t+=x; return t; } out.push(it(1,2,3,4)); // 10
        \\out.join(",");
    );
    try std.testing.expect(v.isString());
    try std.testing.expectEqualStrings("2:7,7,3,y,99,true,10", v.asStr());
}

test "switch scope: no env allocated when no case declares a block-scoped binding" {
    // Perf (#2): `evalSwitch` skips the CaseBlock env (and its hoisting/TDZ
    // instantiation) when no case declares a block-scoped binding, running the
    // cases in the enclosing scope — the same conservative `blockNeedsOwnScope`
    // allowlist as blocks. A case with `let`/`const`/`class`/a block function
    // still gets the env. Checks fallthrough, `var` hoisting out of the switch,
    // block/case-level `let`, and a block-scoped function all stay correct.
    const ctx = try Context.createWith(std.testing.allocator, .{});
    defer ctx.destroy();
    const v = try ctx.evaluate(
        \\function run() {
        \\  var _tw = arguments.length; // tree-walker
        \\  function s1(n){ var r=""; switch(n){ case 1: r+="a"; case 2: r+="b"; break; default: r+="d"; } return r; }
        \\  function s2(n){ switch(n){ case 1: { let x=10; return x; } default: return -1; } }
        \\  function s3(n){ switch(n){ case 1: let y=5; return y; default: return 0; } }
        \\  function s4(n){ switch(n){ case 1: function f(){return 7;} return f(); default: return 0; } }
        \\  function s5(){ switch(1){ case 1: var z=3; } return z; }
        \\  return [s1(1), s1(2), s1(9), s2(1), s2(9), s3(1), s3(9), s4(1), s5()].join(",");
        \\}
        \\run();
    );
    try std.testing.expect(v.isString());
    try std.testing.expectEqualStrings("ab,b,d,10,-1,5,0,7,3", v.asStr());
}

test "enable_gc: mid-script collection reclaims garbage during a running loop (bounded heap)" {
    // Phase 7 / M1 item (a): the GC collects *while JS runs* (at the engine step
    // checkpoints), not just at quiescent points. A long loop allocating
    // throwaway objects would grow the heap without bound if collection only ran
    // at entry; the safepoint collector keeps it bounded. Crucially, this also
    // proves the new roots are sound: the live operand-stack `Value`s (registered
    // active VM `Exec`) and the loop's bindings are never wrongly freed, so the
    // arithmetic result is exact.
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();

    const result = try ctx.evaluate(
        \\let acc = 0;
        \\for (let i = 0; i < 50000; i++) {
        \\  const o = { a: i, b: { c: i }, arr: [i, i, i] };
        \\  acc += o.b.c + o.arr[1];
        \\}
        \\acc;
    );
    // sum_{i=0..49999}(i + i) = 2 * (49999*50000/2) = 2499950000.
    try std.testing.expectEqual(@as(f64, 2499950000), result.asNum());
    // Collection ran repeatedly mid-loop — far more than the single quiescent
    // collect at the top of `evaluate`.
    try std.testing.expect(ctx.gc.?.collections > 2);
    // The heap stayed bounded in the collector's byte currency. A raw cell-count
    // limit changes when an optimization removes larger Environment cells while
    // leaving more 128-byte Objects in the final nursery tranche (#634).
    const accounting = ctx.gc.?.accounting();
    try std.testing.expect(accounting.live_bytes < 2 * ctx.gc.?.nursery_threshold_bytes);
}

test "enable_gc: precise checkpoints reclaim a cache-local nursery batch" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();
    const heap = ctx.gc.?;
    try std.testing.expect(heap.nursery_threshold_bytes > precise_gc_nursery_threshold_bytes);

    const saved = gc_mod.setActiveContext(ctx);
    defer gc_mod.restoreActiveContext(saved);
    while (heap.young_bytes < precise_gc_nursery_threshold_bytes) {
        const object = try heap.create(value.Object, .object);
        object.* = .{};
        object.initInlineSlots();
    }
    try std.testing.expect(!heap.shouldCollectYoung());

    var machine = ctx.interpreter();
    machine.gc_precise_safepoint = true;
    const minor_before = heap.minor_collections;
    try std.testing.expect(ctx.collectYoungMidScriptIfNeeded(heap, &machine));
    try std.testing.expectEqual(minor_before + 1, heap.minor_collections);
    try std.testing.expect(heap.young_bytes < precise_gc_nursery_threshold_bytes);
}

test "enable_gc: precise nursery cadence amortizes large microtask roots" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();
    const heap = ctx.gc.?;
    heap.nursery_threshold_bytes = precise_gc_nursery_threshold_bytes;

    const root_count = precise_gc_nursery_threshold_bytes / @sizeOf(promise.Microtask) + 256;
    const roots = try std.testing.allocator.alloc(promise.Microtask, root_count);
    defer std.testing.allocator.free(roots);
    @memset(roots, .{
        .kind = .callback,
        .reaction = undefined,
        .argument = Value.undef(),
        .fulfilled = true,
    });

    var machine = ctx.interpreter();
    machine.gc_precise_safepoint = true;
    machine.current_microtask_batch = roots;
    const amortized_bytes = machine.preciseJobRootBytes();
    try std.testing.expect(amortized_bytes > precise_gc_nursery_threshold_bytes);

    const saved = gc_mod.setActiveContext(ctx);
    defer gc_mod.restoreActiveContext(saved);
    while (heap.young_bytes < precise_gc_nursery_threshold_bytes) {
        const object = try heap.create(value.Object, .object);
        object.* = .{};
        object.initInlineSlots();
    }
    try std.testing.expect(heap.shouldCollectYoung());
    try std.testing.expect(!ctx.collectYoungMidScriptIfNeeded(heap, &machine));

    // Remembered-set publication failure is a correctness request, not a
    // heuristic threshold: it must bypass root-scan amortization and force the
    // nursery path to fall back to a full collection immediately.
    const full_before = heap.full_collections;
    heap.nursery_force_full.store(true, .release);
    try std.testing.expect(ctx.collectYoungMidScriptIfNeeded(heap, &machine));
    try std.testing.expect(heap.full_collections > full_before);
    try std.testing.expect(!heap.nursery_force_full.load(.acquire));

    while (heap.young_bytes < amortized_bytes) {
        const object = try heap.create(value.Object, .object);
        object.* = .{};
        object.initInlineSlots();
    }
    const minor_before = heap.minor_collections;
    try std.testing.expect(ctx.collectYoungMidScriptIfNeeded(heap, &machine));
    try std.testing.expectEqual(minor_before + 1, heap.minor_collections);
}

test "enable_gc: mid-script safepoints collect nursery before old heap" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();
    ctx.collectGarbage();
    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    heap.nursery_threshold_bytes = Context.GcHeap.min_nursery_threshold_bytes;
    const minor_before = heap.minor_collections;
    const full_before = heap.full_collections;

    const result = try ctx.evaluate(
        \\let acc = 0;
        \\for (let i = 0; i < 40000; i++) {
        \\  const value = { a: i, nested: { b: i + 1 }, values: [i, i + 2] };
        \\  acc += value.a + value.nested.b + value.values[1];
        \\}
        \\acc;
    );
    // sum(3*i + 3), i=0..39999. Keep enough object-cell pressure to cross a
    // running-loop nursery boundary even when block environments are reused.
    try std.testing.expectEqual(@as(f64, 2400060000), result.asNum());
    // More than the one possible exit-boundary cycle proves the running loop
    // entered the nursery collector at VM safepoints.
    try std.testing.expect(heap.minor_collections - minor_before > 1);
    try std.testing.expectEqual(full_before, heap.full_collections);
    try std.testing.expect(ctx.gc_minor_pause_ns_total.load(.monotonic) > 0);
    try std.testing.expect(ctx.gc_minor_pause_ns_max.load(.monotonic) > 0);
    try std.testing.expect(heap.live_cells < 40000);
}

test "enable_gc concurrent finish drains post-sweep slab maintenance once" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWith(std.testing.allocator, .{
        .enable_gc = true,
        .enable_jit = false,
        .concurrent_gc = true,
    });
    defer ctx.destroy();
    const heap = ctx.gc.?;
    const backing = ctx.gc_cell_backing.?;
    const idx = GcCellBacking.bucketIndex(1536, .@"16").?;
    try std.testing.expectEqual(@as(usize, 0), backing.bucket_chunks[idx].items.len);
    const backing_allocator = backing.allocator();
    const live_prefix = try backing_allocator.alignedAlloc(u8, .@"16", 1536);
    defer backing_allocator.free(live_prefix);
    try std.testing.expectEqual(@as(usize, 1), backing.bucket_chunks[idx].items.len);

    const empty_chunks = GcCellBacking.reusable_tail_chunks + 2;
    for (0..empty_chunks) |_| try std.testing.expect(backing.addChunk(idx));
    try std.testing.expectEqual(empty_chunks + 1, backing.bucket_chunks[idx].items.len);

    // Reproduce the production begin/finish boundary without a marker thread:
    // finish drains the grey set synchronously, records exact completion, and
    // leaves Context-owned reclamation pending for this quiescent host frame.
    ctx.beginConcurrentEnvironmentTrace();
    ctx.gc_scan_native_stack = true;
    heap.beginConcurrentMark();
    ctx.gc_scan_native_stack = false;
    try std.testing.expect(heap.concurrent.load(.acquire));
    try std.testing.expectEqual(
        Context.ConcurrentGcFinishResult.finished,
        ctx.finishConcurrentGCIfActive(),
    );
    try std.testing.expect(ctx.gc_concurrent_post_sweep_pending);
    try std.testing.expectEqual(
        Context.ConcurrentGcFinishResult.inactive,
        ctx.finishConcurrentGCIfActive(),
    );

    try std.testing.expect(ctx.drainConcurrentPostSweepMaintenance(.ordinary_collection, false));
    try std.testing.expect(!ctx.gc_concurrent_post_sweep_pending);
    try std.testing.expectEqual(
        GcCellBacking.reusable_tail_chunks + 1,
        backing.bucket_chunks[idx].items.len,
    );
    try std.testing.expect(!ctx.drainConcurrentPostSweepMaintenance(.ordinary_collection, false));
}

test "enable_gc concurrent (M3): the production driver marks on a thread while JS runs" {
    // Phase 7 / M3: with `concurrent_gc`, `collectMidScript` marks on a dedicated
    // thread *concurrently* with the mutator between safepoints. Same workload
    // and exact-result/bounded-heap assertions as the M2 mid-script test, now
    // driven concurrently end-to-end: the mutator allocates objects and per-
    // iteration `let` environments (objects' storage and envs' `vars` are read by
    // the marker under their per-structure locks; cells born this cycle are
    // deferred to the world-stopped finish), its stores feed the marker via the
    // insertion barrier, and finish re-scans the native stack. So live values are
    // never wrongly freed, the arithmetic is exact, and it is TSan-clean.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .concurrent_gc = true });
    defer ctx.destroy();
    try std.testing.expect(ctx.gc_concurrent);
    // This test targets the full-heap concurrent driver, not the independent
    // nursery collector. Context creation enables the nursery by default; turn
    // it off so old-byte growth deterministically reaches the M3 path.
    ctx.gc.?.setNurseryEnabled(false);

    // 4,000 iterations (each allocating several cells + a per-iter `let` env) is
    // enough to cross the heap-growth threshold at least twice — driving multiple
    // begin→marker→finish concurrent cycles — while staying feasible under TSan
    // instrumentation (~15× slowdown).
    const result = try ctx.evaluate(
        \\let acc = 0;
        \\for (let i = 0; i < 4000; i++) {
        \\  const o = { a: i, b: { c: i }, arr: [i, i, i] };
        \\  acc += o.b.c + o.arr[1];
        \\}
        \\acc;
    );
    // sum_{i=0..3999}(i + i) = (3999*4000) = 15,996,000.
    try std.testing.expectEqual(@as(f64, 15996000), result.asNum());
    try std.testing.expect(ctx.gc.?.collections >= 2); // multiple concurrent cycles closed
    try std.testing.expect(ctx.gc.?.live_cells < 20000); // heap stayed bounded
    try std.testing.expect(ctx.gc_marker == null); // no marker outlived the run
    try std.testing.expect(!ctx.gc.?.concurrent.load(.acquire));
    try std.testing.expect(!ctx.gc_concurrent_post_sweep_pending);

    // A retained graph built + repeatedly assigned (env writes) under concurrent
    // marking is intact afterward.
    const r = try ctx.evaluate(
        \\globalThis.keep = { sum: 0 };
        \\for (let i = 0; i < 4000; i++) { globalThis.keep.sum += 1; const junk = { i }; }
        \\globalThis.keep.sum;
    );
    try std.testing.expectEqual(@as(f64, 4000), r.asNum());
}

test "enable_gc concurrent (M3): generators and iterator helpers are safe under concurrent marking" {
    // The deferred-trace path: a *running* generator's `exec` is the live VM
    // stack and an iterator helper's fields update around JS callbacks, so the
    // marker can't read them mid-cycle — `gc.zig` defers tracing those cell kinds
    // to the world-stopped finish (the cell is still marked, so it survives; its
    // edges are found when the mutator is quiescent). This workload runs many
    // generators and Iterator-helper chains while the concurrent marker traces,
    // proving the deferral keeps their reachable state alive and is race-free.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .concurrent_gc = true });
    defer ctx.destroy();
    // Keep the stress witness about concurrent old-space tracing rather than
    // letting the production multi-age nursery satisfy its bounded pressure.
    ctx.gc.?.setNurseryEnabled(false);

    const result = try ctx.evaluate(
        \\function* range(n) { for (let i = 0; i < n; i++) yield i; }
        \\let total = 0;
        \\for (let r = 0; r < 400; r++) {
        \\  // A suspended-and-resumed generator (its exec is live during resume).
        \\  let g = range(20), s = 0;
        \\  for (const x of g) s += x;
        \\  // An iterator-helper chain (map/filter/take — inner state updated
        \\  // around the callbacks the marker must not race).
        \\  const h = range(50).map(x => x * 2).filter(x => x % 3 === 0).take(5);
        \\  for (const y of h) s += y;
        \\  total += s;
        \\}
        \\total;
    );
    // Per round r: sum_{i=0..19} i = 190; helper picks first 5 of {0,6,12,18,...}
    // = 0+6+12+18+24 = 60. So s = 250 per round, × 400 = 100000.
    try std.testing.expectEqual(@as(f64, 100000), result.asNum());
    try std.testing.expect(ctx.gc.?.collections > 2); // concurrent cycles ran mid-workload
    try std.testing.expect(ctx.gc_marker == null);
    try std.testing.expect(!ctx.gc.?.concurrent.load(.acquire));
}

test "enable_gc concurrent (M3): mixed-workload stress amplifier stays correct + race-free" {
    // M3 stress amplifier: hammer the concurrent driver with every cell kind at
    // once — plain objects, arrays (dense + push), Map/Set, WeakMap/WeakSet
    // (keyed by live objects), Promises, closures capturing per-iteration `let`
    // environments, generators, and iterator-helper chains — so a single
    // collection cycle traces objects (locked), environments (binding_lock),
    // promises (Promise.lock), weak collections (isMarked clearing), and
    // generators/iterator-helpers (synchronized activation/state locks)
    // concurrently with the mutator building and mutating all of them. Exact
    // final tallies prove nothing live was wrongly freed; TSan-clean proves no
    // path races the marker.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .concurrent_gc = true });
    defer ctx.destroy();
    // Isolate the concurrent old-space marker. The production age-three
    // nursery deliberately handles this bounded workload before old-space
    // pressure accumulates, which is correct but would not exercise the path
    // this test exists to validate.
    ctx.gc.?.setNurseryEnabled(false);

    const result = try ctx.evaluate(
        \\function* gen(n) { for (let i = 0; i < n; i++) yield i; }
        \\const keys = [];
        \\for (let i = 0; i < 64; i++) keys.push({ id: i }); // live weak keys
        \\const wm = new WeakMap(), ws = new WeakSet();
        \\const arr = [], m = new Map(), s = new Set();
        \\const closures = [];
        \\let acc = 0;
        \\for (let r = 0; r < 300; r++) {
        \\  const o = { r, nested: { v: r }, list: [r, r + 1, r + 2] };
        \\  arr.push(o);
        \\  if (arr.length > 50) arr.shift();          // bounded churn
        \\  m.set('k' + (r % 32), o);
        \\  s.add(r % 48);
        \\  const k = keys[r % keys.length];
        \\  wm.set(k, o); ws.add(k);
        \\  // closure captures this iteration's `let r` and `o` (env binding writes)
        \\  let local = r; closures.push(() => local + o.nested.v);
        \\  if (closures.length > 20) closures.shift();
        \\  let g = gen(10), gs = 0; for (const x of g) gs += x;       // generator
        \\  const h = gen(30).map(x => x + 1).filter(x => x % 2 === 0).take(4);
        \\  for (const y of h) gs += y;                                // iter-helper
        \\  acc += gs;
        \\  Promise.resolve(o).then(() => {});                        // promise + reaction
        \\}
        \\// Verify the live structures survived intact.
        \\let sum = 0;
        \\for (const f of closures) sum += f();
        \\for (const k of keys) { if (wm.has(k)) sum += wm.get(k).r; }
        \\acc * 100000 + m.size * 1000 + s.size * 10 + (sum > 0 ? 1 : 0);
    );
    // gen(10): sum 0..9 = 45; helper: first 4 evens of {x+1 | x in 0..29} =
    // {1..30} evens = 2,4,6,8 = 20. gs = 65/round × 300 = 19500.
    // m.size = 32 (keys k0..k31), s.size = 48 (0..47). sum > 0.
    try std.testing.expectEqual(@as(f64, 19500 * 100000 + 32 * 1000 + 48 * 10 + 1), result.asNum());
    // The 256-byte object slab halves pressure versus the former 512-byte slab;
    // two cycles still prove collection overlapped the running mixed workload.
    try std.testing.expect(ctx.gc.?.collections >= 2);
    try std.testing.expect(ctx.gc_marker == null);
    try std.testing.expect(!ctx.gc.?.concurrent.load(.acquire));
}

test "LockedArena: concurrent allocation from many threads is race-free (GIL-removal prereq #1)" {
    // Blocker #1 for GIL removal: shapes/strings/AST/binding tables are
    // arena-allocated, and `ArenaAllocator` is not thread-safe. `LockedArena`
    // serializes arena access so parallel JS threads can allocate once the GIL
    // is gone. Hammer it directly from 8 threads (bypassing the GIL, as the
    // post-GIL engine would) and confirm every allocation is valid and distinct.
    if (builtin.single_threaded) return error.SkipZigTest;
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    var la = LockedArena{ .inner = arena_state.allocator() };
    defer la.resetLocalFor();
    const a = la.allocator();
    jsthread.resetContentionStats();
    defer jsthread.disableContentionStats();

    const threads = 8;
    const per = 1000;
    const Worker = struct {
        alloc: std.mem.Allocator,
        ok: std.atomic.Value(u32) = .init(0),
        fn run(s: *@This()) void {
            var i: usize = 0;
            while (i < per) : (i += 1) {
                // Mixed sizes + writes, like real shape/string/binding allocs.
                const buf = s.alloc.alloc(u8, 8 + (i % 56)) catch return;
                @memset(buf, @intCast(i & 0xff));
                // Verify our own write survived (a torn arena would corrupt it).
                if (buf[0] == @as(u8, @intCast(i & 0xff)) and buf[buf.len - 1] == @as(u8, @intCast(i & 0xff)))
                    _ = s.ok.fetchAdd(1, .monotonic);
            }
        }
    };
    var w = Worker{ .alloc = a };
    var pool: [threads]std.Thread = undefined;
    for (&pool) |*t| t.* = try std.Thread.spawn(.{}, Worker.run, .{&w});
    for (&pool) |*t| t.join();

    // Every one of the threads*per allocations succeeded and read back intact.
    try std.testing.expectEqual(@as(u32, threads * per), w.ok.load(.monotonic));
    try std.testing.expect(jsthread.contentionStats().arena_lock_acquires < threads * 8);
}

test "LockedArena: current local chunk resize/free skips arena lock" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    var la = LockedArena{ .inner = arena_state.allocator() };
    defer la.resetLocalFor();
    const a = la.allocator();

    const buf = try a.alloc(u8, 32);
    jsthread.resetContentionStats();
    defer jsthread.disableContentionStats();

    try std.testing.expect(!a.resize(buf, 64));
    try std.testing.expect(a.remap(buf, 64) == null);
    a.free(buf);

    const stats = jsthread.contentionStats();
    try std.testing.expectEqual(@as(u64, 0), stats.arena_lock_acquires);
    try std.testing.expectEqual(@as(u64, 0), stats.arena_lock_contentions);
    try std.testing.expectEqual(@as(u64, 0), stats.arena_lock_spins);
}

test "parallel_gc (M3 GIL-removal bring-up): mutators create+shape+mutate disjoint objects in parallel" {
    // The payoff of the GIL-removal prerequisites composed: with thread-safe cell
    // allocation (setParallel), thread-safe arena (LockedArena → shapes/scratch),
    // atomic backing counters, and the per-structure object/shape locks, multiple
    // mutators run real object operations *in parallel with no GIL* — allocating
    // cells, transitioning shapes (shared root, converging under transition_lock),
    // and writing slots (per-object property_lock). Each thread owns a disjoint
    // set of objects; afterward every object is intact and correctly shaped.
    // This is the first true parallel-JS-heap-mutation demonstration. TSan-clean.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true });
    defer ctx.destroy();

    const nthreads = 4;
    const per = 1000;
    const Worker = struct {
        ctx: *Context,
        objs: []*value.Object,
        ok: std.atomic.Value(u32) = .init(0),
        fn run(s: *@This()) void {
            // Allocate into the shared heap/arena from this thread: set the
            // threadlocal active heap + intern arena. No GIL — the thread-safe
            // arena/backing + per-structure locks are what make it safe.
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            for (s.objs, 0..) |*slot, i| {
                const o = gc_mod.allocObj(a) catch return;
                o.* = .{};
                // Two property adds → shape transitions on the shared root shape
                // (serialized + converged by transition_lock), slots under this
                // object's property_lock.
                o.setOwn(a, s.ctx.root_shape, "v", Value.num(@floatFromInt(i))) catch return;
                o.setOwn(a, s.ctx.root_shape, "t", Value.num(1)) catch return;
                slot.* = o;
                if (o.getOwn("v")) |gv| {
                    if (gv.asNum() == @as(f64, @floatFromInt(i))) _ = s.ok.fetchAdd(1, .monotonic);
                }
            }
        }
    };
    var storage: [nthreads][per]*value.Object = undefined;
    var workers: [nthreads]Worker = undefined;
    for (&workers, 0..) |*w, t| w.* = .{ .ctx = ctx, .objs = storage[t][0..] };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();

    var total_ok: u32 = 0;
    for (&workers) |*w| total_ok += w.ok.load(.monotonic);
    try std.testing.expectEqual(@as(u32, nthreads * per), total_ok);
    // Every object across all threads is intact and correctly shaped.
    for (&storage) |*arr| {
        for (arr, 0..) |o, i| {
            const gv = o.getOwn("v") orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(@as(f64, @floatFromInt(i)), gv.asNum());
            const gt = o.getOwn("t") orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(@as(f64, 1), gt.asNum());
        }
    }
}

test "parallel_gc (M3 GIL-removal bring-up): parse+compile+VM-execute disjoint scripts in parallel, no GIL" {
    // Parallel JS *execution* (not just heap mutation): each thread parses,
    // compiles, and runs its own pure-computation script — local vars, a loop,
    // local object allocation, no globalThis writes — on its own Interpreter,
    // truly in parallel with no GIL. Exercises the parser/compiler/VM and the
    // shared heap/arena/shapes + active_interpreters lock under real parallelism.
    // Mid-script GC is off in parallel_gc mode (the safepoint protocol for
    // parallel collection is a later step), so this isolates execution safety.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true });
    defer ctx.destroy();

    const nthreads = 4;
    const Worker = struct {
        ctx: *Context,
        result: std.atomic.Value(i64) = .init(-1),
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            const src = "(function(parameter0,parameter1,parameter2,parameter3,parameter4,parameter5,parameter6,parameter7,parameter8,parameter9,parameter10,parameter11,parameter12,parameter13,parameter14,parameter15){ \"use strict\"; let s = 0; for (let i = 0; i < 2000; i++) { const o = { x: i }; s += o.x; } return s; })()";
            const owned = a.dupe(u8, src) catch return;
            var parser = Parser.initWithScratch(a, s.ctx.gpa, owned) catch return;
            const prog = parser.parseProgram() catch return;
            var machine = s.ctx.interpreter();
            s.ctx.pushActiveInterpreter(&machine) catch return; // exercises active_interp_lock
            defer s.ctx.popActiveInterpreter(&machine);
            const outcome: interp.EvalError!value.Value = if (compiler.Compiler.compileProgram(a, prog)) |chunk|
                vm.run(&machine, chunk, null)
            else |_|
                machine.eval(prog);
            if (outcome) |val| {
                if (val.isNumber()) s.result.store(@intFromFloat(val.asNum()), .monotonic);
            } else |_| {}
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers) |*w| w.* = .{ .ctx = ctx };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();
    // sum_{i=0..1999} i = 1999000 — each thread computed it independently, in parallel.
    for (&workers) |*w| try std.testing.expectEqual(@as(i64, 1999000), w.result.load(.monotonic));
}

test "parallel_gc (M3 GIL-removal bring-up): one shared chunk over a shared object, in parallel, no GIL" {
    // The strongest execution case: all threads run the **same compiled chunk**
    // (so they share its inline caches) over the **same globalThis-rooted object**
    // (so they share its `property_lock` and shape), truly in parallel with no
    // GIL. Each iteration does a `get_prop`+`set_prop` on `shared.counter`
    // (exercises the IC write/record path + the insertion barrier under
    // contention — lost updates are fine, JS without Atomics) and a `get_prop`
    // on `shared.base` (a property never written — its reads must NEVER tear, so
    // every thread's `base`-sum is exact). This drives the seqlock inline caches,
    // `property_lock`, and `binding_lock` (the global `shared` lookup) all at
    // once under real parallel bytecode. TSan-clean is the proof.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true });
    defer ctx.destroy();

    const sh0 = gc_mod.setActiveHeap(ctx.gc);
    defer _ = gc_mod.setActiveHeap(sh0);
    const sa0 = strcell.setActiveArena(ctx.arena());
    defer _ = strcell.setActiveArena(sa0);
    const a = ctx.arena();

    // A shared object rooted on globalThis: fixed shape {counter, base}.
    const shared = try gc_mod.allocObj(a);
    shared.* = .{};
    try shared.setOwn(a, ctx.root_shape, "counter", Value.num(0));
    try shared.setOwn(a, ctx.root_shape, "base", Value.num(100));
    try ctx.global_object.setOwn(ctx.gpa, ctx.root_shape, "shared", Value.obj(shared));

    // Compile ONCE on this thread; every worker runs this same chunk (shared ICs).
    const iters = 1000;
    const src =
        \\(function(){
        \\  let sum = 0;
        \\  for (let i = 0; i < 1000; i++) {
        \\    shared.counter = shared.counter + 1; // set_prop + get_prop (contended)
        \\    sum += shared.base;                  // get_prop of a never-written prop
        \\  }
        \\  return sum;
        \\})()
    ;
    const owned = try a.dupe(u8, src);
    var parser = try Parser.init(a, owned);
    const prog = try parser.parseProgram();
    const chunk = compiler.Compiler.compileProgram(a, prog) catch return error.TestUnexpectedResult;

    const nthreads = 4;
    const Worker = struct {
        ctx: *Context,
        chunk: *@import("bytecode.zig").Chunk,
        result: std.atomic.Value(i64) = .init(-1),
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            var machine = s.ctx.interpreter();
            s.ctx.pushActiveInterpreter(&machine) catch return;
            defer s.ctx.popActiveInterpreter(&machine);
            if (vm.run(&machine, s.chunk, null)) |val| {
                if (val.isNumber()) s.result.store(@intFromFloat(val.asNum()), .monotonic);
            } else |_| {}
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers) |*w| w.* = .{ .ctx = ctx, .chunk = chunk };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();

    // Every thread summed `shared.base` (== 100, never written) exactly `iters`
    // times: a torn read through the shared IC would corrupt this. Exact for all.
    for (&workers) |*w| try std.testing.expectEqual(@as(i64, iters * 100), w.result.load(.monotonic));
    // `counter` raced (no Atomics) so its value is nondeterministic, but it must
    // be a valid in-range number — never torn/garbage — and writes happened.
    const counter = shared.getOwn("counter") orelse return error.TestUnexpectedResult;
    try std.testing.expect(counter.isNumber());
    try std.testing.expect(counter.asNum() >= 1 and counter.asNum() <= nthreads * iters);
}

test "parallel_gc (M3 GIL-removal bring-up): rich builtin-heavy workload in parallel, no GIL" {
    // Broadens parallel-execution coverage past arithmetic/loops onto the shared
    // realm machinery the simpler bring-up tests miss: function calls + closures,
    // Array.prototype methods (push/map/reduce/filter), String concat, Math,
    // object literals + property reads. Each thread parses + compiles (parallel
    // arena allocation through LockedArena) and runs its OWN script, so results
    // are deterministic, but they all hammer the SAME realm intrinsics and
    // prototype chains in parallel with no GIL. TSan-clean here is what surfaces
    // residual shared-state hazards (lazy prototype/method installation, realm
    // caches) that small workloads don't reach.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true });
    defer ctx.destroy();

    const nthreads = 4;
    const Worker = struct {
        ctx: *Context,
        result: std.atomic.Value(i64) = .init(-1),
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            // reduce of (2i+1 for i in 0..199) = 200^2 = 40000; filter/map/closures
            // and the builtins along the way all run against shared intrinsics.
            const src =
                \\(function(){
                \\  let arr = [];
                \\  for (let i = 0; i < 200; i++) arr.push(i);
                \\  let mapped = arr.map(function(x){ return 2 * x + 1; });
                \\  let evens = mapped.filter(function(x){ return x % 2 === 1; });
                \\  let sum = evens.reduce(function(acc, x){ return acc + x; }, 0);
                \\  let label = "sum=" + sum + "/" + Math.max(1, 2);
                \\  let o = { total: sum, tag: label, root: Math.sqrt(sum) };
                \\  return o.total;
                \\})()
            ;
            const owned = a.dupe(u8, src) catch return;
            var parser = Parser.init(a, owned) catch return;
            const prog = parser.parseProgram() catch return;
            var machine = s.ctx.interpreter();
            s.ctx.pushActiveInterpreter(&machine) catch return;
            defer s.ctx.popActiveInterpreter(&machine);
            const outcome: interp.EvalError!value.Value = if (compiler.Compiler.compileProgram(a, prog)) |chunk|
                vm.run(&machine, chunk, null)
            else |_|
                machine.eval(prog);
            if (outcome) |val| {
                if (val.isNumber()) s.result.store(@intFromFloat(val.asNum()), .monotonic);
            } else |_| {}
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers) |*w| w.* = .{ .ctx = ctx };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();
    // All 200 mapped values 2i+1 are odd, so the filter keeps them all and the
    // reduce gives 200^2 = 40000 — each thread computed it independently.
    for (&workers) |*w| try std.testing.expectEqual(@as(i64, 40000), w.result.load(.monotonic));
}

test "parallel_gc (M3 GIL-removal bring-up): concurrent lazy .prototype install yields one identity" {
    // A function's `.prototype` is materialized lazily on first `new`/`.prototype`
    // access (`Interpreter.protoObject`) — a check-then-act over shared object
    // storage. With the GIL dropped, N threads racing that first access on the
    // SAME constructor could each install a distinct prototype, breaking
    // `F.prototype === F.prototype`. The double-checked lock (`Gil.lazy_init_lock`)
    // must make exactly one install win and all threads observe it. `enable_threads`
    // gives the realm a Gil (the lock's home); the workers call `protoObject`
    // directly with no GIL held, modelling the dropped-GIL future. A go-barrier
    // makes them all hit the un-materialized state together. TSan-clean.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true, .enable_threads = true });
    defer ctx.destroy();
    _ = ctx.gil orelse return error.TestUnexpectedResult; // the lock needs a Gil

    const sh0 = gc_mod.setActiveHeap(ctx.gc);
    defer _ = gc_mod.setActiveHeap(sh0);
    const sa0 = strcell.setActiveArena(ctx.arena());
    defer _ = strcell.setActiveArena(sa0);

    // A bare object standing in for a constructor: no `prototype` slot yet, so the
    // first `protoObject` call must materialize one.
    const ctor = try gc_mod.allocObj(ctx.arena());
    ctor.* = .{};

    const nthreads = 8;
    const Worker = struct {
        ctx: *Context,
        ctor: *value.Object,
        go: *std.atomic.Value(bool),
        result: std.atomic.Value(?*value.Object) = .init(null),
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            var machine = s.ctx.interpreter();
            s.ctx.pushActiveInterpreter(&machine) catch return;
            defer s.ctx.popActiveInterpreter(&machine);
            while (!s.go.load(.acquire)) std.atomic.spinLoopHint();
            const p = machine.protoObject(s.ctor) catch return;
            s.result.store(p, .release);
        }
    };
    var go = std.atomic.Value(bool).init(false);
    var workers: [nthreads]Worker = undefined;
    for (&workers) |*w| w.* = .{ .ctx = ctx, .ctor = ctor, .go = &go };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    go.store(true, .release);
    for (&pool) |*th| th.join();

    // Exactly one prototype was installed, and every thread observed that same
    // object — no duplicate install slipped through the check-then-act.
    const canonical = (ctor.getOwn("prototype") orelse return error.TestUnexpectedResult).asObj();
    for (&workers) |*w| {
        const got = w.result.load(.acquire) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(canonical, got);
    }
    // The installed prototype links back: F.prototype.constructor === F.
    const back = (canonical.getOwn("constructor") orelse return error.TestUnexpectedResult);
    try std.testing.expect(back.isObject() and back.asObj() == ctor);
}

test "parallel_gc (M3 GIL-removal bring-up): concurrent first .prototype access via real bytecode is consistent" {
    // End-to-end version of the lazy-`.prototype` fix through the *full* getProperty
    // path (not just `protoObject`): a function `Foo` is defined on globalThis with
    // its `.prototype` left unmaterialized, then N threads each run real bytecode
    // that first-touches `Foo.prototype`, reads `.prototype.constructor`, and
    // constructs an instance — all racing the one-time lazy install with no GIL.
    // Every thread must see `Foo.prototype.constructor === Foo`, `new Foo()
    // instanceof Foo`, and `Foo.length === 2`. A duplicate install (or torn
    // attr/constructor tweak) would break the identity. TSan-clean.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true, .enable_threads = true });
    defer ctx.destroy();
    _ = ctx.gil orelse return error.TestUnexpectedResult;

    // Define the shared function WITHOUT touching `.prototype`, so the first
    // access happens concurrently on the worker threads below.
    _ = try ctx.evaluate("function Foo(a, b) { this.tag = 1; }");

    const nthreads = 8;
    const Worker = struct {
        ctx: *Context,
        go: *std.atomic.Value(bool),
        result: std.atomic.Value(i64) = .init(-999),
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            const src =
                \\(function(){
                \\  var p = Foo.prototype;                 // race the lazy install
                \\  var okCtor = (p.constructor === Foo) ? 1 : 0;
                \\  var inst = new Foo();                  // uses Foo.prototype
                \\  var okInst = (inst instanceof Foo) ? 1 : 0;
                \\  return okCtor * 100 + okInst * 10 + Foo.length; // expect 110 + 2 = 112
                \\})()
            ;
            const owned = a.dupe(u8, src) catch return;
            var parser = Parser.init(a, owned) catch return;
            const prog = parser.parseProgram() catch return;
            var machine = s.ctx.interpreter();
            s.ctx.pushActiveInterpreter(&machine) catch return;
            defer s.ctx.popActiveInterpreter(&machine);
            while (!s.go.load(.acquire)) std.atomic.spinLoopHint();
            const outcome: interp.EvalError!value.Value = if (compiler.Compiler.compileProgram(a, prog)) |chunk|
                vm.run(&machine, chunk, null)
            else |_|
                machine.eval(prog);
            if (outcome) |val| {
                if (val.isNumber()) s.result.store(@intFromFloat(val.asNum()), .monotonic);
            } else |_| {}
        }
    };
    var go = std.atomic.Value(bool).init(false);
    var workers: [nthreads]Worker = undefined;
    for (&workers) |*w| w.* = .{ .ctx = ctx, .go = &go };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    go.store(true, .release);
    for (&pool) |*th| th.join();

    // 110 (constructor identity + instanceof) + Foo.length(2) = 112, for every thread.
    for (&workers) |*w| try std.testing.expectEqual(@as(i64, 112), w.result.load(.monotonic));
}

test "parallel_gc (M3 GIL-removal bring-up): contended primitive and identity collection indexes via real bytecode" {
    // A distinct shared subsystem under real parallel bytecode: N threads each
    // insert disjoint primitive, object, and Symbol keys into shared Map/Set
    // cells, contending their `elements_lock` (which funnels insertion, bucket
    // chains, and rehash). After join every exact-identity lookup must survive:
    // no insert lost or torn, no bucket corruption. TSan-clean proves the index
    // and relocation-stable identity reads are race-free under parallel mutation.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_gc = true,
        .parallel_gc = true,
        .enable_threads = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    _ = try ctx.evaluate(
        \\globalThis.m = new Map();
        \\globalThis.identityMap = new Map();
        \\globalThis.identitySet = new Set();
        \\globalThis.identityKeys = [];
        \\for (let i = 0; i < 1000; i++)
        \\  identityKeys.push({ i }, Symbol("shared:" + i));
    );

    const nthreads = 4;
    const per = 250;
    const Worker = struct {
        ctx: *Context,
        base: usize,
        ok: std.atomic.Value(bool) = .init(false),
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            // Each thread writes its own [base, base+per) block. Identity keys
            // were allocated before the race and remain read-only here.
            var buf: [512]u8 = undefined;
            const src = std.fmt.bufPrint(&buf,
                \\(function(){{
                \\  for (var i = {d}; i < {d}; i++) {{
                \\    m.set(i, i * 2);
                \\    var objectKey = identityKeys[i * 2];
                \\    var symbolKey = identityKeys[i * 2 + 1];
                \\    identityMap.set(objectKey, i * 3);
                \\    identityMap.set(symbolKey, i * 5);
                \\    identitySet.add(objectKey);
                \\    identitySet.add(symbolKey);
                \\  }}
                \\  return true;
                \\}})()
            , .{ s.base, s.base + per }) catch return;
            const owned = a.dupe(u8, src) catch return;
            var parser = Parser.init(a, owned) catch return;
            const prog = parser.parseProgram() catch return;
            var machine = s.ctx.interpreter();
            s.ctx.pushActiveInterpreter(&machine) catch return;
            defer s.ctx.popActiveInterpreter(&machine);
            const outcome: interp.EvalError!value.Value = if (compiler.Compiler.compileProgram(a, prog)) |chunk|
                vm.run(&machine, chunk, null)
            else |_|
                machine.eval(prog);
            if (outcome) |val| s.ok.store(val.isBoolean() and val.asBool(), .release) else |_| {}
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers, 0..) |*w, t| w.* = .{ .ctx = ctx, .base = t * per };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();

    for (&workers) |*w| try std.testing.expect(w.ok.load(.acquire));
    // Verify primitive and exact-identity indexes on the quiescent main thread.
    const size = try ctx.evaluate("m.size");
    try std.testing.expectEqual(@as(f64, nthreads * per), size.asNum());
    const allok = try ctx.evaluate(
        \\(function(){
        \\  for (var k = 0; k < 1000; k++) {
        \\    if (m.get(k) !== k * 2) return false;
        \\    var objectKey = identityKeys[k * 2];
        \\    var symbolKey = identityKeys[k * 2 + 1];
        \\    if (identityMap.get(objectKey) !== k * 3 || identityMap.get(symbolKey) !== k * 5)
        \\      return false;
        \\    if (!identitySet.has(objectKey) || !identitySet.has(symbolKey)) return false;
        \\  }
        \\  return m.size === 1000 && identityMap.size === 2000 && identitySet.size === 2000;
        \\})()
    );
    try std.testing.expect(allok.isBoolean() and allok.asBool());
}

test "parallel_gc (M3 GIL-removal bring-up): shared closure upvalue mutated in parallel stays consistent" {
    // The upvalue path: a closure captures a parent function's local (`n`), and
    // that ONE closure is shared across threads, so every `bump()` reads+writes
    // the same captured binding through `store_upval`/`load_upval` against the
    // shared closure environment. N threads hammer it in parallel with no GIL.
    // `n++` is a read-modify-write so the final value races (lost updates are
    // legal without Atomics), but every observed value must be a valid integer
    // in range — never torn/garbage — and the run must be TSan-clean: the proof
    // that `Environment.binding_lock` serializes upvalue reads/writes + table
    // growth under real parallel bytecode.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true, .enable_threads = true });
    defer ctx.destroy();

    // `shared.bump` closes over the local `n` of `makeCounter`'s activation.
    _ = try ctx.evaluate(
        \\globalThis.shared = (function makeCounter(){
        \\  var n = 0;
        \\  return { bump: function(){ n = n + 1; return n; } };
        \\})();
    );

    const nthreads = 4;
    const per = 1000;
    const Worker = struct {
        ctx: *Context,
        bad: std.atomic.Value(bool) = .init(false), // a bump ever returned out of range
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            // Each call returns the post-increment value of the shared upvalue;
            // it must always be an integer in (0, nthreads*per].
            const src =
                \\(function(){
                \\  var worst = 0;
                \\  for (var i = 0; i < 1000; i++) {
                \\    var v = shared.bump();
                \\    if (typeof v !== "number" || v < 1 || v > 4000 || (v | 0) !== v) worst = -1;
                \\  }
                \\  return worst;
                \\})()
            ;
            const owned = a.dupe(u8, src) catch return;
            var parser = Parser.init(a, owned) catch return;
            const prog = parser.parseProgram() catch return;
            var machine = s.ctx.interpreter();
            s.ctx.pushActiveInterpreter(&machine) catch return;
            defer s.ctx.popActiveInterpreter(&machine);
            const outcome: interp.EvalError!value.Value = if (compiler.Compiler.compileProgram(a, prog)) |chunk|
                vm.run(&machine, chunk, null)
            else |_|
                machine.eval(prog);
            if (outcome) |val| {
                if (val.isNumber() and val.asNum() < 0) s.bad.store(true, .release);
            } else |_| s.bad.store(true, .release);
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers) |*w| w.* = .{ .ctx = ctx };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();

    for (&workers) |*w| try std.testing.expect(!w.bad.load(.acquire)); // every bump in range
    // The final upvalue is some valid count in (0, N*M] (lost updates allowed).
    const final = try ctx.evaluate("shared.bump()");
    try std.testing.expect(final.isNumber());
    try std.testing.expect(final.asNum() >= 1 and final.asNum() <= nthreads * per + 1);
}

test "parallel_gc (M3 GIL-removal bring-up): contended parallel appends to a shared array lose nothing" {
    // Beyond disjoint work: N threads mutate the *same* object in parallel,
    // contending the per-structure lock. Each appends a distinct block of
    // numbers to one shared array (`appendElement` → `elements_lock` + insertion
    // barrier + thread-safe object backing). If the lock correctly serializes the
    // mutators, the array ends with exactly N*M elements and their sum is exact —
    // no append is lost or torn. TSan-clean proves the contended path is race-free.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true });
    defer ctx.destroy();

    const sh0 = gc_mod.setActiveHeap(ctx.gc);
    defer _ = gc_mod.setActiveHeap(sh0);
    const sa0 = strcell.setActiveArena(ctx.arena());
    defer _ = strcell.setActiveArena(sa0);

    const shared = try gc_mod.allocObj(ctx.arena());
    shared.* = .{ .is_array = true };

    const nthreads = 4;
    const per = 1000;
    const Worker = struct {
        ctx: *Context,
        arr: *value.Object,
        base: usize,
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            var i: usize = 0;
            while (i < per) : (i += 1) {
                s.arr.appendElement(a, Value.num(@floatFromInt(s.base + i))) catch return;
            }
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers, 0..) |*w, t| w.* = .{ .ctx = ctx, .arr = shared, .base = t * per };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();

    // No append lost: exactly N*M elements, and the multiset of values is
    // {0 .. N*M-1} (checked by exact sum, since each thread wrote a distinct block).
    try std.testing.expectEqual(@as(usize, nthreads * per), shared.elementsLen());
    var sum: f64 = 0;
    for (0..nthreads * per) |i| {
        const el = shared.elementAt(i) orelse return error.TestUnexpectedResult;
        sum += el.asNum();
    }
    const n: f64 = @floatFromInt(nthreads * per);
    try std.testing.expectEqual(n * (n - 1) / 2, sum); // sum_{0..N*M-1}
}

test "parallel_gc (M3 GIL-removal bring-up): contended parallel property adds + shape growth on a shared object" {
    // The strongest contended case: N threads add distinct *named* properties to
    // the *same* object in parallel — contending `property_lock` AND growing the
    // shared object's shape chain (each add is a `Shape.transition`, serialized +
    // converged under `transition_lock`, allocating through the thread-safe
    // arena). After join the object must carry all N*M properties with correct
    // values — no slot/shape update lost or torn. TSan-clean.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true });
    defer ctx.destroy();

    const sh0 = gc_mod.setActiveHeap(ctx.gc);
    defer _ = gc_mod.setActiveHeap(sh0);
    const sa0 = strcell.setActiveArena(ctx.arena());
    defer _ = strcell.setActiveArena(sa0);

    const shared = try gc_mod.allocObj(ctx.arena());
    shared.* = .{};

    const nthreads = 4;
    const per = 500;
    const Worker = struct {
        ctx: *Context,
        obj: *value.Object,
        base: usize,
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            var buf: [24]u8 = undefined;
            var i: usize = 0;
            while (i < per) : (i += 1) {
                const key = std.fmt.bufPrint(&buf, "k{d}", .{s.base + i}) catch return;
                s.obj.setOwn(a, s.ctx.root_shape, key, Value.num(@floatFromInt(s.base + i))) catch return;
            }
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers, 0..) |*w, t| w.* = .{ .ctx = ctx, .obj = shared, .base = t * per };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();

    // Every one of the N*M distinct properties is present with the right value.
    var buf: [24]u8 = undefined;
    var k: usize = 0;
    while (k < nthreads * per) : (k += 1) {
        const key = try std.fmt.bufPrint(&buf, "k{d}", .{k});
        const got = shared.getOwn(key) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(f64, @floatFromInt(k)), got.asNum());
    }
}

test "parallel_gc (M3 GIL-removal bring-up): concurrent reader + writer on a shared global env is race-free" {
    // The reader-vs-writer case: one thread defines bindings on the shared global
    // env (`put` → `binding_lock`, rehashing the table) while another thread
    // repeatedly reads them (`get`). Now that `get` reads each scope's binding
    // tables under the same `binding_lock` the writer takes, the read can't tear
    // against, or read a freed table from, a concurrent rehash. The reader sees
    // each binding as either absent or its correct value — never garbage —
    // and the run is TSan-clean.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true });
    defer ctx.destroy();

    const sh0 = gc_mod.setActiveHeap(ctx.gc);
    defer _ = gc_mod.setActiveHeap(sh0);
    const sa0 = strcell.setActiveArena(ctx.arena());
    defer _ = strcell.setActiveArena(sa0);

    const n = 1000;
    const Shared = struct {
        ctx: *Context,
        done: std.atomic.Value(bool) = .init(false),
        bad: std.atomic.Value(bool) = .init(false), // set if a read ever sees a wrong value

        fn writer(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            var buf: [24]u8 = undefined;
            var i: usize = 0;
            while (i < n) : (i += 1) {
                const name = std.fmt.bufPrint(&buf, "g{d}", .{i}) catch break;
                s.ctx.env.put(name, Value.num(@floatFromInt(i))) catch break;
            }
            s.done.store(true, .release);
        }
        fn reader(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            var buf: [24]u8 = undefined;
            // Keep reading until the writer is done (and one full pass after).
            while (true) {
                const fin = s.done.load(.acquire);
                var i: usize = 0;
                while (i < n) : (i += 1) {
                    const name = std.fmt.bufPrint(&buf, "g{d}", .{i}) catch break;
                    if (s.ctx.env.get(name)) |v| {
                        // Present → must be the exact value the writer stored.
                        if (v.asNum() != @as(f64, @floatFromInt(i))) s.bad.store(true, .release);
                    }
                }
                if (fin) break;
                std.atomic.spinLoopHint();
            }
        }
    };
    var shared = Shared{ .ctx = ctx };
    const wt = try std.Thread.spawn(.{}, Shared.writer, .{&shared});
    const rt = try std.Thread.spawn(.{}, Shared.reader, .{&shared});
    wt.join();
    rt.join();

    try std.testing.expect(!shared.bad.load(.acquire)); // no torn/garbage read
    // After both finish, every binding is present and correct.
    var buf: [24]u8 = undefined;
    var i: usize = 0;
    while (i < n) : (i += 1) {
        const name = try std.fmt.bufPrint(&buf, "g{d}", .{i});
        const v = ctx.env.get(name) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(f64, @floatFromInt(i)), v.asNum());
    }
}

test "parallel_gc (M3 GIL-removal bring-up): quiescent collection after a parallel build keeps the live graph, reclaims the garbage" {
    // The complete parallel-GC model, end-to-end: N threads concurrently build a
    // *rooted* shared object graph (each appends `id`-bearing objects to one array
    // hung off `globalThis`, contending `elements_lock` + the insertion barrier)
    // while also churning out throwaway garbage. Threads join — bringing the heap
    // to quiescence — and only THEN does a collection run (`collectGarbage`).
    //
    // This is the model that holds today without the (deferred) mid-script STW
    // barrier: mutate fully in parallel, collect at a quiescent point. The
    // collector must (a) keep every object reachable from the rooted array alive
    // and intact, and (b) actually reclaim the per-thread garbage. TSan-clean
    // proves the parallel build that feeds the collector is itself race-free.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true });
    defer ctx.destroy();

    const sh0 = gc_mod.setActiveHeap(ctx.gc);
    defer _ = gc_mod.setActiveHeap(sh0);
    const sa0 = strcell.setActiveArena(ctx.arena());
    defer _ = strcell.setActiveArena(sa0);

    // The shared array is rooted: hung off the (root-traced) global object, so the
    // graph reachable through it must survive collection.
    const shared = try gc_mod.allocObj(ctx.arena());
    shared.* = .{ .is_array = true };
    try ctx.global_object.setOwn(ctx.gpa, ctx.root_shape, "live", Value.obj(shared));

    const nthreads = 4;
    const per = 1000;
    const Worker = struct {
        ctx: *Context,
        arr: *value.Object,
        base: usize,
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            const a = s.ctx.arena();
            var i: usize = 0;
            while (i < per) : (i += 1) {
                // Live: an id-bearing object appended to the rooted array.
                const o = gc_mod.allocObj(a) catch return;
                o.* = .{};
                o.setOwn(a, s.ctx.root_shape, "id", Value.num(@floatFromInt(s.base + i))) catch return;
                s.arr.appendElement(a, Value.obj(o)) catch return;
                // Garbage: an unreachable object created and immediately dropped.
                const g = gc_mod.allocObj(a) catch return;
                g.* = .{};
                g.setOwn(a, s.ctx.root_shape, "junk", Value.num(@floatFromInt(s.base + i))) catch return;
            }
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers, 0..) |*w, t| w.* = .{ .ctx = ctx, .arr = shared, .base = t * per };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();

    // Quiescent collection: every thread has joined, the heap is at rest.
    ctx.collectGarbage();
    try std.testing.expect(ctx.gc.?.collections >= 1);

    // The live graph is intact: exactly N*M elements, each a surviving id-bearing
    // object whose property reads back correctly (the multiset of ids is
    // {0 .. N*M-1}, checked by exact sum).
    try std.testing.expectEqual(@as(usize, nthreads * per), shared.elementsLen());
    var sum: f64 = 0;
    for (0..nthreads * per) |i| {
        const el = shared.elementAt(i) orelse return error.TestUnexpectedResult;
        try std.testing.expect(el.isObject());
        const got = el.asObj().getOwn("id") orelse return error.TestUnexpectedResult;
        sum += got.asNum();
    }
    const n: f64 = @floatFromInt(nthreads * per);
    try std.testing.expectEqual(n * (n - 1) / 2, sum); // sum_{0..N*M-1}
}

test "parallel_gc (M3 GIL-removal bring-up): GlobalSymbolRegistry get-or-create is atomic" {
    // The GlobalSymbolRegistry (`Symbol.for`) is a check-then-act over shared
    // object storage: look the key up, and only register a fresh symbol if
    // absent. Without serialization, two threads calling `Symbol.for(k)` could
    // both miss the lookup and register *distinct* symbols for the same key —
    // breaking `Symbol.for(k) === Symbol.for(k)`. `Gil.symbol_registry_lock`
    // (taken by `symbolForFn`/`symbolRegistry`) makes the whole get-or-create
    // atomic. This drives that exact critical section concurrently over a shared
    // registry object: every thread must agree on one symbol identity per key,
    // and the registry must hold exactly one entry per key. TSan-clean.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{ .enable_gc = true, .parallel_gc = true, .enable_threads = true });
    defer ctx.destroy();
    const g = ctx.gil orelse return error.TestUnexpectedResult;

    const sh0 = gc_mod.setActiveHeap(ctx.gc);
    defer _ = gc_mod.setActiveHeap(sh0);
    const sa0 = strcell.setActiveArena(ctx.arena());
    defer _ = strcell.setActiveArena(sa0);

    const reg = try gc_mod.allocObj(ctx.arena());
    reg.* = .{};

    const nthreads = 4;
    const nkeys = 16;
    const Worker = struct {
        ctx: *Context,
        gil: *@import("gil.zig").Gil,
        reg: *value.Object,
        seen: [nkeys]?*value.Object = undefined,
        fn run(s: *@This()) void {
            const sh = gc_mod.setActiveHeap(s.ctx.gc);
            defer _ = gc_mod.setActiveHeap(sh);
            const sa = strcell.setActiveArena(s.ctx.arena());
            defer _ = strcell.setActiveArena(sa);
            for (&s.seen) |*p| p.* = null;
            const a = s.ctx.arena();
            // Several passes so threads heavily overlap on the same keys.
            var pass: usize = 0;
            while (pass < 64) : (pass += 1) {
                var k: usize = 0;
                while (k < nkeys) : (k += 1) {
                    var buf: [8]u8 = undefined;
                    const key = std.fmt.bufPrint(&buf, "s{d}", .{k}) catch return;
                    // The exact `symbolForFn` critical section: atomic get-or-create.
                    s.gil.lockSymbolRegistry();
                    const sym = if (s.reg.getOwn(key)) |existing| existing.asObj() else blk: {
                        const o = gc_mod.allocObj(a) catch {
                            s.gil.unlockSymbolRegistry();
                            return;
                        };
                        o.* = .{ .is_symbol = true };
                        s.reg.setOwn(a, s.ctx.root_shape, key, Value.obj(o)) catch {
                            s.gil.unlockSymbolRegistry();
                            return;
                        };
                        break :blk o;
                    };
                    s.gil.unlockSymbolRegistry();
                    // Identity must be stable for this key across all passes/threads.
                    if (s.seen[k]) |prev| {
                        if (prev != sym) return; // leaves a null/ mismatch the assert catches
                    } else s.seen[k] = sym;
                }
            }
        }
    };
    var workers: [nthreads]Worker = undefined;
    for (&workers) |*w| w.* = .{ .ctx = ctx, .gil = g, .reg = reg };
    var pool: [nthreads]std.Thread = undefined;
    for (&pool, 0..) |*th, t| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[t]});
    for (&pool) |*th| th.join();

    // Every key resolved to exactly one symbol object, and all threads agree.
    var k: usize = 0;
    while (k < nkeys) : (k += 1) {
        var buf: [8]u8 = undefined;
        const key = try std.fmt.bufPrint(&buf, "s{d}", .{k});
        const canonical = (reg.getOwn(key) orelse return error.TestUnexpectedResult).asObj();
        for (workers) |w| {
            const got = w.seen[k] orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(canonical, got); // single shared identity
        }
    }
}

test "parallel_js (M3 GIL-removal slice): real Thread contends Atomics.Mutex with no context GIL" {
    // Vertical slice of the execution-path GIL drop: the public shared-realm
    // Thread entrypoint runs JS without holding the context GIL, and multiple
    // JS threads contend the production Atomics.Mutex/Lock record. The mutex's
    // own std.Io.Mutex+Condition must serialize the critical section; the shared
    // object update is ordinary JS, so without the mutex exactness is not
    // guaranteed. TSan-clean here proves the production sync path no longer
    // depends on the GIL for mutual exclusion.
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    const result = try ctx.evaluate(
        \\if ($vm.useThreadGIL() !== false) throw new Error("parallel_js did not drop the thread GIL");
        \\const mutex = new Atomics.Mutex();
        \\const shared = { n: 0 };
        \\const threads = [];
        \\for (let t = 0; t < 4; t++) {
        \\  threads.push(new Thread(() => {
        \\    if ($vm.useThreadGIL() !== false) throw new Error("worker still holds the thread GIL");
        \\    for (let i = 0; i < 500; i++) {
        \\      const token = Atomics.Mutex.lock(mutex);
        \\      shared.n = shared.n + 1;
        \\      token.unlock();
        \\    }
        \\    return true;
        \\  }));
        \\}
        \\for (const t of threads) {
        \\  if (t.join() !== true) throw new Error("bad worker result");
        \\}
        \\shared.n;
    );
    try std.testing.expectEqual(@as(f64, 2000), result.asNum());
}

test "parallel_js: Map iterator cursor advances atomically without GIL" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    const result = try ctx.evaluate(
        \\if ($vm.useThreadGIL() !== false) throw new Error("parallel_js did not drop the thread GIL");
        \\const map = new Map();
        \\for (let i = 0; i < 1024; i++) map.set(i, i);
        \\const iterator = map.values();
        \\function drain() {
        \\  let count = 0, sum = 0;
        \\  while (true) {
        \\    const step = iterator.next();
        \\    if (step.done) return count * 1000000 + sum;
        \\    count++;
        \\    sum += step.value;
        \\  }
        \\}
        \\const threads = [];
        \\for (let i = 0; i < 4; i++) threads.push(new Thread(drain));
        \\let count = 0, sum = 0;
        \\for (const thread of threads) {
        \\  const packed = thread.join();
        \\  count += Math.floor(packed / 1000000);
        \\  sum += packed % 1000000;
        \\}
        \\count === 1024 && sum === 523776 && iterator.next().done === true
    );
    try std.testing.expect(result.asBool());
}

test "parallel_js: shared Map/Set cursors stay exact across kinds, concurrent mutation, and GC" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    // Four threads race `next()` over every cursor kind while the main script
    // mutates the live collections and forces young-gen compaction between
    // rounds. Each drained result must be unique (one transaction per entry),
    // exhausted cursors stay idempotent, and post-compaction iteration still
    // observes only live entries.
    const result = try ctx.evaluate(
        \\if ($vm.useThreadGIL() !== false) throw new Error("parallel_js did not drop the thread GIL");
        \\const map = new Map();
        \\const set = new Set();
        \\for (let i = 0; i < 512; i++) { map.set(i, i * 2); set.add(i); }
        \\const cursors = [map.keys(), map.values(), map.entries(), set.values(), set.entries()];
        \\globalThis.drained = [];
        \\function drain(c) {
        \\  let out = "";
        \\  for (;;) {
        \\    const step = c.next();
        \\    if (step.done) break;
        \\    out += step.value + ";";
        \\  }
        \\  return out;
        \\}
        \\function drainAll() {
        \\  let packed = 0;
        \\  for (let k = 0; k < cursors.length; k++) packed += drain(cursors[k]).length;
        \\  return packed;
        \\}
        \\for (let round = 0; round < 3; round++) {
        \\  const threads = [];
        \\  for (let t = 0; t < 3; t++) threads.push(new Thread(drainAll));
        \\  let total = 0;
        \\  for (const thread of threads) total += thread.join();
        \\  if (round === 0 && total <= 0) throw new Error("no concurrent drain output");
        \\  map.set(1000 + round, round);
        \\  set.add(1000 + round);
        \\  if (round === 1) { map.delete(7); set.delete(7); }
        \\  $vm.gc();
        \\}
        \\cursors.every((c) => c.next().done === true) &&
        \\  map.get(1002) === 2 && !set.has(7) && set.has(1000)
    );
    try std.testing.expect(result.asBool());
}

test "parallel_js: WeakMap and WeakSet identity indexes serialize disjoint mutation" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();

    const result = try ctx.evaluate(
        \\if ($vm.useThreadGIL() !== false) throw new Error("parallel_js did not drop the thread GIL");
        \\const weakKeys = [];
        \\const weakMap = new WeakMap();
        \\const weakSet = new WeakSet();
        \\for (let i = 0; i < 512; i++) {
        \\  const key = (i & 1) === 0 ? { index: i } : Symbol("parallel-weak:" + i);
        \\  weakKeys.push(key);
        \\  weakMap.set(key, i);
        \\  weakSet.add(key);
        \\}
        \\function mutateWeakLane(lane) {
        \\  for (let i = lane; i < weakKeys.length; i += 4) {
        \\    const key = weakKeys[i];
        \\    for (let round = 0; round < 8; round++) {
        \\      weakMap.set(key, i + round);
        \\      weakSet.add(key);
        \\      if (weakMap.get(key) !== i + round || !weakMap.has(key) || !weakSet.has(key)) return false;
        \\      if (round === 3) {
        \\        if (!weakMap.delete(key) || weakMap.has(key)) return false;
        \\        if (!weakSet.delete(key) || weakSet.has(key)) return false;
        \\        weakMap.set(key, i + round);
        \\        weakSet.add(key);
        \\      }
        \\    }
        \\  }
        \\  return true;
        \\}
        \\const threads = [];
        \\for (let lane = 0; lane < 4; lane++) threads.push(new Thread(mutateWeakLane, lane));
        \\for (const thread of threads) if (thread.join() !== true) throw new Error("weak worker failed");
        \\let checksum = 0;
        \\for (let i = 0; i < weakKeys.length; i++) {
        \\  if (weakMap.get(weakKeys[i]) !== i + 7 || !weakSet.has(weakKeys[i])) throw new Error("weak result drift");
        \\  checksum += weakMap.get(weakKeys[i]);
        \\}
        \\checksum
    );
    try std.testing.expectEqual(@as(f64, 134_400), result.asNum());
}

test "parallel_js: cooperative shared nursery rendezvous bounds object churn" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .enable_jit = false,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    // Keep the production tranche unchanged. Tracking is armed when the second
    // worker record is registered, so both workers rendezvous before allocating:
    // the first cannot finish its otherwise-untracked churn while the main
    // interpreter is still constructing the second Thread. The two released
    // lanes then each create more than 512 KiB of 128-byte Object-class cells.
    // Either lane therefore crosses the unchanged production tranche while
    // the peer remains registered, independent of scheduler placement.
    ctx.gc_cooperative_tranche_bytes = 512 * 1024;
    try std.testing.expect(ctx.beginCooperativeGcProfile());

    const result = try ctx.evaluate(
        \\const cooperativeChurnGate = new Int32Array(new SharedArrayBuffer(4));
        \\function cooperativeChurn(lane) {
        \\  Atomics.add(cooperativeChurnGate, 0, 1);
        \\  while (Atomics.load(cooperativeChurnGate, 0) !== 2) {}
        \\  const ring = [];
        \\  for (let i = 0; i < 64; i++) ring.push({ value: i, lane: lane, prior: 0 });
        \\  for (let i = 0; i < 4800; i++) {
        \\    const index = i & 63;
        \\    const old = ring[index];
        \\    ring[index] = { value: old.value + i + lane, lane: lane, prior: old.value };
        \\  }
        \\  return 1264 + lane;
        \\}
        \\const first = new Thread(cooperativeChurn, 0);
        \\const second = new Thread(cooperativeChurn, 1);
        \\first.join() + second.join();
    );
    const profile = ctx.endCooperativeGcProfile() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(f64, 2529), result.asNum());
    try std.testing.expect(ctx.gc_cooperative_attempts.load(.monotonic) > 0);
    try std.testing.expect(ctx.gc_cooperative_collections.load(.monotonic) > 0);
    try std.testing.expect(ctx.gc_cooperative_peer_parks.load(.monotonic) > 0);
    try std.testing.expectEqual(profile.attempts, profile.collections + profile.timeouts);
    // TSan can suspend a mutator beyond the deliberately short production
    // rendezvous deadline. A bounded retry is valid there; unsanitized runs
    // must still complete every election without timing out.
    if (!builtin.sanitize_thread) try std.testing.expectEqual(@as(u64, 0), profile.timeouts);
    try std.testing.expectEqual(profile.collections, profile.minor_profile_cycles);
    try std.testing.expect(profile.bytesIssued() > 0);
    try std.testing.expect(profile.pause_ns_total >= profile.rendezvous_ns_total);
    try std.testing.expect(profile.minor_prepare_ns_total > 0);
    try std.testing.expect(profile.minor_trace_ns_total > 0);
    try std.testing.expect(profile.minor_sweep_ns_total > 0);
    try std.testing.expectEqual(@as(u64, 0), ctx.gc_par_request.load(.acquire));
    try std.testing.expectEqual(@as(?*interp.Interpreter, null), ctx.gc_par_collector.load(.acquire));
}

test "parallel_js moving nursery copies survivors at a shared exact rendezvous" {
    if (builtin.single_threaded or !jit.supported or builtin.cpu.arch != .aarch64)
        return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    ctx.gc_cooperative_tranche_bytes = 1024 * 1024;

    _ = try ctx.evaluate(
        \\globalThis.movingNurseryWitness = { marker: 0, child: { warm: true } };
        \\globalThis.movingNurseryGate = new Int32Array(new SharedArrayBuffer(4));
        \\function movingNurserySpin(limit, held) {
        \\  var cursor = 0;
        \\  while (cursor < limit) cursor = cursor + 1;
        \\  return held.marker;
        \\}
        \\function movingNurseryLane(lane) {
        \\  var ring = [];
        \\  for (var i = 0; i < 64; i = i + 1)
        \\    ring.push({ value: i, lane: lane, prior: 0 });
        \\  for (var i = 0; i < 6000; i = i + 1) {
        \\    var index = i & 63;
        \\    var old = ring[index];
        \\    ring[index] = { value: old.value + i + lane, lane: lane, prior: old.value };
        \\  }
        \\  Atomics.add(movingNurseryGate, 0, 1);
        \\  while (Atomics.load(movingNurseryGate, 0) !== 3) {}
        \\  return movingNurserySpin(2000000, movingNurseryWitness) + lane;
        \\}
        \\for (var warm = 0; warm < 10; warm = warm + 1)
        \\  movingNurserySpin(6, movingNurseryWitness);
    );
    const spin_object = ctx.global_object.getOwn("movingNurserySpin").?.asObj();
    const spin_function: *interp.Function = @ptrCast(@alignCast(spin_object.jsFunction().?));
    const spin_chunk = spin_function.chunk orelse return error.TestUnexpectedResult;
    const spin_artifact = spin_chunk.optimizer_tier.loadArtifact(jit.CompiledCode) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(jit.CodeKind.optimizer, spin_artifact.kind);
    try std.testing.expect(spin_artifact.osr != null and spin_artifact.stack_maps != null);

    // Code, global infrastructure, and the SharedArrayBuffer side records are
    // old before the moving-minor witness is introduced. The cycle below then
    // moves the live young data graph while native frames keep executing the
    // already-tenured function metadata.
    ctx.collectGarbage();
    const heap = ctx.gc.?;
    heap.nursery_threshold_bytes = 1024 * 1024;
    _ = try ctx.evaluate(
        \\globalThis.movingNurseryWitness = { marker: 365, child: { live: true } };
        \\globalThis.movingNurseryWeakKeys = [];
        \\globalThis.movingNurseryWeakMap = new WeakMap();
        \\globalThis.movingNurseryWeakSet = new WeakSet();
        \\for (let i = 0; i < 256; i++) {
        \\  const key = (i & 1) === 0 ? { index: i } : Symbol("moving-nursery:" + i);
        \\  movingNurseryWeakKeys.push(key);
        \\  movingNurseryWeakMap.set(key, i * 3);
        \\  movingNurseryWeakSet.add(key);
        \\}
    );
    const handle = try ctx.protectValue(ctx.global_object.getOwn("movingNurseryWitness").?);
    defer std.debug.assert(ctx.unprotectValue(handle));
    const witness_before = @intFromPtr(handle.get().asObj());
    const accounting_before = heap.accounting();
    const attempts_before = ctx.gc_cooperative_attempts.load(.monotonic);
    const collections_before = ctx.gc_cooperative_collections.load(.monotonic);
    const parks_before = ctx.gc_cooperative_peer_parks.load(.monotonic);
    const timeouts_before = ctx.gc_cooperative_timeouts.load(.monotonic);
    const osr_before = vm.optimizerOsrEntriesForTesting();

    const result = try ctx.evaluate(
        \\var movingNurseryFirst = new Thread(movingNurseryLane, 1);
        \\var movingNurserySecond = new Thread(movingNurseryLane, 2);
        \\var movingNurseryMain = movingNurseryLane(3);
        \\movingNurseryMain + movingNurseryFirst.join() + movingNurserySecond.join();
    );
    try std.testing.expectEqual(@as(f64, 1101), result.asNum());

    const accounting_after = heap.accounting();
    try std.testing.expect(accounting_after.moving_minor_collections > accounting_before.moving_minor_collections);
    try std.testing.expect(accounting_after.total_minor_moved_cells > accounting_before.total_minor_moved_cells);
    try std.testing.expect(accounting_after.total_minor_moved_bytes > accounting_before.total_minor_moved_bytes);
    try std.testing.expect(ctx.gc_cooperative_attempts.load(.monotonic) > attempts_before);
    try std.testing.expect(ctx.gc_cooperative_collections.load(.monotonic) > collections_before);
    try std.testing.expect(ctx.gc_cooperative_peer_parks.load(.monotonic) > parks_before);
    const attempts = ctx.gc_cooperative_attempts.load(.monotonic) - attempts_before;
    const collections = ctx.gc_cooperative_collections.load(.monotonic) - collections_before;
    const timeouts = ctx.gc_cooperative_timeouts.load(.monotonic) - timeouts_before;
    // Every elected cooperative attempt has exactly one terminal outcome. The
    // number of bounded retries depends on host scheduling under a sharded run;
    // collection success and complete accounting are the stable invariants.
    try std.testing.expectEqual(attempts, collections + timeouts);
    try std.testing.expect(vm.optimizerOsrEntriesForTesting() > osr_before);
    try std.testing.expect(witness_before != @intFromPtr(handle.get().asObj()));
    try std.testing.expectEqual(@as(f64, 365), handle.get().asObj().getOwn("marker").?.asNum());
    const weak_result = try ctx.evaluate(
        \\let movingWeakChecksum = 0;
        \\for (let i = 0; i < movingNurseryWeakKeys.length; i++) {
        \\  const key = movingNurseryWeakKeys[i];
        \\  if (!movingNurseryWeakMap.has(key) || !movingNurseryWeakSet.has(key)) throw new Error("moved weak key missing");
        \\  movingWeakChecksum += movingNurseryWeakMap.get(key);
        \\}
        \\movingWeakChecksum
    );
    try std.testing.expectEqual(@as(f64, 97_920), weak_result.asNum());
    const moving_weak_state = ctx.global_object.getOwn("movingNurseryWeakMap").?.asObj().collectionState().?;
    try std.testing.expectEqual(@as(usize, 256), moving_weak_state.weak_index.count());
    try std.testing.expect(!ctx.gc_moving_checkpoint_requested.load(.acquire));
    try std.testing.expectEqual(@as(u64, 0), ctx.gc_par_request.load(.acquire));
    try std.testing.expectEqual(@as(?*interp.Interpreter, null), ctx.gc_par_collector.load(.acquire));
}

test "parallel_js moving nursery retries after a bounded opaque-peer timeout" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .enable_jit = false,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    heap.nursery_threshold_bytes = std.math.maxInt(usize);
    _ = try ctx.evaluate("globalThis.movingRetryRoot = { marker: 366 };");
    const handle = try ctx.protectValue(ctx.global_object.getOwn("movingRetryRoot").?);
    defer std.debug.assert(ctx.unprotectValue(handle));
    const root_before = handle.get().asObj();
    const moving_before = heap.accounting().moving_minor_collections;
    const timeouts_before = ctx.gc_cooperative_timeouts.load(.monotonic);

    ctx.gc_cooperative_tranche_bytes = 1;
    heap.nursery_threshold_bytes = 1;
    const backing = ctx.gc_cell_backing.?;
    backing.parallel_cell_bytes_since_collection.store(1, .release);
    ctx.gc_moving_checkpoint_requested.store(true, .release);

    var collector = ctx.interpreter();
    var peer = ctx.interpreter();
    try ctx.pushActiveInterpreter(&collector);
    defer ctx.popActiveInterpreter(&collector);
    try ctx.pushActiveInterpreter(&peer);
    defer ctx.popActiveInterpreter(&peer);
    collector.gc_precise_safepoint = true;
    collector.gc_moving_safepoint = true;
    peer.gc_parked.store(true, .release);
    defer peer.gc_parked.store(false, .release);

    // This peer is frozen at an opaque/native boundary. The 100 ms rendezvous
    // must abort without consuming the moving request or changing any address.
    ctx.serviceCooperativeYoungGc(heap, &collector);
    try std.testing.expectEqual(timeouts_before + 1, ctx.gc_cooperative_timeouts.load(.monotonic));
    try std.testing.expectEqual(root_before, handle.get().asObj());
    try std.testing.expectEqual(moving_before, heap.accounting().moving_minor_collections);
    try std.testing.expect(ctx.gc_moving_checkpoint_requested.load(.acquire));
    try std.testing.expect(backing.parallelCellBytesSinceCollection() >= 1);

    // Publish the next exact generation and retry. No allocation or graph
    // mutation occurred during the aborted attempt, so the same request can
    // complete and rewrite the protected root.
    ctx.gc_par_retry_after_ns.store(0, .release);
    peer.gc_moving_parked.store(true, .release);
    defer peer.gc_moving_parked.store(false, .release);
    peer.gc_published_gen.store(ctx.gc_par_next_request.load(.monotonic), .release);
    ctx.serviceCooperativeYoungGc(heap, &collector);

    try std.testing.expect(root_before != handle.get().asObj());
    try std.testing.expectEqual(moving_before + 1, heap.accounting().moving_minor_collections);
    try std.testing.expectEqual(@as(f64, 366), handle.get().asObj().getOwn("marker").?.asNum());
    try std.testing.expect(!ctx.gc_moving_checkpoint_requested.load(.acquire));
    try std.testing.expectEqual(@as(u64, 0), ctx.gc_par_request.load(.acquire));
    try std.testing.expectEqual(@as(?*interp.Interpreter, null), ctx.gc_par_collector.load(.acquire));
}

test "parallel_js: cooperative nursery roots caller scopes beneath nested VM calls" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .enable_jit = false,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    ctx.gc_cooperative_tranche_bytes = 256 * 1024;

    const result = try ctx.evaluate(
        \\function nestedChurn(seed, iteration) {
        \\  let tail = null;
        \\  for (let i = 0; i < 48; i++)
        \\    tail = { seed, iteration, i, prior: tail };
        \\  return tail.i;
        \\}
        \\function callerScopeLane(seed) {
        \\  const retained = { token: seed };
        \\  let checksum = 0;
        \\  for (let i = 0; i < 1200; i++) {
        \\    checksum += nestedChurn(seed, i);
        \\    if (retained.token !== seed)
        \\      throw new Error("caller scope lost beneath nested call");
        \\  }
        \\  return retained.token + checksum;
        \\}
        \\const first = new Thread(callerScopeLane, 11);
        \\const second = new Thread(callerScopeLane, 29);
        \\first.join() + second.join();
    );
    try std.testing.expectEqual(@as(f64, 112840), result.asNum());
    const collections = ctx.gc_cooperative_collections.load(.monotonic);
    const attempts = ctx.gc_cooperative_attempts.load(.monotonic);
    const timeouts = ctx.gc_cooperative_timeouts.load(.monotonic);
    try std.testing.expect(collections > 0);
    try std.testing.expect(ctx.gc_cooperative_peer_parks.load(.monotonic) > 0);
    // Bounded rendezvous retries depend on host scheduling; every elected
    // attempt must still publish exactly one collection-or-timeout outcome.
    try std.testing.expectEqual(attempts, collections + timeouts);
}

test "parallel_js: multi-age cooperative nursery retains old-owner graph" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const ctx = try Context.createWithTestingOptions(std.testing.allocator, .{
        .enable_threads = true,
        .enable_gc = true,
        .enable_jit = false,
        .parallel_gc = true,
        .parallel_js = true,
    });
    defer ctx.destroy();
    ctx.gc_cooperative_tranche_bytes = 256 * 1024;

    _ = try ctx.evaluate("globalThis.multiAgeShared = { child: null }");
    ctx.collectGarbage();
    const heap = ctx.gc.?;
    const collections_before = ctx.gc_cooperative_collections.load(.monotonic);
    const attempts_before = ctx.gc_cooperative_attempts.load(.monotonic);
    const timeouts_before = ctx.gc_cooperative_timeouts.load(.monotonic);
    const parks_before = ctx.gc_cooperative_peer_parks.load(.monotonic);
    const promoted_before = heap.promoted_cells;

    const result = try ctx.evaluate(
        \\multiAgeShared.child = { value: 41 };
        \\function multiAgeChurn(lane) {
        \\  const ring = [];
        \\  for (let i = 0; i < 64; i++) ring.push({ value: i, lane });
        \\  for (let i = 0; i < 6000; i++) {
        \\    const index = i & 63;
        \\    ring[index] = { value: ring[index].value + i + lane, lane };
        \\    if ((i & 255) === 0 && multiAgeShared.child.value !== 41)
        \\      throw new Error("multi-age child changed");
        \\  }
        \\  return 100 + lane;
        \\}
        \\const first = new Thread(multiAgeChurn, 0);
        \\const second = new Thread(multiAgeChurn, 1);
        \\multiAgeShared.child.value + first.join() + second.join();
    );
    try std.testing.expectEqual(@as(f64, 242), result.asNum());
    const collections = ctx.gc_cooperative_collections.load(.monotonic) - collections_before;
    const attempts = ctx.gc_cooperative_attempts.load(.monotonic) - attempts_before;
    const timeouts = ctx.gc_cooperative_timeouts.load(.monotonic) - timeouts_before;
    try std.testing.expect(collections >= runtime_gc_tenuring_age);
    try std.testing.expect(attempts > 0);
    try std.testing.expect(ctx.gc_cooperative_peer_parks.load(.monotonic) > parks_before);
    // A peer may miss the bounded 100 ms rendezvous under a sharded run. The
    // retry count is scheduler-dependent; successful tenuring and exact
    // terminal-outcome accounting are the stable collector invariants.
    try std.testing.expectEqual(attempts, collections + timeouts);
    try std.testing.expectEqual(@as(u64, 0), ctx.gc_par_request.load(.acquire));
    try std.testing.expectEqual(@as(?*interp.Interpreter, null), ctx.gc_par_collector.load(.acquire));
    try std.testing.expect(heap.promoted_cells > promoted_before);
    try std.testing.expect(heap.last_minor_survived_cells > 0);
    try std.testing.expectEqual(@as(f64, 41), (try ctx.evaluate("multiAgeShared.child.value")).asNum());
}

