test "enable_gc: a collection re-entered from a finalizer is declined, not deadlocked" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();

    // The JIT/GC conductor is a plain non-reentrant gate, and every collection
    // takes it before running finalizers. A host finalizer that calls back into
    // `collectGarbage` therefore used to spin against the lock its own thread
    // already held — an infinite loop at 100% CPU, not a slow test. Two C-API
    // finalizer tests hung on exactly this; the guard is pinned here so a
    // future conductor change cannot quietly reintroduce it without a failure
    // that names the cause.
    try std.testing.expect(!ctx.holdsJitGcConductor());
    ctx.enterJitGcConductor();
    try std.testing.expect(ctx.holdsJitGcConductor());
    // Re-entry must return immediately rather than wait for a lock this thread
    // is holding. Reaching the next line at all is the assertion.
    ctx.collectGarbage();
    ctx.leaveJitGcConductor();

    // The gate is released and ownership cleared, so an ordinary collection
    // still runs afterwards.
    try std.testing.expect(!ctx.holdsJitGcConductor());
    ctx.collectGarbage();
    try std.testing.expect(!ctx.holdsJitGcConductor());
}

test "enable_gc: runtime StringCells are traced and finalized" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true });
    defer ctx.destroy();

    // Retire bootstrap garbage first so the byte-accounting assertions below
    // describe only the three cells created by this test.
    ctx.collectGarbage();
    const baseline = ctx.gc_string_bytes_live;

    const kept_text = "kept-\xF0\x9F\x98\x80";
    const owned_text = "owned-\xED\xA0\x80"; // one lone WTF-8 high surrogate
    const garbage_text = "garbage-string";
    {
        const gc_saved = gc_mod.setActiveHeap(ctx.gc);
        defer _ = gc_mod.setActiveHeap(gc_saved);
        const string_arena_saved = strcell.setActiveArena(ctx.arena());
        defer _ = strcell.setActiveArena(string_arena_saved);

        const kept = try Value.strAlloc(ctx.arena(), kept_text);
        const owned_source = try ctx.gpa.dupe(u8, owned_text);
        const owned = try Value.strOwned(ctx.gpa, owned_source);
        _ = try Value.strAlloc(ctx.arena(), garbage_text);
        try std.testing.expect(kept.asStringCell().isGcManaged());
        try std.testing.expect(owned.asStringCell().isGcManaged());
        try ctx.env.put("__gc_kept_string", kept);
        try ctx.env.put("__gc_owned_string", owned);
    }

    try std.testing.expectEqual(
        baseline + kept_text.len + owned_text.len + garbage_text.len,
        ctx.gc_string_bytes_live,
    );
    var stats = Context.GcFinalizerStats{};
    ctx.gc_finalizer_stats_out = &stats;
    defer ctx.gc_finalizer_stats_out = null;
    ctx.collectGarbage();
    try std.testing.expectEqual(baseline + kept_text.len + owned_text.len, ctx.gc_string_bytes_live);
    try std.testing.expectEqualStrings(kept_text, ctx.env.get("__gc_kept_string").?.asStr());
    try std.testing.expectEqualStrings(owned_text, ctx.env.get("__gc_owned_string").?.asStr());
    try std.testing.expectEqual(@as(usize, 1), stats.strings);

    try ctx.env.put("__gc_kept_string", Value.undef());
    try ctx.env.put("__gc_owned_string", Value.undef());
    ctx.collectGarbage();
    try std.testing.expectEqual(baseline, ctx.gc_string_bytes_live);
    try std.testing.expectEqual(@as(usize, 3), stats.strings);
}

test "enable_gc: moving StringCell preserves and finalizes UTF-16 index" {
    const ctx = try Context.createWith(std.testing.allocator, .{ .enable_gc = true, .enable_jit = false });
    defer ctx.destroy();
    ctx.collectGarbage();

    const heap = ctx.gc.?;
    heap.threshold_bytes = std.math.maxInt(usize);
    heap.nursery_threshold_bytes = std.math.maxInt(usize);
    const expected = try ctx.evaluate(
        \\globalThis.__movingIndexedString = "水😀\ud800x".repeat(64);
        \\__movingIndexedString.charCodeAt(130)
    );
    const before_value = ctx.global_object.getOwn("__movingIndexedString") orelse
        return error.TestUnexpectedResult;
    const before = before_value.asStringCell();
    try std.testing.expect(before.isGcManaged());
    try std.testing.expect(before.hasUtf16Index());
    const stable_id = heap.cellMetadata(@constCast(before)).?.id;

    const moved = ctx.collectYoungAfterRootValidation(heap);
    try std.testing.expectEqual(Context.GcHeap.CompactionStatus.compacted, moved.status);
    const after = ctx.global_object.getOwn("__movingIndexedString").?.asStringCell();
    try std.testing.expect(before != after);
    try std.testing.expectEqual(stable_id, heap.cellMetadata(@constCast(after)).?.id);
    try std.testing.expect(after.isGcManaged());
    try std.testing.expect(after.hasUtf16Index());
    try std.testing.expectEqual(expected.asNum(), (try ctx.evaluate("__movingIndexedString.charCodeAt(130)")).asNum());

    _ = try ctx.evaluate("globalThis.__movingIndexedString = undefined");
    ctx.collectGarbage();
}

